protected const array ID2DESC = [
0=>['No Skill','Empty skill slot','Empty slot'],
1=>['Sceau de guérison','Vous gagnez 82...172 points de vie. Votre bonus d\'armure est réduit de -40 quand vous utilisez cette compétence.','Vous gagnez 82...172 points de vie. Votre bonus d\'armure est réduit de -40 quand vous utilisez cette compétence.'],
2=>['Sceau de résurrection','Ressuscite un membre du groupe. Celui-ci revient à la vie avec 100% de santé et 25% d\'énergie. Ce sceau ne se recharge que lorsque vous obtenez une augmentation de moral.','Ressuscite le membre du groupe visé (100% de santé et 25% d\'énergie). Ce sceau ne se recharge que lorsque vous obtenez une augmentation de moral.'],
3=>['Sceau de capture','Choisissez une compétence d\'un boss de votre profession mort à proximité. Le Sceau de Capture sera remplacé par cette compétence de façon permanente. Si c\'était une compétence élite, vous obtenez 250 points d\'XP pour chaque niveau gagné.','Choisissez une compétence d\'un boss de votre profession mort à proximité. Le Sceau de Capture sera remplacé par cette compétence de façon permanente. Si c\'était une compétence élite, vous obtenez 250 points d\'XP pour chaque niveau gagné.'],
5=>['Blocage de pouvoir','Si l\'ennemi visé est en train de lancer un sort ou un chant, cette compétence est interrompue. Cette compétence et toutes les autres compétences de la même caractéristique sont également inutilisables pendant 1...12 secondes.','Si l\'ennemi visé est en train de lancer un sort ou un chant, cette compétence est interrompue. Cette compétence et toutes les autres compétences de la même caractéristique sont également inutilisables (pendant 1...12 secondes).'],
6=>['Mantra de la terre','Pendant 30...90 secondes, à chaque fois que vous subissez des dégâts de la terre, ceux-ci sont réduits de 26...50% et vous gagnez 2 points d\'énergie.','(30...90 secondes.) Réduit de 26...50% les dégâts de la terre que vous subissez. Vous gagnez 2 points d\'énergie quand vous subissez des dégâts de la terre.'],
7=>['Mantra de flamme','Pendant 30...90 secondes, à chaque fois que vous subissez des dégâts du feu, ceux-ci sont réduits de 26...50% et vous gagnez 2 points d\'énergie.','(30...90 secondes.) Réduit de 26...50% les dégâts du feu que vous subissez. Vous gagnez 2 points d\'énergie quand vous subissez des dégâts du feu.'],
8=>['Mantra de givre','Pendant 30...90 secondes, à chaque fois que vous subissez des dégâts du froid, ceux-ci sont réduits de 26...50% et vous gagnez 2 points d\'énergie.','(30...90 secondes.) Réduit de 26...50% les dégâts du froid que vous subissez. Vous gagnez 2 points d\'énergie quand vous subissez des dégâts du froid.'],
9=>['Mantra de foudre','Pendant 30...90 secondes, à chaque fois que vous subissez des dégâts de la foudre, ceux-ci sont réduits de 26...50% et vous gagnez 2 points d\'énergie.','(30...90 secondes.) Réduit de 26...50% les dégâts de la foudre que vous subissez. Vous gagnez 2 points d\'énergie quand vous subissez des dégâts de la foudre.'],
10=>['Leveur de maléfice','Pendant 5...80 secondes, le prochain maléfice qui vous sera lancé n\'aura pas d\'effet. Son lanceur subira 10...46 points de dégâts.','(5...80 secondes.) Le prochain maléfice qui vous est lancé échoue et son lanceur subit 10...46 points de dégâts.'],
11=>['Distorsion','Pendant 1...5 secondes, vous avez 75% de chances de bloquer les attaques. Quand vous bloquez une attaque de cette manière, soit vous perdez 2 points d\'énergie, soit la Distorsion prend fin.','(1...5 secondes.) Vous avez 75% de chances de bloquer. Coût du blocage : vous perdez 2 points d\'énergie ou la Distorsion prend fin.'],
13=>['Mantra de récupération','Pendant 5...20 secondes, les sorts que vous lancez se rechargent 33% plus vite.','(5...20 secondes.) Vos sorts se rechargent 33% plus vite.'],
14=>['Mantra de persévérance','Pendant 5...25 secondes, tous les maléfices de la magie de l\'illusion que vous lancez durent 10...40% plus longtemps.','(5...25 secondes.) Les maléfices d\'Illusion que vous lancez durent 10...40% plus longtemps.'],
15=>['Mantra des inscriptions','Pendant 5...25 secondes, les sceaux que vous activez en pose de combat se rechargent 10...40% plus vite.','(5...25 secondes.) Les sceaux que vous activez en pose de combat se rechargent 10...40% plus vite.'],
16=>['Mantra de concentration','Pendant 1...38 secondes, la prochaine tentative d\'interruption sur vous échouera.','(1...38 secondes.) La prochaine tentative d\'interruption sur vous échouera.'],
17=>['Mantra de résolution','Pendant 30...90 secondes, vous ne pouvez pas être interrompu, mais pour chaque tentative d\'interruption, soit vous perdez 10...4 points d\'énergie, soit le Mantra de résolution prend fin.','(30...90 secondes.) Vous protège des interruptions. Coût de la protection : vous perdez 10...4 points d\'énergie ou le Mantra de résolution prend fin.'],
18=>['Mantra des sceaux','Pendant 10...40 secondes, vous bénéficiez de +3 de bonus d\'armure pour chaque sceau dont vous êtes équipé. Chaque fois que vous utilisez un sceau, vous gagnez 5...60 points de vie.','(10...40 secondes.) Vous gagnez un bonus d\'armure de +3 pour chaque sceau. Vous gagnez 5...60 points de vie chaque fois que vous utilisez un sceau.'],
19=>['Fragilité','Pendant 8...20 secondes, l\'ennemi visé et les ennemis adjacents subissent 5...20 points de dégâts chaque fois qu\'ils sont affectés ou libérés d\'une nouvelle condition.','Inflige également des maléfices aux ennemis adjacents à la cible (8...20 secondes). Ces ennemis subissent 5...20 points de dégâts chaque fois qu\'ils gagnent ou perdent une condition.'],
21=>['Enchantement inspiré','Lève un enchantement à l\'ennemi visé et vous obtenez 3...15 points d\'énergie. Pendant 20 secondes, l\'enchantement inspiré est remplacé par celui qui a été pris à la cible ennemie.','Supprime un enchantement à la cible ennemie. Effets de la suppression : vous obtenez 3...15 points d\'énergie ; ce sort est remplacé par cet enchantement (20 secondes).'],
22=>['Maléfice inspiré','Lève un maléfice de la cible (un allié ou vous-même) et vous gagnez 4...10 points d\'énergie. Pendant 20 secondes, le maléfice inspiré est remplacé par celui qui a été levé.','Lève un maléfice qui frappe la cible alliée. Effets de la suppression : vous obtenez 4...10 points d\'énergie ; ce sort est remplacé par ce maléfice (20 secondes).'],
23=>['Dissipation de pouvoir','Si l\'ennemi visé est en train de lancer un sort ou un chant, cette compétence est interrompue et l\'ennemi subit 30...120 points de dégâts.','Interrompt un sort ou un chant. Effet de l\'interruption : inflige 30...120 points de dégâts.'],
24=>['Fuite de pouvoir','Si l\'ennemi visé est en train de lancer un sort ou un chant, cette compétence est interrompue et l\'ennemi visé perd 3...17 points d\'énergie.','Interrompt un sort ou un chant. Effet de l\'interruption : provoque une perte de 3...17 points d\'énergie.'],
25=>['Drain de pouvoir','Si l\'ennemi visé est en train de lancer un sort ou un chant, cette compétence est interrompue et vous gagnez 1...31 points d\'énergie.','Interrompt un sort ou un chant. Effet de l\'interruption : vous gagnez 1...31 points d\'énergie.'],
26=>['Empathie','Pendant 5...15 secondes, chaque fois que l\'ennemi visé attaque, il subit 10...55 points de dégâts et inflige 1...15 points de dégâts en moins.','(5...15 secondes.) Chaque fois que l\'ennemi visé attaque, il inflige 1...15 points de dégâts en moins, et subit 10...55 points de dégâts.'],
27=>['Dispersion des illusions','Dissipe un maléfice d\'Envoûteur sur l\'ennemi ciblé. Si un maléfice est dissipé, cet ennemi subit 15...75 points de dégâts et les ennemis adjacents subissent 75% de ces dégâts.','Dissipe un maléfice d\'Envoûteur sur l\'ennemi ciblé. Effet de la suppression : 15...75 points de dégâts à l\'ennemi ciblé et 75% de ces dégâts à tous les ennemis adjacents.'],
28=>['Retour de flamme','Pendant 10 secondes, chaque fois que l\'ennemi visé lance un sort, il subit 35...140 points de dégâts.','(10 secondes.) L\'ennemi visé subit 35...140 points de dégâts chaque fois qu\'il lance un sort.'],
29=>['Black-out','Pendant 2...8 secondes, toutes les compétences de la cible touchée sont inefficaces. Les vôtres seront désactivées pendant 5 secondes.','(2...8 secondes). Désactive les compétences. Vos compétences sont désactivées (5 secondes).'],
30=>['Diversion','Pendant 6 secondes, la prochaine fois que l\'ennemi visé utilisera une compétence, elle mettra 10...56 secondes de plus à se recharger.','(6 secondes.) La compétence suivante de l\'ennemi visé a un temps de recharge accru de +10...56 secondes.'],
31=>['Conjuration de fantasme','Pendant 4...18 secondes, la cible ennemie subit une dégénération de santé de -5.','(4...18 secondes.) Provoque une dégénération de santé de -5.'],
32=>['Illusion de faiblesse','Vous perdez 50...240 points de vie. L\'illusion de faiblesse prend fin si les dégâts que vous subissez font descendre vos points de vie au-dessous de 25% de votre maximum. Quand l\'Illusion de faiblesse prend fin, vous gagnez 50...240 points de vie.','Vous perdez 50...240 points de vie. Effet final : vous gagnez 50...240 points de vie. Prend fin si les dégâts que vous subissez font descendre votre santé au-dessous de 25% de votre maximum.'],
33=>['Armes illusoires','Pendant 30 secondes, vos attaques au corps à corps ne peuvent ni réussir ni échouer. La compétence Armes Illusoires inflige à la place 20...60 points de dégâts à vos cibles chaque fois que vous attaquez au corps à corps. Vous gagnez un bonus d\'armure de +5 pour chaque compétence de Magie de l\'illusion équipée.','(30 secondes.) Inflige 20...60 points de dégâts aux ennemis à la place d\'autres dégâts ou effets lors de combats rapprochés. Vous gagnez un bonus d\'armure de +5 pour chaque compétence de Magie de l\'Illusion équipée. Vos attaques au corps à corps ne peuvent ni réussir ni échouer.'],
34=>['Visage avenant','Pendant 4...10 secondes, à chaque fois que la cible (un allié ou vous-même) visée est touchée au corps à corps, tous les ennemis adjacents perdent toute leur adrénaline et 3 points d\'énergie.','(4...10 secondes.) Tous les ennemis adjacents perdent toute leur adrénaline ainsi que 3 points d\'énergie chaque fois que la cible (un allié ou vous-même) est touchée par une attaque au corps à corps.'],
35=>['Ignorance','Pendant 8...20 secondes la cible ennemie ne peut pas utiliser ses sceaux.','(8...20 secondes.) L\'ennemi visé ne peut pas utiliser de sceaux.'],
36=>['Enigme des arcanes','Pendant 5...15 secondes, le temps d\'incantation des sorts de l\'ennemi visé et de tous les ennemis adjacents est doublé. Lorsque ce maléfice prend fin, vous gagnez 1...7 points d\'énergie.','Inflige également des maléfices aux ennemis adjacents à la cible (5...15 secondes). Double le temps de lancement des sorts. Effet final : vous gagnez 1...7 points d\'énergie.'],
37=>['Illusion de hâte','Pendant 5...11 secondes, vous ne souffrez plus d\'Infirmité et vous déplacez 33% plus vite. Lorsque l\'Illusion de hâte prend fin, vous souffrez d\'Infirmité pendant 3 secondes.','(5...11 secondes.) Vous vous déplacez 33% plus vite. Effet initial : annule l\'Infirmité. Effet final : vous êtes frappé d\'Infirmité (3 secondes).'],
38=>['Canalisation','Pendant 8...56 secondes, à chaque fois que vous lancez un sort, vous bénéficiez d\'1 point d\'énergie pour chaque ennemi dans la zone.','(8...56 secondes.) Chaque fois que vous lancez un sort, vous gagnez 1 point d\'énergie par ennemi dans la zone.'],
39=>['Afflux d\'énergie','L\'ennemi ciblé perd 1...10 points d\'énergie. Pour chaque point d\'énergie perdu, cet ennemi subit 7 points de dégâts et tous les ennemis à proximité subissent 75% de ces dégâts.','La cible perd 1...10 points d\'énergie. Pour chaque point d\'énergie perdu, elle subit 7 points de dégâts et les ennemis à proximité subissent 75% de ces dégâts.'],
40=>['Festin éthéré','L\'ennemi visé perd 3 points d\'énergie. Vous êtes guéri de 20...65 points de vie pour chaque point d\'énergie perdu.','Provoque une perte de 3 points d\'énergie. Vous gagnez 20...65 points de vie par point d\'énergie perdu.'],
41=>['Seigneur éthéré','Vous perdez toute votre énergie. Pendant 5...10 secondes, la cible ennemie subit une dégénération d\'énergie de -1...3 et vous bénéficiez d\'une régénération d\'énergie de +1...3.','Vous perdez toute votre énergie. L\'ennemi visé subit une dégénération d\'énergie de -1...3 et vous bénéficiez d\'une régénération d\'énergie de +1...3. (5...10 secondes.)'],
42=>['Flamme d\'énergie','La cible ennemie perd 1...10 points d\'énergie et subit 9 points de dégâts pour chaque point d\'énergie perdu.','Provoque une perte de 1...10 points d\'énergie. Inflige 9 points de dégâts par point d\'énergie perdu.'],
43=>['Maladresse','Pendant 4 secondes, la cible et les ennemis adjacents sont affectés par le maléfice Maladresse. La prochaine fois que chaque ennemi attaque, cette action est interrompue et l\'ennemi subit 10...80 points de dégâts.','(4 secondes.) Les ennemis adjacents sont également affectés. Interrompt l\'attaque suivante. Effet de l\'interruption : inflige 10...80 points de dégâts.'],
44=>['Douleur fantôme','Pendant 10 secondes, la cible ennemie subit une dégénération de santé de -1...4. Quand la Douleur fantôme cesse, la cible souffre d\'une Blessure profonde qui réduit sa santé maximum de 20% pendant 5...20 secondes.','(10 secondes.) Provoque une dégénération de santé de -1...4. Effet final : provoque la Blessure profonde (5...20 secondes).'],
45=>['Fardeau éthéré','Pendant 6...12 secondes, la cible ennemie se déplace 50% moins vite. Quand le Fardeau éthéré disparaît, vous gagnez 10...18 points d\'énergie.','(6...12 secondes.) La cible ennemie se déplace 50% moins vite. Effet final : vous gagnez 10...18 points d\'énergie.'],
46=>['Culpabilité','Pendant 6 secondes, la prochaine fois que l\'ennemi visé lance un sort qui vise un autre ennemi, ce sort échoue et vous lui volez jusqu\'à 5...14 points d\'énergie.','(6 secondes.) Le sort suivant de l\'ennemi visé échoue et vous volez 5...14 points d\'énergie. Aucun effet si le sort de l\'ennemi ne vise pas un de vos alliés.'],
47=>['Incompétence','Pendant 4 secondes, la prochaine fois que l\'ennemi visé ou tout ennemi adjacent attaque, il subit 30...135 points de dégâts et est aveuglé pendant 10 secondes.','(4 secondes.) Affecte également les ennemis proches de la cible. Inflige 30...135 points de dégâts. Provoque l\'Aveuglement (10 secondes). Aucun effet sauf si l\'ennemi affecté attaque.'],
48=>['Esprit de l\'échec','Pendant 30 secondes, l\'ennemi visé a 25% de chances de rater ses attaques. Vous gagnez 1...3 points d\'énergie pour chaque attaque que l\'ennemi manque lors du combat.','(30 secondes.) L\'ennemi visé a 25% de chances de manquer. Vous gagnez 1...3 points d\'énergie chaque fois qu\'il manque.'],
49=>['Délabrement spirituel','Pendant 5...40 secondes, lorsque cet ennemi est la cible de l\'une de vos compétences d\'Envoûteur autre qu\'un maléfice, il perd 1 point d\'énergie et subit 5...25 points de dégâts supplémentaires par point d\'énergie perdu. Si l\'énergie de l\'ennemi visé tombe à 0, le Délabrement spirituel prend fin et l\'ennemi subit 15...100 points de dégâts.','(5...40 secondes.) Provoque la perte d\'un point d\'énergie chaque fois que l\'ennemi est la cible de vos compétences d\'Envoûteur autre qu\'un maléfice. Inflige 5...25 points de dégâts par point d\'énergie perdu. Si l\'énergie de l\'ennemi visé tombe à 0, il subit 15...100 points de dégâts et le Délabrement spirituel prend fin.'],
50=>['Embarras de l\'incapable','Après 3 secondes, l\'ennemi ciblé subit 20...100 points de dégâts et les ennemis adjacents subissent 75% de ces dégâts. Si cet ennemi réussit à utiliser une compétence, Embarras du gaspilleur prend fin prématurément et n\'inflige aucun dégât.','(3 secondes.) Effet final : inflige 20...100 points de dégâts à l\'ennemi ciblé et 75% de ces dégâts aux ennemis adjacents. Aucun effet et prend fin prématurément si l\'ennemi ciblé réussit à utiliser une compétence.'],
51=>['Honte','Pendant 6 secondes, la prochaine fois que l\'ennemi visé lance un sort qui vise un allié, ce sort échoue et vous lui volez jusqu\'à 5...14 points d\'énergie.','(6 secondes.) Le sort suivant de l\'ennemi visé échoue et vous volez 5...14 points d\'énergie. Aucun effet si le sort de l\'ennemi ne vise pas un de ses alliés.'],
52=>['Panique','Pendant 1...10 secondes, la cible ennemie et tous les ennemis à proximité sont sous l\'emprise de Panique. Lorsqu\'un ennemi sous l\'emprise de Panique parvient à utiliser une compétence, tous les ennemis à proximité sont interrompus.','Inflige également des maléfices aux ennemis proches de votre cible (1...10 secondes). Interrompt tous les ennemis à proximité lorsqu\'un ennemi affecté parvient à activer une compétence.'],
53=>['Migraine','Pendant 5...20 secondes, la cible ennemie subit une dégénération de santé de -1...8 et le temps d\'activation de ses compétences est rallongé de 100%.','(5...20 secondes.) Entraîne une dégénération de santé de -1...8 et double le temps d\'activation des compétences.'],
54=>['Angoisse paralysante','Pendant 5...20 secondes, la cible se déplace et attaque 50% moins vite et subit une dégénération de santé de -1...8.','(5...20 secondes.) L\'ennemi visé se déplace et attaque 50% moins vite et subit une dégénération de santé de -1...8.'],
55=>['Rêves enfiévrés','Pendant 10...25 secondes, chaque fois que l\'ennemi visé est affecté par une nouvelle condition, tous les ennemis dans la zone en sont également affectés. Si la cible est affectée par au moins deux conditions, elle est frappée de Stupeur pendant 1...3 secondes.','(10...25 secondes.) Les ennemis dans la zone sont affectés par toute nouvelle condition qui affecte la cible ennemie. Inflige la Stupeur à la cible ennemie (1...3 secondes) si cette dernière est affectée par au moins deux conditions.'],
56=>['Images apaisantes','Pendant 8...20 secondes, l\'ennemi visé et tous les ennemis adjacents ne peuvent pas récupérer d\'adrénaline.','Inflige également des maléfices aux ennemis adjacents à la cible (8...20 secondes). Ces ennemis ne peuvent pas gagner d\'adrénaline.'],
57=>['Cri de frustration','Si l\'ennemi ciblé est en train d\'utiliser une compétence, lui et tous les ennemis dans la zone sont interrompus. Cet ennemi subit 15...75 points de dégâts et les ennemis dans la zone subissent 75% de ces dégâts.','Si l\'ennemi ciblé est en train d\'utiliser une compétence, lui et tous les ennemis dans la zone sont interrompus. Cet ennemi subit 15...75 points de dégâts et les ennemis dans la zone subissent 75% de ces dégâts.'],
58=>['Sceau de minuit','Vous subissez les effets de l\'Aveuglement, ainsi que l\'ennemi touché pendant 15 secondes.','(15 secondes.) Inflige l\'Aveuglement. Vous souffrez de l\'Aveuglement (15 secondes).'],
59=>['Sceau de lassitude','La cible ennemie et tous les ennemis adjacents perdent 3...8 points d\'énergie et souffrent de Faiblesse pendant 1...12 secondes.','Affecte également les ennemis près de la cible. Provoque une perte de 3...8 points d\'énergie et inflige la Faiblesse (1...12 secondes).'],
61=>['Sceau sangsue','Interrompt l\'action de l\'ennemi. S\'il s\'agissait d\'un sort, vous gagnez 3...15 points d\'énergie.','Interrompt une action. Effet de l\'interruption : vous gagnez 3...15 points d\'énergie si l\'action est un sort.'],
62=>['Sceau d\'humilité','La compétence d\'élite de l\'ennemi ciblé est désactivée pendant 1...16 secondes. Vos compétences autres que celles d\'Envoûteur sont désactivées pendant 4 secondes.','Désactivation de compétence d\'élite sur cible (1...16 secondes). Désactive vos compétences sauf celles d\'Envoûteur (4 seconds).'],
63=>['Sceau de voûte','Tous les sceaux hormis le Sceau de voûte sont rechargés. Pendant 20 secondes, les 0...6 prochaines fois que vous utiliserez un sceau visant un ennemi, tous les autres ennemis proches de votre cible subiront 15...60 points de dégâts et seront interrompus.','(20 secondes.) 0...6 de vos prochains sceaux interrompent et infligent 15...60 points aux ennemis adjacents à votre cible. Effet initial : recharge tous vos autres sceaux.'],
65=>['Mimétisme des arcanes','Pendant 20 secondes, le Mimétisme des arcanes devient la compétence élite (qui n\'est pas une Transformation) de l\'allié visé.','Cette compétence devient la compétence élite de l\'allié visé (20 secondes). Vous ne pouvez pas vous prendre pour cible. Aucun effet si la compétence élite de la cible est une Transformation.'],
66=>['Chaînes spirituelles','Pendant 5...20 secondes, l\'ennemi visé perd 5 points d\'énergie dès qu\'il attaque.','(5...20 secondes.) L\'ennemi visé perd 5 points d\'énergie chaque fois qu\'il attaque.'],
67=>['Annihilateur de maléfices','Ote un maléfice qui frappe la cible (un allié ou vous-même). Si un maléfice est levé, les ennemis proches de la cible subissent 30...120 points de dégâts.','Lève un maléfice qui frappe la cible alliée. Effet de la suppression : inflige 30...120 points de dégâts aux ennemis à proximité de cet allié.'],
68=>['Drain d\'enchantement','Ote un enchantement à l\'ennemi visé. Si l\'enchantement est supprimé, vous gagnez 8...17 points d\'énergie et 40...120 points de vie.','Supprime un enchantement à la cible ennemie. Effet de la suppression : vous gagnez 8...17 points d\'énergie et 40...120 points de vie.'],
69=>['Dissipation des enchantements','Ote un enchantement à l\'ennemi visé. Si l\'enchantement est supprimé, l\'ennemi subit 14...100 points de dégâts.','Supprime un enchantement à la cible ennemie. Effet de la suppression : inflige 14...100 points de dégâts.'],
72=>['Résistance aux éléments','Pendant 30...90 secondes, vous gagnez +40 de bonus d\'armure contre les dégâts élémentaires, mais perdez 24...12 de bonus d\'armure contre les dégâts physiques.','(30...90 secondes.) Vous bénéficiez d\'un bonus d\'armure de +40 contre les dégâts élémentaires. Votre bonus d\'armure est réduit de -24...12 contre les dégâts physiques.'],
73=>['Résistance physique','Pendant 30...90 secondes, vous gagnez +40 de bonus d\'armure contre les dégâts physiques, mais perdez 24...12 de bonus d\'armure contre les dégâts élémentaires.','(30...90 secondes.) Vous bénéficiez d\'un bonus d\'armure de +40 contre les dégâts physiques. Votre bonus d\'armure est réduit de -24...12 contre les dégâts élémentaires.'],
74=>['Echo','Pendant 30 secondes, l\'écho est remplacé par la prochaine compétence que vous utiliserez. L\'écho agit comme cette compétence pendant 30 secondes.','(30 secondes.) L\'Echo est remplacé par la compétence suivante que vous utilisez (30 secondes).'],
75=>['Echo des arcanes','Si vous lancez un sort dans les 20 secondes, il remplace l\'écho des arcanes pendant 20 secondes. L\'Echo des arcanes se termine prématurément si vous utilisez une compétence autre qu\'un sort.','(20 secondes.) L\'Echo des arcanes est remplacé par le sort suivant que vous utilisez (20 secondes). Cet enchantement prend fin si vous utilisez une compétence qui n\'est pas un sort.'],
76=>['Fardeau imaginaire','Pendant 8...20 secondes, la cible se déplace 50% moins vite.','(8...20 secondes.) La cible ennemie se déplace 50% moins vite.'],
77=>['Tempête chaotique','Crée une Tempête chaotique sur la position de l\'ennemi d\'une durée de 10 secondes. Toutes les secondes, les ennemis adjacents à cette position subissent 5...25 points de dégâts et perdent 0...2 points d\'énergie.','Inflige 5...25 points de dégâts et entraîne la perte de 0...2 points d\'énergie toutes les secondes (10 secondes). Frappe les ennemis adjacents à la position initiale de la cible.'],
78=>['Epidémie','Répand toutes les conditions négatives avec leur durée restante de la cible ennemie vers tous les ennemis qui lui sont adjacents.','Les conditions dont souffre l\'ennemi visé sont transmises aux ennemis adjacents.'],
79=>['Drain d\'énergie','La cible ennemie perd 2...9 points d\'énergie. Vous obtenez 3 points d\'énergie pour chaque point d\'énergie perdu par l\'ennemi.','Provoque une perte de 2...9 points d\'énergie. Vous obtenez 3 points d\'énergie par point d\'énergie perdu.'],
80=>['Siphon d\'énergie','La cible ennemie perd 4...7 points d\'énergie. Vous obtenez 2 points d\'énergie pour chaque point d\'énergie perdu par l\'ennemi.','Provoque une perte de 4...7 points d\'énergie. Vous obtenez 2 points d\'énergie par point d\'énergie perdu.'],
81=>['Vol des arcanes','Pendant 5...35 secondes, l\'ennemi ne peut plus utiliser un sort choisi aléatoirement et le Vol des Arcanes est remplacé par ce sort.','(5...35 secondes.) Désactive un sort aléatoire. Cette compétence remplace ce sort.'],
82=>['Mantra de rappel','Pendant 20 secondes, vous n\'en tirez aucun bénéfice. Vous gagnez 10...25 points d\'énergie quand le Mantra de rappel prend fin.','(20 secondes.) Effet final : vous gagnez 10...25 points d\'énergie.'],
83=>['Animation d\'horreur squelettique','Visez le cadavre le plus près pour animer une horreur squelettique de niveau 1...17.','Crée une horreur squelettique de niveau 1...17. Exploite un cadavre récent.'],
84=>['Animation de démon squelette','Vous utilisez le cadavre le plus proche pour animer un démon squelette de niveau 1...17. Les démons squelettes peuvent attaquer à distance.','Crée un démon squelette de niveau 1...17 capable d\'attaquer à distance. Exploite un cadavre récent.'],
85=>['Animation de serviteurs squelettes','Vous utilisez le cadavre le plus proche pour animer deux serviteurs squelettes de niveau 0...12.','Crée deux serviteurs squelettes de niveau 0...12. Exploite un cadavre récent.'],
86=>['Equilibre de Grenth','Si l\'ennemi visé dispose de plus de santé que vous, vous récupérez la moitié de la différence (pas plus que votre santé maximum) et celui-ci perd la même quantité. Si cet ennemi a moins de santé que vous, vous perdez la moitié de la différence et l\'ennemi récupère la même quantité de santé.','Vous gagnez la moitié de la différence de santé entre vous et l\'ennemi visé et celui-ci en perd autant. Si cet ennemi a moins de santé que vous, vous perdez la moitié de la différence et l\'ennemi récupère la même quantité.'],
87=>['Regard de Verata','Si la cible morte-vivante animée et hostile obéit à un maître, leur lien est brisé et elle devient hostile envers toutes les autres créatures. Si elle n\'a pas de maître, vous devenez le sien et la soignez de 60...80 (50% de risques d\'échec avec Magie de mort 4 ou moins).','Vous privez le serviteur mort-vivant visé de maître. S\'il n\'en a déjà plus, vous devenez le sien et le soignez de 60...80. 50% de chances d\'échouer sauf si la valeur de Magie de mort est de 5 ou plus.'],
88=>['Aura de Verata','Tous les morts-vivants animés hostiles dans les environs sont liés à vous. Les effets de l\'Aura de Verata cessent au bout de 120...300 secondes. Tous les liens qui vous unissent aux morts-vivants sont alors brisés (50% de risques d\'échec avec une Magie de mort de 4 ou inférieure).','(120...300 secondes.) Vous devenez le maître de tous les serviteurs morts-vivants hostiles de la zone. Effet final : vos serviteurs morts-vivants n\'ont plus de maître. 50% de chances d\'échouer sauf si la valeur de Magie de mort est de 5 ou plus.'],
89=>['Froideur mortelle','L\'ennemi subit 5...50 points de dégâts du froid. S\'il a plus de 50% de ses points de vie, il subit 5...50 points de dégâts de l\'ombre supplémentaires.','Inflige 5...50 points de dégâts du froid. Inflige 5...50 points de dégâts supplémentaires si l\'ennemi visé a plus de 50% de santé.'],
90=>['Sacrifice de Verata','Pendant 5...10 secondes, vos alliés morts-vivants bénéficient d\'une régénération de santé de +10. Toutes les conditions qui affectent ces alliés vous sont transférées. Si ce sort réussit et si vous contrôlez 3 serviteurs ou moins, le Sacrifice de Verata se recharge instantanément.','(5...10 secondes.) 10 serviteurs morts-vivants alliés bénéficient d\'une régénération de santé de +10. Rechargement instantané si vous ne contrôlez pas plus de 3 serviteurs. Toutes les conditions affectant vos serviteurs vous sont transférées.'],
91=>['Puits de pouvoir','Exploitez le cadavre le plus proche ou sacrifiez 66% de santé pour créer à cet endroit un Puits de pouvoir. Pendant 10...30 secondes, les alliés dans la zone du Puits de pouvoir bénéficient d\'une régénération de santé de +1...6 et d\'une régénération d\'énergie de +2.','(10...30 secondes.) Les alliés présents dans ce puits bénéficient de +1...6 points de régénération de santé et de +2 points de régénération d\'énergie. c=@SkillDull>Exploite un cadavre frais ou sacrifie 66% de la santé.'],
92=>['Puits de sang','Exploitez le cadavre le plus proche ou sacrifiez 66% de santé pour créer à cet endroit un Puits de sang. Pendant 8...20 secondes, les alliés dans la zone bénéficient d\'une régénération de santé de +1...6.','(8...20 secondes.) Les alliés présents dans ce puits bénéficient de +1...6 points de régénération de santé. Exploite un cadavre frais ou sacrifie 66% de la santé.'],
93=>['Puits de souffrance','Exploitez le cadavre le plus proche ou sacrifiez 66% de santé pour créer à cet endroit un Puits de douleur. Les ennemis dans la zone subissent une dégénération de santé de -1...6 pendant 10...30 secondes.','(10...30 secondes.) Les ennemis présents dans ce puits subissent -1...6 points de dégénération de santé. Exploite un cadavre frais ou sacrifie 66% de la santé.'],
94=>['Puits du profane','Exploitez le cadavre le plus proche ou sacrifiez 66% de santé pour créer à cet endroit un Puits du profane. Pendant 8...20 secondes, les ennemis dans la zone sont privés de tous leurs enchantements et ne peuvent pas être visés par d\'autres enchantements. (50% de risques d\'échec avec Magie de mort 4 ou inférieure).','(8...20 secondes.) Les ennemis présents dans ce puits perdent tous leurs enchantements et ne peuvent plus être la cible d\'enchantements. Exploite un cadavre frais ou sacrifie 66% de la santé. 50% de risques d\'échec à moins d\'avoir au moins 5 points en Magie de la mort.'],
95=>['Explosion putride','Le cadavre le plus proche de votre cible explose et provoque une onde de choc qui inflige 24...120 points de dégâts aux ennemis à proximité.','Fait exploser un cadavre qui inflige 24...120 points de dégâts aux ennemis à proximité. Exploite un cadavre récent.'],
96=>['Festin de l\'âme','Vous utilisez le cadavre le plus proche pour obtenir 50...280 points de vie.','Vous gagnez 50...280 points de vie. Exploite un cadavre récent.'],
97=>['Voyage nécrotique','Vous utilisez un cadavre au hasard ou vous sacrifiez 30...20% de santé pour vous téléporter sur la position de l\'ennemi ciblé. Vous subissez Maladie pendant 6 secondes, et tous les ennemis à proximité sont empoisonnés pendant 5...20 secondes.','Vous utilisez un cadavre au hasard ou vous sacrifiez 30...20% de santé pour vous téléporter sur la position de l\'ennemi ciblé. Vous subissez Maladie pendant 6 secondes, et tous les ennemis à proximité sont empoisonnés pendant 5...20 secondes.'],
98=>['Combustion corporelle','Vous utilisez un cadavre au hasard pour vous téléporter sur sa position et vous obtenez 25...100 points de vie et 5...20 points d\'énergie.','Vous vous téléportez vers un cadavre. Vous gagnez 25...100 points de vie et 5...20 points d\'énergie. Exploite un cadavre récent.'],
99=>['Lien parasitaire','Pendant 20 secondes, l\'ennemi subit une dégénération de santé de -1. Lorsque le Lien parasitaire prend fin, vous récupérez 30...120 points de vie.','(20 secondes.) Provoque une dégénération de santé de -1. Effet final : vous rend 30...120 points de santé.'],
100=>['Ame barbelée','Pendant 30 secondes, l\'ennemi visé subit 15...30 points de dégâts si on lui lance un enchantement ou un maléfice.','(30 secondes.) Inflige 15...30 points de dégâts quand un enchantement ou un maléfice est lancé sur l\'ennemi visé.'],
101=>['Barbelés','Pendant 30 secondes, l\'ennemi visé subit 4...16 points de dégâts en plus si on lui inflige des dégâts physiques.','(30 secondes.) L\'ennemi visé subit 4...16 points de dégâts chaque fois qu\'il subit des dégâts physiques.'],
102=>['Choc de l\'ombre','L\'ennemi subit 12...48 points de dégâts de l\'ombre. S\'il a plus de 50% de ses points de vie, vous lui volez jusqu\'à 12...48 points de vie.','Inflige 12...48 points de dégâts. Vole jusqu\'à 12...48 points de vie si cet ennemi a plus de 50% de santé.'],
103=>['Prix de l\'échec','Pendant 30 secondes, l\'ennemi a 25% de risques de rater ses attaques et de subir 1...46 points de dégâts à chaque attaque ratée.','(30 secondes.) 25% de chances de manquer. L\'ennemi visé subit 1...46 points de dégâts chaque fois qu\'il manque une attaque.'],
104=>['Nova mortelle','Pendant 30 secondes, si la cible (un allié ou vous-même) meurt, tous les ennemis adjacents reçoivent 26...100 points de dégâts et sont empoisonnés pendant 15 secondes.','(30 secondes.) Inflige 26...100 points de dégâts et provoque l\'Empoisonnement (15 secondes) des ennemis adjacents si l\'allié visé meurt.'],
105=>['Essaim mortel','L\'Essaim mortel vole lentement et inflige 30...90 points de dégâts du froid à trois cibles maximum dans la zone.','Essaim mortel se déplace lentement et inflige 30...90 points de dégâts du froid. Frappe 2 ennemis supplémentaires dans la zone.'],
106=>['Putréfaction','L\'ennemi de chair visé souffre de Maladie pendant 10...25 secondes et perd progressivement de la santé.','Inflige la Maladie (10...25 secondes).'],
107=>['Virulence','Si l\'ennemi visé souffrait d\'une condition, il est atteint de Maladie, d\'Empoisonnement et de Faiblesse pendant 3...15 secondes.','Inflige la Maladie, l\'Empoisonnement et la Faiblesse (3...15 secondes). Aucun effet si l\'ennemi ne souffre pas déjà d\'une condition.'],
108=>['Souffrance','L\'ennemi visé et tous les ennemis à proximité subissent une dégénération de santé de -0...3 pendant 6...30 secondes.','Inflige également des maléfices aux ennemis à proximité de la cible (6...30 secondes). Ces ennemis subissent une dégénération de santé de -0...3.'],
109=>['Siphon de vie','Pendant 12...24 secondes, la cible ennemie subit une dégénération de santé de -1...3 à votre profit (régénération de santé de +1...3).','(12...24 secondes.) L\'ennemi visé subit une dégénération de santé de -1...3. Vous bénéficiez d\'une régénération de santé de +1...3.'],
110=>['Festin impie','Vous volez jusqu\'à 10...65 points de vie à 1...4 ennemis maximum se trouvant dans la zone.','Vole 10...65 points de vie à 1...4 ennemis dans la zone autour de vous.'],
111=>['Réveil du sang','Pendant 20...44 secondes, vous avez +2 en Magie du sang et +2 en Malédiction, mais si vous sacrifiez des points de vie, vous en perdez 50% de plus que la normale.','(20...44 secondes.) Vous avez +2 en Magie du sang et en Malédictions. Vous sacrifiez 50% de santé en plus que normalement.'],
112=>['Désacralisation d\'enchantements','L\'ennemi et tous ceux à proximité subissent 6...60 points de dégâts de l\'ombre et 4...20 points de dégâts de l\'ombre pour chaque enchantement qui les affecte.','Inflige 6...60 points de dégâts à la cible et aux ennemis à proximité. Inflige 4...20 points de dégâts supplémentaires pour chaque enchantement qui les affectent.'],
113=>['Chair putréfiée','Pendant 20...44 secondes, les alliés dans la zone sont immunisé contre Maladie. Les ennemis qui frappent ces alliés au corps à corps sont atteints de Maladie pendant 3...15 secondes.','(20...44 secondes.) Les ennemis qui frappent au corps-à-corps des alliés dans la zone subissent Maladie (3...15 secondes) ; l\'allié frappé est immunisé à Maladie.'],
114=>['Aura de la liche','Tous les cadavres à portée de voix sont exploités et vous animez une horreur squelettique de niveau 1...17, plus une horreur squelettique pour chaque cadavre exploité de cette manière. Pendant 5...45 secondes, votre caractéristique de Magie de la mort est augmentée de +1.','Exploite tous les cadavres à portée de voix. Anime une horreur squelettique de niveau 1...17, plus une horreur squelettique pour chaque cadavre exploité. Votre Magie de la mort est augmentée de +1 (5...45 secondes).'],
115=>['Transfusion sanguine','Pendant 7 secondes, vous bénéficiez d\'une régénération de santé de +3...6. Lorsque Transfusion sanguine prend fin, vous obtenez 40...190 points de vie.','(7 secondes.) Vous bénéficiez d\'une régénération de santé de +3...6. Effet final : vous rend 40...190 points de vie.'],
116=>['Aura noire','Pendant 30 secondes, à chaque fois que la cible (un allié ou vous-même) sacrifie des points de vie, l\'Aura noire inflige 5...50 points de dégâts de l\'ombre à tous les ennemis adjacents et vous perdez 5...20 points de vie .','(30 secondes.) Inflige 5...50 points de dégâts aux ennemis adjacents chaque fois que l\'allié visé sacrifie de la santé. Coût des dégâts : vous perdez 5...20 points de vie.'],
117=>['Affaiblissement','La cible est frappée de Faiblesse pendant 10...30 secondes.','Inflige la Faiblesse (10...30 secondes).'],
118=>['Sang du faible','L\'ennemi visé et tous les ennemis proches souffrent de Faiblesse pendant 5...20 secondes.','Inflige la Faiblesse (5...20 secondes) à l\'ennemi visé et aux ennemis à proximité.'],
119=>['Pouvoir du sang','Pendant 10 secondes, la cible alliée bénéficie d\'une régénération d\'énergie de +3...6.','(10 secondes.) Régénération d\'énergie de +3...6. Vous ne pouvez pas vous prendre pour cible.'],
120=>['Sang du Maître','Tous vos alliés morts-vivants sont soignés de 30...116 points de vie. Vous sacrifiez 2% de santé maximum en plus par serviteur soigné de cette manière.','Soigne vos serviteurs morts-vivants de 30...116 points de vie. Coût des soins : vous sacrifiez +2% de santé par serviteur soigné.'],
121=>['Esprit malveillant','Pendant 10...25 secondes, chaque fois que l\'ennemi visé attaque ou utilise une compétence, l\'Esprit malveillant lui inflige 15...45 points de dégâts de l\'ombre, ainsi qu\'à tous les alliés adjacents de cet ennemi.','(10...25 secondes.) Chaque fois que l\'ennemi visé attaque ou utilise une compétence, lui et les ennemis adjacents subissent 15...45 points de dégâts.'],
122=>['Intervention néfaste','Pendant 5...20 secondes, l\'ennemi visé reçoit 20% de guérison en moins. S\'il meurt lorsqu\'il est frappé de l\'Intervention néfaste, une horreur squelettique (sans maître) de niveau 1...17 est invoquée.','(5...20 secondes.) L\'ennemi visé reçoit 20% de guérison en moins. Si cet ennemi meurt pendant qu\'il souffre de ce maléfice, une horreur squelettique (sans maître) de niveau 1...17 est invoquée.'],
123=>['Parasite sournois','Pendant 5...15 secondes, chaque fois que l\'ennemi visé réussit une attaque, vous lui volez jusqu\'à 15...45 points de vie.','(5...15 secondes.) Vole 15...45 points de vie chaque fois que l\'ennemi visé réussit une attaque.'],
124=>['Frissons glacés','Pendant 10...40 secondes, chaque fois que l\'ennemi subit des dégâts du froid pendant qu\'il utilise une compétence, il est interrompu et soit vous perdez 8...3 points d\'énergie, soit les Frissons glacés se terminent.','(10...40 secondes.) Des dégâts du froid interrompent les compétences de la cible ennemie. Coût de l\'interruption : vous perdez 8...3 points d\'énergie ou les Frissons glacés se terminent.'],
125=>['Flétrissure','Pendant 5...35 secondes, la cible ennemie subit une dégénération de santé de -2...4 et d\'énergie de -1. Si l\'énergie de l\'ennemi visé devient nulle, il subit 15...75 points de dégâts et Flétrissure prend fin.','(5...35 secondes.) Provoque une dégénération de santé de -2...4 et une dégénération d\'énergie de -1. Inflige 15...75 points de dégâts si l\'énergie de l\'ennemi visé tombe à 0. Prend fin si l\'énergie de l\'ennemi visé tombe à 0.'],
126=>['Transfert de vie','Pendant 6...12 secondes, la cible ennemie et les ennemis adjacents subissent une dégénération de santé de -3...8 que vous gagnez en régénération de santé.','Inglige également un maléfice aux ennemis adjacents à la cible (6...12 seconds). Provoque une dégénération de santé de -3...8. Vous bénéficiez d\'une régénération de santé de +3...8.'],
127=>['Marque de subversion','Pendant 6 secondes, la prochaine fois que l\'ennemi visé lance un sort qui vise un de ses alliés, ce sort échoue et vous lui volez jusqu\'à 10...92 points de vie.','(6 secondes.) Le sort suivant de l\'ennemi visé échoue et vous volez 10...92 points de vie. Aucun effet si le sort de l\'ennemi ne vise pas un de ses alliés.'],
128=>['Sangsue de l\'âme','Pendant 10 secondes, à chaque fois que l\'ennemi visé lance un sort, vous lui prenez jusqu\'à 16...80 points de vie.','(10 secondes.) Vole 16...80 points de vie chaque fois que l\'ennemi visé lance un sort.'],
129=>['Souillure charnelle','Pendant 5...35 secondes, l\'ennemi visé ne reçoit que deux tiers des points de vie habituellement restitués par la guérison.','(5...35 secondes.) Réduit de 33% les soins reçus par l\'ennemi visé. Seules les compétences dont la description contient le mot "soins/guérison" sont affectées.'],
130=>['Chair démoniaque','Pendant 30...60 secondes, chaque fois que vous utilisez une compétence qui vise un ennemi, vous infligez 5...20 points de dégâts de l\'ombre à tous les autres ennemis proches de vous.','(30...60 secondes.) Lorsque vous utilisez une compétence sur un ennemi, vous infligez 5...20 points de dégâts de l\'ombre à tous les autres ennemis proches de vous.'],
131=>['Sceau barbelé','Vous infligez un Saignement pendant 3...15 secondes à la cible et à tous les ennemis adjacents.','La cible et les ennemis adjacents sont frappés de Saignement pendant 3...15 secondes.'],
132=>['Sceau du fléau','Vous transférez vers l\'ennemi visé toutes les conditions négatives qui vous affectent et leur durée restante, rallongée de 100...200%. (50% de risques d\'échec avec Malédictions de niveau 4 ou inférieur.)','Transfère vers l\'ennemi visé toutes les conditions négatives qui vous affectent et leur durée restante, rallongée de 100...200%. 50% de risques d\'échec à moins de posséder Malédictions de niveau 5 ou supérieur.'],
133=>['Pacte noir','Inflige 20...60 points de dégâts des ombres à la cible ennemie.','Inflige 20...60 points de dégâts.'],
134=>['Ordre de la douleur','Pendant 5 secondes, à chaque fois qu\'un membre du groupe inflige des dégâts physiques à l\'ennemi, il inflige +3...16 points de dégâts.','Enchante tous les membres de l\'équipe (5 secondes). 3...16 points de dégâts supplémentaires chaque fois qu\'ils infligent des dégâts physiques.'],
135=>['Appréhension','Pendant 4...18 secondes, la vitesse d\'attaque de l\'ennemi est réduite de 50% et il subit une dégénération de santé de -1...3.','(4...18 secondes.) L\'ennemi visé attaque 50% moins vite et subit une dégénération de santé de -1...3.'],
136=>['Ombre de terreur','L\'ennemi et tous ceux qui lui sont adjacents attaquent 50% plus lentement que la normale pendant 5...30 secondes.','Inflige également des maléfices aux ennemis adjacents à la cible (5...30 secondes). Ils attaquent 50% moins vite.'],
137=>['Rigor Mortis','Pendant 8...20 secondes, la cible ennemie ne peut pas bloquer.','(8...20 secondes.) L\'ennemi visé ne peut pas bloquer.'],
138=>['Lien noir','Durant les prochaines 30...60 secondes, à chaque fois que vous subissez des dégâts, 75% de ces dégâts sont infligés à votre plus proche serviteur.','(30...60 secondes.) Transfère 75% des dégâts que vous subissez à votre serviteur le plus proche.'],
139=>['Transfert de condition','Pendant 15...60 secondes, à chaque fois que vous devriez recevoir une condition, elle est transférée à votre plus proche serviteur à la place.','(15...60 secondes.) Chaque fois qu\'une condition vous est infligée, elle est aussitôt transférée à votre serviteur mort-vivant le plus proche.'],
140=>['Malaise','Pendant 5...35 secondes, la cible ennemie subit une dégénération d\'énergie de -1 et vous subissez une dégénération de santé de -1. Si l\'énergie de l\'ennemi visé devient nulle, il subit 5...50 points de dégâts et Malaise prend fin.','(5...35 secondes.) Provoque une dégénération d\'énergie de -1. Inflige 5...50 points de dégâts si l\'énergie de l\'ennemi visé tombe à 0. Vous subissez une dégénération de santé de -1. Prend fin si l\'énergie de l\'ennemi visé tombe à 0.'],
141=>['Abolition des enchantements','Supprime 5...9 enchantements à la cible ennemie. Vous perdez 55...25 points de vie pour chaque enchantement de Moine supprimé.','Supprime 5...9 enchantements affectant l\'ennemi visé. Coût de la suppression : vous perdez 55...25 points de vie par enchantement de Moine supprimé.'],
142=>['Malédiction latente','Pendant 6...30 secondes, l\'ennemi visé et tous les ennemis à proximité souffrent d\'une dégénération de santé de -1...4 et reçoivent 25% de guérison en moins.','(6...30 secondes.) La cible et tous les ennemis à proximité souffrent d\'une dégénération de santé de -1...4 et reçoivent 25% de guérison en moins.'],
143=>['Suppression d\'un enchantement','Ote 0...2 enchantements à l\'ennemi visé. Si un enchantement est supprimé, vous volez 5...65 points de vie.','Ote 0...2 enchantements à la cible ennemie. Effet de la suppression : vous volez 5...65 points de vie.'],
144=>['Engelures','Vous êtes empoisonné pendant 10 secondes. Les ennemis dans la zone de votre cible subissent 10...44 points de dégâts du froid et perdent 1...2 enchantements.','Inflige 10...44 points de dégâts du froid aux ennemis dans la zone autour de votre cible et supprime 1...2 enchantements les affectant. Vous souffrez d\'Empoisonnement (10 secondes).'],
145=>['Sceau d\'agonie','Vous souffrez de Saignement pendant 25 secondes. Tous les ennemis à proximité subissent 10...70 points de dégâts.','Inflige 10...70 points de dégâts aux ennemis proches de vous. Vous souffrez de Saignement (25 secondes).'],
146=>['Offrande de sang','Vous gagnez 8...20 points d\'énergie.','Vous gagnez 8...20 points d\'énergie.'],
147=>['Fureur noire','Pendant 5 secondes, à chaque fois que l\'attaque d\'un membre du groupe réussit, il gagne une décharge d\'adrénaline. (50% de risques d\'échec avec une Magie du sang de 4 ou inférieure.)','Enchante les membres du groupe (5 secondes). Ces derniers gagnent une décharge d\'adrénaline chaque fois qu\'ils réussissent une attaque. 50% de risques d\'échouer sauf si la valeur de Magie du sang est de 5 ou plus.'],
148=>['Ordre du vampire','Pendant 5 secondes, à chaque fois qu\'un membre du groupe qui ne se trouve pas sous les effets d\'un autre enchantement de Nécromant inflige des dégâts physiques à un ennemi, il lui vole jusqu\'à 3...16 points de vie.','Enchante tous les membres du groupe (5 secondes). Ils volent 3...16 points de vie chaque fois qu\'ils infligent des dégâts physiques. Les membres du groupe sous l\'effet d\'un autre enchantement de Nécromant ne sont pas affectés.'],
149=>['Propagation du fléau','Vous transférez 1...3 conditions négatives avec leur durée restante à la cible ennemie et à tous les ennemis adjacents.','Vous transférez 1...3 conditions avec leur durée restante à la cible ennemie et à tous les ennemis adjacents.'],
150=>['Marque de douleur','Pendant 30 secondes, à chaque fois que l\'ennemi subit des dégâts physiques, la Marque de douleur inflige 10...40 points de dégâts de l\'ombre aux ennemis adjacents.','(30 secondes.) Inflige 10...40 points de dégâts aux ennemis adjacents chaque fois que l\'ennemi visé subit des dégâts physiques.'],
151=>['Festin de corruption','La cible et tous les ennemis adjacents subissent 16...80 points de dégâts de l\'ombre. Vous absorbez jusqu\'à 8...40 points de vie à chaque ennemi frappé d\'un maléfice.','Inflige 16...80 points de dégâts à la cible et aux ennemis adjacents. Vole 8...40 points de vie à chaque ennemi victime d\'un maléfice.'],
152=>['Goût de la mort','Prend jusqu\'à 100...400 points de vie à l\'allié mort-vivant animé visé.','Vole 100...400 points de vie au serviteur mort-vivant allié.'],
153=>['Regard vampirique','Vous volez jusqu\'à 18...60 points de vie à l\'ennemi visé.','Vole 18...60 points de vie.'],
154=>['Caresse contagieuse','Vous transférez 1...3 conditions négatives avec leur durée restante à la cible ennemie touchée.','Transfère 1...3 conditions dont vous souffrez à l\'ennemi visé.'],
155=>['Caresse nocive','L\'ennemi touché subit 20...65 points de dégâts.','Inflige 20...65 points de dégâts.'],
156=>['Caresse vampirique','Vous volez 29...74 points de vie à l\'ennemi touché.','Vole 29...74 points de vie.'],
157=>['Rituel de sang','Pendant 8...14 secondes, l\'allié touché bénéficie d\'une régénération d\'énergie de +3. Le Rituel de sang ne peut pas être utilisé sur le lanceur.','(8...14 secondes.) Régénération d\'énergie de +3. Vous ne pouvez pas vous prendre pour cible.'],
158=>['Caresse d\'agonie','L\'ennemi touché visé subit 20...58 points de dégâts de l\'ombre.','Inflige 20...58 points de dégâts.'],
159=>['Armure affaiblie','La cible ennemie et les ennemis adjacents souffrent de la condition Armure brisée pendant 5...20 secondes.','Affecte aussi les ennemis adjacents. Inflige la condition Armure brisée (5...20 secondes).'],
160=>['Vitesse du vent','Pendant 5...13 secondes, la cible (un allié ou vous-même) se déplace 33% plus vite.','(5...13 secondes.) L\'allié ciblé se déplace 33% plus vite.'],
162=>['Bourrasque','Renverse l\'ennemi visé pendant 2 secondes (50% de risques d\'échec avec Magie de l\'air 4 ou inférieure).','Renverse. 50% de risques d\'échec avec Magie de l\'air inférieure à 5.'],
163=>['Tornade','Tous les ennemis adjacents subissent 15...75 points de dégâts du froid. Les attaquants ennemis frappés par la Tornade sont assommés. Si vous êtes en état d\'Afflux, ce sort frappe les ennemis proches au lieu des ennemis adjacents.','Affecte les ennemis adjacents à votre position. Inflige 15...75 points de dégâts du froid. Attaque assommante contre les attaquants ennemis. En état d\'Afflux, frappe les ennemis proches au lieu des ennemis adjacents.'],
164=>['Affinité élémentaire','Pendant 25...60 secondes, vous êtes en parfaite harmonie avec l\'Air, le Feu, l\'Eau et la Terre : vous bénéficiez de +1...2 pour ces caractéristiques. Vous gagnez 1 point d\'énergie, plus 50% du coût en énergie de base nécessaire aux compétences d\'une école de magie associée à l\'un de ces éléments.','(25...60 secondes.) Vos caractéristiques élémentaires augmentent de 1...2. Vous gagnez 1 point d\'énergie, plus 50% du coût en points d\'énergie de toute compétence de Magie de l\'air, du feu, de l\'eau ou de la terre que vous utilisez.'],
165=>['Armure de la terre','Pendant 30 secondes, vous gagnez 24...60 points de bonus d\'armure, mais vous vous déplacez 50...14% moins vite.','(30 secondes.) Vous gagnez un bonus d\'armure de +24...60. Vous vous déplacez 50...14% moins vite.'],
166=>['Armure cinétique','Pendant 12 secondes, vous bénéficiez de +20...80 points d\'armure. Chaque fois que vous lancez un sort, Armure cinétique est renouvelée pour 12 secondes.','(12 secondes.) Vous bénéficiez de +20...80 points d\'armure. Bonus de renouvellement : incantation d\'un sort.'],
167=>['Eruption','Crée une éruption sur la position de l\'ennemi ciblé. Chaque seconde pendant 5 secondes, les ennemis près de cette zone subissent 10...40 points de dégâts de la terre et sont aveuglés pendant 10 secondes.','Inflige 10...40 points de dégâts de la terre par seconde (5 secondes). Frappe les ennemis à proximité de la position initiale de la cible. Provoque l\'Aveuglement (10 secondes).'],
168=>['Aura magnétique','Pendant 1...8 secondes, vous bloquez la prochaine attaque dirigée contre vous et infligez 10...50 points de dégâts à l\'ennemi attaquant. Si vous êtes en état d\'Afflux, tous les membres de votre équipe à portée de voix sont également sous l\'effet de l\'enchantement.','(1...8 secondes.) Vous bloquez la prochaine attaque dirigée contre vous et renvoyez 10...50 points de dégâts à votre attaquant. Si vous êtes en état d\'Afflux, l\'enchantement affecte les membres de votre équipe à portée de voix.'],
169=>['Affinité terrestre','Pendant 36...60 secondes, vous êtes en parfaite harmonie avec la Terre. Vous gagnez 1 point d\'énergie et 30% du coût en énergie de base pour toute compétence de Magie de la terre utilisée.','(36...60 secondes.) Quand vous utilisez une compétence de Magie de la terre, vous gagnez 1 point d\'énergie plus 30% de son coût en énergie.'],
170=>['Séisme','Vous invoquez un séisme sur la position de l\'ennemi visé. Tous les ennemis près de cette position sont renversés et subissent 26...100 points de dégâts de la terre.','Inflige 26...100 points de dégâts de la terre. Affecte également les ennemis près de la cible. Renverse.'],
171=>['Lapidation','Vous envoyez une grosse pierre qui inflige 45...105 points de dégâts de la terre si elle touche sa cible. Si l\'ennemi souffre de Faiblesse, il sera renversé.','Projectile : inflige 45...105 points de dégâts de la terre. Attaque renversante si la cible ennemie souffre de Faiblesse.'],
172=>['Dagues de pierre','Vous lancez deux dagues de pierre. Si elles touchent leur cible, elles infligent chacune 8...33 points de dégâts de la terre. Si vous êtes en état d\'Afflux, chaque projectile inflige un Saignement pendant 1...5 secondes.','Deux projectiles : chacun inflige 8...33 points de dégâts de la Terre. En état d\'Afflux, inflige un Saignement pendant 1...5 secondes,'],
173=>['Etreinte de la terre','Pendant 5...20 secondes, tous les ennemis proches se déplacent 50% moins vite.','Inflige des maléfices aux ennemis à proximité de vous (5...20 secondes). Ces ennemis se déplacent 50% moins vite.'],
174=>['Réplique sismique','Les ennemis à proximité subissent 15...85 points de dégâts de la terre. Les créatures renversées subissent 15...85 points de dégâts de la terre supplémentaires.','Inflige 15...85 points de dégâts de terre aux ennemis à proximité. inflige 15...85 points de dégâts de la terre supplémentaires aux ennemis renversés.'],
175=>['Protection contre les éléments','Vous créez une zone de protection contre les éléments sur votre position. Pendant 8...20 secondes, les alliés qui ne sont pas des esprits dans la zone de protection obtiennent +24 de bonus d\'armure contre les dégâts élémentaires.','(8...20 secondes.) Les alliés dans cette Protection ont un bonus d\'armure de +24 contre les dégâts élémentaires. Les esprits ne sont pas affectés.'],
176=>['Protection de contact','Vous créez une zone de Protection de contact sur votre position actuelle. Pendant 5...20 secondes, les alliés (sauf les esprits) dans cette zone ont 50% de chances de bloquer les attaques de mêlée.','(5...20 secondes.) Les alliés dans cette Protection ont 50% de chances de bloquer les attaques de mêlée. Les esprits alliés ne sont pas affectés.'],
177=>['Protection contre l\'ennemi','Vous créez une zone de Protection contre l\'ennemi sur votre position actuelle. Pendant 8...20 secondes, les ennemis (sauf les esprits) dans cette zone se déplacent 50% moins vite.','(8...20 secondes.) Les ennemis dans cette Protection se déplacent 50% moins vite.'],
178=>['Prodige éthéré','Vous perdez tous les enchantements. Pendant 8...20 secondes, vous bénéficiez d\'une régénération d\'énergie de +6. Quand Prodige éthéré prend fin, vous perdez 2 points de vie pour chacun de vos points d\'énergie.','(8...20 secondes.) Vous bénéficiez d\'une régénération d\'énergie de +6. Effet final : vous perdez 2 points de vie pour chaque point d\'énergie que vous avez. Vous perdez tous vos enchantements.'],
179=>['Liens incendiaires','Au bout de 3 secondes, l\'ennemi visé et tous ceux qui sont proches de lui subissent 20...80 points de dégâts du feu et s\'embrasent pendant 1...3 secondes. S\'active immédiatement si l\'ennemi meurt.','(3 secondes.) Effet final : inflige 20...80 points de dégâts du feu et inflige la Brûlure (1...3 secondes) aux ennemis à proximité de votre cible. S\'active également si l\'ennemi meurt.'],
180=>['Aura de rétablissement','Pendant 60 secondes, vous gagnez 0...1 points d\'énergie et êtes soigné de 200...500% du coût en énergie pour chaque sort que vous lancez.','(60 secondes.) Vous gagnez 0...1 points d\'énergie et êtes soigné de 200...500% du coût en énergie pour chaque sort que vous lancez.'],
181=>['Renouveau éthéré','Pendant 5...20 secondes, à chaque fois que vous lancez un sort, vous gagnez 1...4 points d\'énergie et 5...20 points de vie pour chaque enchantement qui vous affecte.','(5...20 secondes.) Chaque fois que vous lancez un sort, vous gagnez 1...4 points d\'énergie et 5...20 points de vie par enchantement vous affectant.'],
182=>['Conjuration de flamme','Pendant 60 secondes, si vous utilisez une arme de feu, vos attaques infligent 5...20 points de dégâts du feu supplémentaires.','(60 secondes.) Vos attaques infligent +5...20 points de dégâts du feu. Aucun effet si votre arme n\'inflige pas des dégâts du feu.'],
183=>['Enfer','Tous les ennemis adjacents reçoivent 30...135 points de dégâts du feu.','Inflige 30...135 points de dégâts du feu aux ennemis qui vous sont adjacents.'],
184=>['Affinité ignée','Pendant 36...60 secondes, vous êtes en parfaite harmonie avec le Feu. Vous gagnez 1 point d\'énergie et 30% du coût en énergie de base pour toute compétence de Magie du feu utilisée.','(36...60 secondes.) Quand vous utilisez une compétence de Magie du feu, vous gagnez 1 point d\'énergie plus 30% de son coût en énergie.'],
185=>['Flamme spirituelle','La cible et les ennemis adjacents subissent 15...60 points de dégâts du feu. Si vous avez plus d\'énergie que l\'ennemi visé, celui-ci et tous les ennemis adjacents subissent 15...60 points de dégâts du feu en plus et s\'embrasent pendant 1...10 secondes.','Inflige 15...60 points de dégâts de feu. Si vous avez plus d\'énergie que l\'ennemi visé, inflige 15...60 points de dégâts du feu en plus et applique Brûlure (1...10 secondes). Affecte aussi les ennemis adjacents.'],
186=>['Boule de feu','Vous lancez une boule de feu qui frappe l\'ennemi ciblé et tous les ennemis à proximité pour leur infliger 7...112 points de dégâts de feu.','Projectile : inflige 7...112 points de dégâts de feu à la cible et aux ennemis à proximité.'],
187=>['Météore','La cible ennemie et tous les ennemis adjacents sont renversés et subissent 7...112 points de dégâts du feu.','Inflige 7...112 points de dégâts du feu et renverse. Affecte également les ennemis près de la cible.'],
188=>['Projection de flammes','Tous les ennemis proches reçoivent 15...120 points de dégâts du feu.','Inflige 15...120 points de dégâts du feu à tous les ennemis proches de vous.'],
189=>['Invocation de Rodgort','L\'ennemi visé et tous les ennemis à proximité subissent 15...120 points de dégâts du feu et s\'embrasent pendant 1...3 secondes.','Inflige 15...120 points de dégâts de feu. Affecte également les ennemis près de la cible. Provoque une Brûlure (1...3 secondes).'],
190=>['Marque de Rodgort','La cible ennemie et tous les ennemis proches subissent les effets du maléfice Marque de Rodgort. Pendant 10...35 secondes, à chaque fois qu\'un ennemi subit des dégâts du feu, il s\'embrase pendant 1...4 secondes.','Inflige également des maléfices aux ennemis proches de votre cible (10...35 secondes). Inflige la Brûlure (1...4 secondes) quand ces ennemis subissent des dégâts du feu.'],
191=>['Immolation','L\'ennemi visé subit 20...75 points de dégâts du feu et s\'embrase pendant 1...3 secondes.','Inflige 20...75 points de dégâts de feu. Provoque une Brûlure (1...3 secondes).'],
192=>['Pluie de météores','Crée une Pluie de météores sur la position de l\'ennemi. Pendant 9 secondes, les ennemis adjacents à cette position subissent 7...112 points de dégâts du feu et sont renversés toutes les 3 secondes.','Inflige 7...112 points de dégâts du feu et renverse toutes les 3 secondes (9 secondes). Frappe les ennemis adjacents à la position initiale de la cible.'],
193=>['Phénix','Un Phénix flamboyant apparaît près de vous, avant de s\'envoler vers votre cible pour exploser à l\'impact. Cette explosion inflige 10...60 points de dégâts du feu à votre cible et aux ennemis à proximité. Si vous êtes en état d\'Afflux, les alliés dans le rayon d\'action sont soignées de 20...80 points de vie.','Projectile : inflige 10...60 points de dégâts du feu à la cible et aux ennemis à proximité. Les alliés sont soignés de 20...80 points de vie si vous êtes en état d\'Afflux.'],
194=>['Eclat de feu','Vous envoyez une flamme vers l\'ennemi qui inflige 20...65 points de dégâts du feu si elle touche sa cible. Si vous êtes en état d\'Afflux, Eclat de feu affecte aussi les ennemis adjacents.','Projectile : inflige 20...65 points de dégâts du feu. En état d\'Afflux, affecte les ennemis adjacents.'],
195=>['Fontaine de lave','Pendant 5 secondes, les ennemis adjacents à la position où le sort a été lancé subissent 5...50 points de dégâts du feu chaque seconde. Si vous êtes en état d\'Afflux, le sort frappe les ennemis à proximité au lieu des ennemis adjacents.','Inflige 5...50 points de dégâts du feu par seconde (5 secondes). Affecte les ennemis adjacents à votre position initiale. En état d\'Afflux, le rayon d\'action est étendu aux ennemis à proximité.'],
196=>['Chaleur de fournaise','Déclenche une Chaleur de fournaise sur la position de l\'ennemi. Pendant 5 secondes, les ennemis à proximité de cette position subissent 10...40 points de dégâts du feu par seconde. Lorsque la Chaleur de fournaise cesse, les ennemis dans sa zone d\'effet sont embrasés pendant 3 secondes.','Inflige 10...40 points de dégâts du feu par seconde (5 secondes). Frappe les ennemis à proximité de la position initiale de la cible. Effet final : inflige Brûlure (3 secondes).'],
197=>['Tempête de feu','Crée une Tempête de feu sur la position de l\'ennemi. Pendant 10 secondes, les ennemis adjacents à cette position subissent 5...35 points de dégâts du feu par seconde.','Inflige 5...35 points de dégâts du feu par seconde (10 secondes). Frappe les ennemis adjacents à la position initiale de la cible.'],
198=>['Glyphe de pouvoir élémentaire','Pendant 25 secondes, la valeur de vos caractéristiques liées aux éléments augmente de 2 pour 10 prochains sorts.','(25 secondes.) Augmente la valeur de vos caractéristiques liées aux éléments de +2 pour vos 10 sorts suivants.'],
199=>['Glyphe d\'énergie','1...3 des prochains sorts ne causent pas l\'Afflux et coûtent 10...25 points d\'énergie en moins. Vos caractéristiques élémentaires augmentent de 1...2.','1...3 des prochains sorts ne causent pas l\'Afflux et coûtent 10...25 points d\'énergie en moins. Vos caractéristiques élémentaires augmentent de 1...2.'],
200=>['Glyphe d\'énergie mineure','Pendant les 15 prochaines secondes, 2 des prochains sorts coûtent 10...18 points d\'énergie en moins.','(15 secondes.) 2 des prochains sorts coûtent 10...18 points d\'énergie en moins.'],
201=>['Glyphe de concentration','Pendant 15 secondes, il est impossible d\'interrompre 1 de vos sorts, et la condition de Stupeur n\'a aucun effet sur eux.','(15 secondes.) Il est impossible d\'interrompre 1 de vos sorts et la condition Stupeur n\'a aucun effet sur eux.'],
202=>['Glyphe de sacrifice','Pendant 15 secondes, le prochain sort est lancé sans incantation préalable, mais il mettra 30 secondes en plus à se recharger. Prend fin prématurément si vous utilisez une compétence autre qu\'un sort.','(15 secondes.) Votre prochain sort se lance instantanément mais met 30 secondes supplémentaires à se recharger. Prend fin si vous utilisez une compétence autre qu\'un sort.'],
203=>['Glyphe du renouveau','Pendant 15 secondes, votre prochain sort se rechargera instantanément.','(15 secondes.) Votre sort suivant se recharge instantanément.'],
204=>['Rouille','Inflige 10...85 points de dégâts du froid à la cible et aux ennemis adjacents. Pendant 5...20 secondes, l\'ennemi visé et tous les ennemis adjacents mettent deux fois plus de temps pour activer les sceaux. Si vous êtes en état d\'Afflux, les sceaux des ennemis touchés sont interrompus et désactivés pendant 1...10 secondes.','Inflige 10...85 points de dégâts du froid à la cible et aux ennemis adjacents. Inflige des maléfices à la cible et aux ennemis adjacents (5...20 secondes). Double le temps d\'activation des sceaux. Interrompt et désactive les sceaux pendant 1...10 secondes si vous êtes en état d\'Afflux.'],
205=>['Décharge foudroyante','Après 3 secondes, la cible ennemie est renversée, subit 14...100 points de dégâts de la foudre et a une Armure brisée pendant 5...20 secondes. Ce sort dispose de 25% de pénétration d\'armure.','(3 secondes.) Effet final : inflige 14...100 points de dégâts de la foudre, renverse et applique la condition Armure brisée (5...20 secondes). 25% de pénétration d\'armure.'],
206=>['Armure de givre','Pendant 10...34 secondes, vous bénéficiez de +40 en armure contre les dégâts physiques et de +1 en Magie de l\'eau.','(10...34 secondes.) Vous gagnez +40 en armure contre les dégâts physiques et +1 en Magie de l\'eau.'],
207=>['Conjuration du froid','Pendant 60 secondes, si vous utilisez une arme du froid, vos attaques infligent 5...20 points de dégâts du froid supplémentaires.','(60 secondes.) Vos attaques infligent +5...20 points de dégâts du froid. Aucun effet si votre arme n\'inflige pas des dégâts du froid.'],
208=>['Affinité aquatique','Pendant 36...60 secondes, vous êtes en parfaite harmonie avec l\'Eau. Vous gagnez 1 point d\'énergie et 30% du coût en énergie de base pour toute compétence de Magie de l\'eau utilisée.','(36...60 secondes.) Quand vous utilisez une compétence de Magie de l\'eau, vous gagnez 1 point d\'énergie plus 30% de son coût en énergie.'],
209=>['Gel spirituel','L\'ennemi visé subit 10...60 points de dégâts du froid. Si vous avez plus d\'énergie que l\'ennemi visé, il subit 10...60 points de dégâts du froid en plus et se déplace 90% plus lentement pendant 1...5 secondes.','Inflige 10...60 points de dégâts du froid. Si vous avez plus d\'énergie que l\'ennemi visé, il subit 10...60 points de dégâts du froid en plus et se déplace 90% plus lentement (1...5 secondes).'],
210=>['Prison de glace','Pendant 8...20 secondes, les jambes de l\'ennemi sont prises dans la glace et ses mouvements sont ralentis de 66%.','(8...20 secondes.) La cible ennemie se déplace 66% moins vite.'],
211=>['Tessons de glace','L\'ennemi visé et ceux qui sont adjacents subissent 20...80 points de dégâts du froid et sont ralentis de 66% pendant 2...6 secondes.','Inflige également des maléfices aux ennemis adjacents à la cible (2...6 secondes). Ces ennemis se déplacent 66% moins vite. Effet initial : inflige 20...80 points de dégâts du froid.'],
212=>['Explosion glaciale','Tous les ennemis proches subissent 10...85 points de dégâts du froid et sont ralentis de 66% pendant 3...8 secondes.','Inflige des maléfices aux ennemis à proximité de vous. Ces ennemis se déplacent 66% moins vite (3...8 secondes). Effet initial : inflige 10...85 points de dégâts du froid aux ennemis à proximité.'],
213=>['Tempête de glace','Vous envoyez un pic de glace qui inflige 10...85 points de dégâts du froid s\'il touche sa cible. L\'ennemi se déplacera alors 66% moins vite pendant 2...6 secondes.','Projectile : inflige 10...85 points de dégâts du froid. La cible ennemie se déplace 66% moins vite (2...6 secondes).'],
214=>['Lance de glace','Vous envoyez une Lance de glace qui inflige 10...60 points de dégâts du froid si elle touche sa cible. Si vous êtes en état d\'Afflux, vous bénéficiez d\'une régénération de santé de +1...4 pendant 5 secondes.','Projectile : inflige 10...60 points de dégâts du froid. Vous bénéficiez d\'une régénération de santé de +1...4 pendant 5 secondes si vous êtes en état d\'Afflux.'],
215=>['Maelström','Crée un Maelström à l\'endroit où se trouve l\'ennemi ciblé. Pendant 10 secondes, les ennemis adjacents à la zone subissent 10...25 points de dégâts du froid par seconde. Le Maelström interrompt le lancement des sorts s\'il touche sa cible.','Inflige 10...25 points de dégâts du froid et interrompt les sorts toutes les secondes (10 secondes). Frappe les ennemis adjacents à la position initiale de la cible.'],
216=>['Brume de fer','Pendant 8...15 secondes, vous bénéficiez d\'un bonus d\'armure de +15. Vos sorts magiques d\'air qui ciblent un ennemi s\'activent et se rechargent 33% plus vite, mais vous subissez un Afflux de 2 points.','(8...15 secondes.) Gagnez +15 d\'armure. Vos sorts magiques d\'air qui ciblent un ennemi s\'activent et se rechargent 33% plus vite, mais vous subissez un Afflux de 2 points.'],
217=>['Vague de cristal','Les ennemis qui vous sont adjacents subissent 10...70 points de dégâts, mais sont libérés de toute condition négative. Chaque condition supprimée inflige 5...15 points de dégâts.','Inflige 10...70 points de dégâts à tous les ennemis qui vous sont adjacents. Les ennemis perdent toutes leurs conditions et subissent 5...15 points de dégâts pour chaque condition supprimée.'],
218=>['Chair d\'obsidienne','Pendant 8...20 secondes, vous bénéficiez de +20 de bonus d\'armure et vous ne pouvez pas être la cible de sorts ennemis, mais vous ne pouvez pas attaquer et vous subissez une dégénération d\'énergie de -2.','(8...20 secondes.) Vous bénéficiez de +20 de bonus d\'armure et vous ne pouvez pas être la cible de sorts ennemis. Vous ne pouvez pas attaquer et vous subissez une dégénération d\'énergie de -2.'],
219=>['Flamme d\'obsidienne','Inflige 22...112 points de dégâts à la cible ennemie. Ce sort ignore l\'armure.','Inflige 22...112 points de dégâts.'],
220=>['Eblouissement','L\'ennemi est aveuglé pendant 3...8 secondes.','Provoque l\'Aveuglement (3...8 secondes).'],
221=>['Conjuration de la foudre','Pendant 60 secondes, si vous utilisez une arme de la foudre, vos attaques infligent 5...20 points de dégâts de la foudre supplémentaires.','(60 secondes.) Vos attaques infligent +5...20 points de dégâts de la foudre. Aucun effet si votre arme n\'inflige pas des dégâts de la foudre.'],
222=>['Eclair foudroyant','Inflige 10...60 points de dégâts de la foudre à l\'ennemi visé. Ce sort a 25% de pénétration d\'armure. Si vous êtes en état d\'Afflux, la cible ennemie est affectée par un maléfice pendant 3 secondes. Lorsque ce maléfice prend fin, cet ennemi subit à nouveau 20...40 points de dégâts de la foudre.','Inflige 10...60 points de dégâts de la foudre. 25% de pénétration d\'armure. Inflige un maléfice pendant 3 secondes en état d\'Afflux. Effet final : inflige 20...40 points de dégâts de la foudre.'],
223=>['Chaîne d\'éclairs','L\'ennemi visé et jusqu\'à deux autres ennemis proches de lui subissent 10...85 points de dégâts de la foudre. Ce sort a une pénétration d\'armure de 25%.','Inflige 10...85 points de dégâts de la foudre. Frappe également deux ennemis près de la cible. 25% de pénétration d\'armure.'],
224=>['Décharge incapacitante','L\'ennemi ciblé subit 25...50 points de dégâts de la foudre et souffre de Faiblesse pendant 5...20 secondes. Ce sort offre 25% de pénétration d\'armure.','Inflige 25...50 points de dégâts de la foudre. Inflige la Faiblesse (5...20 secondes). 25% de pénétration d\'armure.'],
225=>['Affinité aérienne','Pendant 36...60 secondes, vous êtes en parfaite harmonie avec l\'Air. Vous gagnez 1 point d\'énergie et 30% du coût en énergie de base pour toute compétence de Magie de l\'air utilisée.','(36...60 secondes.) Quand vous utilisez une compétence de Magie de l\'air, vous gagnez 1 point d\'énergie plus 30% de son coût en énergie.'],
226=>['Choc spirituel','La cible ennemie subit 10...50 points de dégâts de la foudre. Si vous avez plus d\'énergie qu\'elle, elle subit 10...50 points de dégâts de la foudre supplémentaires et est renversée. Ce sort a une pénétration d\'armure de 25%.','Inflige 10...50 points de dégâts de la foudre. Si vous avez plus d\'énergie que la cible, elle subit +10...50 points de dégâts de la foudre et est renversée. 25% de pénétration d\'armure.'],
227=>['Marque éblouissante','Pendant 10 secondes, la cible et tous les ennemis adjacents à subissent 5...25 points de dégâts par seconde. Les ennemis utilisant des compétences offensives sont aveuglés pendant 3 secondes. Ce maléfice prend fin si vous utilisez une compétence qui vise cet ennemi.','(10 secondes.) Inflige 5...25 points de dégâts par seconde à la cible et aux ennemis adjacents. Aveugle les ennemis utilisant des compétences d\'attaque. Prend fin si vous utilisez une compétence qui vise cet ennemi.'],
228=>['Coup de tonnerre','Vous générez une onde de choc massive à l\'emplacement de l\'ennemi ciblé. Inflige 10...50 points de dégâts d\'éclair à la cible et à tous les ennemis à proximité. Les ennemis touchés sont interrompus et souffrent d\'Armure fissurée et de Faiblesse pendant 5...20 secondes. Ce sort bénéficie de 25% de pénétration d\'armure.','Inflige 10...50 points de dégâts d\'éclair. Affecte également les ennemis à proximité. Inflige les altérations Armure fissurée et Faiblesse (5...20 secondes). Provoque une interruption. 25% de pénétration d\'armure.'],
229=>['Globe de foudre','Vous envoyez un Globe de foudre qui inflige 10...100 points de dégâts de la foudre à la cible. Ce sort a 25% de pénétration d\'armure.','Projectile : inflige 10...100 points de dégâts de la foudre. 25% de pénétration d\'armure.'],
230=>['Javelot de foudre','Vous envoyez un Javelot de foudre qui inflige 15...50 points de dégâts de la foudre s\'il touche sa cible. Le Javelot de foudre interrompt les attaquants ennemis. Ce sort offre 25% de pénétration d\'armure et frappe tous les ennemis situés entre vous et la cible.','Projectile : inflige 15...50 points de dégâts de la foudre. Est interrompu si l\'ennemi visé attaque. 25% de pénétration d\'armure. Frappe tous les ennemis entre vous et la cible.'],
231=>['Décharge électrique','L\'ennemi touché est renversé et subit 10...60 points de dégâts de la foudre. Cette compétence offre 25% de pénétration d\'armure.','Inflige 10...60 points de dégâts de la foudre. Renverse. 25% de pénétration d\'armure.'],
232=>['Caresse foudroyante','L\'ennemi visé qui est touché et tous les ennemis adjacents subissent 10...60 points de dégâts de la foudre, sont aveuglés pendant 1...4 secondes et souffrent d\'Armure brisée pendant 1...10 secondes. Cette compétence a 25% de pénétration d\'armure.','Inflige 10...60 points de dégâts de la foudre. Affecte également les ennemis près de la cible. Inflige Aveuglement (1...4 secondes) et Armure brisée (1...10 secondes) à tous les ennemis touchés. 25% de pénétration d\'armure.'],
233=>['Aura tourbillon','Pendant 3...7 secondes, vous bénéficiez d\'une régénération de santé de +1...6 et de 50% de chances de bloquer les attaques. Si vous êtes en état d\'Afflux, tous les membres de votre équipe à portée de voix sont également sous l\'effet de l\'enchantement.','(3...7 secondes.) Confère une régénération de santé de +1...6 et 50% de chances de bloquer les projectiles. En état d\'Afflux, enchante également les membres de votre équipe à portée de voix.'],
234=>['Congélation','La zone où se trouve l\'ennemi est congelée. Tous les ennemis à cet endroit subissent 10...85 points de dégâts du froid. Pendant 10 secondes, ils se déplacent 66% moins vite.','Inflige également des maléfices aux ennemis se trouvant dans la zone de votre cible (10 secondes). Ces ennemis se déplacent 66% moins vite. Effet initial : inflige 10...85 points de dégâts du froid.'],
235=>['Vision troublée','Pendant 4...10 secondes, la vision de l\'ennemi visé et de ceux qui sont adjacents est troublée. Ils ont alors 50% de risques de manquer leurs attaques.','Inflige également des maléfices aux ennemis adjacents à la cible (4...10 secondes). Ils ont 50% de risques de manquer leurs attaques.'],
236=>['Forme de brume','Pendant 10...45 secondes, vous subissez 33% de dégâts en moins face aux ennemis sous l\'effet d\'un maléfice de la Magie de l\'eau. Quand vous lancez un sort élémentaire, tous les alliés (autres qu\'esprits) à portée de voix regagnent 50...250% du coût énergétique du sort.','(10...45 secondes.) 33% de dégâts en moins face aux ennemis sous l\'effet d\'un maléfice de la Magie de l\'eau. Les alliés (autres qu\'esprits) à portée de voix regagnent 50...250% du coût énergétique de vos sorts élémentaires.'],
237=>['Trident marin','Vous lancez un Trident marin qui se déplace très rapidement vers l\'ennemi. S\'il fait mouche, il inflige 10...90 points de dégâts du froid à sa cible et jusqu\'à 2 ennemis adjacents. S\'il touche un ennemi en mouvement, celui-ci est renversé.','Projectile rapide : inflige 10...90 points de dégâts du froid et renverse les ennemis en mouvement. Tire 2 projectiles supplémentaires sur les ennemis adjacents.'],
238=>['Armure de brume','Pendant 8...20 secondes, vous bénéficiez de +10...40 de bonus d\'armure et vous vous déplacez 33% plus vite.','(8...20 secondes.) Vous gagnez +10...40 en armure et vous déplacez 33% plus vite.'],
239=>['Protection contre le mal','Crée une protection contre le mal à cette position. Pendant 5...15 secondes, les alliés (autres qu\'esprits) dans cette zone bénéficient de +1...3 en régénération de santé, +12...24 en armure et encore +12...24 en armure contre les dégâts élémentaires. Ce sort est désactivé pendant 20 secondes.','(5...15 secondes.) Les alliés bénéficiant de cette protection gagnent +1...3 en régénération de santé, +12...24 en armure et encore +12...24 en armure contre les dégâts élémentaires. Les esprits ne sont pas affectés. Cette compétence est désactivée pendant 20 secondes.'],
240=>['Châtiment','Cette attaque inflige 10...55 points de dégâts sacrés. Si elle attaque, votre cible subit 10...35 points de dégâts sacrés en plus.','Inflige 10...55 points de dégâts sacrés. Inflige 10...35 points de dégâts sacrés supplémentaires si la cible attaque.'],
241=>['Lien de vie','Tant que cet enchantement est actif, quand l\'allié visé subit des dégâts des suites d\'une attaque, la moitié de ces dégâts vous sont infligés. Les dégâts que vous subissez de cette manière sont réduits de 3...30 points.','Vous subissez à la place de l\'allié visé la moitié des dégâts qui lui sont infligés. Les dégâts redirigés vers vous sont réduits de 3...30 points. Vous ne pouvez pas vous prendre pour cible.'],
242=>['Esprit de Balthazar','Tant que cet enchantement est actif, la cible (un allié ou vous-même) gagne de l\'adrénaline et de l\'énergie après avoir subi des dégâts. (La quantité d\'adrénaline dépendra de la valeur de vos Prières de Châtiment.)','L\'allié visé gagne de l\'adrénaline et 1 point d\'énergie quand il subit des dégâts.'],
243=>['Force de l\'honneur','Tant que cet enchantement est actif, la cible (un allié ou vous-même) inflige 5...25 points de dégâts supplémentaires au corps à corps.','L\'allié visé inflige 5...25 points de dégâts supplémentaires au corps à corps.'],
244=>['Affinité vitale','Tant que cet enchantement est actif, la cible (un allié ou vous-même) inflige 30% de dégâts en moins avec ses attaques, mais récupère 14...50% de santé supplémentaire lorsqu\'elle est soignée.','La cible alliée récupère 14...50% de santé en plus lorsqu\'elle est guérie. Cet allié inflige 30% de dégâts en moins avec ses attaques.'],
245=>['Esprit protecteur','Pendant 5...23 secondes, la cible (un allié ou vous-même) ne peut pas perdre plus de 10% de santé maximum dus à des dégâts provoqués par une attaque unique ou par un sort.','(5...23 secondes.) Les dégâts subis sont réduits à 10% de la santé maximum de l\'allié visé.'],
246=>['Intervention divine','Pendant 10 secondes, la prochaine fois que la cible (un allié ou vous-même) subit des dégâts qui devraient être fatals, ces dégâts sont annulés et la cible est soignée de 26...240 points de vie.','(10 secondes.) Les prochains dégâts mortels subis par l\'allié visé seront annulés. Effet de l\'annulation : soigne de 26...240 points de vie.'],
247=>['Symbole de Courroux','Crée un Symbole du courroux à l\'emplacement de l\'ennemi ciblé. Pendant 5 secondes, les ennemis adjacents sont frappés chaque seconde et subissent 10...40 points de dégâts sacrés.','Inflige 10...40 points de dégâts sacrés chaque seconde (5 secondes). Affecte les ennemis adjacents à l\'emplacement initial de l\'ennemi ciblé.'],
248=>['Punition','Tant que cet enchantement est actif, à chaque fois que la cible (un allié ou vous-même) subit des dégâts issus d\'attaques, ce sort renvoie 33% des dégâts à l\'attaquant. (Maximum de 5...20 points de dégâts).','Inflige 33% des dégâts de chaque attaque (maximum : 5...20) à l\'assaillant.'],
249=>['Colère divine','Pendant 10...30 secondes, les 1...10 prochaines fois que la cible alliée subit des dégâts suite à une attaque, ce sort renvoie 66% des dégâts à l\'attaquant (maximum de 5...50 points de dégâts).','(10...30 secondes.) Renvoie 66% des dégâts de chaque attaque (maximum 5...50) à l\'attaquant. Prend fin après avoir infligé 1...10 fois des dégâts. Auto-ciblage impossible.'],
250=>['Liens de l\'Essence','Tant que cet enchantement est actif, si la cible (un allié ou vous-même) subit des dégâts physiques ou élémentaires, vous gagnez 1 point d\'énergie.','Vous gagnez 1 point d\'énergie chaque fois que l\'allié visé subit des dégâts physiques ou élémentaires.'],
251=>['Guérison néfaste','Pendant 30 secondes, à chaque fois que l\'ennemi visé est soigné, la créature qui le soigne subit 15...80 points de dégâts sacrés.','(30 secondes.) Chaque fois que l\'ennemi visé est soigné, le soigneur subit 15...80 points de dégâts sacrés.'],
252=>['Bannissement','La cible ennemie subit 20...65 points de dégâts sacrés. Ce sort inflige le double de dégâts aux créatures invoquées.','Inflige 20...65 points de dégâts sacrés. Inflige deux fois plus de dégâts aux créatures invoquées.'],
253=>['Sacrifice néfaste','Pendant 8...20 secondes, à chaque fois que l\'ennemi visé et les ennemis adjacents sacrifient des points de vie, ils en perdent deux fois plus que la normale.','Inflige également des maléfices aux ennemis adjacents à la cible (8...20 secondes). Double le sacrifice de santé.'],
254=>['Esprit vigoureux','Pendant 30 secondes, à chaque fois que la cible (un allié ou vous-même) attaque ou lance un sort, elle est soignée de 5...20 points de vie.','(30 secondes.) Soigne de 5...20 points de vie chaque fois que l\'allié visé attaque ou lance un sort.'],
255=>['Esprit vigilant','Tant que cet enchantement est actif, la cible (un allié ou vous-même) reçoit une régénération de santé de +2, elle est soignée de 30...180 points de vie lorsque les effets de l\'esprit vigilant s\'estompent.','Confère une régénération de santé de +2. Effet final : soigne de 30...180 points de vie.'],
256=>['Aura sacrée','Tant que cet enchantement est actif, les enchantements de Moine que vous lancez durent 10...35% plus longtemps.','Les enchantements de Moine que vous lancez durent 10...35% plus longtemps.'],
257=>['Egide','Pendant 6...15 secondes, tous les membres de l\'équipe à portée de voix ont 50% de probabilités de bloquer les attaques.','Enchante tous les membres de l\'équipe à portée de voix (6...15 secondes). 50% de chances de bloquer.'],
258=>['Gardien','Pendant 2...7 secondes, la cible (un allié ou vous-même) a 50% de chances de bloquer les attaques.','(2...7 secondes.) 50% de chances de bloquer.'],
259=>['Bouclier de détournement','Pendant 3...10 secondes, la cible (un allié ou vous-même) a 75% de chances de bloquer les attaques et bénéficie d\'un bonus d\'armure de 15...30.','(3...10 secondes.) 75% de chances de bloquer. Bonus d\'armure de +15...30.'],
260=>['Aura de foi','Pendant 3 secondes, la cible (un allié ou vous-même) gagne 50...100% de santé supplémentaire lorsqu\'elle est soignée et subit 5...50% de dégâts en moins.','(3 secondes.) La cible (un allié ou vous-même) gagne 50...100% de santé supplémentaire lorsqu\'elle est soignée et subit 5...50% de dégâts en moins.'],
261=>['Bouclier de régénération','Pendant 5...13 secondes, l\'allié ciblé gagne +3...10 points de régénération de santé et 20...45 points d\'armure.','(5...13 secondes.) +3...10 points de régénération de santé et +20...45 points d\'armure.'],
262=>['Bouclier du jugement','Pendant 8...20 secondes, toutes les créatures qui attaquent la cible (un allié ou vous-même) sont assommées et subissent 5...50 points de dégâts sacrés.','(8...20 secondes.) Inflige 5...50 points de dégâts sacrés aux ennemis qui attaquent la cible alliée. Attaque assommante.'],
263=>['Lien de protection','Tant que cet enchantement est actif, la cible (un allié ou vous-même) ne peut pas subir plus de 5% de dégâts en une seule attaque ou un seul sort. Si le Lien de protection absorbe des dégâts, soit vous perdez 6...3 points d\'énergie, soit le sort prend fin.','La cible alliée ne peut par perdre plus de 5% de santé maximum en une seule attaque ou sort.Chaque fois que les dégâts sont réduits, vous perdez 6...3 points d\'énergie ou ce sort prend fin.'],
264=>['Pacifisme','Pendant 4...8 secondes, l\'ennemi visé ne peut pas attaquer. L\'effet cesse si la cible subit des dégâts.','(4...8 secondes.) L\'ennemi visé ne peut pas attaquer. Prend fin si cette cible subit des dégâts.'],
265=>['Amitié','Pendant 4...12 secondes, les ennemis adjacents ne peuvent pas attaquer. L\'effet prend fin lorsque l\'ennemi subit des dégâts.','(4...12 secondes.) Les ennemis adjacents à vous ne peuvent pas attaquer. Prend fin si un ennemi subit des dégâts.'],
266=>['Paix et harmonie','La cible alliée perd 0...9 conditions et maléfices. Pendant 1...3 secondes, les conditions et maléfices expirent 90% plus vite sur cet allié. Toutes vos Prières de châtiment sont désactivées pendant 20 secondes.','La cible alliée perd 0...9 conditions et maléfices. Les conditions et maléfices expirent 90% plus vite sur cet allié (1...3 secondes). Désactives vos Prières de châtiment (20 secondes).'],
267=>['Clairvoyance du juge','Pendant 8...20 secondes, les attaques de la cible (un allié ou vous-même) infligent des dégâts sacrés et bénéficient d\'un bonus de +20% de pénétration d\'armure.','(8...20 secondes.) Convertit les dégâts des attaques de l\'allié visé en dégâts sacrés et ajoute une pénétration d\'armure de +20%.'],
268=>['Aura inflexible','Pendant que cet enchantement est actif, vos sorts de Moine rétablissent +15...60% de santé en plus. Lorsqu\'il prend fin, un membre du groupe mort aléatoire est ressuscité avec la totalité de sa santé et de son énergie et est téléporté jusqu\'à votre position.','Vos sorts de Moine rétablissent +15...60% de santé en plus. Effet final : un membre du groupe aléatoire est ressuscité avec la totalité de sa santé et de son énergie et est téléporté jusqu\'à votre position.'],
269=>['Marque de protection','Pendant 10 secondes, à chaque fois que la cible (un allié ou vous-même) subit des dégâts, ils sont transformés en soins (maximum 6...60). L\'effet de toutes les prières de protection est annulé pendant 5 secondes.','(10 secondes.) Convertit les dégâts subis en soins (maximum : 6...60 points de vie). L\'effet de toutes les prières de protection est annulé (5 secondes.).'],
270=>['Barrière vitale','Tant que cet enchantement est actif, les dégâts infligés à l\'allié visé sont réduits de 20...50%. Si vous avez moins de 50% de santé quand l\'allié subit les dégâts, la Barrière vitale se dissipe.','Réduit les dégâts de 20...50%. Vous ne pouvez pas vous prendre pour cible. Si vous avez moins de 50% de santé quand la cible subit des dégâts, la Barrière vitale se dissipe.'],
271=>['Feu du zélote','Pendant 60 secondes, à chaque fois que vous utilisez une compétence sur la cible (un allié ou vous-même), tous les ennemis adjacents à la cible subissent 5...35 points de dégâts du feu et vous perdez 1 points d\'énergie.','(60 secondes.) Chaque fois que vous utilisez une compétence sur un allié, tous les ennemis adjacents à lui subissent 5...35 points de dégâts du feu. Coût des dégâts : vous perdez 1 points d\'énergie.'],
272=>['Aura de Balthazar','Pendant 8 secondes, les ennemis adjacents à la cible (un allié ou vous-même) subissent 10...30 points de dégâts sacrés par seconde.','(8 secondes.) Inflige 10...30 points de dégâts sacrés par seconde aux ennemis adjacents à l\'allié visé.'],
273=>['Briseur de sorts','Pendant 5...17 secondes, la cible alliée ne peut pas être la cible de sorts ennemis.','(5...17 secondes.) La cible alliée ne peut pas être la cible de sorts ennemis.'],
274=>['Graine de guérison','Pendant 10 secondes, si l\'allié visé subit des dégâts, celui-ci et tous les alliés adjacents gagnent 3...30 points de vie.','(10 secondes.) La cible et les alliés adjacents obtiennent 3...30 points de vie chaque fois que cet allié subit des dégâts. Vous ne pouvez pas vous prendre pour cible.'],
275=>['Rétablissement partiel','Supprime une condition (Poison, Maladie, Aveuglement, Stupeur, Saignement, Infirmité, Brûlure, Faiblesse, Armure brisée ou Blessure profonde) chez la cible alliée. Si une condition est supprimée, cet allié est soigné de 5...70 points de vie.','Supprime une condition. Effet de la suppression : soigne de 5...70 points de vie. Vous ne pouvez pas vous prendre pour cible.'],
276=>['Rétablissement total','Supprime toutes les conditions (Poison, Maladie, Aveuglement, Stupeur, Saignement, Infirmité, Brûlure, Armure brisée, Faiblesse et Blessure profonde) affectant l\'allié visé. Pour chaque condition supprimée, cet allié est soigné de 10...70 points de vie.','Supprime toutes les conditions. Effet de la suppression : soigne de 10...70 points de vie par condition supprimée. Vous ne pouvez pas vous prendre pour cible.'],
277=>['Guérison des affections','Supprime une condition (Poison, Maladie, Aveuglement, Stupeur, Saignement, Infirmité, Brûlure, Faiblesse, Armure brisée ou Blessure profonde) affectant la cible (un allié ou vous-même). Pour chaque condition restante, cette cible est soignée de 5...70 points de vie.','Supprime une condition. Effet de la suppression : soigne de 5...70 points de vie par condition restante.'],
278=>['Purification des conditions','Supprime toutes les conditions (Poison, Maladie, Aveuglement, Stupeur, Saignement, Infirmité, Brûlure, Faiblesse, Armure brisée et Blessure profonde) chez la cible alliée.','Supprime toutes les conditions.'],
279=>['Guérison divine','Soigne le lanceur et les membres du groupe à portée de voix de 15...60 points.','Les membres du groupe à portée de voix et vous êtes soignés de 15...60 points de vie.'],
280=>['Zone de guérison','Soigne le lanceur et toutes les créatures adjacentes de 30...180 points de vie.','Vous êtes soigné ainsi que les alliés et ennemis adjacents de 30...180 points de vie.'],
281=>['Prière de guérison','Soigne la cible (un allié ou vous-même) de 30...80 points de vie.','Soigne de 30...80 points de vie.'],
282=>['Parole de guérison','La cible (un allié ou vous-même) est soignée de 5...100 points de vie. Si elle a moins de 50% de santé, elle récupère 30...115 points de vie supplémentaires.','Soigne de 5...100 points de vie. Soigne de 30...115 points de vie en plus si l\'allié visé a moins de 50% de santé.'],
283=>['Baiser de Dwayna','Soigne l\'allié visé de 20...65 points de vie, et de 15...40 points supplémentaires pour chaque enchantement ou maléfice qui l\'affecte.','Soigne de 20...65 points de vie. Soigne de 15...40 points de vie supplémentaires pour chaque enchantement et maléfice affectant l\'allié visé. Vous ne pouvez pas vous prendre pour cible.'],
284=>['Bienfait divin','Tant que cet enchantement est actif, à chaque fois que vous lancez un sort de Prière de protection ou de Faveur divine qui vise un allié, celui-ci est soigné de 15...60 points de vie et vous perdez 1 points d\'énergie.','Chaque fois que vous lancez un sort de Prière de protection ou de Faveur divine visant un allié, celui-ci est soigné de 15...60 points de vie. Coût de la guérison : vous perdez 1 points d\'énergie.'],
285=>['Mains du guérisseur','Pendant 10 secondes, chaque fois que la cible (un allié ou vous-même) subit des dégâts, elle reçoit 5...35 points de vie.','(10 secondes.) Soigne de 5...35 points de vie chaque fois que la cible subit des dégâts.'],
286=>['Guérison des autres','Soigne l\'allié de 35...180 points de vie.','Soigne de 35...180 points de vie. Vous ne pouvez pas vous prendre pour cible.'],
287=>['Guérison de groupe','Soigne tout le groupe de 30...75 points de vie.','Soigne tout le groupe de 30...75 points de vie.'],
288=>['Souffle de guérison','Pendant 15 secondes, la cible (un allié ou vous-même) bénéficie d\'une régénération de santé de +4...9.','(15 secondes.) Confère une régénération de santé de +4...9.'],
289=>['Bénédiction vitale','Tant que cet enchantement est actif, la cible (un allié ou vous-même) a +40...200 de santé maximum.','+40...200 de santé maximum.'],
290=>['Rénovation','Tant que cet enchantement est actif, la cible (un allié ou vous-même) bénéficie d\'une régénération de santé de +1...4.','Confère une régénération de santé de +1...4.'],
291=>['Vie par procuration','Tant que cet enchantement est actif, à chaque fois que la cible (un allié ou vous-même) touche un ennemi, vous gagnez 2...17 points de vie.','Vous gagnez 2...17 points de vie chaque fois que l\'allié visé frappe un ennemi.'],
292=>['Transfert de santé','Vous perdez la moitié de vos points de vie. L\'allié visé est soigné de 100...136% des points de vie perdus.','Soigne de 100...136% de votre santé actuelle divisée par deux. Vous perdez la moitié de vos points de vie actuels. Vous ne pouvez pas vous prendre pour cible.'],
293=>['Sceau de dévotion','Soigne la cible (un allié ou vous-même) de 20...120 points de vie.','Soigne de 20...120 points de vie.'],
294=>['Sceau du jugement','La cible ennemie est assommée. Elle subit 15...75 points de dégâts sacrés, ainsi que les ennemis adjacents.','Assomme la cible. Inflige 15...75 points de dégâts sacrés à la cible et aux ennemis adjacents.'],
295=>['Sceau d\'épuration','Annule tous les maléfices et conditions qui affectent la cible (un allié ou vous-même). Vous perdez 10 points d\'énergie pour chaque maléfice ou condition annulée.','Supprime la totalité des maléfices et des conditions. Coût de la suppression : 10 points d\'énergie par suppression.'],
296=>['Sceau de la calamité','La cible ennemie subit 30...60 points de dégâts sacrés. Si elle était en train d\'attaquer, elle est assommée.','Inflige 30...60 points de dégâts sacrés. Attaque assommante si l\'ennemi visé attaque.'],
297=>['Sceau sacré','Vous obtenez 3 points d\'énergie pour chaque enchantement que vous maintenez. Vous ne pouvez pas obtenir plus de 3...24 points d\'énergie de cette manière.','Vous récupérez 3 points d\'énergie pour chaque enchantement que vous maintenez. Vous ne pouvez pas obtenir plus de 3...24 points d\'énergie de cette manière.'],
298=>['Martyre','Transfère toutes les conditions et leur temps restant de vos alliés vers vous.','Vous transférez vers vous toutes les conditions de tous vos alliés.'],
299=>['Mains du protecteur','Pendant 8 secondes, les dégâts et le vol de vie subis par l\'allié visé sont réduits de 3...18. Lorsque Mains du protecteur prend fin, cet allié est soigné de 5...50 points de vie.','(8 secondes.) Réduit les dégâts et le vol de vie subis de 3...18. Effet final : soigne de 5...50 points de vie.'],
300=>['Contemplation de la pureté','Perte de tous les enchantements. Pour chaque enchantement perdu, vous gagnez 0...80 points de vie et êtes libéré d\'un maléfice et d\'une condition (1...8 maléfices et conditions maximum).','Vous gagnez 0...80 points de vie et perdez un maléfice et une condition par enchantement vous affectant. (maximum : 1...8 maléfices et conditions). Vous perdez tous vos enchantements.'],
301=>['Annulation des maléfices','Lève un maléfice qui frappe la cible (un allié ou vous-même).','Lève un maléfice qui frappe la cible alliée.'],
302=>['Expiation des maléfices','Ote un maléfice qui frappe la cible (un allié ou vous-même). Si un maléfice est levé de cette manière, les ennemis dans la zone subissent 10...85 points de dégâts sacrés.','Lève un maléfice qui frappe la cible alliée. Effet de la suppression : inflige 10...85 points de dégâts sacrés aux ennemis dans la zone de l\'allié visé.'],
303=>['Conversion des maléfices','Lève tous les maléfices qui frappent l\'allié visé. Pendant 8...20 secondes, il bénéficie d\'un bonus d\'armure de +10 pour chaque maléfice de Nécromant levé.','Supprime tous les maléfices. Bonus d\'armure de +10 par maléfice de Nécromant supprimé (8...20 secondes). Vous ne pouvez pas vous prendre pour cible.'],
304=>['Lumière de Dwayna','Vous ressuscitez tous les membres du groupe morts dans la zone. Ils reviennent à la vie avec 25% de leur santé et aucun point d\'énergie.','Ressuscite tous les membres morts du groupe dans la zone (25% de santé, 0 point d\'énergie).'],
305=>['Résurrection','Vous ressuscitez le membre du groupe visé. Celui-ci revient à la vie avec 25% de santé et aucun point d\'énergie.','Ressuscite le membre du groupe visé (25% de santé et 0 point d\'énergie).'],
306=>['Renaissance','Ressuscite un membre du groupe. Celui-ci revient à la vie avec 25% de santé et aucun point d\'énergie et est téléporté à votre position. Toutes ses compétences sont inutilisables pendant 10...3 secondes. Ce sort consomme toute l\'énergie qu\'il vous reste.','Ressuscite le membre du groupe visé (25% de santé et 0 point d\'énergie). Téléporte la cible vers vous. Désactive les compétences de la cible (10...3 secondes). Vous perdez toute votre énergie.'],
307=>['Revers de fortune','Pendant 8 secondes, la prochaine fois que l\'allié visé doit subir des dégâts ou un vol de vie, ces derniers sont transformés en points de vie, 15...80 points maximum.','(8 secondes.) Les prochains dégâts subis ou le prochain vol de vie seront convertis en soins (maximum : 15...80 points).'],
308=>['Secours','Tant que cet enchantement est actif, la régénération d\'énergie et de santé de l\'allié augmente de +1, mais vous perdez 1 point d\'énergie à chaque fois qu\'il lance un sort.','Régénération de santé de +1 et régénération d\'énergie de +1. Vous ne pouvez pas vous prendre pour cible. Vous perdez 1 point d\'énergie chaque fois que l\'allié visé lance un sort.'],
309=>['Voile sacré','Pendant que vous maintenez cet enchantement, le temps d\'incantation de tout maléfice lancé sur la cible (allié ou vous-même) est doublé. Lorsque Voile sacré prend fin, un maléfice de la cible est supprimé.','Double le temps d\'incantation des maléfices lancés sur l\'allié visé. Effet final : supprime un maléfice.'],
310=>['Esprit divin','Pendant 1...14 secondes, les sorts de Moine vous coûtent 5 points d\'énergie en moins (coût minimum : 1 point d\'énergie).','(1...14 secondes.) Les sorts de Moine coûtent 5 points d\'énergie en moins. Coût minimum : 1 points d\'énergie.'],
311=>['Egalité de conditions','Toutes les conditions négatives de l\'allié vous sont transférées. Pour chaque condition transférée, vous gagnez 6...26 points de vie.','Transfère vers vous toutes les conditions affectant l\'allié visé. Effet du transfert : vous gagnez 6...26 points de vie par condition. Vous ne pouvez pas vous prendre pour cible.'],
312=>['Choc sacré','L\'ennemi touché subit 10...55 points de dégâts sacrés. Si elle est assommée, votre cible subira 10...55 points de dégâts sacrés en plus.','Inflige 10...55 points de dégâts sacrés. Inflige 10...55 points de dégâts sacrés supplémentaires si la cible est assommée.'],
313=>['Caresse de guérison','L\'allié touché est soigné de 20...80 points de vie. La santé récupérée grâce à la Faveur Divine est doublée pour ce sort.','Soigne de 20...80 points de vie. Double la santé récupérée grâce à la Faveur Divine pour ce sort.'],
314=>['Reviviscence','Touchez le corps d\'un membre du groupe tombé au combat. Il revient à la vie avec 20...65% de vie et 42...90% d\'énergie.','Ressuscite le membre du groupe visé (20...65% de santé et 42...90% d\'énergie).'],
315=>['Vengeance','Ressuscite un membre du groupe mort avec tous ses points de vie et d\'énergie. Pendant 30 secondes, ce membre du groupe inflige 25% de dégâts en plus. Lorsque cet enchantement prend fin, le membre du groupe visé meurt. Les personnages mourant sous les effets de cet enchantement n\'obtiennent pas de handicap.','(30 secondes.) Ressuscite le membre du groupe visé (santé et énergie maximum). Cet allié inflige 25% de dégâts en plus et ne subit pas de handicap. Effet final : cet allié meurt.'],
316=>['Extrême limite !','Pour chaque ennemi à portée de voix (maximum 1...6), vous gagnez une décharge d\'adrénaline. Pendant 10...20 secondes, votre santé maximum augmente de 10...60.','(10...20 secondes.) Vous bénéficiez d\'une santé maximum de +10...60. Effet initial : vous gagnez une décharge d\'adrénaline par ennemi à portée de voix (maximum 1...6).'],
317=>['Fureur guerrière','Pendant 5...20 secondes, vous vous déplacez 33% plus vite et gagnez 2 fois plus d\'adrénaline lors des attaques. La Fureur guerrière prend fin si vous utilisez des compétences ne nécessitant pas d\'adrénaline.','(5...20 secondes.) Vous vous déplacez 33% plus vite et vos attaques vous font gagner 2 fois plus d\'adrénaline. Prend fin si vous utilisez une compétence ne nécessitant pas d\'adrénaline.'],
318=>['Défi à la douleur','Pendant 20 secondes, vous avez 90...300 points de vie supplémentaires, bénéficiez d\'un bonus d\'armure de 20 et subissez 1...10 points de dégâts en moins.','(20 secondes.) Vous bénéficiez de +90...300 points de santé maximum, d\'un bonus d\'armure de +20 et subissez -1...10 points de dégâts en moins.'],
319=>['Course','Pendant 8...20 secondes, vous courez 25% plus vite.','(8...20 secondes.) Vous vous déplacez 25% plus vite.'],
320=>['Coupe-jarret','Si cette attaque réussit, la cible est frappée d\'Infirmité pendant 3...15 secondes et ses mouvements sont ralentis.','Inflige l\'Infirmité (3...15 secondes).'],
321=>['Coup sauvage','Perte de toute l\'adrénaline. Si l\'attaque réussit, vous portez un coup critique et la pose utilisée par la cible prend fin. Cette attaque ne peut pas être bloquée.','Inflige toujours un coup critique. Supprime une pose de combat. Impossible à bloquer. Vous perdez toute votre adrénaline.'],
322=>['Attaque puissante','Cette attaque inflige +10...40 points de dégâts si elle réussit.','Inflige +10...40 points de dégâts.'],
323=>['Frappe désespérée','Si cette attaque réussit, vous infligez +10...40 points de dégâts et la cible est affectée par une des conditions suivantes : Blessure profonde (pendant 20 secondes), Faiblesse (pendant 20 secondes), Saignement (pendant 25 secondes) ou Infirmité (pendant 15 secondes). Vous êtes assommé après une Frappe désespérée.','Inflige +10...40 points de dégâts. Inflige au hasard une des conditions suivantes : Blessure profonde (20 secondes), Faiblesse (20 secondes), Saignement (25 secondes) ou Infirmité (15 secondes). Vous êtes assommé.'],
324=>['Frisson de victoire','Si ce coup réussit, il inflige +20...40 points de dégâts. Si vous disposez de plus de points de vie que la cible ennemie, vous obtenez 1...2 décharges d\'adrénaline.','Inflige +20...40 points de dégâts. Si vous disposez de plus de points de vie que votre cible, vous obtenez 1...2 décharges d\'adrénaline.'],
325=>['Coup de diversion','Vous agitez votre arme devant l\'ennemi sans lui infliger de dégâts, mais vous interrompez son action (et les actions des ennemis qui lui sont adjacents).','Frappe aussi les ennemis adjacents à votre cible. Interrompt une action. N\'inflige pas de dégâts.'],
326=>['Attaque du protecteur','Si cette attaque frappe un ennemi en mouvement, vous infligez 10...40 points de dégâts supplémentaires.','Inflige +10...40 points de dégâts si la cible est en mouvement.'],
327=>['Frappe du griffon','Si cette attaque réussit, vous infligez +5...20 points de dégâts. Si elle est bloquée, la cible est assommée et subit 10...34 points de dégâts.','Inflige +5...20 points de dégâts. Attaque assommante infligeant 10...34 points de dégâts si elle est bloquée.'],
328=>['Frappe pure','Si la Frappe pure réussit, vous infligez +1...30 points de dégâts. Si vous n\'utilisez pas de pose, la Frappe pure ne peut pas être bloquée.','Inflige +1...30 points de dégâts. Vous ne pouvez la bloquer qu\'en pose de combat.'],
329=>['Brise-crâne','Si cette attaque réussit, elle interrompt l\'action en cours de la cible. Si cette dernière incantait un sort, elle subit Stupeur pendant 15 secondes.','Interrompt une action. Inflige l\'altération Stupeur (15 secondes) si la cible incantait un sort.'],
330=>['Hache cyclone','Attaque tournoyante à la hache qui inflige +4...12 points de dégâts à tous les ennemis adjacents.','Inflige +4...12 points de dégâts à tous les ennemis qui vous sont adjacents.'],
331=>['Coup de marteau','Perte de toute l\'adrénaline. Si le Coup de marteau réussit, la cible est assommée.','Attaque assommante. Vous perdez toute votre adrénaline.'],
332=>['Attaque du taureau','Si cette attaque frappe un ennemi en déplacement, vous infligez +5...30 points de dégâts et la cible est assommée.','Inflige +5...30 points de dégâts et assomme la cible ennemie si elle se déplace.'],
333=>['Je vous vengerai !','Pour chaque allié mort, votre vitesse d\'attaque augmente de 25% et vous bénéficiez d\'une régénération de santé de +3...7 pendant 10 secondes.','Vous bénéficiez d\'une régénération de santé de +3...7 et vous attaquez 25% plus vite (10 secondes par allié mort).'],
334=>['Ratissage','Si cette attaque frappe un ennemi souffrant d\'une Blessure profonde, vous infligez +4...16 points de dégâts et la cible est frappée d\'Infirmité pendant 15 secondes.','Inflige +4...16 points de dégâts et provoque l\'Infirmité (15 secondes) si l\'ennemi visé souffre de Blessure profonde.'],
335=>['Clivage','Si cette attaque porte, vous infligez +10...40 points de dégâts et frappez jusqu\'à 1...2 ennemis adjacents, qui subissent 10...40 points de dégâts tranchants.','Inflige +10...40 points de dégâts et frappe jusqu\'à 1...2 ennemis adjacents, qui subissent 10...40 points de dégâts tranchants.'],
336=>['Frappe du bourreau','Cette attaque inflige +15...45 points de dégâts si elle réussit.','Inflige +15...45 points de dégâts.'],
337=>['Démembrement','Si cette attaque à la hache réussit, vous infligez une Blessure profonde qui réduit la santé maximum de la cible de 20% pendant 5...20 secondes.','Provoque la Blessure profonde (5...20 secondes).'],
338=>['Eviscération','Si l\'Eviscération réussit, vous infligez +10...45 points de dégâts et une Blessure profonde qui réduit la santé maximum de la cible de 20% pendant 5...20 secondes.','Inflige +10...45 points de dégâts. Provoque la Blessure profonde (5...20 secondes).'],
339=>['Coup pénétrant','Si cette attaque réussit, vous infligez +10...25 points de dégâts. Cette attaque à la hache a 20% de pénétration d\'armure.','Inflige +10...25 points de dégâts. Pénétration d\'armure de 20%.'],
340=>['Taillade d\'interruption','Si elle réussit, cette attaque interrompt l\'action de la cible. S\'il s\'agissait d\'une compétence, celle-ci devient inutilisable pendant 20 secondes de plus.','Interrompt une action. Effet de l\'interruption : la compétence interrompue est désactivée pendant +20 secondes.'],
341=>['Coup rapide','Cette attaque inflige +1...20 points de dégâts si elle réussit. En cas de blocage de Coup rapide, l\'ennemi visé subit 1...20 points de dégâts et Blessure profonde pendant 20 secondes.','Inflige +1...20 points de dégâts. Inflige 1...20 points de dégâts et la Blessure profonde (20 secondes) si l\'ennemi réussit à bloquer.'],
342=>['Hache tournante','Si cette attaque frappe un ennemi souffrant d\'une Blessure Profonde, vous infligez 5...25 points de dégâts supplémentaires et la cible est prise de Faiblesse pendant 20 secondes.','Inflige +5...25 points de dégâts et provoque la Faiblesse (20 secondes) si l\'ennemi visé souffre de Blessure profonde.'],
343=>['Pour la justice !','Pendant 20 secondes, chaque fois que vous gagnez de l\'adrénaline, vous en obtenez 100% de plus.','(20 secondes.) Vous gagnez 100% d\'adrénaline en plus.'],
344=>['Rafale','Pendant 5 secondes, votre vitesse d\'attaque augmente de 33%, mais vous infligez 25% de dégâts en moins.','(5 secondes). Vous attaquez 33% plus vite. Vous infligez 25% de dégâts en moins.'],
345=>['Pose défensive','Pendant 1...5 secondes, vous avez 75% de chances de bloquer les attaques au corps à corps et les projectiles. Lorsque la Pose défensive prend fin, vous obtenez une décharge d\'adrénaline pour chaque compétence d\'attaque au corps à corps dont vous disposez (maximum de 0...4 décharges).','(1...5 secondes.) Vous avez 75% de chances de bloquer les attaques. Effet final : vous obtenez une décharge d\'adrénaline pour chaque compétence d\'attaque au corps à corps dont vous disposez (maximum de 0...4 décharges).'],
346=>['Frénésie','Pendant 8 secondes, vous attaquez 33% plus vite, mais vous subissez 175...125% de dégâts.','(8 secondes.) Vous attaquez 33% plus vite. Vous subissez 175...125% de dégâts.'],
347=>['Résistance à la douleur','Pendant 7...18 secondes, vous avez 90...300 points de vie supplémentaires.','(7...18 secondes.) Vous avez +90...300 de santé maximum.'],
348=>['Prenez garde !','Les membres du groupe à portée de voix bénéficient d\'un bonus d\'armure de +5...25 pendant 10 secondes. Ce cri prend fin après 10 attaques.','(10 secondes.) Les membres du groupe à portée de voix bénéficient d\'un bonus d\'armure de +5...25. Prend fin après 10 attaques reçues.'],
349=>['Sprint','Pendant 8...14 secondes, vous courez 25% plus vite.','(8...14 secondes.) Vous vous déplacez 25% plus vite.'],
350=>['Coup ventral','Si cette attaque frappe un ennemi assommé, le nuage de poussière soulevé aveugle les ennemis adjacents pendant 3...7 secondes.','Inflige l\'Aveuglement aux ennemis adjacents (3...7 secondes) si l\'ennemi visé est assommé.'],
351=>['Coup puissant','Cette attaque inflige +10...40 points de dégâts si elle réussit.','Inflige +10...40 points de dégâts.'],
352=>['Coup écrasant','Si cette attaque réussit, vous infligez +1...20 points de dégâts. Si vous frappez un ennemi assommé, vous lui infligez une Blessure profonde qui réduit sa santé maximum de 20% pendant 5...20 secondes.','Inflige +1...20 points de dégâts. Inflige la Blessure profonde si l\'ennemi visé est assommé (5...20 secondes).'],
353=>['Swing brutal','Attaque tous les ennemis adjacents. La cible ennemie subit 1...20 points de dégâts.','Attaque tous les ennemis adjacents et leur inflige +1...20 points de dégâts.'],
354=>['Marteau pilon','L\'ennemi ciblé et tous les ennemis adjacents sont assommés (50% de risques d\'échec avec Maîtrise du marteau 4 ou moins).','Assomme la cible et les ennemis adjacents. 50% de chances d\'échouer sauf si la valeur de Maîtrise du marteau est de 5 ou plus.'],
355=>['Marteau dévastateur','Si l\'attaque du Marteau dévastateur réussit, la cible est assommée et frappée de Faiblesse pendant 5...20 secondes.','Attaque assommante. Inflige la Faiblesse (5...20 secondes).'],
356=>['Coup impérieux','Si cette attaque réussit, vous infligez +5...20 points de dégâts. Si elle est bloquée, la cible est assommée et subit 5...20 points de dégâts.','Inflige +5...20 points de dégâts. Inflige 5...20 points de dégâts et assomme si l\'ennemi réussit à bloquer.'],
357=>['Contrecoup','Si cette attaque frappe un ennemi en combat, il est assommé.','Attaque assommante si l\'ennemi visé attaque.'],
358=>['Brise-échine','Si le Brise-échine réussit, vous infligez +1...20 points de dégâts et la cible est assommée. Si vous avez 8 points en Force ou plus, cet assommement dure 4 secondes.','Inflige +1...20 points de dégâts. Provoque l\'assommement. L\'assommement dure 4 secondes si vous avez 8 points en Force ou plus.'],
359=>['Coup de brute','Perte de toute l\'adrénaline. Si cette attaque frappe un ennemi souffrant de Faiblesse, il est assommé et vous infligez +1...30 points de dégâts.','Inflige +1...30 points de dégâts. Attaque assommante si l\'ennemi visé souffre de Faiblesse. Vous perdez toute votre adrénaline.'],
360=>['Coup de boutoir','Si cette attaque au marteau réussit, la cible est frappée de Faiblesse pendant 5...20 secondes.','Inflige la Faiblesse (5...20 secondes).'],
361=>['Sceau de dolyak','Pendant 8...20 secondes, vous gagnez +10...40 de bonus d\'armure et vous ne pouvez pas être assommé, mais vos mouvements sont ralentis de 75%.','(8...20 secondes.) Vous bénéficiez d\'un bonus d\'armure de +10...40 et ne pouvez pas être assommé. Vous vous déplacez 75% moins vite.'],
362=>['Adresse du Guerrier','Pendant 5...11 secondes, vos attaques au corps à corps ne peuvent pas être bloquées.','(5...11 secondes.) Vos attaques au corps à corps sont impossibles à bloquer.'],
363=>['Coup de bouclier','Pendant 5...11 secondes, si vous utilisez un bouclier, la prochaine compétence d\'attaque au corps à corps utilisée contre vous sera bloquée, votre attaquant sera assommé et sa compétence sera inutilisable pendant 15 secondes supplémentaires.','(5...11 secondes.) Vous bloquez la compétence d\'attaque au corps à corps suivante. Provoque un renversement et +15 secondes de temps de recharge. Aucun effet si vous n\'utilisez pas de bouclier.'],
364=>['Chargez !','Tous les alliés à portée de voix perdent la condition d\'Infirmité. Pendant 5...13 secondes, tous les alliés se déplacent 33% plus vite.','(5...13 secondes.) Les alliés à portée de voix se déplacent 33% plus vite. Effet initial : les alliés perdent la condition d\'Infirmité.'],
365=>['"A moi la victoire !"','Vous gagnez 10...68 points de vie et 3...7 points d\'énergie pour chaque condition qui affecte l\'ennemi ciblé.','Vous gagnez 10...68 points de vie et 3...7 points d\'énergie par condition affectant l\'ennemi visé.'],
366=>['Craignez-moi !','Tous les ennemis à proximité perdent 2...6 points d\'énergie. Pendant 1...15 secondes, vos attaques au corps à corps ont +5...30% de chances d\'infliger un coup critique contre les ennemis immobiles.','(1...15 secondes.) Vous avez +5...30% de chances de réaliser un coup critique avec les attaques au corps à corps contre les ennemis immobiles. Effet initial : les ennemis à proximité perdent 2...6 points d\'énergie.'],
367=>['Levez les boucliers !','Pendant 5...11 secondes, tous les membres du groupe à portée de voix et vous-même bénéficiez d\'un bonus d\'armure de +60 contre les projectiles qui vous sont lancés.','(5...11 secondes.) Les membres du groupe à portée de voix bénéficient d\'un bonus d\'armure de +60 contre les projectiles qui leur sont lancés.'],
368=>['Je survivrai !','Vous bénéficiez de +3 points de régénération de santé pour chaque condition dont vous souffrez. Cette régénération cesse au bout de 5...11 secondes.','(5...11 secondes.) Vous bénéficiez d\'une régénération de santé de +3 par condition vous affectant.'],
370=>['Pose du berserker','Pendant 8...14 secondes, vous attaquez 33% plus vite et gagnez 100% d\'adrénaline en plus. La Pose du Berserker prend fin si vous utilisez une compétence.','(8...14 secondes.) Vous attaquez 33% plus vite et recevez 100% d\'adrénaline en plus. Prend fin si vous utilisez une compétence.'],
371=>['Pose d\'équilibre','Pendant 8...20 secondes, vous ne pouvez pas être assommé et vous ne subissez pas de dégâts supplémentaires en recevant une attaque critique.','(8...20 secondes.) Vous ne pouvez pas être assommé et les coups critiques ne vous infligent pas de dégâts en plus.'],
372=>['Défense du gladiateur','Pendant 5...11 secondes, vous avez 75% de chances de bloquer les attaques. A chaque fois que vous bloquez une attaque au corps à corps de cette manière, l\'attaquant subit 5...35 points de dégâts.','(5...11 secondes.) Vous avez 75% de chances de bloquer. Votre assaillant subit 5...35 points de dégâts chaque fois que vous bloquez une attaque au corps à corps ainsi.'],
373=>['Déviation des flèches','Pendant 1...6 secondes, vous avez 75% de chances de bloquer les attaques. Si vous bloquez un projectile, les ennemis adjacents souffrent de Saignement pendant 5...15 secondes.','(1...6 secondes.) Vous avez 75% de chances de bloquer les attaques. Les ennemis adjacents souffrent de Saignement (5...15 secondes) chaque fois que vous bloquez un projectile.'],
374=>['Endurance du Guerrier','Pendant 5...35 secondes, vous gagnez 3 points d\'énergie pour chaque attaque au corps à corps réussie. L\'Endurance du Guerrier ne peut pas faire monter votre énergie au-delà de 10...25.','(5...35 secondes.) Vous gagnez 3 points d\'énergie chaque fois que vous réussissez une attaque au corps à corps. Vous ne récupérez pas d\'énergie si vous avez plus de 10...25 points d\'énergie.'],
375=>['Pose de combat des Nains','Pendant 5...11 secondes, si vous utilisez un marteau, votre vitesse d\'attaque est augmentée de 33%, vous gagnez un bonus d\'armure de +40, et vos compétences d\'attaque interrompent les ennemis quand elles réussissent.','(5...11 secondes.) Votre vitesse d\'attaque est augmentée de 33%, vous gagnez un bonus d\'armure de +40, et vos compétences d\'attaque interrompent les actions. Ne fonctionne que si vous êtes équipé d\'un marteau.'],
376=>['Pose de discipline','Pendant 1...4 secondes, vous bénéficiez d\'un bonus d\'armure de +10 et vous avez 75% de chances de bloquer les attaques. La Pause de discipline prend fin si vous utilisez une compétence d\'adrénaline.','(1...4 secondes.) Vous avez 75% de chances de bloquer et bénéficiez d\'un bonus d\'armure de +10. Prend fin si vous utilisez une compétence d\'adrénaline.'],
377=>['Pose prudente','Pendant 1...6 secondes, vous bloquez toutes les compétences d\'attaque lancées contre vous. Pour chaque attaque bloquée, vous gagnez de l\'adrénaline et 5 points d\'énergie. La Pose prudente prend fin si vous utilisez une compétence.','(1...6 secondes). Vous bloquez les compétences d\'attaque. Vous gagnez de l\'adrénaline et 5 points d\'énergie par attaque bloquée. Prend fin si vous utilisez une compétence.'],
378=>['Pose du bouclier','Pendant 1...6 secondes, si vous utilisez un bouclier, vous avez 75% de chances de bloquer les attaques lancées contre vous, et les dégâts sont réduits de 2 pour chaque rang en Force (maximum de 15 points de réduction de dégâts).','(1...6 secondes.) Vous avez 75 % de chances de bloquer les attaques. Les dégâts sont réduits de 2 pour chaque rang en Force (maximum de 15 points de réduction de dégâts). Ne fonctionne que si vous êtes équipé d\'un bouclier.'],
379=>['Charge du taureau','Pendant 1...7 secondes, vous vous déplacez 50% plus vite et, si vous touchez un ennemi en déplacement au corps à corps, vous l\'assommez. La Charge du taureau prend fin si vous utilisez une compétence.','(1...7 secondes.) Vous vous déplacez 50% plus vite. Renverse les ennemis en mouvement que vous touchez au corps à corps. Prend fin si vous utilisez une compétence.'],
380=>['Défense de Bonetti','Pendant 5...11 secondes, vous avez 75% de chances de bloquer les attaques au corps à corps et les projectiles. Vous gagnez 5 points d\'énergie pour chaque attaque de mêlée bloquée. La Défense de Bonetti prend fin si vous utilisez une compétence.','(5...11 secondes.) Vous avez 75% de chances de bloquer. Vous gagnez 5 points d\'énergie par attaque au corps à corps bloquée. Prend fin si vous utilisez une compétence.'],
381=>['Cent lames','Pendant 15 secondes, à chaque fois que vous attaquez avec une épée, tous les ennemis adjacents subissent 10...35 points de dégâts tranchants.','(15 secondes.) Inflige 10...35 points de dégâts tranchants à tous les ennemis adjacents chaque fois que vous attaquez avec une épée.'],
382=>['Tranche-artère','Si cette attaque réussit, l\'ennemi sera victime de Saignements pendant 5...25 secondes et perdra progressivement des points de vie.','Provoque le Saignement (5...25 secondes).'],
383=>['Taillade de Galrath','Cette attaque inflige +1...40 points de dégâts si elle réussit.','Inflige +1...40 points de dégâts.'],
384=>['Entaille','Si cette attaque frappe un ennemi affecté par le Saignement, vous lui infligez 5...20 points de dégâts supplémentaires et une Blessure profonde qui réduit sa santé maximum de 20% pendant 5...20 secondes.','Inflige +5...20 points de dégâts et provoque la Blessure profonde (5...20 secondes) si votre cible souffre de Saignement.'],
385=>['Botte fatale','Perte de toute l\'adrénaline. Si la Botte fatale touche sa cible, vous infligez 5...40 points de dégâts supplémentaires. Ces dégâts sont doublés si la cible a moins de 50% de ses points de vie.','Inflige +5...40 points de dégâts. Inflige +5...40 points de dégâts supplémentaires si l\'ennemi visé a moins de 50% de santé. Vous perdez toute votre adrénaline.'],
386=>['Lame chercheuse','Si cette attaque réussit, vous infligez +1...20 points de dégâts. Si elle est bloquée, la cible est prise de Saignement pendant 25 secondes et subit 1...20 points de dégâts.','Inflige +1...20 points de dégâts. Inflige 1...20 points de dégâts et provoque le Saignement (25 secondes) si l\'ennemi réussit à bloquer.'],
387=>['Riposte','Pendant 8 secondes, si vous avez une épée en main, vous bloquez la prochaine attaque au corps à corps et votre attaquant subit 20...80 points de dégâts.','(8 secondes.) Vous bloquez l\'attaque au corps à corps suivante et votre assaillant subit 20...80 points de dégâts. Aucun effet si vous n\'avez pas d\'épée en main.'],
388=>['Riposte mortelle','Pendant 8 secondes, si vous avez une épée en main, vous bloquez la prochaine attaque au corps à corps contre vous, l\'attaquant subit 15...90 points de dégâts et souffre de Saignement pendant 3...25 secondes.','(8 secondes.) Vous bloquez l\'attaque au corps à corps suivante et votre assaillant subit 15...90 points de dégâts. Provoque le Saignement (3...25 secondes). Aucun effet si vous n\'avez pas d\'épée en main.'],
389=>['Prospérité','Toutes vos compétences d\'attaque sont rechargées. Vous gagnez 2...7 points d\'énergie pour chaque compétence rechargée par la Prospérité.','Recharge vos compétences d\'attaque. Vous gagnez 2...7 points d\'énergie par compétence rechargée.'],
390=>['Taillade sauvage','Si cette attaque réussit, elle interrompt l\'action de la cible ennemie. Si cette action était un sort, vous infligez 1...40 points de dégâts supplémentaires.','Interrompt une action. Effet de l\'interruption : inflige +1...40 points de dégâts si l\'action est un sort.'],
391=>['Tir du chasseur','Si le Tir du chasseur réussit, votre cible souffre de Saignement pendant 3...25 secondes.','Provoque le Saignement (3...25 secondes).'],
392=>['Immobilisation','Si l\'Immobilisation réussit, la cible est frappée d\'Infirmité pendant 3...15 secondes.','Inflige l\'Infirmité (3...15 secondes).'],
393=>['Tir incapacitant','Si le Tir incapacitant réussit, la cible est frappée d\'Infirmité pendant 4...14 secondes. Cette attaque ne peut être bloquée.','Ne peut être bloqué. Inflige l\'Infirmité (4...14 secondes).'],
394=>['Tir puissant','Si le Tir puissant réussit, l\'ennemi visé subit 25...50 points de dégâts.','L\'ennemi visé subit 25...50 points de dégâts.'],
395=>['Tir de barrage','Toutes vos préparations sont annulées. Vous décochez des flèches sur l\'ennemi visé et jusqu\'à 5 ennemis adjacents à votre cible. Ces flèches infligent +5...20 points de dégâts si elles font mouche.','Inflige +5...20 points de dégâts. Frappe 5 ennemis adjacents à votre cible. Toutes vos préparations sont annulées.'],
396=>['Tir double','Vous tirez deux flèches sur l\'ennemi visé. Ces flèches infligent 25% moins de dégâts.','Vous tirez simultanément 2 flèches sur l\'ennemi visé. Ces flèches infligent 25% de dégâts en moins.'],
397=>['Tir rapide','Vous décochez une flèche qui se déplace deux fois plus vite.','Vous tirez une flèche qui se déplace deux fois plus vite.'],
398=>['Attaque pénétrante','Si l\'Attaque pénétrante réussit, vous infligez +5...25 points de dégâts et cette attaque offre une pénétration d\'armure de 10%.','Inflige +5...25 points de dégâts. Pénétration d\'armure de 10%.'],
399=>['Tir de diversion','Si le Tir de diversion réussit, il interrompt l\'action de la cible mais n\'inflige que 1...16 points de dégâts. Si l\'ennemi utilisait une compétence, celle-ci est inutilisable pendant 20 secondes de plus.','Interrompt une action. Effet de l\'interruption : la compétence interrompue est désactivée pendant +20 secondes. Inflige seulement 1...16 points de dégâts.'],
400=>['Tir de précision','Si le Tir de précision réussit, vous infligez +3...10 points de dégâts. Le Tir de précision ne peut pas être bloqué. Cette action peut facilement être interrompue.','Inflige +3...10 points de dégâts. Impossible à bloquer. Cette compétence peut être facilement interrompue.'],
402=>['Tir déterminé','Si le Tir déterminé réussit, vous infligez +5...20 points de dégâts. S\'il échoue toutes vos compétences d\'attaques seront rechargées.','Inflige +5...20 points de dégâts. Recharge vos compétences d\'attaque si la cible n\'est pas blessée.'],
403=>['Tir ciblé','Vous décochez une flèche qui se déplace trois fois plus rapidement et qui ne peut pas être bloquée.','Vous tirez une flèche qui se déplace trois fois plus vite. Impossible à bloquer.'],
404=>['Flèche empoisonnée','Si la Flèche empoisonnée touche sa cible, elle est empoisonnée pendant 5...20 secondes.','Provoque l\'Empoisonnement (5...20 secondes).'],
405=>['Tir du serment','Si le Tir du serment réussit, toutes vos compétences (à part celle-ci) se rechargent. S\'il est raté, toutes vos compétences sont inutilisables pendant 10...4 secondes (50% de risques d\'échec avec une Expertise de 7 ou inférieur).','Si l\'attaque réussit, toutes vos compétences sont rechargées, à l\'exception du Tir du serment. Désactive toutes vos compétences en cas d\'échec (10...4 secondes). 50% de chances d\'échouer sauf avec une valeur d\'Expertise d\'au moins 8.'],
406=>['Tir débilitant','Si le Tir débilitant réussit, la cible perd 1...10 points d\'énergie.','Provoque une perte de 1...10 points d\'énergie.'],
407=>['Tir à bout portant','Vous tirez une flèche dont la portée est réduite de moitié, mais qui inflige +10...40 points de dégâts.','Inflige +10...40 points de dégâts.'],
408=>['Coup cérébral','Si le coup cérébral atteint un ennemi qui est en train de lancer un sort, celui-ci est interrompu et l\'ennemi est frappé de Stupeur pendant 5...20 secondes. Cette attaque n\'inflige que 1...16 points de dégâts.','Interrompt un sort. Effet de l\'interruption : inflige la Stupeur (5...20 secondes). Inflige seulement 1...16 points de dégâts.'],
409=>['Tir de représailles','Si le Tir de représailles réussit, vous infligez 10...20 points de dégâts supplémentaires et l\'action de la cible est interrompue.','Inflige +10...20 points de dégâts. Interrompt une action.'],
411=>['Charme animal','Charme l\'animal visé. Une fois charmé, votre familier vous suivra tant que le charme animal sera équipé. Vous ne pouvez pas charmer un animal de 4 niveaux supérieur à vous.','Charme l\'animal visé. Une fois charmé, votre familier vous suivra tant que le charme animal sera équipé. Vous ne pouvez pas charmer un animal de 4 niveaux supérieur à vous.'],
412=>['Cri de protection','Pendant 120 secondes, votre familier bénéficie d\'une réduction de dégâts de base de 5...20 points.','(120 secondes.) Votre familier bénéficie d\'une réduction de dégâts de 5...20.'],
415=>['Cri de hâte','Pendant 30 secondes, votre familier bénéficie de 33% de vitesse d\'attaque en plus et se déplace 33% plus vite.','(30 secondes.) Votre familier se déplace et attaque 33% plus rapidement.'],
422=>['Renaissance animale','Vous ressuscitez tous les compagnons animaux alliés dans la zone. Ils reviennent à la vie avec 10...94% de santé.','Ressuscite tous les familiers alliés dans la zone (10...94% de santé).'],
423=>['Lien symbiotique','Pendant 120...300 secondes, la régénération de santé de votre animal augmente de 1...3 points et la moitié de tous les dégâts qui lui sont infligés vous sont transférés.','(120...300 secondes.) Votre familier bénéficie d\'une régénération de santé de +1...3. Vous subissez la moitié des dégâts infligés à votre familier à sa place.'],
424=>['Jet de terre','L\'ennemi touché et les ennemis adjacents sont aveuglés pendant 3...15 secondes.','Provoque l\'Aveuglement (3...15 secondes). Affecte également les ennemis adjacents à la cible.'],
425=>['Esquive','Pendant 5...11 secondes, vous vous déplacez 33% plus vite et avez 27...75% de chances de bloquer les projectiles qui vous visent. L\'Esquive cesse si vous attaquez.','(5...11 secondes.) Vous vous déplacez 33% plus vite et vous avez 27...75% de chances de bloquer les projectiles. Prend fin si vous attaquez.'],
426=>['Tir sauvage','Si le Tir sauvage réussit, l\'action de la cible est interrompue. S\'il s\'agissait d\'un sort, vous infligez 13...28 points de dégâts.','Interrompt une action. Effet de l\'interruption : inflige +13...28 points de dégâts si l\'action est un sort.'],
427=>['Sceau antidote','Vous guérit du Poison, de la Maladie, de l\'Aveuglement et d\'une autre condition.','Vous guérit du Poison, de la Maladie, de l\'Aveuglement et d\'une autre condition.'],
428=>['Flèches incendiaires','Vous lancez des flèches sur la cible ennemie et jusqu\'à 2 ennemis autour de votre cible. Ces ennemis s\'embrasent pendant 1...3 secondes.','Frappe 2 ennemis près de votre cible et inflige la Brûlure (1...3 secondes).'],
429=>['Flèches de Melandru','Pendant 18 secondes, vos flèches provoquent un Saignement de 3...25 secondes et infligent +8...28 points de dégâts si elles touchent une cible se trouvant sous un enchantement.','(18 secondes.) Vos flèches infligent le Saignement (3...25 secondes) et +8...28 points de dégâts aux ennemis enchantés.'],
430=>['Pari du tireur','Pendant 18 secondes, vous gagnez 5...10 points d\'énergie quand vos flèches touchent leur cible, mais en perdez 10 si elles ratent leur objectif.','(18 secondes). Vous gagnez 5...10 points d\'énergie chaque fois que vos flèches font mouche. Vous perdez 10 points d\'énergie chaque fois que vous manquez votre cible.'],
431=>['Flèches de feu','Pendant 24 secondes, vos flèches explosent à l\'impact et infligent 3...18 points de dégâts du feu à la cible et aux ennemis adjacents.','(24 secondes.) Vos flèches infligent 3...18 points de dégâts du feu à la cible et aux ennemis adjacents.'],
432=>['Lecture du vent','Pendant 24 secondes, vos flèches se déplacent deux fois plus vite et infligent 3...10 points de dégâts en plus.','(24 secondes.) +3...10 points de dégâts. Vos flèches se déplacent deux fois plus vite.'],
433=>['Flèches enflammées','Pendant 24 secondes, vos flèches infligent des dégâts du feu et causent 3...24 points de dégâts du feu en plus.','(24 secondes.) +3...24 points de dégâts du feu. Vos flèches infligent des dégâts du feu.'],
434=>['Gaz suffocant','Pendant 1...12 secondes, vos flèches infligent 1...8 points de dégâts en plus et répandent du Gaz suffocant à l\'impact sur tous les ennemis adjacents. Le Gaz suffocant interrompt les ennemis lorsqu\'ils tentent de lancer des sorts.','(1...12 secondes.) +1...8 points de dégâts. Répand du Gaz suffocant sur les ennemis adjacents à la cible. Le Gaz suffocant interrompt les sorts.'],
435=>['Application de poison','Dure 24 secondes. Pendant ce temps, les ennemis frappés par vos attaques physiques sont empoisonnés pendant 3...15 secondes.','(24 secondes.) Vos attaques physiques infligent l\'Empoisonnement (3...15 secondes).'],
436=>['Bien-être animal','Vous soignez votre familier de 40...120 points de vie. S\'il est mort, il est ressuscité avec 10...58% de santé. Si vous utilisez Bien-être animal, votre familier vous accompagnera lors de vos déplacements.','Votre familier gagne 40...120 points de vie. Ressuscite votre familier (10...58% de santé). Si vous utilisez Bien-être animal, votre familier vous accompagnera lors de vos déplacements.'],
437=>['Assaut bestial','Votre familier tente un Assaut bestial qui infligera +5...20 points de dégâts. Si l\'attaque touche un ennemi qui lance un sort, celui-ci sera assommé.','Inflige +5...20 points de dégâts. Attaque assommante si la cible ennemie lance un sort.'],
438=>['Assaut de mutilation','Votre compagnon animal tente une Frappe estropiante qui inflige +5...20 points de dégâts. Si cette attaque porte, cet ennemi subit Infirmité pendant 3...15 secondes.','Inflige +5...20 points de dégâts. Inflige l\'altération Infirmité (3...15 secondes) si cette attaque porte.'],
439=>['Coup barbare','Votre familier tente un Coup barbare qui infligera +5...35 points de dégâts. S\'il touche un ennemi qui attaque, celui-ci sera pris de Saignements pendant 5...25 secondes.','Inflige +5...35 points de dégâts. Inflige le Saignement si l\'ennemi visé attaque (5...25 secondes).'],
440=>['Assaut de charognard','Votre familier tente un Assaut de charognard qui inflige +10...25 points de dégâts. Si cette attaque touche un ennemi qui souffre d\'une condition, vous obtenez 3...15 points d\'énergie.','Inflige +10...25 points de dégâts. Vous gagnez 3...15 points d\'énergie si l\'ennemi visé souffre d\'une condition.'],
441=>['Assaut de Melandru','Votre familier tente un Assaut de Melandru qui inflige +5...20 points de dégâts aux ennemis à proximité.','Inflige 5...20 points de dégâts aux ennemis à proximité.'],
442=>['Attaque féroce','Votre familier tente une Attaque féroce qui inflige +13...28 points de dégâts. Si cette attaque réussit, vous gagnez de l\'adrenaline et 3...10 points d\'énergie.','Inflige +13...28 points de dégâts. Vous gagnez de l\'adrénaline et 3...10 points d\'énergie.'],
443=>['Coup du prédateur','Votre familier tente un Coup du prédateur qui inflige +5...35 points de dégâts. Si cette attaque réussit, votre familier bénéficiera de 5...50 points de vie.','Inflige +5...35 points de dégâts. Votre familier gagne 5...50 points de vie si cette attaque réussit.'],
444=>['Coup brutal','Votre familier tente un Coup brutal qui inflige +5...35 points de dégâts. Si cette attaque touche un ennemi dont la santé est inférieure à 50%, cet ennemi subira +5...35 points de dégâts en plus.','Inflige +5...35 points de dégâts. Inflige +5...35 points de dégâts supplémentaires si l\'ennemi visé a moins de 50% de santé.'],
445=>['Attaque d\'interruption','Votre familier tente une attaque d\'interruption qui inflige +1...12 points de dégâts. Si cette attaque touche un ennemi utilisant une compétence, cette dernière est inutilisable pendant 20 secondes de plus.','Inflige +1...12 points de dégâts. Interrompt une compétence. Effet de l\'interruption : la compétence interrompue est désactivée pendant +20 secondes.'],
446=>['Onguent des trolls','Pendant 13 secondes, vous bénéficiez d\'une régénération de santé de +3...10.','(13 secondes.) Vous bénéficiez d\'une régénération de santé de +3...10.'],
447=>['Cri d\'Otyugh','Pendant 10...25 secondes, votre familier bénéficie d\'un bonus d\'armure de +24 et ne peut pas être bloqué.','(10...25 secondes.) Votre familier bénéficie d\'un bonus d\'armure de +24 et ses attaques ne peuvent être bloquées.'],
448=>['Echappatoire','Pendant 1...8 secondes, vous vous déplacez 33% plus vite et avez 75% de chances de bloquer les attaques.','(1...8 secondes.) Vous vous déplacez 33% plus vite et avez 75% de chances de bloquer.'],
449=>['Pose de pratique','Pendant 20...35 secondes, vos préparations se rechargent 50% plus vite et durent 30...300% plus longtemps.','(20...35 secondes.) Vos préparations se rechargent 50% plus vite et durent 30...300% plus longtemps.'],
450=>['Tourbillon défensif','Pendant 8...20 secondes, vous avez 75% de chances de bloquer les attaques. Bloquer un projectile de la sorte infligera 5...11 points de dégâts aux ennemis adjacents.','(8...20 secondes.) Vous avez 75% de chances de bloquer. Inflige 5...11 points de dégâts aux ennemis adjacents chaque fois que vous bloquez un projectile.'],
451=>['Résistance de Melandru','Pendant 8...20 secondes, votre régénération de santé est de +4 et votre régénération d\'énergie de +1 point pour chaque condition et maléfice dont vous souffrez.','(8...20 secondes.) Votre régénération de santé est de +4 et votre régénération d\'énergie de +1 point pour chaque condition et maléfice qui vous affecte.'],
452=>['Défenses du Drider','Pendant 5...11 secondes, vous avez 75% de chances de bloquer les attaques et bénéficiez d\'un bonus d\'armure de 34...60 contre les dégâts élémentaires.','(5...11 secondes.) Vous avez 75% de chances de bloquer et bénéficiez d\'un bonus d\'armure de +34...60 contre les dégâts élémentaires.'],
453=>['Réflexes foudroyants','Pendant 5...11 secondes, vous avez 75% de chances de bloquer les attaques au corps à corps et les projectiles. Vous attaquez aussi 33% plus vite.','(5...11 secondes.) Vous attaquez 33% plus vite et avez 75% de chances de bloquer.'],
454=>['Fureur du tigre','Toutes vos compétences qui ne sont pas des attaques sont inutilisables pendant 5 secondes. Pendant 5...11 secondes, vous attaquez 25% plus vite.','(5...11 secondes.) Vous attaquez 25% plus vite. Désactive vos compétences non offensives (5 secondes).'],
455=>['Chasseur de tempêtes','Pendant 8...20 secondes, vous vous déplacez 25% plus vite et vous bénéficiez de 1...5 points d\'énergie quand vous subissez des dégâts des éléments.','(8...20 secondes.) Vous vous déplacez 25% plus vite et gagnez 1...5 points d\'énergie chaque fois que vous subissez des dégâts élémentaires.'],
456=>['Vitesse du serpent','Pendant 15...30 secondes, le temps de rechargement de vos compétences est réduit de 33%. La Vitesse du serpent cesse si vous perdez plus de 50% de vos points de vie.','(15...30 secondes.) Vos compétences se rechargent 33% plus vite. Prend fin si votre santé tombe en dessous de 50%.'],
457=>['Piège à poussière','Quand le Piège à poussière se déclenche, chaque seconde (sur un total de 5 secondes), tous les ennemis à proximité sont aveuglés pendant 3...8 secondes et subissent 10...25 points de dégâts. Vous pouvez être facilement interrompu lorsque vous activez cette compétence. Elle prend fin après 90 secondes.','(90 secondes.) Affecte les ennemis à proximité. Inflige 10...25 points de dégâts par seconde (5 secondes). Provoque l\'Aveuglement (3...8 secondes) toutes les secondes (5 secondes). Cette compétence peut être facilement interrompue.'],
458=>['Piège barbelé','Quand le Piège barbelé se déclenche, tous les ennemis proches de la zone d\'effet subissent 7...23 points de dégâts perforants et sont frappés d\'Infirmité et de Saignement pendant 3...25 secondes. Le Piège barbelé fonctionne pendant 90 secondes. Vous pouvez être facilement interrompu lorsque vous utilisez cette compétence.','(90 secondes.) Affecte les ennemis à proximité. Inflige 7...23 points de dégâts perforants. Inflige l\'Infirmité et le Saignement (3...25 secondes). Cette compétence peut être facilement interrompue.'],
459=>['Piège de flammes','Quand le Piège de flammes se déclenche, tous les ennemis proches de la zone d\'effet subissent 5...20 points de dégâts du feu chaque seconde (pendant 3 secondes) et s\'embrasent pendant 1...3 secondes. Le Piège de flammes se termine au bout de 90 secondes. Vous pouvez être facilement interrompu lorsque vous utilisez cette compétence.','(90 secondes.) Affecte les ennemis à proximité. Inflige 5...20 points de dégâts du feu par seconde (3 secondes). Inflige la Brûlure (1...3 secondes). Cette compétence peut être facilement interrompue.'],
460=>['Source de guérison','Pendant 10 secondes, tous les alliés adjacents sont soignés de 15...60 points de vie toutes les 2 secondes. Cette action peut facilement être interrompue.','(10 secondes.) Affecte les alliés adjacents. Soigne de 15...60 points de vie toutes les 2 secondes. Cette compétence peut être facilement interrompue.'],
461=>['Piège à pointes','Quand le Piège à pointes se déclenche, toutes les secondes (pendant 2 secondes au total), tous les ennemis à proximité subissent 10...40 points de dégâts perforants, sont frappés d\'Infirmité pendant 3...25 secondes et sont assommés. Le Piège à pointes prend fin au bout de 90 secondes. Vous pouvez être facilement interrompu lorsque vous utilisez cette compétence.','(90 secondes.) Affecte les ennemis à proximité. Toutes les secondes (pendant 2 secondes) ce piège inflige 10...40 points de dégâts perforants, assomme et frappe d\'Infirmité (3...25 secondes). Cette compétence peut être facilement interrompue.'],
462=>['Hiver','Crée un esprit de niveau 1...10. Pour les créatures dans sa portée, tous les dégâts élémentaires sont transformés en dégâts du froid. Cet esprit disparaît au bout de 30...240 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...240 secondes). Convertit les dégâts élémentaires en dégâts du froid pour les créatures à portée. N\'affecte pas les esprits.'],
463=>['Vannage','Crée un esprit de niveau 1...10. Les créatures (sauf les esprits) dans sa portée subissent 4 points de dégâts supplémentaires chaque fois qu\'elles reçoivent des dégâts physiques. Cet esprit disparaît au bout de 30...240 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...240 secondes). Augmente les dégâts physiques de +4 pour les créatures à portée. N\'affecte pas les esprits.'],
464=>['Voie d\'extinction','Crée un esprit de niveau 1...10. Si une créature (autre qu\'un esprit) dans sa portée meurt, la Voie d\'extinction inflige 14...50 points de dégâts à toutes les créatures de même type qui ont moins de 90% de santé et sont à portée de l\'esprit. Cet esprit disparaît au bout de 30...240 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...240 secondes). Il inflige 14...50 points de dégâts aux créatures à sa portée chaque fois qu\'une créature du même type meurt. N\'affecte pas les esprits. Les créatures qui ont plus de 90% de santé ne subissent aucun dégât.'],
465=>['Grand brasier','Crée un esprit de niveau 1...10. Pour les créatures dans sa portée n\'étant pas des esprits, tous les dégâts physiques sont transformés en dégâts du feu. Cet esprit disparaît au bout de 30...240 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...240 secondes). Convertit les dégâts physiques en dégâts du feu pour les créatures à portée. N\'affecte pas les esprits.'],
466=>['Brasier','Crée un esprit de niveau 1...10. Pour les créatures (autres que des esprits) se trouvant dans sa portée, toutes vos flèches qui touchent leur objectif infligent des dégâts du feu. Cet esprit disparaît au bout de 30...240 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...240 secondes). Toutes les flèches infligent des dégâts du feu pour les créatures à portée. N\'affecte pas les esprits.'],
467=>['Saison fertile','Crée un esprit de niveau 1...10. Les créatures n\'étant pas des esprits dans sa portée ont +50...150 de santé maximum et bénéficient d\'un bonus d\'armure de +8. Cet esprit disparaît au bout de 15...90 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 15...90 secondes). Les créatures à portée bénéficient de +50...150 de santé maximum et d\'un bonus d\'armure de +8. N\'affecte pas les esprits.'],
468=>['Symbiose','Crée un esprit de niveau 1...10. Pour chaque enchantement lancé sur une créature autre qu\'un esprit dans sa portée, celle-ci bénéficie de +27...150 de santé maximum. Cet esprit disparaît au bout de 30...240 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...240 secondes). Les créatures à portée bénéficient de +27...150 de santé maximum par enchantement les affectant. N\'affecte pas les esprits.'],
469=>['Echos primitifs','Crée un esprit de niveau 1...10. Pour les créatures dans sa portée (sauf les esprits), l\'utilisation des sceaux coûte 10 points d\'énergie. Cet esprit disparaît au bout de 30...240 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...240 secondes). Les sceaux coûtent 10 points d\'énergie pour les créatures à portée. N\'affecte pas les esprits.'],
470=>['Saison des prédateurs','Crée un esprit de niveau 1...10. Pour les créatures dans sa portée autres que des esprits, la guérison est réduite de 20%. Si vos attaques réussissent, vous gagnerez 5 points de vie. Cet esprit disparaît au bout de 30...240 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...240 secondes). Les soins rendent 20% de santé en moins aux créatures à portée. Elles gagnent 5 points de vie chaque fois qu\'elles réussissent une attaque. N\'affecte pas les esprits.'],
471=>['Terre gelée','Crée un esprit de niveau 1...10. Les créatures autres que des esprits dans sa portée ne peuvent pas activer de compétences de résurrection. Cet esprit meurt au bout de 30...180 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...180 secondes). Les créatures à portée ne peuvent pas activer de compétences de résurrection. N\'affecte pas les esprits.'],
472=>['Vents favorables','Crée un esprit de niveau 1...10. Pour les créatures à sa portée (sauf les esprits), les flèches volent deux fois plus vite et infligent +6 points de dégâts. Cet esprit disparaît au bout de 30...240 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...240 secondes). Les flèches se déplacent deux fois plus vite et infligent +6 points de dégâts pour les créatures à portée. N\'affecte pas les esprits.'],
474=>['Vent énergisant','Crée un esprit de niveau 1...6. Pour les créatures dans sa portée autres que des esprits, toutes les compétences coûtent 15 points d\'énergie en moins (coût minimum de 10 points) et se rechargent 25% moins vite. Cet esprit disparaît au bout de 1...60 secondes.','Crée un esprit de niveau 1...6 (durée de vie de 1...60 secondes). Le coût en énergie des compétences est réduit de 15 points (coût minimum de 10 points d\'énergie) et leur temps de recharge est accru de 25% pour les créatures à portée. N\'affecte pas les esprits.'],
475=>['Zéphyr véloce','Crée un esprit de niveau 1...10. Pour les créatures dans sa portée autres que des esprits, toutes les compétences se rechargent deux fois plus vite et leur utilisation consomme 30% du coût en énergie de base. Cet esprit disparaît au bout de 15...90 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 15...90 secondes). Les compétences coûtent 30% d\'énergie en plus et se rechargent deux fois plus vite pour les créatures à portée. N\'affecte pas les esprits.'],
476=>['Renouveau de la nature','Crée un esprit de niveau 1...10. Pendant 30...240 secondes, la durée d\'incantation de tous les enchantements et maléfices lancés par des créatures (autres que des esprits) est doublée. Le maintien des enchantements consomme deux fois plus d\'énergie. Cet esprit disparaît au bout de 30...240 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...240 secondes). Pour les créatures à portée, les enchantements et les maléfices sont deux fois plus longs à lancer et le maintien des enchantements coûte deux fois plus d\'énergie. N\'affecte pas les esprits.'],
477=>['Terrain boueux','Crée un esprit de niveau 1...10. Toutes les créatures dans sa portée autres que des esprits se déplacent 10% moins vite et les augmentations de vitesse n\'ont pas d\'effet. Cet esprit disparaît au bout de 30...180 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...180 secondes). Les créatures à portée se déplacent 10% moins vite ; annule également les augmentations de vitesse. N\'affecte pas les esprits.'],
570=>['Marque d\'insécurité','Pendant 5...25 secondes, la cible ennemie souffre d\'une dégénération de santé de -1...5, et les enchantements et poses de combat sur cet ennemi prennent fin 20...60% plus vite. Toutes vos compétences autres que celles d\'Assassin sont désactivées pendant 5 secondes.','(5...25 secondes.) Inflige -1...5 points de dégénération de santé. Les enchantements et les postures de l\'ennemi ciblé prennent fin 20...60% plus vite. Désactive vos compétences autres que celles d\'Assassin (5 secondes).'],
571=>['Dague d\'interruption','Vous envoyez une Dague d\'interruption sur la cible ennemie qui inflige 10...35 points de dégâts de la terre. Si cet ennemi était en train d\'activer une compétence, celle-ci est interrompue. Sa portée est la moitié de celle d\'un sort normal.','Projectile : inflige 10...35 points de dégâts de la terre. Interrompt une compétence.'],
572=>['Paradoxe mortel','Toutes vos compétences d\'attaques sont inutilisables pendant 10 secondes. Pendant 5...15 secondes, vos compétences d\'Assassin s\'activent et se rechargent 33% plus vite.','(5...15 secondes.) Vos compétences d\'Assassin s\'activent et se rechargent 33% plus vite. Désactive vos compétences d\'attaque (10 secondes).'],
763=>['Regard ictérique','Dissipe un enchantement de la cible ennemie. Si un enchantement a été dissipé, pendant les 1...20 prochaines secondes, l\'incantation de votre prochain enchantement est réduite de 0...1 secondes et coûte 1...10 points d\'énergie en moins.','Dissipe un enchantement de la cible ennemie. Effet de la dissipation : l\'incantation de votre prochain enchantement est réduite de 0...1 secondes et coûte 1...10 points d\'énergie en moins. (1...20 secondes.)'],
764=>['Complainte Funeste','Pendant 2...6 secondes, toutes les caractéristiques de la cible ennemie se remettent à 0.','(2...6 secondes.) Les caractéristiques de la cible ennemie se remettent à 0.'],
766=>['Regard du mépris','Si la cible visée possède plus de 50% de santé, elle perd tous ses enchantements.','Supprime les enchantements de la cible ennemie. Aucun effet si la santé de cet ennemi est inférieure à 50%.'],
769=>['Défense de la vipère','Tous les ennemis adjacents sont empoisonnés pendant 5...20 secondes. Vous faites une Foulée de l\'ombre jusqu\'à une position proche directement opposée à votre cible.','Inflige l\'Empoisonnement (5...20 secondes) à tous les ennemis adjacents. Vous faites une Foulée de l\'ombre jusqu\'à une position proche directement opposée à votre cible.'],
770=>['Retour','Tous les ennemis adjacents souffrent d\'Infirmité pendant 3...8 secondes. Vous faites une Foulée de l\'ombre jusqu\'à la position de l\'allié visé.','Provoque l\'Infirmité (3...8 secondes) chez tous les ennemis adjacents. Vous effectuez une foulée de l\'ombre vers la position de la cible alliée. Vous ne pouvez pas vous prendre pour cible.'],
771=>['Aura de déplacement','Lorsque vous lancez l\'Aura de déplacement, vous faites une Foulée de l\'Ombre vers l\'ennemi ciblé. Lorsque vous cessez d\'utiliser l\'Aura de déplacement, vous retournez à votre position d\'origine.','Vous faites une foulée de l\'ombre vers la cible ennemie. Effet final : vous retournez sur votre position d\'origine.'],
772=>['Tsungrai était généreux','Vous tenez les cendres de Tsungrai pendant un maximum de 15...60 secondes et vous bénéficiez de +50...140 points de vie. Lorsque vous les déposez, vous bénéficiez de 100...280 points de vie.','(15...60 secondes.) Vous avez +50...140 de santé maximum. Effet de la pose : vous gagnez 100...280 points de vie.'],
773=>['Vorizon était puissant','Vous tenez ses cendres jusqu\'à un maximum de 15...60 secondes. Pendant ce temps, vous bénéficiez d\'un bonus d\'armure de +15 et d\'un maximum d\'énergie de +30.','(15...60 secondes.) Vous bénéficiez d\'un bonus d\'armure de +15 et de +30 d\'énergie maximum.'],
775=>['Efflorescence mortelle','Doit succéder à une attaque main gauche. Si elle réussit, l\'Efflorescence mortelle inflige +20...45 points de dégâts à l\'ennemi visé et tous les ennemis adjacents reçoivent 20...45 points de dégâts.','Inflige +20...45 points de dégâts. Affecte également les ennemis adjacents à la cible. Doit succéder à une attaque main gauche.'],
776=>['Crocs incisifs','Doit succéder à une attaque main gauche. Si l\'attaque réussit, elle inflige +10...20 points de dégâts et l\'ennemi touché est pris de Saignements et souffre de Blessure profonde pendant 5...20 secondes.','Inflige +10...20 points de dégâts. Provoque le Saignement et la Blessure profonde (5...20 secondes). Doit succéder à une attaque main gauche.'],
777=>['Cornes du boeuf','Doit succéder à une attaque main gauche. Si l\'attaque réussit, elle inflige +1...11 points de dégâts. Si l\'ennemi touché n\'est adjacent à aucun de ses alliés, il est assommé.','Inflige +1...11 points de dégâts. Assomme la cible ennemie si cette dernière n\'est pas adjacente à l\'un de ses alliés. Doit succéder à une attaque main gauche.'],
778=>['Retombée arachnide','Doit toucher un ennemi assommé. Si elle réussit, la Retombée arachnide inflige +15...35 points de dégâts et l\'ennemi visé est empoisonné pendant 5...20 secondes.','Inflige +15...35 points de dégâts. Provoque l\'Empoisonnement (5...20 secondes). Aucun effet si la cible ennemie n\'est pas assommée.'],
779=>['Coup du lotus noir','Si le coup du lotus réussit, il inflige +10...31 points de dégâts. Si la cible ennemie souffre d\'un maléfice, vous gagnez 5...13 points d\'énergie.','Inflige +10...31 points de dégâts. Vous gagnez 5...13 points d\'énergie si la cible ennemie souffre d\'un maléfice.'],
780=>['Crocs du renard','Doit succéder une attaque main droite. Crocs du renard ne peut pas être bloqué et inflige +10...35 points de dégâts si l\'attaque réussit.','Inflige +10...35 points de dégâts. Impossible à bloquer. Doit succéder à une attaque main droite.'],
781=>['Frappe de Moebius','Doit succéder à une attaque d\'ambidextrie. Si elle réussit, la Frappe de Moebius inflige +10...35 points de dégâts. Si vous touchez un ennemi dont la santé est inférieure à 50%, toutes vos autres compétences d\'attaque seront rechargées.','Inflige +10...35 points de dégâts. Recharge toutes vos autres compétences d\'attaque si la santé de la cible ennemie est inférieure à 50%. Doit succéder à une attaque d\'ambidextrie.'],
782=>['Coup déchiqueteur','Si le Coup déchiqueteur réussit, la cible sera prise de Saignements pendant 5...20 secondes.','Provoque le Saignement (5...20 secondes).'],
783=>['Attaque sournoise','Si l\'attaque réussit, vous infligez +19...31 points de dégâts. Si votre cible possède plus de 90% de sa santé, vous lui infligez 15...75 points de dégâts supplémentaires.','Inflige +19...31 points de dégâts. Inflige 15...75 points de dégâts supplémentaires si la santé de la cible ennemie est supérieure à 90%.'],
784=>['Enlacement reptilien','L\'Enlacement reptilien doit succéder à une attaque main droite. La cible ennemie est assommée. Elle est empoisonnée pendant 5...20 secondes.','Attaque assommante. provoque l\'Empoisonnement (5...20 secondes). Doit succéder à une attaque main droite.'],
785=>['Stigmate mortel','Pendant 4...10 secondes, l\'ennemi visé reçoit 50% de guérison en moins.','(4...10 secondes.) La cible ennemie reçoit 50% de guérison en moins.'],
786=>['Paume d\'acier','La cible ennemie touchée subit 5...50 points de dégâts, et si elle souffre d\'une condition ou d\'un maléfice, elle est assommée. Cette compétence est considérée comme une attaque main droite.','Inflige 5...50 points de dégâts. Assomme la cible ennemie si cette dernière souffre d\'un maléfice ou d\'une condition. Compte comme une attaque main droite.'],
787=>['Arme résistante','Pendant 3...12 secondes, la cible (un allié ou vous-même) possède l\'Arme résistante. Pendant qu\'elle souffre d\'un maléfice ou d\'une condition, cette cible bénéficie d\'une régénération de santé de +1...6 et d\'un bonus d\'armure de +24.','(3...12 secondes.) Régénération de santé de +1...6 et bonus d\'armure de +24. Aucun effet si l\'allié visé n\'est pas affecté par un maléfice ou une condition.'],
788=>['Mingson était aveugle','Vous tenez les cendres de Mingson pendant un maximum de 15...60 secondes. Lorsque vous les déposez, tous les ennemis proches sont aveuglés pendant 3...8 secondes.','(15...60 secondes.) Effet de la pose : inflige l\'Aveuglement (3...8 secondes) à tous les ennemis à proximité.'],
789=>['Kuurong était avide','Vous tenez les cendres de Kuurong pendant un maximum de 15...60 secondes. Lorsque vous les déposez, tous les ennemis adjacents reçoivent 15...75 points de dégâts et sont assommés.','(15...60 secondes.) Effet si lâché : inflige 15...75 points de dégâts et renverse tous les ennemis dans la zone.'],
790=>['Khanhei était revanchard','Vous tenez les cendres de Khanhei pendant 5...11 secondes. Chaque fois qu\'un ennemi vous touche au combat pendant que vous tenez les cendres, vous absorbez 10...45 points de vie à l\'ennemi.','(5...11 secondes.) Vous volez 10...45 points de vie à chaque ennemi vous touchant avec une attaque.'],
791=>['Chair de ma chair','Vous perdez la moitié de vos points de vie. Vous ressuscitez le membre du groupe ciblé avec le nombre de points de vie actuel dont vous disposez et 5...20% d\'énergie.','Ressuscite le membre du groupe visé. Il revient à la vie avec la moitié de votre capital actuel de points de vie et 5...20% d\'énergie. Vous perdez la moitié de vos points de vie.'],
792=>['Arme à fragmentation','Pendant 20 secondes, la cible (un allié ou vous-même) possède une Arme à fragmentation. 1...5 de ses prochaines attaques réussies infligent 5...50 points de dégâts à 4 ennemis adjacents maximum.','(20 secondes.) Les attaques infligent 5...50 points de dégâts à 3 ennemis adjacents. Prend fin au bout de 1...5 attaques.'],
793=>['Arme de protection','Pendant 3...8 secondes, la cible (un allié ou vous-même) possède une Arme de protection, qui lui confère une régénération de santé de +2...4 et 50% de chances de bloquer les attaques.','(3...8 secondes.) Confère une régénération de santé de +2...4. 50% de chances de bloquer.'],
794=>['Arme des doléances','Pendant 3...14 secondes, la cible (un allié ou vous-même) a l\'arme des doléances en sa possession. Chaque fois que l\'Arme des doléances touche un ennemi qui attaque, celui-ci est interrompu.','(3...14 secondes.) Les attaques interrompent les ennemis qui attaquent.'],
795=>['Arme du tourment','Pendant 12 secondes, la cible (un allié ou vous-même) possède une Arme du tourment. Les prochaines attaques (au nombre de 3) de la cible (un allié ou vous-même) infligent 10...50 points de dégâts en moins et absorbent jusqu\'à 10...50 points de vie.','(12 secondes.) Les attaques de l\'allié visé volent 10...50 points de vie mais infligent 10...50 points de dégâts en moins. Prend fin au bout de 3 attaques.'],
799=>['Mirage brumeux','Vous faites une Foulée de l\'ombre jusqu\'à la cible ennemie. Elle sera frappée de Stupeur pendant 3...9 secondes.','Vous faites une Foulée de l\'ombre vers cet ennemi. Inflige la Stupeur (3...9 secondes).'],
800=>['Toxine immuable','Pendant 5 secondes, la cible ennemie souffre d\'une dégénération de santé de -1...5. Si cet ennemi est en mouvement lorsque la Toxine immuable doit prendre fin, elle durera pendant encore 5 secondes.','(5 secondes.) Provoque une dégénération de santé de -1...5. Renouvellement : si l\'ennemi visé se déplace lorsque ce maléfice prend fin.'],
801=>['Linceul du silence','Tous vos sorts sont inutilisables pendant 15 secondes. Pendant 1...6 secondes, la cible ennemie touchée ne peut pas lancer de sorts.','(1...6 secondes.) La cible ennemie ne peut pas lancer de sorts. Vos sorts sont désactivés pendant 15 secondes.'],
802=>['Vaines défenses','Pendant 1...11 secondes la cible ennemie ne peut pas bloquer vos attaques.','(1...11 secondes.) La cible ennemie ne peut pas bloquer vos attaques.'],
803=>['Buveur d\'énergie','Si l\'ennemi visé lance un sort ou un chant, celui-ci est interrompu et pendant 10 secondes, à chaque fois que cet ennemi lance un sort, vous lui volez jusqu\'à 5...15 points d\'énergie.','interrompt un sort ou un chant. Effet de l\'interruption : vole 5...15 points d\'énergie chaque fois qu\'une cible ennemie lance un sort (10 secondes).'],
804=>['Alanguissement arcane','Pendant 1...10 secondes, tous les sorts lancés par l\'ennemi visé entraînent un Afflux de 10.','(1...10 secondes.) Les sorts de l\'ennemi visé entraînent un Afflux de 10.'],
805=>['Animation d\'horreur vampirique','Utilisez le cadavre le plus près pour animer une Horreur vampirique de niveau 1...17. A chaque fois que l\'horreur vampirique sous votre contrôle inflige des dégâts, vous récupérez la même quantité en points de vie.','Crée une horreur vampirique de niveau 1...17. Vous gagnez un nombre de points de vie égal aux dégâts qu\'elle inflige. Exploite un cadavre récent.'],
806=>['Ferveur de l\'adepte','Pendant 5 secondes et 3 secondes supplémentaires par rang de Moisson des âmes, les sorts de Nécromant que vous lancez vous coûtent -1...6 points d\'énergie, mais vous souffrez de Saignement pendant 10 secondes à chaque fois que vous les lancez.','(5 secondes plus 3 secondes pour chaque rang de Moisson des âmes.) Le coût de vos sorts de Nécromant est réduit de 1...6 points d\'énergie. Vous souffrez de Saignement (10 secondes) à chaque fois que vous les lancez.'],
808=>['Empreinte du Faucheur','Pendant 30 secondes, la cible ennemie souffre d\'une dégénération de santé de -1...5. Si elle meurt sous l\'effet de l\'Empreinte du Faucheur, vous bénéficiez de 5...15 points d\'énergie.','(30 secondes.) Provoque une dégénération de santé de -1...5. Vous gagnez 5...15 points d\'énergie si la cible ennemie meurt lorsqu\'elle souffre de ce maléfice.'],
809=>['Brise-roc','La cible ennemie subit 25...100 points de dégâts du froid, se déplace 66% plus lentement et souffre du maléfice Brise-roc pendant 3 secondes. Lorsqu\'il prend fin, cet ennemi et tous ceux à proximité subissent 25...100 points de dégâts du froid.','(3 secondes.) Effet initial : inflige 25...100 points de dégâts du froid, et la cible se déplace 66% plus lentement. Effet final : inflige 25...100 points de dégâts du froid à la cible et à tous les ennemis adjacents.'],
810=>['Défense du protecteur','Pendant 5...11 secondes, les alliés adjacents à votre position ont 75% de chances de bloquer les attaques. La défense du protecteur prend fin si vous bougez.','(5...11 secondes.) Les alliés adjacents à votre position ont 75% de chances de bloquer. Prend fin si vous vous déplacez.'],
811=>['Course unique','Pendant 5...15 secondes, vous et votre familier vous déplacez 25% plus vite.','(5...15 secondes.) Vous et votre familier vous déplacez 25% plus vite.'],
812=>['Xinrae était rebelle','Vous tenez les cendres de Xinrae pendant un maximum de 15...60 secondes. Pendant ce temps, vous ne pouvez pas perdre plus de 20% de votre santé maximum par attaque. Lorsque vous déposez ses cendres, vous volez 5...50 points de vie à tous les ennemis à proximité.','(15...60 secondes.) Vous ne pouvez pas perdre plus de 20% de votre santé maximum par attaque. Effet de la pose : vous volez 5...50 points de vie aux ennemis à proximité.'],
813=>['Aura de Lyssa','Pendant 10 secondes, vous bénéficiez d\'une régénération d\'énergie de +0...5. Cet enchantement se réapplique chaque fois que vous lancez un sort sur un ennemi.','(10 secondes.) Vous bénéficiez d\'une régénération d\'énergie de +0...5. Renouvellement : chaque fois que vous lancez un sort sur un ennemi.'],
814=>['Refuge ombreux','Pendant 6 secondes, vous bénéficiez d\'une régénération de santé de +5...10. Lorsque le Refuge Ombreux se termine, vous gagnez 40...100 points de vie si vous attaquez.','(6 secondes.) Vous bénéficiez d\'une régénération de santé de +5...10. Effet final : vous soigne de 40...100 points de vie si vous attaquez.'],
815=>['Attache de Scorpion','Pendant 8...20 secondes, la prochaine fois que vous et l\'ennemi ciblé êtes séparés de plus de 22 mètres, vous vous téléportez jusqu\'à cet ennemi, qui sera alors assommé. La portée de ce sort est la moitié de celle d\'un sort normal.','(8...20 secondes.) Vous vous téléportez sur la cible ennemie et l\'assommez la prochaine fois que cette cible se trouve à plus de 22 mètres de vous.'],
816=>['Imitation de pose','Pendant 10...35 secondes, chaque fois que la cible ennemie adopte une pose de combat, vous prenez la même pose.','(10...35 secondes.) Vous adoptez la pose utilisée par la cible ennemie.'],
817=>['Discorde','Si la cible ennemie souffre d\'une condition et est affectée par un maléfice ou un enchantement, elle subit 30...110 points de dégâts.','Inflige 30...110 points de dégâts. Sans effet si la cible ennemie ne souffre d\'aucune condition et n\'est victime d\'aucun maléfice ou enchantement.'],
818=>['Puits de Lassitude','Exploitez le cadavre visé ou sacrifiez 66% de santé pour créer un Puits de lassitude pendant 10...55 secondes. Les ennemis se trouvant dans ce puits subissent une dégénération d\'énergie de -1.','(10...55 secondes.) Les ennemis présents dans ce puits subissent -1 point de dégénération d\'énergie. Exploite un cadavre frais ou sacrifie 66% de la santé.'],
819=>['Esprit vampirique','Vous volez jusqu\'à 15...60 points de vie à la cible ennemie. Pendant 10 secondes, vous bénéficiez d\'une régénération de santé de +5...10.','Vous volez 15...60 points de vie à la cible ennemie. Vous bénéficiez d\'une régénération de santé de +5...10 (10 secondes).'],
820=>['Dépravation','Pendant 5...20 secondes, chaque fois qu\'une cible ennemie lance un sort, cet ennemi et un ennemi à proximité perdent 1...5 points d\'énergie.','(5...20 secondes.) Provoque une perte de 1...5 points d\'énergie chaque fois que l\'ennemi visé lance un sort. Un ennemi à proximité de votre cible perd aussi de l\'énergie.'],
821=>['Veines glaciales','La cible ennemie souffre de 10...90 points de dégâts du froid. Pendant 10...35 secondes, si la cible ennemie meurt, tous les ennemis à proximité souffrent de 20...110 points de dégâts du froid.','(10...35 secondes.) Inflige 20...110 points de dégâts du froid aux ennemis à proximité si la cible ennemie meurt. Effet initial : inflige 10...90 points de dégâts du froid.'],
822=>['Genoux flageolants','Pendant 1...16 secondes, la cible ennemie souffre d\'une dégénération de santé de -1...4 et subit 5...20 points de dégâts en se déplaçant.','(1...16 secondes.) La cible ennemie souffe d\'une dégénération de santé de -1...4 et subit 5...20 points de dégâts en se déplaçant.'],
823=>['Vélocité Incandescente','Pendant 7 secondes, votre vitesse est augmentée et vous vous déplacez 30...45% plus vite. Lorsque la Vélocité Incandescente prend fin, tous les ennemis à proximité s\'embrasent pendant 3...9 secondes.','(7 secondes.) Vous vous déplacez 30...45% plus vite. Vous souffrez de Brûlure (7 secondes).Effet final : inflige la Brûlure (3...9 secondes) aux ennemis adjacents.'],
824=>['Flèches de Lave','Les Flèches de Lave se dirigent vers un maximum de 3 ennemis proches de votre cible et infligent 20...65 points de dégâts du feu si elles atteignent leur cible.','Projectile : inflige 20...65 points de dégâts du feu. Effet bonus : envoie des projectiles sur 2 autres ennemis proches de votre cible.'],
825=>['Lit de Braise','Vous créez un Lit de Braise sur la position de l\'ennemi. Pendant 5 secondes, les ennemis adjacents à l\'ennemi visé subissent 5...29 points de dégâts du feu par seconde. Les ennemis renversés sur le Lit de Braise s\'embrasent pendant 3...7 secondes.','Inflige 5...29 points de dégâts du feu par seconde (5 secondes) à la position de la cible. Frappe les ennemis adjacents à votre cible. Embrase (3...7 secondes) les ennemis renversés.'],
826=>['Silhouette','Pendant 5...21 secondes, vous ne pouvez pas être la cible de sorts ennemis, et vous bénéficiez d\'une réduction de dégâts de 5 pour chaque enchantement d\'Assassin vous affectant. Vous ne pouvez pas infliger plus de 5...25 points de dégâts avec une seule compétence ou attaque.','(5...21 secondes.) Vous ne pouvez pas être la cible de sorts ennemis. Vous gagnez 5 points de réduction de dégâts chaque fois qu\'un enchantement d\'Assassin vous affecte. Vous ne pouvez pas infliger plus de 5...25 points de dégâts avec une seule compétence ou attaque.'],
827=>['Siphon de force','Pendant 5...20 secondes, la cible ennemie inflige -5...50 points de dégâts avec ses attaques et toutes vos attaques contre cet ennemi ont 50% de chances supplémentaires d\'être des coups critiques.','(5...20 secondes.) La cible ennemie inflige -5...50 points de dégâts lors de ses attaques. Vous avez +50% de chances d\'infliger un coup critique à cet ennemi.'],
828=>['Miasme insalubre','L\'ennemi visé subit 10...65 points de dégâts du froid. S\'il est affecté par une condition, cet ennemi est touché par le maléfice Miasme insalubre et subit une dégénération de santé de -1...5 pendant 10 secondes.','Provoque une dégénération de santé de -1...5 (10 secondes). Effet initial : inflige 10...65 points de dégâts du froid. Le maléfice n\'est appliqué que si la cible ennemie souffre d\'une condition.'],
830=>['Lumière du jugement','Invoque Lumière de jugement sur la position de la cible ennemie. Pendant 5 secondes, les ennemis adjacents à cette position subissent 10...50 points de dégâts sacrés et s\'embrasent pendant 1...3 secondes toutes les secondes.','Inflige 10...50 points de dégâts sacrés et une Brûlure (1...3 secondes) toutes les secondes (5 secondes). Frappe les ennemis adjacents à la position initiale de la cible.'],
831=>['Rage primitive','Pendant 1...9 secondes, vous attaquez 33% plus vite et vous vous déplacez 33% plus rapidement, mais vous subissez 150...125% de dégâts.','(1...9 secondes.) Vous attaquez 33% plus vite et vous vous déplacez 33% plus rapidement. Vous subissez 150...125% de dégâts.'],
832=>['Animation du Golem de chair','Utilisez le cadavre le plus proche pour animer un Golem de chair de niveau 3...25. Ce Golem de chair laisse 1...4 cadavres que vous pourrez utiliser. Vous ne pouvez disposer que d\'un seul Golem de chair à la fois.','Crée un golem de chair de niveau 3...25 qui laisse 1...4 cadavres récents lorsqu\'il meurt. Exploite un cadavre récent. Vous ne pouvez avoir qu\'un seul golem de chair à la fois.'],
834=>['Extrême hâte','Pendant 6...12 secondes, la cible visée et tous les ennemis adjacents subissent les effets du maléfice Extrême hâte. Pendant ce temps, ils attaquent 25% plus vite mais ont 50% de chances de manquer leurs attaques.','Inflige également des maléfices aux ennemis adjacents à votre cible (6...12 secondes). Ces derniers ont 50% de chances d\'échouer mais attaquent 25% plus vite.'],
835=>['Lien du sang','Pendant 3...12 secondes, la cible ennemie et tous les ennemis adjacents sont affectés par le Lien du sang. Chaque fois qu\'un allié frappe l\'un d\'eux, cet allié gagne 5...20 points de vie. Si l\'un de ces ennemis meurt alors qu\'il est affecté par un maléfice, tous les alliés adjacents à cet ennemi reçoivent 20...100 points de vie.','Inflige également des maléfices aux ennemis adjacents à votre cible (3...12 secondes). Les alliés frappant ces ennemis reçoivent 5...20 points de vie. Si l\'un de ces ennemis meurt alors qu\'il affecté par un maléfice, les alliés adjacents sont soignés de 20...100 points.'],
836=>['Chevauchée de l\'éclair','Vous rejoignez la cible à la vitesse de l\'éclair. Tous les ennemis adjacents sont aveuglés pendant 1...5 secondes. Si votre cible est un ennemi, il subit 10...70 points de dégâts de la foudre. Ce sort a une pénétration d\'armure de 25%.','Inflige 10...70 points de dégâts de la foudre. 25% de pénétration d\'armure. Aveugle tous les ennemis adjacents (1...5 secondes). Vous rejoignez la cible instantanément. La cible peut être un allié.'],
837=>['Compagnon d\'énergie','Pendant 36...60 secondes, le Compagnon d\'énergie augmente votre maximum de PV et celui de l\'allié ciblé à raison de 1...3 par point d\'énergie maximum de chacun. A la première application de cet enchantement, votre cible et vous gagnez 1...12 points d\'énergie. Vous gagnez 1 point d\'énergie supplémentaire tous les 2 points de Conservation d\'énergie.','(36...60 secondes.) Votre maximum de PV et celui de l\'allié ciblé augmentent de 1...3 par point d\'énergie maximum. Effet initial : vous gagnez tous deux 1...12 points d\'énergie. Vous gagnez +1 point d\'énergie tous les 2 points de Conservation d\'énergie.'],
838=>['Douleur de Dwayna','Pendant 30 secondes, la cible (un allié ou vous-même) et tous les alliés à proximité sont enchantés par la Douleur de Dwayna. Si un allié meurt sous les effets de l\'enchantement, votre groupe est soigné de 5...50 points de vie.','Enchante les alliés près de votre cible (30 secondes). Votre groupe est soigné de 5...50 points de vie chaque fois qu\'un de ses alliés meurt.'],
839=>['"Battez en retraite !"','Si des alliés morts se trouvent à portée de voix, votre groupe se déplace 33% plus vite pendant 5...11 secondes.','(5...11 secondes.) Les membres du groupe à portée de voix se déplacent 33% plus vite. Ne fonctionne que si des alliés morts se trouvent à portée de voix.'],
840=>['Coeur empoisonné','Tous les ennemis à proximité et vous-même êtes empoisonnés pendant 5...15 secondes.','Provoque l\'Empoisonnement (5...15 secondes) chez les ennemis adjacents. Vous êtes également empoisonné.'],
841=>['Humus fétide','La cible ennemie subit 15...65 points de dégâts du froid. Si elle est assommée, la cible ennemie est empoisonnée pendant 5...20 secondes.','Inflige 15...65 points de dégâts du froid. Provoque l\'Empoisonnement (5...20 secondes) si la cible ennemie est assommée.'],
842=>['Arc foudroyant','La cible ennemie subit 5...40 points de dégâts de la foudre. Si vous êtes en état d\'Afflux, deux ennemis prroches de l\'ennemi visé subissent 15...85 points de dégâts de la foudre. Les dégâts infligés par l\'Arc foudroyant ont 25% de pénétration d\'armure.','Inflige 5...40 points de dégâts de la foudre. Inflige 15...85 points de dégâts de la foudre à deux ennemis proches si vous êtes en état d\'Afflux. 25% de pénétration d\'armure.'],
843=>['Rafale','Pendant 5...11 secondes, l\'allié ciblé et vous-même vous déplacez 33% plus vite. Lorsque vous lancez ce sort, tous les ennemis adjacents à vous ou à votre cible subissent 15...70 points de dégâts de froid. Les ennemis touchés par Rafale alors qu\'ils attaquent ou se déplacent sont renversés.','(5...11 secondes.) Vous et l\'allié ciblé vous déplacez 33% plus vite. Effet initial : les ennemis adjacents à vous ou à l\'allié ciblé subissent 15...70 points de dégâts de froid. Les ennemis qui attaquent ou se déplacent sont renversés.'],
844=>['Bouleversement terrestre','Crée un Bouleversement terrestre sur la position de l\'ennemi. Durant les 5 secondes qui suivent, Bouleversement terrestre inflige 10...40 points de dégâts de la terre par seconde aux ennemis à proximité de cette position. Tout ennemi se déplaçant plus vite que la normale lorsqu\'il est touché par le Bouleversement terrestre est renversé.','Inflige 10...40 points de dégâts de la terre par seconde (5 secondes). Frappe les ennemis à proximité de la position initiale de la cible. Renverse les ennemis qui se déplacent plus vite que la normale.'],
845=>['Flamme liquide','La cible ennemie subit 7...112 points de dégâts du feu. Si cet ennemi est en train d\'attaquer ou de lancer un sort, les ennemis à proximité subissent aussi 7...112 points de dégâts du feu.','Inflige 7...112 points de dégâts de feu. Inflige 7...112 points de dégâts du feu aux ennemis près de votre cible si cette dernière attaque ou lance un sort.'],
846=>['Buée','La cible ennemie subit 20...60 points de dégâts du froid. Si l\'ennemi ciblé est en feu, la Buée l\'aveugle pendant 5...10 secondes et il subit 20...60 points de dégâts du feu en plus.','Inflige 20...60 points de dégâts du froid. Provoque l\'Aveuglement (5...10 secondes) et inflige 20...60 points de dégâts du feu si l\'ennemi est affecté par Brûlure.'],
847=>['Sceau du compagnon','Soigne l\'allié ciblé de 20...80 points de vie. Votre prochain sort de Prière de guérison ou de Prière de protection qui vise un allié soigne de 20...100 points de vie supplémentaires.','Soigne de 20...80 points de vie. Votre prochain sort de Prière de guérison ou de Prière de protection qui vise un allié soigne de 20...100 points de vie supplémentaires.'],
848=>['Inversion de maléfice','Lève un maléfice qui frappe la cible. Si un maléfice a été supprimé de cette manière, pendant 5...10 secondes, la prochaine fois que la cible alliée subit des dégâts, ces derniers sont réduits de 5...50 points.','(5...10 secondes.) Supprime un maléfice de l\'allié visé. Les prochains dégâts qu\'il subira seront réduits de 5...50. Aucun effet si l\'allié n\'est pas affecté par un maléfice.'],
849=>['Taillade lacérante','Si l\'attaque réussit, vous infligez +5...20 points de dégâts. Si elle touche un ennemi assommé, celui-ci sera pris de Saignements pendant 5...20 secondes.','Inflige +5...20 points de dégâts. Inflige le Saignement (5...20 secondes) si la cible ennemie est assommée.'],
850=>['Attaque féroce','Sii Attaque féroce réussit, elle inflige +5...20 points de dégâts. Si l\'ennemi visé souffrait de Faiblesse, il souffre aussi à présent de Blessure profonde pendant 1...8 secondes.','Inflige +5...20 points de dégâts. Inflige Blessure profonde (1...8 secondes si la cible ennemie est Affaiblie.'],
851=>['Attaque lunisolaire','Vous attaquez la cible deux fois. Ces attaques ne peuvent pas être bloquées.','Vous attaquez la cible ennemie à deux reprises. Impossible à bloquer.'],
852=>['Tir de ricochet','Si Tir de ricochet réussit, vous infligez +3...15 points de dégâts. Si Tir de ricochet est bloqué, tous les ennemis à proximité de votre cible subissent 5...65 points de dégâts.','Inflige 3...15 points de dégâts. Inflige 5...65 points de dégâts aux ennemis dans la zone si bloqué.'],
853=>['Tir de Melandru','Si le Tir de Melandru réussit, votre cible souffre de Saignement pendant 5...25 secondes. Si le tir touche un ennemi en fuite ou assommé, ce dernier reçoit +10...25 points de dégâts et souffre d\'Infirmité pendant 5...15 secondes.','Provoque le Saignement (5...25 secondes). Inflige +10...25 points de dégâts et provoque l\'Infirmité (5...15 secondes) si la cible ennemie est en fuite ou assommée.'],
854=>['Attrape','Lorsque l\'attrape est déclenchée, tous les ennemis à proximité sont frappés d\'Infirmité pendant 3...15 secondes. L\'attrape prend fin au bout de 90 secondes. Vous pouvez être facilement interrompu lorsque vous activez cette compétence.','(90 secondes.) Affecte les ennemis à proximité. Inflige l\'Infirmité (3...15 secondes). Cette compétence peut être facilement interrompue.'],
858=>['Valse des dagues','Vous lancez trois Valses des dagues contre la cible ennemie. Chacune inflige 5...35 points de dégâts de la terre si elle fait mouche. La portée de cette compétence est réduite de moitié. Cette compétence est considérée comme une attaque main droite.','Trois projectiles : chacun inflige 5...35 points de dégâts de la Terre. Est considérée comme une attaque main droite.'],
859=>['Conjuration de cauchemar','Pendant 2...16 secondes, la cible ennemie subit une dégénération de santé de -8.','(2...16 secondes.) Provoque une dégénération de santé de -8.'],
860=>['Sceau d\'interruption','Si l\'ennemi visé est en train de lancer un sort, celui-ci est interrompu et l\'ennemi subit 10...51 points de dégâts. S\'il est affecté par un maléfice, le Sceau d\'Interruption peut interrompre toutes les compétences n\'étant pas des sorts.','Interrompt un sort. Peut interrompre n\'importe quelle compétence si la cible ennemie est victime d\'un maléfice. Effet de l\'interruption : inflige 10...51 points de dégâts.'],
862=>['Regard féroce','Inflige 20...40 points de dégâts et vole 20...40 points de vie à la cible ennemie et à tous les ennemis à proximité.','Inflige 20...40 points de dégâts et vole 20...40 points de vie à la cible ennemie et aux ennemis à proximité.'],
863=>['Ordre d\'apostasie','Pendant 5 secondes, chaque fois qu\'un membre du groupe inflige des dégâts physiques à un ennemi, celui-ci perd un enchantement. Pour chaque enchantement de Moine supprimé, vous perdez 10...3% de santé maximum.','Enchante tous les membres de l\'équipe (5 secondes). Ces derniers retirent un enchantement lorsqu\'ils infligent des dégâts physiques. Coût de la suppression : pour chaque enchantement de Moine, vous perdez 10...3% de santé maximum.'],
864=>['Regard de l\'oppresseur','La cible ennemie et les ennemis adjacents subissent 10...30 points de dégâts de l\'ombre. Les ennemis déjà affectés par une condition sont Empoisonnés et Affaiblis pendant 3...12 secondes.','Inflige 10...30 points de dégâts à la cible et aux ennemis adjacents. Inflige Poison et Faiblesse (3...12 secondes) aux ennemis souffrant d\'une condition.'],
865=>['Masse foudroyante','La cible ennemie subit 10...100 points de dégâts de la foudre et inflige Armure brisée pendant 5...20 secondes. La Masse foudroyante a 25% de pénétration d\'armure.','Inflige 10...100 points de dégâts de la foudre. Inflige Armure brisée (5...20 secondes). 25% de pénétration d\'armure.'],
866=>['Lame vaporeuse','La cible ennemie subit 15...135 points de dégâts du froid. Les dégâts de la Lame vaporeuse sont réduits de moitié si cet ennemi bénéficie d\'un enchantement.','Inflige 15...135 points de dégâts du froid. Dégâts réduits de moitié si l\'ennemi visé est enchanté.'],
867=>['Lumière rédemptrice','Vous guérissez la cible (un allié ou vous-même) de 40...120 points de vie. Si votre cible est sous l\'effet d\'un enchantement, vous récupérez 1...3 points d\'énergie.','Soigne de 40...120 points de vie. Vous gagnez 1...3 points d\'énergie si l\'allié visé est enchanté.'],
869=>['"Froussard !"','Si la cible ennemie est en mouvement, elle sera assommée.','Attaque assommante si la cible ennemie se déplace.'],
870=>['Pestilence','Crée un esprit de niveau 1...10. Lorsqu\'une créature autre qu\'un esprit meurt dans sa portée, les conditions dont elle souffrait sont transmises à toutes les créatures dans la zone souffrant déjà d\'une condition. Cet esprit disparaît au bout de 30...180 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...180 secondes). Quand une créature meurt à portée, les conditions dont elle souffrait sont transmises à toute créature de la zone souffrant déjà d\'une condition. Les esprits ne sont pas affectés.'],
871=>['Mélodie des Ombres','Crée un esprit de niveau 1...10. Les attaques de l\'esprit infligent 5...20 points de dégâts et entraînent l\'Aveuglement pendant 1...6 secondes. Il meurt au bout de 30 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30 secondes). Ses attaques infligent +5...20 points de dégâts et entraînent l\'Aveuglement (1...6 secondes).'],
876=>['Sceau des Ombres','L\'ennemi ciblé subit 5...35 points de dégâts. S\'il était aveuglé, cet ennemi subira 15...60 points de dégâts en plus.','Inflige 5...35 points de dégâts. Inflige 15...60 points de dégâts supplémentaires si la cible ennemie est aveuglée.'],
877=>['Equilibre de Lyssa','La cible ennemie perd un enchantement. Si vous disposez de plus d\'enchantements que la cible ennemie, cette compétence n\'a aucun effet.','Supprime un enchantement à la cible ennemie. Aucun effet si vous avez plus d\'enchantements que cet ennemi.'],
878=>['Visions de Regret','Pendant 10 secondes, la cible et les ennemis adjacents subissent 15...45 points de dégâts chaque fois qu\'ils utilisent une compétence et 5...50 points de dégâts supplémentaires s\'ils ne sont pas affectés par un autre maléfice d\'Envoûteur.','Inflige également des maléfices aux ennemis adjacents à la cible (10 secondes). Ils subissent 15...45 points de dégâts chaque fois qu\'ils utilisent une compétence et 5...50 points de dégâts supplémentaires s\'ils ne sont pas affectés par un autre maléfice d\'Envoûteur.'],
879=>['Illusion de douleur','Pendant 8 secondes, l\'ennemi visé souffre d\'une dégénération de santé de -3...10 et subit 3...10 points de dégâts par seconde. Quand l\'Illusion de douleur prend fin, cet ennemi est soigné de 36...120 points de vie.','(8 secondes.) Provoque une dégénération de santé de -3...10 et l\'ennemi visé subit 3...10 points de dégâts toutes les secondes. Effet final : cet ennemi est soigné de 36...120 points de vie.'],
880=>['Vol de vitesse','Pendant 1...10 secondes, le temps d\'incantation des sorts de l\'ennemi visé et de tous les ennemis adjacents est doublé. Le temps d\'incantation des sorts que vous ou vos alliés lancez sur ces ennemis est 50% plus rapide.','Inflige également des maléfices aux ennemis adjacents (1...10 secondes). Double le temps de lancement des sorts. Le temps d\'incantation des sorts que vous ou vos alliés lancez sur les cibles ennemies est réduit de -50%.'],
881=>['Sceau éthéré','Si vous avez moins de 5...10 points d\'énergie, vous bénéficiez de 10...20 points d\'énergie.','Vous gagnez 10...20 points d\'énergie. Valable uniquement si vous avez moins de 5...10 points d\'énergie.'],
882=>['Sceau de désenchantement','Perte de toute l\'énergie. L\'ennemi ciblé perd un enchantement.','Supprime un enchantement. Vous perdez toute votre énergie.'],
883=>['Aphonie','Pendant 5...20 secondes, l\'ennemi ciblé et tous les ennemis à proximité ne peuvent pas utiliser de cris ou chants','Inflige également des maléfices aux ennemis à proximité de la cible (5...20 secondes). Ces ennemis ne peuvent pas utiliser de cris ou de chants.'],
884=>['Flammes virulentes','L\'ennemi ciblé et ceux à proximité sont frappés par des Flammes virulentes. Les ennemis déjà embrasés lors du lancement de cette compétence subissent 10...100 points de dégâts du feu. Les autres ennemis s\'embrasent pendant 1...7 secondes.','Frappe tous les ennemis proches de la cible. Inflige 10...100 points de dégâts du feu aux ennemis déjà embrasés. Embrase (1...7 secondes) les ennemis non embrasés.'],
885=>['Gardien protecteur','Pendant 2...6 secondes, tous les membres du groupe à portée de voix ont 75% de chances de bloquer les attaques. Le cas échéant, tous les alliés à proximité sont soignés de 10...40 points de vie et la compétence prend fin.','(2...6 secondes.) Les membres du groupe à portée de voix ont 75% de chances de bloquer les attaques. Effet du blocage : les alliés à proximité sont soignés de 10...40 points de vie et la compétence prend fin.'],
886=>['Bise reposante','Pendant 8...18 secondes, la ciblé visée (un allié ou vous-même) bénéficie d\'une régénération de santé de +10. Cet enchantement prend fin si cette cible attaque ou utilise une compétence.','(8...18 secondes.) Confère une régénération de santé de +10. Prend fin si l\'allié visé attaque ou utilise un compétence.'],
887=>['Sceau de rajeunissement','Soigne la cible (un allié ou vous-même) de 15...75 points de vie. Si celle-ci est en train de lancer un sort ou d\'attaquer, elle est soignée de 15...75 points de vie supplémentaires.','Soigne de 15...75 points de vie. Soigne de 15...75 points de vie supplémentaires si l\'allié visé lance un sort ou attaque.'],
888=>['Hache tournoyante','Si Hache tournoyante réussit, vous infligez +5...20 points de dégâts et toute pose de combat utilisée par votre cible prend fin. Cette attaque ne peut pas être bloquée.','Inflige +5...20 points de dégâts et supprime une pose de combat. Impossible à bloquer.'],
889=>['Coup forcé','Si Coup forcé réussit, il inflige +10...30 points de dégâts et chaque pose utilisée par la cible prend fin. La cible ennemie est frappée de Faiblesse pendant 5...20 secondes. Cette attaque ne peut être bloquée.','Inflige +10...30 points de dégâts. Supprime la pose de la cible ennemie. Inflige la Faiblesse (5...20 secondes). Ne peut être bloqué.'],
891=>['"Nul ne passera !"','Tous les ennemis à proximité en mouvement sont assommés. Cette compétence se recharge 1...8 secondes plus vite pour chaque ennemi assommé (maximum de 25 secondes).','Assomme tous les ennemis à proximité qui se déplacent. Se recharge 1...8 secondes plus vite pour chaque ennemi affecté (maximum de 25 secondes).'],
892=>['Lame vacillante','Si Lame vacillante réussit, vous infligez +10...40 points de dégâts. Si cette attaque touche un ennemi en déplacement, celui-ci est frappé de Stupeur pendant 10 secondes.','Inflige +10...40 points de dégâts. Provoque la Stupeur (10 secondes) si la cible ennemie est en déplacement.'],
893=>['Flèches chercheuses','Pendant 3...14 secondes, vos flèches ne peuvent pas être bloquées. Flèches chercheuses prend fin si elle ne fait pas mouche.','(3...14 secondes.) Vos flèches sont impossibles à bloquer. Prend fin si votre attaque échoue.'],
898=>['Surcharge','Pendant 5 secondes, l\'ennemi ciblé subit -1...3 points de dégénération de santé. Si l\'ennemi ciblé réussit à utiliser une compétence, Surtension lui inflige 15...75 points de dégâts ainsi que 75% de ces dégâts à tous les ennemis adjacents.','(5 secondes.) Provoque -1...3 points de dégénération de santé. Si l\'ennemi ciblé réussit à utiliser une compétence, il subit 15...75 points de dégâts et tous les ennemis adjacents subissent 75% de ces dégâts.'],
899=>['Images d\'attrition','Pendant 5...10 secondes, la cible visée souffre d\'une dégénération de santé de -1...3. Si cet ennemi était en train d\'attaquer, il subira 10...52 points de dégâts.','(5...10 secondes.) Provoque une dégénération de santé de -1...3. Effet initial : 10...52 points de dégâts si la cible ennemie est en train d\'attaquer.'],
900=>['Fardeau partagé','Pendant 5...20 secondes, la cible ennemie et tous les ennemis dans la zone attaquent, lancent des sorts et se déplacent 50% plus lentement.','Inflige également des maléfices aux ennemis à proximité de votre cible (5...20 secondes). Ces ennemis attaquent, lancent des sorts et se déplacent 50% moins vite.'],
901=>['Lien des âmes','Pendant 30 secondes, chaque fois que la cible ennemie est guérie, le guérisseur subit 20...80 points de dégâts. Ce maléfice prend fin si la cible souffre d\'un maléfice de Prières de Châtiment.','(30 secondes.) Chaque fois que la cible ennemie est guérie, le guérisseur reçoit 20...80 points de dégâts.Prend fin si la cible souffre d\'un maléfice de Prières de Châtiment. '],
902=>['Sang de l\'agresseur','Vous volez jusqu\'à 5...45 points de vie à l\'ennemi visé. Si cet ennemi était en train d\'attaquer, il souffre de Faiblesse pendant 3...12 secondes.','Vole 5...45 points de vie. Inflige Faiblesse (3...12 secondes) si la cible ennemie était en train d\'attaquer.'],
903=>['Prisme de glace','La cible ennemie subit 15...75 points de dégâts du froid. Si cet ennemi est frappé d\'un maléfice de la Magie de l\'eau, Prisme de glace inflige +15...75 points de dégâts du froid à tous les ennemis à proximité.','Inflige 15...75 points de dégâts du froid. Inflige +15...75 points de dégâts du froid aux ennemis à proximité si l\'ennemi ciblé est frappé d\'un maléfice de la Magie de l\'eau.'],
904=>['Hache de rage','Si cette attaque réussit, elle inflige +5...35 points de dégâts. Si elle est bloquée, vous gagnez 3 décharges d\'adrénaline.','Inflige +5...35 points de dégâts. Vous gagnez 3 décharges d\'adrénaline si elle est bloquée.'],
905=>['Coup propice','Si Coup propice réussit, il inflige +5...20 points de dégâts et vous gagnez 3...8 points d\'énergie. Si la cible ennemie souffre de Faiblesse, cette attaque ne peut être bloquée.','Inflige +5...20 points de dégâts et vous gagnez 3...8 points d\'énergie. Ne peut être bloqué si l\'ennemi est Affaibli.'],
906=>['"A genoux !"','Vous perdez toute votre adrénaline. Si des cibles adjacentes sont assommées, toutes vos poses de combat se rechargent.','Recharge toutes vos poses de combat si vous êtes adjacent à un ennemi assommé. Vous perdez toute votre adrénaline.'],
907=>['Taillade du dragon','Si l\'attaque réussit, vous infligez +10...40 points de dégâts et gagnez 1...5 décharges d\'adrénaline.','Inflige +10...40 points de dégâts. Vous gagnez 1...5 décharges d\'adrénaline si l\'attaque réussit.'],
908=>['Tir du maraudeur','Si l\'attaque réussit, cette attaque inflige +25...55 points de dégâts et toutes vos compétences n\'étant pas des attaques restent inutilisables pendant 5 secondes.','Inflige +25...55 points de dégâts. Vos compétences non offensives sont désactivées (5 secondes) si cette attaque réussit.'],
909=>['Tir focalisé','This shot moves three times faster, cannot be blocked, and strikes for +10...40 damage but all of your other attack skills are disabled for 8...4 seconds.','Deals +10...40 damage. Unblockable. This shot moves three times faster.Your other attack skills are disabled (8...4 seconds).'],
910=>['Faille de l\'esprit','Ouvre une Faille de l\'esprit sur la position de la cible ennemie. Après 3 secondes, tous les ennemis adjacents subissent 25...125 points de dégâts de la foudre et souffrent d\'Armure brisée pendant 1...20 secondes.','Après 3 secondes, affecte les ennemis adjacents à la position initiale de l\'ennemi. Inflige 25...125 points de dégâts de la foudre et la condition Armure brisée (1...20 secondes.'],
911=>['Union','Crée un esprit de niveau 1...12. A chaque fois qu\'un allié à sa portée (autre qu\'un esprit) subit des dégâts ou un vol de vie, ceux-ci sont réduits de 15 points et l\'esprit subit 15 points de dégâts. Il disparaît au bout de 30...60 secondes.','Crée un esprit de niveau 1...12 (durée de vie de 30...60 secondes). A chaque fois qu\'un allié à sa portée (autre qu\'un esprit) subit des dégâts ou un vol de vie, ceux-ci sont réduits de 15 points et l\'esprit subit 15 points de dégâts.'],
913=>['Tanasen était tranquille','Vous tenez les cendres de Tanasen jusqu\'à un maximum de 5...20 secondes. Pendant ce temps, vous bénéficiez d\'un bonus d\'armure de +10...25 et vous ne pouvez pas être interrompu.','(5...20 secondes.) Vous bénéficiez d\'un bonus d\'armure de +10...25. Rien ne peut vous interrompre.'],
914=>['Consommation des âmes','Vous volez 5...70 points de santé à l\'ennemi ciblé. Toutes les créatures hostiles invoquées et à portée de voix de cet ennemi subissent 25...125 points de dégâts.','Vole 5...70 points de santé. Inflige 25...125 points de dégâts aux créatures hostiles invoquées et à portée de voix de l\'ennemi ciblé.'],
915=>['Esprit illuminé','La cible (un allié ou vous-même) est soignée de 60...180 points de vie. Si des esprits se trouvent à portée de voix, vous ne sacrifiez pas de santé.','Soigne de 60...180 points de vie. Vous ne sacrifiez pas de santé si un esprit se trouve à portée de voix.'],
916=>['Lamentation','L\'ennemi visé et tous les ennemis à proximité subissent une dégénération de santé de -0...3 pendant 5...20 secondes. Si vous vous trouvez à portée de voix d\'un esprit ou d\'un cadavre lorsque ce maléfice est appliqué, ces ennemis subissent 10...50 points de dégâts.','Inflige également des maléfices aux ennemis proches de la cible (5...20 secondes). Provoque une dégénération de santé de -0...3. Effet initial : inflige 10...50 points de dégâts à ces ennemis si vous vous trouvez à portée de voix d\'un esprit ou d\'un cadavre.'],
917=>['Rupture d\'âme','L\'esprit allié ciblé est détruit. Tous les ennemis à proximité reçoivent 50...140 points de dégâts de la foudre et sont aveuglés pendant 3...12 secondes.','Détruit l\'esprit allié visé. Inflige 50...140 points de dégâts de la foudre et inflige l\'Aveuglement (3...12 secondes) aux ennemis à proximité.'],
918=>['Esprit de chair','L\'esprit allié touché est détruit. Tous les alliés à proximité sont soignés de 30...240 points de vie.','Détruit l\'esprit allié touché. Soigne les alliés à proximité de 30...240 points de vie.'],
919=>['Brûlure de l\'esprit','La cible ennemie subit 5...50 points de dégâts de la foudre. Si des esprits se trouvent à portée de voix, Brûlure de l\'esprit cause la Brûlure pendant 1...5 secondes.','Inflige 5...50 points de dégâts de la foudre. Inflige Brûlure (1...5 secondes si vous êtes à portée de voix d\'un esprit.'],
920=>['Destruction','Crée un esprit de niveau 1...14 qui meurt après 30 secondes. Lorsque cet esprit meurt, tous les ennemis dans la zone subissent 5...25 points de dégâts pour chaque seconde de vie de l\'esprit (maximum de 150 points de dégâts).','Crée un esprit de niveau 1...14 qui meurt après 30 secondes. Lorsque cet esprit meurt, tous les ennemis dans la zone subissent 5...25 points de dégâts pour chaque seconde de vie de l\'esprit (maximum de 150 points de dégâts).'],
921=>['Dissonance','Crée un esprit de niveau 1...12. Celui-ci inflige 5...20 points de dégâts et toute personne touchée par cette attaque est interrompue. Cet esprit meurt au bout de 10...25 secondes.','Crée un esprit de niveau 1...12 (durée de vie de 10...25 secondes). Ses attaques infligent 5...20 points de dégâts et interrompent les actions.'],
923=>['Désenchantement','Crée un esprit de niveau 1...12. Celui-ci inflige 5...20 points de dégâts et toute personne touchée par cette attaque perd un enchantement. Cet esprit meurt au bout de 10...35 secondes.','Crée un esprit de niveau 1...12 (durée de vie de 10...35 secondes). Ses attaques infligent 5...20 points de dégâts et suppriment un enchantement.'],
925=>['Rappel','Pendant que vous maintenez le Rappel rien ne se passe. Lorsque le Rappel prend fin, vous faites une Foulée de l\'Ombre jusqu\'à la position de l\'allié visé lors de l\'activation de cette compétence et toutes vos compétences sont inutilisables pendant 3 secondes.','Effet final : vous faites une foulée de l\'ombre vers la cible alliée. Vous ne pouvez pas vous prendre pour cible et toutes vos compétences sont désactivées pendant 3 secondes lorsque la compétence prend fin.'],
926=>['Dagues affûtées','Pendant 5...30 secondes, vos attaques à la dague infligent le Saignement pendant 5...15 secondes.','(5...30 secondes.) Vos attaques à la dague provoquent le Saignement (5...15 secondes).'],
927=>['Peur honteuse','Pendant 10 secondes, l\'ennemi visé se déplace 10% plus vite que la normale. Pour chaque seconde où la cible est en mouvement, elle subit 5...20 points de dégâts.','(10 secondes.) La cible ennemie subit 5...20 points de dégâts par seconde lorsqu\'elle est en mouvement mais se déplace 10% plus vite.'],
928=>['Linceul de l\'Ombre','Pendant 3...9 secondes, l\'ennemi visé ne peut pas être la cible d\'enchantements.','(3...9 secondes.) La cible ennemie ne peut pas être la cible d\'enchantements.'],
929=>['Ombre de hâte','Pendant 10...40 secondes, vous vous déplacez 15% plus vite que la normale. Lorsqu\'Ombre de hâte prend fin, vous retournez sur votre position d\'origine.','(10...40 secondes.) Vous vous déplacez 15% plus vite. Effet final : vous retournez sur votre position d\'origine.'],
930=>['Incantation propice','Pendant 20 secondes, le prochain sort que vous lancez est désactivé pendant 10...5 secondes supplémentaires et vous gagnez 110...200% de son coût en énergie.','(20 secondes.) Votre prochain sort vous confère 110...200% de son coût en énergie. Ce sort met 10...5 secondes de plus à se recharger.'],
931=>['Retour de pouvoir','Si l\'ennemi visé lance un sort ou un chant, cette compétence est interrompue et l\'ennemi visé bénéficie de 10...5 points d\'énergie.','Interrompt un sort ou un chant. Effet de l\'interruption : l\'ennemi visé gagne 10...5 points d\'énergie.'],
932=>['Complication','Si l\'ennemi visé prépare une compétence, elle est interrompue et désactivée pour cet ennemi et tous les ennemis de la zone pendant 5...12 secondes supplémentaires.','Interrompt une compétence. Effet de l\'interruption : désactive la compétence interrompue (+5...12 secondes) pour l\'ennemi visé et tous les ennemis de la zone.'],
933=>['Tempête destructrice','La cible ennemie perd tous ses enchantements. Pour chaque enchantement levé de cette manière, la compétence est inutilisable pendant 7 secondes supplémentaires.','Supprime tous les enchantements. Coût de la suppression : la Tempête destructrice est désactivée pendant 7 secondes pour chaque enchantement supprimé.'],
934=>['Sceau contre nature','L\'ennemi visé subit 15...75 points de dégâts. Si cet ennemi est sous l\'effet d\'un maléfice ou d\'un enchantement, les ennemis adjacents à votre cible subissent 5...50 points de dégâts.','Inflige 15...75 points de dégâts. Inflige 5...50 points de dégâts aux autres ennemis adjacents si la cible est sous l\'effet d\'un maléfice ou d\'un enchantement.'],
935=>['Fiel','Pendant 20 secondes, ce maléfice n\'a aucun effet. Lorsqu\'il prend fin, l\'ennemi visé et tous les ennemis dans la zone subissent 1...6 points de dégâts pour chaque seconde pendant lesquelles le Fiel est actif.','(20 secondes.) Effet final : inflige 1...6 points de dégâts pour chaque seconde pendant laquelle le Fiel était actif. Inflige également des dégâts à d\'autres ennemis dans la zone.'],
936=>['Enchantements envenimés','La cible ennemie perd un enchantement. Pour chaque enchantement restant, la cible ennemie est empoisonnée pendant 3...10 secondes.','Supprime un enchantement chez la cible ennemie. Provoque l\'Empoisonnement (3...10 secondes par enchantement restant).'],
937=>['Onde de choc','Tous les ennemis dans la zone subissent 15...60 points de dégâts de la terre et souffrent de Faiblesse pendant 1...10 secondes. Les ennemis proches subissent en outre 15...60 points de dégâts de la terre en plus et souffrent d\'Armure brisée pendant 1...10 secondes. Les ennemis adjacents subissent les effets précédents plus 15...60 points de dégâts de la terre et sont aveuglés pendant 1...10 secondes.','Les ennemis dans la zone subissent 15...60 points de dégâts de la terre et souffrent de Faiblesse pendant 1...10 secondes. Les ennemis proches subissent en outre 15...60 points de dégâts de la terre en plus et souffrent d\'Armure brisée (1...10 secondes). Les ennemis adjacents subissent les effets précédents plus 15...60 points de dégâts de la terre et sont aveuglés (1...10 secondes).'],
938=>['Protection de stabilité','Vous créez une Protection de stabilité sur votre position actuelle. Pendant 10...25 secondes, les alliés autres que les esprits ne peuvent pas être renversés.','(10...25 secondes.) Les alliés bénéficiant de cette protection ne peuvent pas être renversés. Les esprits alliés ne sont pas affectés.'],
939=>['Chaînes de glace','Pendant 1...10 secondes, la vitesse de déplacement de la cible ennemie est réduite de 66%. Sous les effets d\'un enchantement, la vitesse de déplacement de cet ennemi est réduite de 90%.','(1...10 secondes.) La cible ennemie se déplace 66% moins vite. Cet ennemi se déplace 90% moins vite s\'il est enchanté.'],
941=>['Lumière divine','Vous soignez la cible (un allié ou vous-même) de 10...120 points de vie et supprimez une condition et un maléfice.','Soigne de 10...120 points de vie. Supprime une condition et un maléfice.'],
942=>['Retrait de maléfices','Ôte tous les maléfices de la cible alliée et de tous les alliés adjacents. Ce sort met 2 secondes supplémentaires à se recharger pour chaque maléfice supprimé de cette manière. (50% de risques d\'échec avec Faveur divine inférieure à 5.)','Dissipe tous les maléfices. Affecte également les alliés adjacents. Coût de la suppression : +2 secondes de recharge pour chaque maléfice dissipé. 50% de risques d\'échec à moins d\'avoir au moins 5 points en Faveur divine.'],
943=>['Extinction','Supprime une condition de chaque membre du groupe. Si la condition supprimée est la Brûlure, la cible est soignée de 10...100 points de vie.','Affecte tous les membres de l\'équipe. Supprime une condition. Les membres du groupe soulagés de la Brûlure sont soignés de 10...100 points de vie.'],
944=>['Sceau de force',' 1...16 prochaines attaques infligent +5 points de dégâts.','Vos attaques infligent +5 points de dégâts. Prend fin au bout de 1...16 attaques.'],
946=>['Concentration du trappeur','Pendant 12...36 secondes, vos compétences de piège sont difficiles à interrompre et votre caractéristique de Survie est augmentée de 0...4.','(12...36 secondes.) Vos compétences de piège sont difficiles à interrompre. Votre caractéristique de Survie est augmentée de +0...4.'],
947=>['Ronces','Crée un esprit de niveau 1...10. Toute créature (autre qu\'un esprit) assommée dans sa portée subit 5 points de dégâts et est prise de Saignements pendant 5...20 secondes. Cet esprit meurt après 30...240 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...240 secondes). Les créatures assommées subissent 5 points de dégâts et sont prises de Saignement (5...20 secondes). N\'affecte pas les esprits.'],
948=>['Coup désespéré','Si vous avez moins de 50...80% de santé, vous infligez +15...60 points de dégâts.','Inflige +15...60 points de dégâts si vous avez moins de 50...80% de santé.'],
949=>['Méthode du renard','Pendant 10...35 secondes, vos prochaines attaques au corps à corps (au nombre de 1...6) que vous lancez ne peuvent pas être bloquées.','(10...35 secondes.) Vos attaques sont impossibles à bloquer. Prend fin au bout de 1...6 attaques.'],
950=>['Fardeau nébuleux','Pendant 3...15 secondes, la cible ennemie se déplace 25% moins vite, et quand elle n\'est pas affectée par un autre maléfice, son bonus d\'armure est réduit de 20...30 contre vos attaques.','(3...15 secondes.) La cible ennemie se déplace 25% moins vite et son bonus d\'armure est réduit de 20...30. La réduction du bonus d\'armure n\'affecte cet ennemi que s\'il n\'est victime d\'aucun autre maléfice.'],
951=>['Siphon de vitesse','Pendant 5...15 secondes, la cible ennemie se déplace 33% moins vite et vous vous déplacez 33% plus vite. Ce sort se recharge 50% plus rapidement s\'il est lancé sur un ennemi en mouvement.','(5...15 secondes.) La cible ennemie se déplace 33% moins vite et vous vous déplacez 33% plus vite. Se recharge 50% plus rapidement si lancé sur un ennemi en mouvement.'],
952=>['Charge mortelle','Vous faites une Foulée de l\'Ombre vers la cible ennemie. Si celle-ci a plus de santé que vous, vous êtes soigné de 65...200 points.','Vous faites une Foulée de l\'ombre vers la cible ennemie. Vous êtes soigné de 65...200 points de vie si cet ennemi a une santé supérieure à la vôtre.'],
953=>['Flux de puissance','Si l\'ennemi visé lance un sort ou un chant, cette compétence est interrompue et pendant 4...10 secondes, l\'ennemi ciblé subit une dégénération d\'énergie de -2.','Interrompt un sort ou un chant. Effet de l\'interruption : -2 de dégénération d\'énergie (4...10 secondes).'],
954=>['Expulsion de maléfices','Lève jusqu\'à deux maléfices de la cible (un allié ou vous-même).','Lève deux maléfices qui frappent la cible (un allié ou vous-même).'],
955=>['Confiscation d\'enchantement','Ote 1 enchantements à la cible ennemie. Si un enchantement est levé de cette manière, cet ennemi souffre de Saignement pendant 5...25 secondes.','Ote 1 enchantements. Effet de la suppression : inflige le Saignement (5...25 secondes).'],
957=>['Bouclier contre les sorts','Pendant 5...20 secondes, lorsque vous lancez des sorts, les ennemis ne peuvent pas vous cibler avec des sorts. Quand le Bouclier contre les sorts prend fin, toutes vos compétences sont inutilisables pendant 8...4 secondes.','(5...20 secondes.) Lorsque vous lancez des sorts, vous ne pouvez pas être la cible de sorts. Effet final : vos compétences sont désactivées (8...4 secondes).'],
958=>['Souffle réparateur','La ciblé alliée est soignée de 40...100 points de vie. Sa portée correspond à la moitié de la portée d\'un sort normal.','Soigne de 40...100 points de vie. Vous ne pouvez pas vous prendre pour cible.'],
959=>['Lumière éthérée','La cible (un allié ou vous-même) est soignée de 25...100 points de vie. Ce sort est facilement interrompu.','Soigne de 25...100 points de vie. Facilement interrompu.'],
960=>['Libération d\'enchantements','Vous perdez tous les enchantements. Chaque membre du groupe est soigné de 5...35 points de vie pour chaque enchantement de Moine perdu.','Supprime tous vos enchantements. Soigne tous les membres du groupe de 5...35 points de vie par enchantement de Moine supprimé.'],
961=>['Lacération','Crée un esprit de niveau 1...10. Les créatures prises de saignement dans sa portée subissent une dégénération de santé de -2. Lorsque cet esprit meurt, toutes les créatures (autres que des esprits) se trouvant dans sa portée et ayant moins de 90% de leur santé sont prises de Saignements pendant 5...25 secondes. Cet esprit meurt au bout de 30...240 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...240 secondes). Les créatures prises de Saignement à portée subissent une dégénération de santé de -2. Effet final : inflige le Saignement (5...25 secondes) aux créatures à portée qui ont moins de 90% de santé. N\'affecte pas les esprits.'],
962=>['Transfert d\'esprit','L\'esprit le plus proche de vous perd 5...50 points de vie. La cible (un allié ou vous-même) est soignée de 5 points de vie pour chaque point de vie perdu.','L\'esprit le plus proche de vous perd 5...50 points de vie. Soigne l\'allié visé de 5 points de vie par point de vie perdu.'],
963=>['Restauration','Crée un esprit de niveau 1...14. Lorsque cet esprit meurt, tous les membres du groupe dans la zone sont ressuscités avec 5...50% de leur santé et 0 points d\'énergie. Cet esprit meurt au bout de 30 secondes.','Crée un esprit de niveau 1...14 (durée de vie de 30 secondes). Effet final : ressuscite les membres du groupe dans la zone avec 5...50% de santé et 0 point d\'énergie.'],
964=>['Arme de vengeance','Pendant 8 secondes, la prochaine fois que la cible (un allié ou vous-même) subit des dégâts ou un vol de vie, elle absorbe 15...60 points de vie à cet ennemi.','(8 secondes.) Vole 15...60 points de vie au prochain ennemi infligeant des dégâts ou un vol de vie à l\'allié visé.'],
973=>['Poudre aveuglante','Doit succéder à une attaque main gauche. La cible ennemie et tous les ennemis adjacents sont aveuglés pendant 3...15 secondes.','Inflige l\'Aveuglement (3...15 secondes) à la cible et à tous les ennemis adjacents. Doit succéder à une attaque main gauche.'],
974=>['Toucher de la mante','La cible ennemie subit Infirmité pendant 5...20 secondes. Cette compétence est considérée comme une attaque de main gauche.','Inflige l\'altération Infirmité (5...20 secondes). Cette compétence est considérée comme une attaque de main gauche.'],
975=>['Assaut épuisant','Doit succéder à une attaque main droite. L\'action de l\'ennemi visé est interrompue. Si cette action était un lancer de sort, l\'ennemi visé subit un Afflux de 10.','Interrompt une action. Inflige un Afflux de 10 si l\'action interrompue était un lancer de sort. Doit succéder à une attaque main droite.'],
976=>['Coup répété','Doit suivre une attaque main gauche. Si elle réussit, cette attaque inflige +10...30 points de dégâts. Si elle manque, il lui faudra 15 secondes supplémentaires pour se recharger.','Inflige +10...30 points de dégâts. Cette compétence met 15 secondes de plus à se recharger en cas d\'échec. Doit succéder à une attaque main gauche.'],
977=>['Méthode du lotus','Pendant 20 secondes, la prochaine fois que vous frappez avec une compétence d\'attaque ambidextre, vous obtenez 5...20 points d\'énergie.','(20 secondes.) Vous obtenez 5...20 points d\'énergie la prochaine fois que vous frappez avec une attaque d\'ambidextrie.'],
978=>['Marque d\'instabilité','Pendant 20 secondes, la prochaine fois que vous touchez une cible ennemie avec une compétence d\'attaque ambidextre, cet ennemi est assommé.','(20 secondes.) La cible ennemie sera assommée par votre prochaine attaque d\'ambidextrie.'],
979=>['Défiance','Pendant 6 secondes, le prochain sort que l\'ennemi ciblé lance sur l\'un de vos alliés échoue et inflige 10...80 points de dégâts à cet ennemi ainsi que 75% de ces dégâts à tous les ennemis à proximité.','(6 secondes.) Le prochain sort que l\'ennemi ciblé lance sur l\'un de vos alliés échoue et lui inflige 10...80 points de dégâts ainsi que 75% de ces dégâts aux ennemis à proximité.'],
980=>['Festin de l\'esprit','Vous détruisez tous les esprits des alliés à proximité. Pour chaque esprit détruit de cette manière, tous les membres du groupe sont soignés de 50...100 points de vie.','Soigne tous les membres du groupe de 50...100 points de vie par esprit allié à proximité. Tous les esprits alliés à proximité sont détruits.'],
981=>['Rétablissement','Crée un esprit de niveau 1...14. Les alliés (autres que des esprits) dans sa portée bénéficient d\'une régénération de santé de +1...3. Cet esprit disparaît au bout de 15...45 secondes.','Crée un esprit de niveau 1...14 (durée de vie de 15...45 secondes). Les alliés (autres que les esprits) à portée bénéficient d\'une régénération de santé de +1...3 .'],
982=>['Refuge','Crée un esprit de niveau 1...12. Les alliés (autres que des esprits) dans sa portée ne peuvent pas perdre plus de 10% de leur santé maximum sur une attaque. Lorsque cet esprit empêche les dégâts, il perd 75...45 points de vie. Cet esprit dure 30...60 secondes.','Crée un esprit de niveau 1...12 (durée de vie de 30...60 secondes). Les alliés (autres que les esprits) à portée ne peuvent pas perdre plus de 10% de leur santé maximum d\'un seul coup. Coût de la prévention des dégâts : cet esprit perd 75...45 points de vie.'],
983=>['Arme de l\'Ombre','Pendant 1...7 secondes, la cible (un allié ou vous-même) a une Arme de l\'Ombre en sa possession. Chaque fois que cette cible est touchée par une attaque, son attaquant est frappé d\'Aveuglement pendant 5 secondes. Les 1...3 prochaines fois que cet allié réussit une attaque, sa cible est frappée d\'Aveuglement pendant 5 secondes.','(1...7 secondes.) Inflige l\'Aveuglement (5 secondes) à toute créature attaquant l\'allié visé. Les 1...3 prochaines attaques réussies de la cible (un allié ou vous-même) infligent Aveuglement (5 secondes).'],
985=>['Chausse-trappes','Target foe and all foes adjacent to your target are Crippled and Bleeding for 5...15 seconds. Caltrops has half the normal range.','Inflicts Crippled and Bleeding conditions (5...15 seconds) on target and adjacent foes.'],
986=>['Coup des neuf queues','Doit succéder à une attaque main gauche. Le Coup des neuf queues ne peut pas être bloqué et inflige +15...40 points de dégâts si l\'attaque réussit.','Inflige +15...40 points de dégâts. Impossible à bloquer. Doit succéder à une attaque main gauche.'],
987=>['Méthode de la paume vide','Pendant 5...15 secondes, les attaques de main gauche et les attaques doubles ne coûtent aucune énergie et se rechargent 25...50% plus vite.','(5...15 secondes.) Vos attaques de main gauche et vos attaques doubles ne coûtent aucune énergie et se rechargent 25...50% plus vite.'],
988=>['Frappe à la tempe','Doit suivre une attaque main droite. Si l\'attaque réussit, la cible ennemie est frappée de Stupeur et d\'Aveuglement pendant 1...10 secondes. Si la cible ennemie était en train de lancer un sort, ce sort est interrompu.','Interrompt un sort. Provoque la Stupeur et l\'Aveuglement (1...10 secondes). Doit succéder à une attaque main droite.'],
989=>['Coup du phénix doré','Si vous n\'êtes pas sous l\'effet d\'un enchantement, cette compétence échoue. Si l\'attaque Coup du phénix doré réussit, elle inflige +10...30 points de dégâts à la cible, et tous les ennemis adjacents subissent 10...30 points de dégâts','Inflige +10...30 points de dégâts à la cible et 10...30 points de dégâts aux ennemis adjacents. Echoue si vous n\'êtes pas sous l\'effet d\'un enchantement'],
990=>['Censure d\'Enchantements','La cible ennemie perd 1 enchantement. Toutes vos autres compétences n\'étant pas des attaques sont inutilisables pendant 8...4 secondes. Pour chaque compétence désactivée de cette manière, la cible ennemie touchée perd 1 enchantement supplémentaire.','Supprime un enchantement pour chaque compétence non offensive dont vous disposez. Toutes vos compétences non offensives sont désactivées (8...4 secondes).'],
991=>['Négation de maléfices','Supprime un maléfice d\'une cible alliée et un autre maléfice pour chacune de vos compétences de Faveur Divine qui se rechargent.','Supprime un maléfice d\'une cible alliée et un autre maléfice pour chacune de vos compétences de Faveur Divine qui se rechargent.'],
992=>['Triple coup','Vous attaquez la cible ennemie et tous les ennemis adjacents. Chaque attaque réussie inflige +10...40 points de dégâts.','Inflige +10...40 points de dégâts. Affecte aussi les ennemis adjacents.'],
993=>['Coup enragé','Si Coup enragé réussit, vous gagnez 1...4 décharges d\'adrénaline. Si vous touchez un ennemi en mouvement, vous infligez +10...40 points de dégâts et votre cible est assommée.','Vous recevez 1...4 décharges d\'adrénaline si votre attaque réussit. Inflige +10...40 points de dégâts et assomme votre cible si celle-ci était en mouvement.'],
994=>['Coup de renouvellement','Si Coup de renouvellement réussit, il inflige +10...40 points de dégâts. Si vous frappez un ennemi assommé, vous gagnez 3 points d\'énergie et cette attaque se recharge instantanément.','Inflige +10...40 points de dégâts. Vous gagnez 3 points d\'énergie et cette attaque se recharge instantanément si la cible ennemie était assommée.'],
995=>['Pose du tigre','Pendant 4...10 secondes, vous attaquez 33% plus vite. La Pose du tigre prend fin si une de vos attaques échoue.','(4...10 secondes.) Vous attaquez 33% plus vite. Prend fin si votre attaque échoue.'],
996=>['Entaille permanente','Si elle réussit, cette compétence inflige +5...20 points de dégâts et 5...20 points de dégâts supplémentaires si vous êtes en pose de combat.','Inflige +5...20 points de dégâts. Inflige 5...20 points de dégâts supplémentaires si vous êtes en pose.'],
997=>['Famine','Crée un esprit de niveau 1...10. Lorsqu\'une créature dans sa portée (autre qu\'un esprit) atteint 0 points d\'énergie, elle subit 20...70 points de dégâts. Cet esprit meurt au bout de 30...180 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...180 secondes). Inflige 20...70 points de dégâts aux créatures à portée qui ont 0 point d\'énergie. N\'affecte pas les esprits.'],
1018=>['Oeil critique','Pendant 10...35 secondes, vous avez 3...15% de chances supplémentaires d\'infliger un coup critique lors d\'une attaque. Vous obtenez 1 points d\'énergie chaque fois que vous infligez un coup critique.','(10...35 secondes.) Vous avez +3...15% de chances d\'infliger un coup critique. Vous obtenez 1 points d\'énergie chaque fois que vous infligez un coup critique.'],
1019=>['Attaque critique','Doit succéder à une attaque main gauche. Si elle réussit, cette attaque inflige +10...30 points de dégâts et résulte en un coup critique. Vous bénéficiez de 1...3 points d\'énergie.','Inflige +10...30 points de dégâts. Coup critique automatique. Vous gagnez 1...3 points d\'énergie. Doit succéder à une attaque main gauche.'],
1020=>['Lames d\'acier','Doit succéder à une attaque main gauche. Si elle réussit, cette attaque inflige +5...16 points de dégâts (bonus maximum : 60) pour chaque attaque à la dague qui se recharge.','Inflige +5...16 points de dégâts (maximum : 60) pour chaque attaque à la dague qui se recharge. Doit succéder à une attaque main gauche.'],
1021=>['Frappe de la jungle','Doit suivre une attaque dominante. Si cette attaque porte, elle inflige +10...25 points de dégâts. Si elle touche un ennemi sous le coup d\'Infirmité, cet ennemi et tous les ennemis adjacents subissent 1...31 points de dégâts.','Inflige +10...25 points de dégâts. Inflige 1...31 points de dégâts à l\'ennemi ciblé et aux ennemis adjacents si l\'ennemi ciblé est sous le coup d\'Infirmité. Doit suivre une attaque dominante.'],
1022=>['Affront sauvage','Doit succéder à une attaque main droite. Si elle réussit, cette attaque inflige +10...35 points de dégâts et chaque pose utilisée par la cible prend fin. Cette attaque ne peut être bloquée.','Inflige +10...35 points de dégâts. Annule la pose de la cible ennemie. Impossible à bloquer. Doit succéder à une attaque main droite.'],
1023=>['Piqûre de mante sauteuse','Si la Piqûre de mante sauteuse réussit, la cible ennemie subit +5...15 points de dégâts. Si l\'attaque touche un ennemi en déplacement, celui-ci souffre d\'Infirmité pendant 3...15 secondes.','Inflige +5...15 points de dégâts. Provoque l\'Infirmité (3...15 secondes) si la cible ennemie est en mouvement.'],
1024=>['Attaque de la mante noire','Si cette attaque réussit, vous infligez +8...20 points de dégâts. Si la cible ennemie est sous les effets d\'un maléfice, elle souffre d\'Infirmité pendant 3...15 secondes.','Inflige +8...20 points de dégâts. Provoque l\'Infirmité (3...15 secondes) si la cible ennemie est affectée par un maléfice.'],
1025=>['Blessure d\'interruption','Si cette attaque réussit, elle interrompt l\'action de la cible ennemie. S\'il s\'agissait d\'un sort, il est inutilisable pendant 3...10 secondes.','Interrompt une action. Si l\'action interrompue était un sort, celui-ci est désactivé (3...10 secondes).'],
1026=>['Coup du lotus doré','Si elle réussit, cette attaque inflige +5...20 points de dégâts. Si vous êtes affecté par un enchantement, vous obtenez 5...8 points d\'énergie.','Inflige +5...20 points de dégâts. Vous gagnez 5...8 points d\'énergie si vous êtes sous les effets d\'un enchantement.'],
1027=>['Défenses critiques','Pendant 4...10 secondes, vous avez 75% de chances de bloquer. Les Défenses critiques se rechargent chaque fois que vous infligez un coup critique.','(4...10 secondes.) Vous avez 75% de chances de bloquer. Renouvellement : chaque fois que vous infligez un coup critique.'],
1028=>['Méthode du geste parfait','Pendant 60 secondes, chaque fois que vous infligez un coup critique, vous obtenez 10...40 points de vie.','(60 secondes.) Vos coups critiques vous soignent de 10...40 points de vie.'],
1029=>['Apostasie obscure','Pendant 3...17 secondes, chaque fois que vous réussissez un coup critique, vous supprimez un enchantement de votre cible. Si vous supprimez un enchantement de cette manière, soit vous perdez 10...3 points d\'énergie, soit l\'Apostasie obscure prend fin.','(3...17 secondes.) Vos coups critiques suppriment un enchantement. Coût de la suppression : vous perdez 10...3 points d\'énergie ou l\'Apostasie obscure prend fin.'],
1030=>['Fureur de Locuste','Pendant 10...35 secondes, vous avez 50% de chances supplémentaires de faire une attaque double en utilisant des dagues','(10...35 secondes.) Vous avez +50% de chances d\'effectuer une attaque double. Aucun effet si vous n\'utilisez pas de dagues.'],
1031=>['Linceul de détresse','Pendant 30...60 secondes, si votre santé est inférieure à 50%, vous bénéficiez d\'une régénération de santé de +3...8 et de 75% de chances de bloquer les attaques.','(30...60 secondes.) Vous bénéficiez d\'une régénération de santé de +3...8 et de 75% de chances de bloquer les attaques. Sans effet si votre santé est supérieure à 50%.'],
1032=>['Coeur d\'ombre','Vous êtes soigné de 30...150 points de vie. Vous faites une Foulée de l\'ombre jusqu\'à une position proche directement opposée à votre cible.','Vous êtes soigné de 30...150 points de vie et vous faites une Foulée de l\'ombre jusqu\'à une position proche directement opposée à votre cible.'],
1033=>['Empalement','Doit suivre une attaque d\'ambidextrie. La cible ennemie reçoit 25...100 points de dégâts de la terre et souffre de Blessure profonde pendant 5...20 secondes.','Inflige 25...100 points de dégâts de la terre. Provoque la Blessure profonde (5...20 secondes). Doit succéder à une attaque d\'ambidextrie.'],
1034=>['Plaie suintante','For 1...7 seconds, target foe moves 33% slower. That foe takes 5...25 damage each second while suffering from a condition.','(1...7 secondes.) La cible ennemie se déplace 33% moins vite. Cet ennemi subit 5...25 points de dégâts par seconde s\'il souffre d\'une condition.'],
1035=>['Promesse de l\'Assassin','Pendant 5...15 secondes, si la cible ennemie meurt, vous bénéficiez de 5...20 points d\'énergie et toutes vos compétences sont rechargées.','(5...15 secondes.) Si la cible ennemie meurt, vous obtenez 5...20 points d\'énergie et toutes vos compétences sont rechargées.'],
1036=>['Sceau de malice','Pour chaque condition dont la cible ennemie souffre, vous perdez une condition.','Vous perdez une condition pour chaque condition qui affecte l\'ennemi visé.'],
1037=>['Echappatoire obscure','Pendant 5...15 secondes, vous vous déplacez 25% plus vite et subissez la moitié des dégâts. L\'effet cesse si votre attaque inflige des dégâts.','(5...15 secondes.) Vous vous déplacez 25% plus vite et subissez la moitié des dégâts. Prend fin si vous réussissez une attaque.'],
1038=>['Dague d\'Infirmité','Vous envoyez une Dague d\'Infirmité sur la cible ennemie. L\'attaque inflige 15...60 points de dégâts de la terre si elle réussit, et cause l\'Infirmité chez les ennemis en mouvement pendant 3...15 secondes. La portée de ce sort est deux fois plus courte.','Projectile : inflige 15...60 points de dégâts de la terre. Provoque l\'Infirmité (3...15 secondes) si la cible ennemie est en mouvement.'],
1040=>['Marche des esprits','Faites une Foulée de l\'ombre vers l\'esprit visé.','Vous faites une foulée de l\'ombre vers l\'esprit visé.'],
1041=>['Furie invisible','Tous les ennemis adjacents sont aveuglés pendant 3...10 secondes. Pendant 10...30 secondes, vous ne pouvez pas être bloqué par des ennemis aveuglés.','Provoque l\'Aveuglement (3...10 secondes). Vos attaques ne peuvent pas être bloquées par des ennemis aveuglés (10...30 secondes).'],
1042=>['Lames éclatantes','Pendant 5...30 secondes, vous avez 75% de chances de bloquer les attaques ennemies pendant que vous attaquez. A chaque fois que vous bloquez une attaque de cette manière, l\'attaquant subit 5...20 points de dégâts.','(5...30 secondes.) 75% de chances de bloquer pendant que vous attaquez. Effet du blocage : 5...20 points de dégâts à l\'assaillant.'],
1043=>['Ruée','Pendant 3 secondes, vous courez 50% plus vite.','(3 secondes.) Vous vous déplacez 50% plus vite.'],
1044=>['Prison obscure','Vous faites une Foulée de l\'ombre en direction de la cible ennemie. Pendant 1...6 secondes, la cible se déplace 33% moins vite.','Vous faites une foulée de l\'ombre vers la cible ennemie. Cet ennemi se déplace 33% moins vite (1...6 secondes).'],
1045=>['Coup de paume','La cible ennemie visée subit 10...65 points de dégâts et souffre d\'Infirmité pendant 1...5 secondes. Cette compétence compte comme une attaque main gauche.','Inflige 10...65 points de dégâts et la condition d\'Infirmité (1...5 secondes). Compte comme une attaque de main gauche.'],
1048=>['Enchantement révélé','Ote un enchantement à l\'ennemi visé et vous obtenez 3...15 points d\'énergie. Pendant 20 secondes, l\'enchantement révélé est remplacé par celui qui a été pris à la cible ennemie.','Supprime un enchantement à la cible ennemie. Effets de la suppression : vous obtenez 3...15 points d\'énergie ; ce sort est remplacé par cet enchantement (20 secondes).'],
1049=>['Maléfice révélé','Lève un maléfice de la cible (un allié ou vous-même) et vous gagnez 4...10 points d\'énergie. Pendant 20 secondes, le maléfice révélé est remplacé par celui qui a été levé.','Lève un maléfice qui frappe la cible alliée. Effets de la suppression : vous obtenez 4...10 points d\'énergie ; ce sort est remplacé par ce maléfice (20 secondes).'],
1052=>['Cumul de douleur','La cible ennemie subit 15...75 points de dégâts. Si celle-ci est affectée par 2 maléfices ou plus, elle souffre de Blessure profonde pendant 5...20 secondes.','Inflige 15...75 points de dégâts. Provoque une Blessure profonde (5...20 secondes) si la cible ennemie est affectée par 2 maléfices ou plus.'],
1053=>['Distraction psychique','Toutes vos autres compétences sont désactivées pendant 8 secondes. Si l\'ennemi visé est en train d\'utiliser une compétence, celle-ci est interrompue et désactivée pendant 5...12 secondes supplémentaires.','Interrompt une compétence. Effet de l\'interruption : désactive la compétence interrompue (+5...12 secondes). Vos autres compétences sont désactivées (8 secondes).'],
1054=>['Visage de l\'ancêtre','Pendant 4...10 secondes, à chaque fois que la cible (un allié ou vous-même) visée est touchée par une attaque au corps à corps, tous les ennemis adjacents perdent toute leur adrénaline et 3 points d\'énergie.','(4...10 secondes.) Tous les ennemis adjacents perdent toute leur adrénaline ainsi que 3 points d\'énergie chaque fois que la cible (un allié ou vous-même) est touchée par une attaque au corps à corps.'],
1055=>['Insécurité récurrente','Pendant 5 secondes, la cible ennemie subit une dégénération de santé de -1...6. Si cet ennemi est victime d\'un autre maléfice lorsqu\'Insécurité récurrente prend fin, l\'effet est renouvelé.','(5 secondes.) Provoque une dégénération de santé de -1...6. Renouvellement : se renouvelle au lieu de prendre fin si la cible ennemie est frappée d\'un autre maléfice.'],
1056=>['Fardeau de Kitah','Pendant 6...12 secondes, la cible ennemie se déplace 50% moins vite. Quand le Fardeau de Kitah prend fin, vous gagnez 10...18 points d\'énergie.','(6...12 secondes.) La cible ennemie se déplace 50% moins vite. Effet final : vous gagnez 10...18 points d\'énergie.'],
1057=>['Instabilité psychique','Interrompt l\'action de l\'ennemi visé. S\'il s\'agit d\'une compétence, cet ennemi et tous les ennemis à proximité sont assommés pendant 2...4 secondes. (50 % de risques d\'échec avec Incantation rapide 4 ou inférieure).','Interrompt une action. Effet de l\'interruption : s\'il s\'agit d\'une compétence, pendant 2...4 secondes l\'ennemi visé et tous les ennemis à proximité sont assommés. 50 % de risques d\'échec avec Incantation rapide 4 ou inférieure.'],
1059=>['Sceau du Mangeur de Maléfices','La cible alliée touchée, et jusqu\'à 2...5 alliés adjacents perdent chacun un maléfice. Vous gagnez 1...4 points d\'énergie pour chaque maléfice supprimé de cette manière.','Lève un maléfice qui frappe la cible et 2...5 alliés adjacents. Effet de la suppression : vous gagnez 1...4 points d\'énergie pour chaque maléfice levé.'],
1061=>['Rétroaction','La cible ennemie perd un enchantement. Si un enchantement est ôté de cette manière, cet ennemi perd aussi 4...10 points d\'énergie.','Supprime un enchantement. Effet de la suppression : la cible ennemie perd 4...10 points d\'énergie.'],
1062=>['Larcin arcane','Pendant 5...35 secondes, l\'ennemi ciblé ne peut plus utiliser un sort choisi aléatoirement et le Larcin arcane est remplacé par ce sort.','(5...35 secondes.) Désactive un sort aléatoire. Cette compétence remplace ce sort.'],
1066=>['Vainqueur dépouillé','Pendant 3...15 secondes, chaque fois que l\'ennemi ciblé attaque ou lance un sort sur une créature ayant moins de santé, cet ennemi perd 25...100 points de vie.','(3...15 secondes.) Provoque une perte de 25...100 points de vie chaque fois que la cible ennemie attaque ou lance un sort sur une créature ayant une santé inférieure à la sienne.'],
1067=>['Coup du fléau','L\'ennemi subit 12...48 points de dégâts de l\'ombre. S\'il a plus de 50% de ses points de vie, vous lui volez jusqu\'à 12...48 points de vie.','Inflige 12...48 points de dégâts. Vole 12...48 points de vie si la santé de la cible ennemie est supérieure à 50%.'],
1068=>['Frisson amer','La cible ennemie subit 15...60 points de dégâts du froid. Si cet ennemi avait plus de santé que vous, le Frisson amer se rechargera instantanément.','Inflige 15...60 points de dégâts du froid. Se recharge instantanément si la cible ennemie a une santé supérieure à la vôtre.'],
1069=>['Saveurs de douleur','Si la cible ennemie a moins de 50% de santé, vous obtenez 30...150 points de vie.','Vous soigne de 30...150 points de vie. Aucun effet si la santé de la cible ennemie n\'est pas inférieure à 50%.'],
1070=>['Enchantements profanés','L\'ennemi et tous ceux à proximité subissent 6...60 points de dégâts de l\'ombre et 4...20 points de dégâts de l\'ombre pour chaque enchantement qui les affecte.','Inflige 6...60 points de dégâts à la cible et aux ennemis à proximité. Inflige 4...20 points de dégâts supplémentaires pour chaque enchantement qui les affectent.'],
1071=>['Frissons de terreur','Pendant 10...40 secondes, à chaque fois que l\'ennemi subit des dégâts du froid pendant qu\'il utilise une compétence, il est interrompu et soit vous perdez 8...3 points d\'énergie, soit les Frissons de terreur se terminent.','(10...40 secondes.) Des dégâts du froid interrompent les compétences de la cible ennemie. Coût de l\'interruption : vous perdez 8...3 points d\'énergie ou ce maléfice prend fin.'],
1075=>['Nuée vampirique','La nuée vampirique absorbe jusqu\'à 15...60 points de vie à trois cibles ennemies maximum se trouvant dans la zone.','Vole 15...60 points de vie. Touche 2 ennemis supplémentaires dans la zone.'],
1076=>['Buveur de sang','Si votre santé est supérieure à 90%, vous êtes pris de Saignement pendant 6 secondes. Vous absorbez jusqu\'à 20...65 points de vie à votre cible ennemie.','Vole 20...65 points de vie. Vous souffrez de Saignement (6 secondes) si votre santé est supérieure à 90%.'],
1077=>['Morsure vampirique','Vous touchez l\'ennemi pour lui voler 29...74 points de vie.','Vole 29...74 points de vie.'],
1078=>['Morsure de bauge','L\'ennemi visé touché subit 20...58 points de dégâts.','Inflige 20...58 points de dégâts.'],
1079=>['Toucher de faiblesse','La cible ennemie touchée perd 5...65 points de vie et souffre de Faiblesse pendant 5...20 secondes.','Provoque une perte de 5...65 points de vie. Inflige la Faiblesse (5...20 secondes).'],
1081=>['Vent de Teinai','La cible ennemie et les ennemis adjacents subissent 10...40 points de dégâts du froid. Les ennemis embrasés touchés par le Vent de Teinai subissent 40...80 points de dégâts supplémentaires et sont interrompus.','Inflige 10...40 points de dégâts du froid. Les ennemis embrasés subissent 40...80 points de dégâts et sont interrompus. Frappe également les ennemis adjacents.'],
1082=>['Flèche de choc','Vous envoyez une Flèche de choc qui vole rapidement en direction de la cible ennemie, et qui inflige 5...50 points de dégâts de la foudre. Si la Flèche de choc frappe un ennemi souffrant d\'Armure brisée, vous gagnez 5 points d\'énergie et 1 point d\'énergie supplémentaire tous les 2 rangs de Conservation d\'énergie. La Flèche de choc a 25% de pénétration d\'armure.','Projectile rapide : inflige 5...50 points de dégâts de la foudre. Vous gagnez 5 points d\'énergie et 1 point d\'énergie supplémentaire tous les 2 rangs de Conservation d\'énergie si vous frappez un ennemi souffrant d\'Armure brisée. 25% de pénétration d\'armure.'],
1083=>['Sol instable','Vous créez un Sol instable sur la position de l\'ennemi visé. Pendant 5 secondes, les ennemis à proximité subissent 10...40 points de dégâts de la terre chaque seconde. Les ennemis qui attaquent et sont frappés par Sol instable sont renversés.','Inflige 10...40 points de dégâts de la terre par seconde (5 secondes) et renverse les attaquants ennemis. Frappe les ennemis à proximité de la position initiale de la cible.'],
1084=>['Armure d\'éclats','Pendant 5...11 secondes, vous avez 25...50% de chances de bloquer les attaques et lorsque vous êtes la cible d\'un sort hostile ou d\'une attaque, un ennemi à proximité reçoit 5...35 points de dégâts de la terre.','(5...11 secondes.) Vous avez 25...50% de chances de bloquer les attaques. Inflige 5...35 points de dégâts de la terre à un ennemi à proximité chaque fois que vous êtes la cible d\'une attaque ou d\'un sort ennemi.'],
1085=>['Explosion de cendres','La cible ennemie et les ennemis adjacents subissent 35...65 points de dégâts de la terre. Les ennemis embrasés touchés par l\'Explosion de cendres subissent un maléfice pendant 5 secondes et ont 20...75% de chances de rater leurs attaques.','Inflige 35...65 points de dégâts de la terre. Les ennemis embrasés touchés par l\'Explosion de cendres subissent un maléfice pendant 5 secondes et ont 20...75 % de chances de rater leurs attaques. Also strikes adjacent.'],
1086=>['Pas du dragon','Vous invoquez un Pas du dragon sur la position de l\'ennemi visé. Tous les ennemis près de cette position sont renversés et subissent 26...100 points de dégâts de la terre.','Inflige 26...100 points de dégâts de la terre. Renverse. Affecte également les ennemis près de la cible.'],
1088=>['Seconde chance','Vous gagnez 1 points d\'énergie et 5 points de vie pour chaque point d\'énergie limité par l\'Afflux. Vous perdez tous vos enchantements.','Vous gagnez 1 points d\'énergie et 5 points de vie pour chaque point d\'Afflux. Vous perdez tous vos enchantements.'],
1090=>['Charbons ardents','La cible ennemie subit 10...70 points de dégâts du feu. Si vous êtes en état d\'Afflux, l\'ennemi est sous l\'effet d\'un maléfice pendant 3 secondes et subit 5...25 points de dégâts du feu supplémentaires par seconde.','Inflige 10...70 points de dégâts de feu à la cible. Si vous êtes en état d\'Afflux, l\'ennemi reçoit un maléfice pendant 3 secondes, subissant 5...25 points de dégâts du feu par seconde.'],
1091=>['Double dragon','Vous invoquez le pouvoir du dragon. Pendant 8 secondes, l\'allié ciblé et vous-même êtes enchantés par le Double dragon. Les ennemis adjacents subissent 10...40 points de dégâts du feu chaque seconde. De plus, quand votre allié ou vous-même utilisez une compétence ciblant un ennemi, celui-ci s\'embrase pendant 1...4 secondes.','(8 secondes.) Vous affecte, vous et l\'allié ciblé. Les ennemis adjacents subissent 10...40 points de dégâts du feu chaque seconde. Les compétences ciblant un ennemi infligent également Brûlure (1...4 secondes).'],
1093=>['Chaleur de Teinai','Déclenche une Chaleur de Teinai sur la position de l\'ennemi pendant 10...15 secondes. Les ennemis se trouvant à cette position subissent une dégénération de santé de 2...5 points. Les ennemis affaiblis attaquent 33% moins vite. Cette compétence est désactivée pendant 20 secondes.','(10...15 secondes.) Provoque une dégénération de santé de -2...5. Les ennemis affaiblis attaquent 33% moins vite. Désactivée pendant 20 secondes.'],
1094=>['Souffle de Feu','Crée un Souffle de feu sur la position actuelle de l\'ennemi. Pendant 5 secondes, les ennemis adjacents à cette position subissent 10...40 points de dégâts du feu par seconde.','Inflige 10...40 points de dégâts du feu par seconde (5 secondes). Frappe les ennemis adjacents à la position initiale de la cible.'],
1095=>['Eclat constellé','L\'ennemi touché et tous les ennemis à proximité subissent 7...112 points de dégâts du feu et s\'embrasent pendant 1...4 secondes. A chaque ennemi touché, vous gagnez 2 points d\'énergie.','Inflige 7...112 points de dégâts de feu. Embrase (1...4 secondes). Vous gagnez 2 points d\'énergie par ennemi touché. Affecte également les ennemis dans la zone.'],
1096=>['Glyphe d\'essence','Pendant 15 secondes, votre prochain sort ne nécessite pas de temps d\'incantation, mais vous fait perdre toute votre énergie.','(15 secondes.) Votre sort suivant est lancé instantanément. Vous perdez toute votre énergie.'],
1097=>['Prison de Teinai','Pendant 1...8 secondes, la cible ennemie est prise dans de la glace et se déplace 66% moins vite. Si l\'ennemi a Armure brisée, le froid provoque une dégénération de santé de 5...9 points.','(1...8 secondes.) La cible ennemie se déplace 66% moins vite. Les ennemis avec Armure brisée subissent une dégénération de santé de 5...9.'],
1098=>['Miroir de glace','Vous brisez un Miroir de glace en mille morceaux. Tous les ennemis près de vous et de l\'allié ciblé subissent 15...70 points de dégâts du froid et sont ralentis de 66% pendant 2...6 secondes. Si vous frappez un ennemi victime d\'un maléfice de la Magie de l\'eau, le Miroir de glace se recharge 50% plus vite.','Inflige 15...70 points de dégâts du froid et ralentit les ennemis de 66% (2...6 secondes). Affecte les ennemis proches de vous et de l\'allié ciblé. Se recharge 50% plus vite s\'il touche un ennemi frappé d\'un maléfice de la Magie de l\'eau.'],
1099=>['Cristaux de Teinai','L\'ennemi visé subit 20...40 points de dégâts. Si l\'ennemi visé est sous l\'effet d\'un maléfice de la Magie de l\'eau, lui et les ennemis à proximité reçoivent 20...40 points de dégâts supplémentaires, et les ennemis à proximité subissent la condition Armure brisée pendant 5...15 secondes.','Inflige 20...40 points de dégâts à la cible. Inflige +20...40 points de dégâts supplémentaires et la condition Armure brisée (5...15 secondes) si l\'ennemi visé est sous l\'effet d\'un maléfice de la Magie de l\'eau.'],
1113=>['Colère de Kirin','Pendant 5 secondes, les ennemis adjacents à la position sur laquelle le sort a été lancé subissent 8...32 points de dégâts sacrés par seconde.','Inflige 8...32 points de dégâts sacrés par seconde (5 secondes). Affecte les ennemis adjacents à votre position initiale.'],
1114=>['Lien spirituel','Pendant 8 secondes, à chaque fois que la cible (un allié ou vous-même) subit plus de 50 points de dégâts infligés par les 10 prochaines attaques ou sorts, cette cible est soignée de 30...90 points de vie.','(8 secondes.) Soigne de 30...90 points de vie chaque fois que l\'allié visé subit plus de 50 points de dégâts. Prend fin lorsque cet allié a subi des dégâts de 10 attaques ou sorts.'],
1115=>['Atmosphère enchanteresse','Pendant 4...10 secondes, les enchantements lancés sur un autre allié coûtent 10 points d\'énergie en moins (1 points d\'énergie minimum).','(4...10 secondes.) Les enchantements lancés sur l\'allié visé coûtent 10 points d\'énergie en moins (minimum : 1 points d\'énergie). Vous ne pouvez pas vous prendre pour cible.'],
1117=>['Paradis exquis','Soigne le lanceur et les membres du groupe à portée de voix de 15...60 points de vie.','Soigne le lanceur et les membres du groupe à portée de voix de 15...60 points de vie.'],
1118=>['Vague de guérison','La cible alliée est soignée de 20...120 points de vie. Tous les membres du groupe à portée de voix de votre cible regagnent un nombre de points de vie égal au bonus Faveur divine de ce sort. Vos Prières de châtiment sont inutilisables pendant 20 secondes.','Soigne de 20...120 points de vie. Les membres du groupe à portée de voix de votre cible gagnent un nombre de points de vie égal au bonus Faveur divine. <c x="SkillDull">Désactive vos Prières de châtiment (20 secondes).'],
1119=>['Cercle de guérison de Karei','Soigne le lanceur et toutes les créatures adjacentes de 30...180 points de vie.','Vous soigne de 30...180 points de vie. Soigne également les créatures adjacentes.'],
1120=>['Regard de Jamei','Soigne l\'allié de 35...180 points de vie.','Soigne de 35...180 points de vie. Vous ne pouvez pas vous prendre pour cible.'],
1121=>['Don de santé','Toutes vos compétences faisant appel à la caractéristique Prières de guérison sont inutilisables pendant 10...5 secondes. La cible alliée est soignée de 15...150 points de vie.','Soigne de 15...150 points de vie. Désactive toutes vos autres compétences liées aux Prières de guérison (10...5 secondes). Vous ne pouvez pas vous prendre pour cible.'],
1123=>['Bouclier de vie','Supprime 0...2 conditions affectant la cible alliée. Pendant 8 secondes, la prochaine fois que cet allié doit subir des dégâts ou un vol de vie, il gagne à la place l\'équivalent en points de vie (maximum 20...100 points).','(8 secondes.) Les prochains dégâts subis ou le prochain vol de vie seront convertis en soins (maximum : 20...100 points). Effet initial : supprime 0...2 conditions.'],
1126=>['Suppression empathique','Vous et un allié visé perdez 1 condition et 1 maléfice et êtes soignés de 50 points de vie.','Supprime une condition et un maléfice à l\'allié visé et à vous-même et guérit de 50 points de vie.Vous ne pouvez pas vous prendre pour cible.'],
1128=>['Chant de résurrection','Ressuscite le membre visé du groupe avec l\'équivalent de vos points de vie actuels et 5...35% d\'énergie. Sa portée est la moitié de celle d\'un sort normal.','Ressuscite le membre du groupe visé. Il revient à la vie avec votre capital actuel de points de vie et 5...35% d\'énergie.'],
1129=>['Parole du censeur','La cible ennemie subit 30...130 points de dégâts sacrés. Si votre cible avait moins de 50% de santé, Paroles de censure prend 20 secondes de plus pour se recharger.','Inflige 30...130 points de dégâts sacrés. +20 de temps de recharge si la cible ennemie a moins de 50% de santé.'],
1130=>['Lance de lumière','La Lance de lumière se dirige en direction de l\'ennemi et inflige 26...56 points de dégâts sacrés si elle touche sa cible. La Lance de lumière inflige +15...60 points de dégâts si elle touche un ennemi qui attaque.','Projectile : inflige 26...56 points de dégâts sacrés. Inflige 15...60 points de dégâts supplémentaires si la cible ennemie attaque.'],
1131=>['Coup d\'Amederoc','L\'ennemi touché subit 10...55 points de dégâts sacrés. Si elle est assommée, votre cible subira 10...55 points de dégâts sacrés en plus.','Inflige 10...55 points de dégâts sacrés. Inflige 10...55 points de dégâts sacrés supplémentaires si la cible ennemie est assommée.'],
1133=>['Attaque d\'ivresse','Si cette attaque réussit, vous infligez +10...40 points de dégâts et la cible est affectée par une des conditions suivantes : Blessure profonde (pendant 20 secondes), Faiblesse (pendant 20 secondes), Saignement (pendant 25 secondes) ou Infirmité (pendant 15 secondes). Vous êtes assommé après une Attaque d\'ivresse.','Inflige +10...40 points de dégâts. Inflige au hasard une des conditions suivantes : Blessure profonde (20 secondes), Faiblesse (20 secondes), Saignement (25 secondes) ou Infirmité (15 secondes). Vous êtes assommé.'],
1134=>['Frappe du Léviathan','Si cette attaque réussit, vous infligez +5...20 points de dégâts. Si elle est bloquée, la cible est assommée et subit 10...34 points de dégâts.','Inflige +5...20 points de dégâts. Attaque assommante infligeant 10...34 points de dégâts si elle est bloquée.'],
1135=>['Frappe de Jaizhenju','Si la Frappe de Jaizhenju réussit, vous infligez +1...30 points de dégâts. Si vous n\'utilisez pas de pose, la Frappe de Jaizhenju ne peut pas être bloquée.','Inflige +1...30 points de dégâts. Vous ne pouvez la bloquer qu\'en pose de combat.'],
1136=>['Taillade pénétrante','Si cette attaque réussit, vous infligez +10...25 points de dégâts. Cette attaque à la hache a 20% de pénétration d\'armure.','Inflige +10...25 points de dégâts. Pénétration d\'armure de 20%.'],
1137=>['Frappe du Yéti','Perte de toute l\'adrénaline. Attaque tous les ennemis adjacents. Si cette attaque frappe un ennemi souffrant d\'une condition, cet ennemi est assommé. (50% de risques d\'échec avec Maîtrise du marteau 4 ou inférieure.)','Attaque tous les ennemis adjacents. Assomme les ennemis souffrant d\'une condition. Vous perdez toute votre adrénaline. 50% de risques d\'échec sauf si vous avez Maîtrise du marteau 5 ou supérieure.'],
1141=>['"Vous mourrez !"','Si la cible ennemie a moins de 90% de santé, vous gagnez 1...3 décharges d\'adrénaline.','Vous gagnez 1...3 décharges d\'adrénaline. Aucun effet à moins que l\'ennemi ciblé ne soit à moins de 90% de santé.'],
1142=>['Parade propice','Pendant 8 secondes, la prochaine attaque lancée contre vous est bloquée. Vous gagnez 1...4 décharges d\'adrénaline lorsque cette pose prend fin.','(8 secondes.) Bloque une attaque. Effet final : vous gagnez 1...4 décharges d\'adrénaline.'],
1144=>['Attaque d\'Aildargent','Cette attaque inflige +1...40 points de dégâts si elle réussit.','Inflige +1...40 points de dégâts.'],
1146=>['Poussée','L\'ennemi ciblé touché subit 15...75 points de dégâts, sa posture prend fin et il est assommé.','L\'ennemi ciblé touché subit 15...75 points de dégâts, sa posture prend fin et il est assommé.'],
1191=>['Attaque éclatante','Si l\'Attaque éclatante réussit, vous infligez +5...25 points de dégâts et cette attaque offre une pénétration d\'armure de 10%.','Inflige +5...25 points de dégâts. Pénétration d\'armure de 10%.'],
1192=>['Tir de Zojun','Vous tirez une flèche dont la portée est réduite de moitié, mais qui inflige +10...40 points de dégâts.','Inflige +10...40 points de dégâts.'],
1194=>['Lien du prédateur','Pendant 5...20 secondes, votre familier attaque 25% plus vite et vous soigne de 1...31 points de vie à chaque attaque réussie.','(5...20 secondes.) Votre familier attaque 25% plus vite et vous recevez 1...31 points de vie chaque fois qu\'il réussit une attaque.'],
1195=>['Guérison partagée','Pendant 15 secondes, votre familier vole 1...20 points de vie chaque fois qu\'il réussit une attaque. Votre familier et vous êtes soignés de 20...104 points de vie. Si votre familier est mort, il est ressuscité avec 50% de santé. Si vous êtes équipé de cette compétence, votre familier vous accompagnera lors de vos déplacements.','(15 secondes.) Les attaques de votre familier volent 1...20 points de vie. Effet initial : vous soigne vous et et votre familier de 20...104 points, ressuscite votre familier (50% de santé) s\'il meurt. Si vous êtes équipé de cette compétence, votre familier vous accompagnera lors de vos déplacements.'],
1196=>['Hâte de Zojun','Pendant 5...11 secondes, vous vous déplacez 33% plus vite et avez 27...75% de chances de bloquer les projectiles qui vous visent. Hâte de Zojun prend fin si vous attaquez.','(5...11 secondes.) Vous vous déplacez 33% plus vite et vous avez 27...75% de chances de bloquer les projectiles. Prend fin si vous attaquez.'],
1197=>['Aiguillons','Cette compétence inflige seulement 10...30 points de dégâts et tire une flèche qui se déplace plus vite que la normale. Si l\'attaque touche un ennemi dont la santé est inférieure à 50%, elle se rechargera instantanément. Vos autres compétences d\'attaque sont inutilisables pendant 2 secondes.','Flèche rapide. Inflige 10...30 points de dégâts. Rechargement instantané si la cible ennemie a moins de 50% de santé. Vos autres compétences d\'attaque sont inutilisables (2 secondes).'],
1198=>['Flèche à pointe large','Vous décochez une flèche à pointe large qui se déplace plus lentement que la normale. Si l\'attaque réussit, l\'ennemi ciblé est frappé de Stupeur pendant 5...20 secondes et si la cible ennemie lance un sort, celui-ci est interrompu.','Flèche lente. Interrompt un sort. Inflige la Stupeur (5...20 secondes).'],
1199=>['Flèches de verre','Pendant 10...35 secondes, vos flèches infligent +6...20 points de dégâts si elles touchent leur objectif, et entraînent le Saignement pendant 10...20 secondes si elles sont bloquées.','(10...35 secondes.) Vos flèches infligent +6...20 points de dégâts. Provoque le Saignement (10...20 secondes) en cas de blocage.'],
1200=>['Sceau de l\'Archer','Pendant 1...24 secondes, les conditions que vous appliquez lorsque vous êtes équipé d\'un arc durent 150% plus longtemps.','(1...24 secondes.) Les conditions que vous appliquez lorsque vous êtes équipé d\'un arc durent 150% plus longtemps.'],
1201=>['Attaque sauvage','Votre familier tente une Attaque sauvage qui infligera +5...20 points de dégâts. Si l\'attaque touche un ennemi qui lance un sort, celui-ci sera assommé.','Inflige +5...20 points de dégâts. Attaque assommante si la cible ennemie lance un sort.'],
1202=>['Coup enragé','Votre familier tente un Coup enragé qui inflige une Blessure profonde à l\'ennemi visé pendant 5...20 secondes, ainsi que +10...50 points de dégâts.','Provoque une Blessure profonde (5...20 secondes) et inflige +10...50 points de dégâts.'],
1203=>['Violence bestiale','Votre familier tente une Violence bestiale qui infligera +5...20 points de dégâts. S\'il touche un ennemi assommé, celui-ci est pris de Stupeur pendant 4...10 secondes.','Inflige +5...20 points de dégâts. Provoque la Stupeur (4...10 secondes) si la cible ennemie est assommée.'],
1205=>['Morsure empoisonnée','Votre familier tente une Morsure empoisonnée qui afflige l\'ennemi pendant 5...20 secondes.','Provoque l\'Empoisonnement (5...20 secondes).'],
1206=>['Bond','La prochaine attaque de votre familier est un Bond qui inflige +5...20 points de dégâts. Si l\'attaque touche un ennemi en mouvement, celui-ci est assommé.','Inflige +5...20 points de dégâts. Attaque assommante si la cible ennemie se déplace.'],
1209=>['Furie bestiale','Toutes vos compétences qui ne sont pas des attaques sont inutilisables pendant 5 secondes. Pendant 5...11 secondes, vous attaquez 25% plus vite.','(5...11 secondes.) Vous attaquez 25% plus vite. Vos compétences non offensives sont désactivées (5 secondes).'],
1211=>['Nid de vipère','Crée un Nid de Vipère. Lorsqu\'il est activé, tous les ennemis à proximité subissent 5...35 points de dégâts perforants et sont empoisonnés pendant 5...20 secondes. Le Nid de vipères prend fin au bout de 90 secondes. Ce piège est facilement interrompu.','(90 secondes.) Affecte les ennemis à proximité. Inflige 5...35 points de dégâts perforants. Provoque l\'Empoisonnement (5...20 secondes). Cette compétence peut être facilement interrompue.'],
1212=>['Equinoxe','Crée un esprit de niveau 1...10. Les sorts entraînant l\'Afflux lancés dans son rayon d\'action provoquent un Afflux supplémentaire de 10. Il disparaît au bout de 30...240 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...240 secondes). Les sorts entraînant l\'Afflux lancés dans son rayon d\'action provoquent un Afflux supplémentaire de 10.'],
1213=>['Tranquillité','Crée un esprit de niveau 1...10. Les enchantements lancés par les créatures (autres que des esprits) se trouvant dans sa portée se terminent 20...50% plus vite. Cet esprit disparaît au bout de 15...120 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 15...120 secondes). Les enchantements prennent fin 20...50% plus vite sur les créatures à portée. N\'affecte pas les esprits.'],
1215=>['Clameur des âmes','La cible ennemie et tous les ennemis à proximité subissent 10...65 points de dégâts de la foudre. Si vous êtes à portée de voix d\'un esprit ou vous tenez un paquet, vous gagnez 10 points d\'énergie.','Inflige 10...65 points de dégâts de la foudre à la cible et aux ennemis à proximité. Vous gagnez 10 points d\'énergie si vous êtes à portée de voix d\'un esprit ou tenez un paquet.'],
1217=>['Seigneur de rituel','Pendant 5...35 secondes, vos caractéristiques de Ritualiste bénéficient d\'un bonus de 2...4 pour votre prochaine compétence. Si cette compétence est Rituel d\'asservissement, elle se recharge 10...60% plus vite et Seigneur de rituel se recharge instantanément.','(5...35 secondes.) Vous bénéficiez d\'un bonus de +2...4 à toutes les caractéristiques de Ritualiste pour votre prochaine compétence. Si cette compétence est Rituel d\'asservissement, elle se recharge 10...60% plus vite et Seigneur de rituel se recharge instantanément.'],
1218=>['Daoshen était cruel','Vous tenez les cendres de Daoshen pendant un maximum de 15...60 secondes. En tenant ses cendres, toutes les compétences du Ritualiste bénéficient de 10% de pénétration d\'armure. Lorsque vous déposez ses cendres, tous les ennemis à proximité subissent 15...85 points de dégâts de la foudre.','(15...60 secondes.) Vos compétences de Ritualiste bénéficient de 10% de pénétration d\'armure. Effet de la pose : inflige 15...85 points de dégâts de la foudre à tous les ennemis à proximité.'],
1219=>['Kaolai était protecteur','Vous tenez les cendres de Kaolai pendant un maximum de 15...60 secondes. Pendant ce temps, vous bénéficiez d\'un bonus d\'armure de 20. Lorsque vous les déposez, tous les membres du groupe sont soignés de 20...95 points de vie.','(15...60 secondes.) Vous bénéficiez d\'un bonus d\'armure de +20. Effet de la pose : tous les membres du groupe sont soignés de 20...95 points de vie.'],
1220=>['Songkai était attentive','Vous tenez les cendres de Songkai pendant un maximum de 45 secondes. Pendant ce temps, vos sorts et rituels d\'asservissement coûtent -5...50% d\'énergie sur la base du coût initial.','(45 secondes.) Vos sorts et rituels d\'asservissement coûtent -5...50% d\'énergie sur la base du coût initial.'],
1221=>['Xiko était coriace','Vous tenez les cendres de Xiko pendant un maximum de 5...20 secondes. Pour chaque maléfice ou condition qui vous affecte quand vous tenez les cendres, vous gagnez +3 en régénération de santé. En lâchant les cendres, vous perdez 1...4 conditions.','(5...20 secondes.) Vous bénéficiez d\'une régénération de santé de +3 par maléfice ou condition vous affectant. Effet de la pose : vous perdez 1...4 conditions.'],
1222=>['Namei était si gaie','Vous tenez les cendres de Naomei pendant un maximum de 45 secondes. Lorsque vous les déposez, tous les membres du groupe dans la zone sont ressuscités avec 15...75% de santé et aucune énergie.','(45 secondes.) Effet de la pose : ressuscite les membres du groupe dans la zone (15...75% de santé, 0 point d\'énergie).'],
1223=>['Lingwah était angoissée','Vous tenez les cendres de Lingwah pendant un maximum de 10...60 secondes. En tenant ses cendres, vos maléfices de Ritualiste coûtent 1...5 points d\'énergie en moins et durent 50% plus longtemps. Lorsque vous déposez ses cendres, tous vos maléfices de Ritualiste sont rechargés.','(10...60 secondes.) Vos maléfices de Ritualiste coûtent 1...5 points d\'énergie en moins et durent 50% plus longtemps. Effet de la pose : tous vos maléfices de Ritualiste sont rechargés.'],
1224=>['Attraction d\'esprit','Vous téléportez un esprit allié ciblé jusqu\'à votre position.','Téléporte l\'esprit allié visé vers votre position.'],
1225=>['Frappe canalisée','La cible ennemie subit 5...95 points de dégâts de la foudre. Cet ennemi reçoit 5...35 points de dégâts de la foudre supplémentaires si vous tenez un objet.','Inflige 5...95 points de dégâts de la foudre. Inflige 5...35 points de dégâts de la foudre supplémentaires si vous tenez un objet.'],
1226=>['Coup du compagnon spirituel','La cible ennemie subit 20...65 points de dégâts de la foudre et tous les esprits que vous contrôlez à portée de voix bénéficient de 20...65 points de vie.','Inflige 20...65 points de dégâts de la foudre. Tous les esprits que vous contrôlez à portée de voix gagnent 20...65 points de vie.'],
1227=>['Frappe d\'essence','La cible ennemie subit 15...60 points de dégâts de la foudre. Si des esprits se trouvent à portée de voix, vous gagnez 1...9 points d\'énergie.','Inflige 15...60 points de dégâts de la foudre. Vous gagnez 1...9 points d\'énergie si un esprit est à portée de voix.'],
1228=>['Siphon de l\'esprit','L\'esprit le plus proche de vous perd toute son énergie. Vous bénéficiez de 30...60% de cette énergie.','L\'esprit le plus proche de vous perd toute son énergie. Vous bénéficiez de 30...60% de cette énergie.'],
1229=>['Expansion explosive','Pendant 15...60 secondes, chaque fois que vous créez une créature, jusqu\'à 5 ennemis proches de cette créature reçoivent 20...65 points de dégâts de la foudre.','(15...60 secondes.) Inflige 20...65 points de dégâts de la foudre à 5 ennemis près de chaque créature invoquée.'],
1230=>['Compagnon de création','Pendant 15...60 secondes, chaque fois que vous créez une créature, vous bénéficiez de 5...50 points de vie et de 1...6 points d\'énergie.','(15...60 secondes.) Vous gagnez 5...50 points de vie et 1...6 points d\'énergie chaque fois que vous créez une créature.'],
1231=>['Canalisation d\'esprit','Pendant 12 secondes, vous bénéficiez d\'une régénération d\'énergie de +1...6. Si vous vous trouvez à portée de voix d\'un esprit lorsque vous lancez ce sort, vous gagnez 3...12 points d\'énergie.','(12 secondes.) Vous bénéficiez d\'une régénération d\'énergie de +1...6. Effet initial : si vous vous trouvez à portée de voix d\'un esprit, vous gagnez 3...12 points d\'énergie.'],
1232=>['Armure de l\'impassible','Pendant 10...35 secondes, vos esprits à portée de voix subissent 50% de dégâts en moins et sont immunisés contre les coups critiques.','(10...35 secondes.) Vos esprits à portée de voix subissent 50% de dégâts en moins et sont immunisés contre les coups critiques.'],
1233=>['Souvenirs apaisants','La cible (un allié ou vous-même) est soignée de 10...100 points de vie. Si vous tenez un objet, vous bénéficiez de 3 points d\'énergie.','Soigne de 10...100 points de vie. Vous gagnez 3 points d\'énergie si vous tenez un objet.'],
1234=>['Guérison du corps et de l\'âme','Soigne l\'allié ciblé à hauteur de 20...115 points de vie. Cet allié est débarrassé d\'une condition par esprit à portée de voix.','Soigne de 20...115 points de vie. Supprime une condition par esprit à portée de voix.'],
1235=>['Arme émoussée','Pendant 5...20 secondes, la cible ennemie et tous les ennemis adjacents ne peuvent pas infliger de coups critiques et infligent 3...20 points de dégâts en moins.','Inflige également des maléfices aux ennemis adjacents à votre cible (5...20 secondes). Supprime la capacité à réaliser un coup critique. Réduit les dégâts de 3...20.'],
1236=>['Chaînes d\'asservissement','Pendant 3 secondes, l\'ennemi visé et tous les ennemis à proximité se déplacent 90 % moins vite et subissent 1...30 points de dégâts par seconde en se déplaçant.','Inflige également des maléfices aux ennemis proches de votre cible (3 secondes). Ces ennemis se déplacent 90% moins vite et subissent 1...30 points de dégâts par seconde en se déplaçant.'],
1237=>['Lien de douleur','Pendant 10...20 secondes, l\'ennemi visé et tous les ennemis à proximité souffrent du maléfice Lien de douleur et subissent 8...20 points de dégâts lorsqu\'ils sont touchés par l\'attaque d\'un esprit.','Inflige également des maléfices aux ennemis à proximité de votre cible (10...20 secondes). Les esprits infligent 8...20 points de dégâts supplémentaires à ces ennemis.'],
1238=>['Sceau de création','Vous gagnez 4 points d\'énergie pour chaque créature invoquée que vous contrôlez à portée de voix (maximum de 3...12 points d\'énergie).','Bénéfice de 4 points d\'énergie (maximum de 3...12 points) pour chaque créature invoquée que vous contrôlez à portée de voix.'],
1239=>['Sceau des Esprits','Crée 3 esprits de niveau 1...12. Ces esprits infligent 5...20 points de dégâts avec leurs attaques et meurent au bout de 60 secondes.','Crée 3 esprits de niveau 1...12 (durée de vie de 60 secondes). Ces esprits infligent 5...20 points de dégâts avec leurs attaques.'],
1240=>['Contorsion de l\'âme','Pendant 5...45 secondes, vos Rituels d\'asservissement coûtent 15 points d\'énergie en moins (Minimum 5) et se rechargent instantanément. Contorsion de l\'âme prend fin après 1...3 Rituels d\'asservissement.','(5...45 secondes.) Vos Rituels d\'asservissement coûtent 15 points d\'énergie en moins (Minimum 5) et se rechargent instantanément. Prend fin après 1...3 Rituels d\'asservissement.'],
1244=>['Vivacité spectrale','Pendant 5...30 secondes, les sorts que vous lancez à portée de voix d\'un esprit se rechargent 25% plus vite.','(5...30 secondes.) Les sorts que vous lancez se rechargent 25% plus vite. Aucun effet si vous n\'êtes pas à portée de voix d\'un esprit.'],
1245=>['Vision de l\'au-delà','La cible ennemie subit 20...65 points de dégâts de la foudre. Si vous vous trouvez à portée de voix d\'un esprit, cet ennemi est Aveuglé pendant 2...6 secondes.','Inflige 20...65 points de dégâts de la foudre. Provoque l\'Aveuglement pendant 2...6 secondes si vous êtes à portée de voix d\'un esprit.'],
1246=>['Rage de l\'ancêtre','Pendant 1 secondes, rien ne se passe. Lorsque cette compétence prend fin, tous les ennemis adjacents à la cible alliée subissent 5...110 points de dégâts de la foudre.','(1 secondes.) Effet final : inflige 5...110 points de dégâts de la foudre aux ennemis adjacents à l\'allié visé.'],
1247=>['Douleur','Crée un esprit de niveau 1...12. L\'attaque de cet esprit inflige 5...30 points de dégâts. L\'esprit meurt au bout de 30...150 secondes.','Crée un esprit de niveau 1...12 (durée de vie de 30...150 secondes). Ses attaques infligent 5...30 points de dégâts.'],
1249=>['Déplacement','Crée un esprit de niveau 1...14. Tous les alliés autre que des esprits à portée ont 75% de chances de bloquer les attaques. Chaque fois qu\'une attaque est bloquée de cette manière, cet esprit subit 60 points de dégâts. Il disparaît au bout de 30...60 secondes.','Crée un esprit de niveau 1...14 (durée de vie de 30...60 secondes). Les alliés (autres que les esprits) à portée ont 75% de chances de bloquer. Effet du blocage : cet esprit subit 60 points de dégâts.'],
1250=>['Préservation','Vous créez un esprit de niveau 1...14. Toutes les 4 secondes, cet esprit soigne un allié (autre qu\'un esprit) dans la zone de 10...115 points de vie. Il meurt au bout de 90 secondes.','Crée un esprit de niveau 1...14 (durée de vie de 90 secondes). Toutes les 4 secondes, cet esprit soigne un allié (autre qu\'un esprit) de 10...115 points de vie.'],
1251=>['Vie','Crée un esprit de niveau 1...14. Lorsque cet esprit meurt, tous les alliés (autres que des esprits) dans sa portée sont soignés de 1...7 points de vie pour chaque seconde d\'existence de cet esprit. Il meurt au bout de 20 secondes.','Crée un esprit de niveau 1...14 (durée de vie de 20 secondes). Affecte les alliés à portée, à l\'exception des esprits. Effet final : soigne de 1...7 points de vie par seconde d\'existence de cet esprit.'],
1252=>['Lien terrestre','Crée un esprit de niveau 1...14. Tous les ennemis (autres que des esprits) assommés dans sa portée le sont pour au moins 3 secondes. Chaque fois, cet esprit perd 50...25 points de vie. Il meurt au bout de 15...45 secondes.','Crée un esprit de niveau 1...14 (durée de vie de 15...45 secondes). Chaque fois que des ennemis (autres que des esprits) à portée sont assommés, ils le sont pour au moins 3 secondes. Coût de l\'assommement : cet esprit perd 50...25 points de vie.'],
1253=>['Mélodie du sang','Crée un esprit de niveau 1...12 qui meurt au bout de 30...150 secondes. Les attaques de cet esprit absorbent jusqu\'à 5...25 points de vie.','Crée un esprit de niveau 1...12 (durée de vie de 30...150 secondes). Ses attaques volent 5...25 points de vie.'],
1255=>['Voyage','Crée un esprit de niveau 1...12. Chaque fois que l\'attaque de cet esprit touche un ennemi immobile, cet ennemi est assommé et l\'esprit perd 70...50 points de vie. Il meurt au bout de 30...60 secondes.','Crée un esprit de niveau 1...12 (durée de vie de 30...60 secondes). Ses attaques peuvent assommer les ennemis immobiles. Coût de l\'assommement : cet esprit perd 70...50 points de vie.'],
1257=>['Arme d\'Esprit illuminé','Pendant 10 secondes, la cible (un allié ou vous-même) bénéficie de 5...25 points de vie par seconde et de 5...25 points de vie en plus par seconde si cette cible se trouve à portée de voix d\'un esprit.','(10 secondes.) L\'allié visé gagne 5...25 points de vie par seconde. 5...25 points de vie supplémentaires par seconde tant qu\'un esprit est à portée de voix.'],
1258=>['Arme brute','Donne à la cible (un allié ou vous-même) une Arme brute pendant 10...40 secondes. Le porteur de l\'arme inflige +5...15 points de dégâts tant qu\'il n\'est pas sous l\'effet d\'un enchantement.','(10...40 secondes.) Les attaques infligent +5...15 points de dégâts. Aucun effet si l\'allié visé est enchanté.'],
1259=>['Arme guidée','Pendant 4...10 secondes, les attaques de la cible visée (allié ou vous-même) ne peuvent pas être bloquées.','(4...10 secondes.) Les attaques sont impossibles à bloquer.'],
1260=>['Soumission','Pendant 5...30 secondes, la cible ennemie et tous les ennemis de la zone attaquent 50% moins vite.','Inflige également des maléfices aux ennemis dans la zone de la cible (5...30 secondes). Ces ennemis attaquent 50% moins vite.'],
1261=>['Armure glaciale','Pendant 10...25 secondes, vous bénéficiez de +10...40 de bonus d\'armure contre les dégâts physiques et vous ne pouvez pas être embrasé.','(10...25 secondes.) Vous bénéficiez d\'un bonus d\'armure de +10...40 contre les dégâts physiques et d\'une immunité contre la Brûlure.'],
1262=>['Anneau de guérison','Soigne les créatures adjacentes de 30...180 points de vie. Le lanceur n\'est pas soigné.','Soigne les alliés et les ennemis adjacents de 30...180 points de vie. Le lanceur n\'est pas soigné.'],
1263=>['Renouvellement de vie','Ressuscite le membre du groupe mort touché avec 50% de sa santé et 5...20% de son énergie. Ce membre du groupe et tous les alliés à portée de voix sont soignés de 55...130 points de vie.','Ressuscite le membre du groupe visé (50% de santé et 5...20% d\'énergie). Soigne les alliés à portée de voix de 55...130 points de vie.'],
1264=>['Destinée','Vous infligez à l\'ennemi 10...60 points de dégâts de la foudre (135 points maximum) pour chaque rituel d\'asservissement en recharge que vous avez.','Inflige 10...60 points de dégâts de la foudre (maximum : 135) pour chacun de vos rituels d\'asservissement se rechargeant.'],
1265=>['Compagnon d\'arme','Vous soignez la cible (un allié ou vous-même) de 15...60 points de vie. Si cette cible est sous l\'effet d\'un sort d\'altération d\'arme, le Compagnon d\'arme la soigne de 15...75 points de vie supplémentaires.','Soigne de 15...60 points de vie. Soigne de 15...75 points de vie supplémentaires si cet allié est sous les effets d\'un sort d\'altération d\'arme.'],
1266=>['Apaisement','Crée un esprit de niveau 1...12. Les ennemis dans sa portée mettent deux fois plus de temps pour récupérer de l\'adrénaline. Cet esprit disparaît au bout de 15...45 secondes.','Crée un esprit de niveau 1...12 (durée de vie de 15...45 secondes). Les ennemis à portée accumulent de l\'adrénaline deux fois moins vite.'],
1267=>['Arme vitale','Pendant 5...30 secondes, la cible (un allié ou vous-même) possède l\'Arme vitale et a une santé maximum de +40...175.','(5...30 secondes.) +40...175 de santé maximum.'],
1268=>['Arme de rapidité','Pendant 5...25 secondes, la cible (un allié ou vous-même) possède l\'Arme de rapidité et ses sorts et rituels d\'asservissement se rechargent 33% plus vite.','(5...25 secondes.) Les sorts et les rituels d\'asservissement se rechargent 33% plus vite.'],
1269=>['Sceau de Rage','La cible ennemie subit 5...50 points de dégâts sacrés et +5...10 points de dégâts sacrés pour chaque compétence d\'adrénaline qu\'il possède.','Inflige 5...50 points de dégâts sacrés. Inflige 5...10 points de dégâts sacrés supplémentaires pour chaque compétence d\'adrénaline que l\'ennemi possède.'],
1333=>['Conditions prolongées','Répand toutes les conditions de la cible ennemie à tous les ennemis à proximité de cette dernière. La durée de ces conditions est augmentée de 5...100% (30 secondes maximum).','Répand toutes les conditions de la cible ennemie à tous les ennemis à proximité de cette dernière. La durée de ces conditions est augmentée de 5...100% (30 secondes maximum).'],
1334=>['Hypochondrie','Transfère toutes les conditions de tous les ennemis de la zone à l\'ennemi visé.','Transfère toutes les conditions des ennemis de la zone à l\'ennemi visé.'],
1335=>['Fin du gaspilleur','Pendant 5 secondes, la cible ennemie est sous l\'emprise de Fin du gaspilleur. Chaque seconde sous l\'emprise du sort, la cible ennemie et tous les ennemis adjacents subissent 1...10 points de dégâts et 1...10 points de dégâts supplémentaires pour chaque seconde d\'activation de ce sort. Ce sort cesse prématurément si la cible ennemie utilise une compétence.','(5 secondes.) Chaque seconde sous l\'emprise du sort, la cible ennemie et tous les ennemis adjacents subissent 1...10 points de dégâts. Les ennemis subissent +1...10 points de dégâts pour chaque seconde d\'activation du sort. Se termine prématurément si la cible ennemie utilise une compétence.'],
1336=>['Douleur spirituelle','L\'ennemi visé subit 15...75 points de dégâts. Toutes les créatures hostiles invoquées situées près de cet ennemi subissent 25...125 points de dégâts.','Inflige 15...75 points de dégâts. Inflige 25...125 points de dégâts aux créatures hostiles invoquées qui sont situées près de l\'ennemi visé.'],
1337=>['Drain d\'illusions','Vous enlevez un maléfice d\'Envoûteur à la cible ennemie. Si ce maléfice est enlevé de cette manière, l\'ennemi perd 1...5 points d\'énergie et vous bénéficiez de 4 points d\'énergie pour chaque point qu\'il perd.','Supprime un maléfice d\'Envoûteur lancé par l\'ennemi visé. Provoque une perte de 1...5 points d\'énergie. Vous gagnez 4 points d\'énergie par point perdu. Aucun effet si aucun maléfice n\'est supprimé.'],
1338=>['Persistance du souvenir','Pendant 5...20 secondes, chaque fois qu\'un sort que vous lancez est interrompu, ce sort est instantanément rechargé.','(5...20 secondes.) Vos sorts interrompus se rechargent instantanément.'],
1339=>['Symboles d\'inspiration','Pendant 6...40 secondes, cette compétence devient la compétence élite de la cible ennemie. Les compétences élites que vous lancez utilisent votre caractéristique d\'Incantation rapide au lieu des caractéristiques qui y sont normalement associées.','(6...40 secondes.) Cette compétence devient la compétence élite de la cible ennemie. Les compétences élites utilisent votre caractéristique d\'Incantation rapide et non vos caractéristiques normales.'],
1340=>['Célérité symbolique','Pendant 36...60 secondes, tous vos sceaux utilisent votre caractéristique d\'Incantation rapide au lieu de leurs attributs habituels.','(36...60 secondes.) Vos sceaux utilisent votre attribut d\'Incantation rapide.'],
1341=>['Frustration','Pendant 5...20 secondes, la cible ennemie lance ses sorts 50% moins vite et subit 5...50 points de dégâts chaque fois qu\'elle est interrompue. Si une compétence est interrompue, Frustration inflige deux fois plus de dégâts.','(5...20 secondes.) Entraîne un ralentissement de 50% du temps d\'incantation des sorts. L\'ennemi visé subit 5...50 points de dégâts chaque fois qu\'il est interrompu. Inflige le double de dégâts à l\'interruption de compétence.'],
1342=>['Taquinerie','Si la cible ennemie utilise une compétence, elle et les autres ennemis de la zone sont interrompus et vous volez 0...5 points d\'énergie à chaque ennemi de la zone.','Interrompt une compétence. Effet de l\'interruption : les autres ennemis de la zone sont aussi interrompus et vous volez 0...5 points d\'énergie à chaque ennemi de la zone.'],
1343=>['Fantôme éthéré','Pendant 10 secondes, la cible ennemie subit une dégénération d\'énergie de -1. Si ce maléfice est supprimé prématurément, cet ennemi perd 1...5 points d\'énergie.','(10 secondes.) Provoque une dégénération d\'énergie de -1. Fait perdre 1...5 points d\'énergie si ce maléfice prend fin prématurément.'],
1344=>['Toile d\'interruption','Vous interrompez la cible ennemie. Pendant 10 secondes, la cible ennemie est victime du maléfice de Toile d\'interruption. Lorsque ce maléfice prend fin, cet ennemi est interrompu à nouveau.','(10 secondes.) Effet initial : interrompt une compétence. Effet final : interrompt une compétence.'],
1345=>['Enigme de l\'enchanteur','Pendant 10 secondes, l\'ennemi ciblé lance ses enchantements 100...200% moins vite. Si aucun enchantement n\'affecte l\'ennemi ciblé lorsque ce maléfice est appliqué, il subit 10...100 points de dégâts et tous les ennemis adjacents encaissent 75% de ces dégâts.','Inflige 100...200% de ralentissement à l\'incantation des enchantements (10 secondes). Effet initial : si aucun enchantement n\'affecte l\'ennemi ciblé, il subit 10...100 points de dégâts et tous les ennemis adjacents encaissent 75% de ces dégâts.'],
1346=>['Sceau des illusions','Vos prochains sorts autres que d\'Illusion (1...3 sorts) utilisent la caractéristique d\'Illusion au lieu de leur caractéristique normale.','Vos prochains sorts autres que d\'Illusion (1...3 sorts) utilisent la caractéristique d\'Illusion au lieu de leur caractéristique normale.'],
1347=>['Congédiement d\'enchantement','Supprime un enchantement chez la cible ennemie. Si cet ennemi est sous l\'effet d\'un maléfice, cette compétence se recharge 20...50% plus vite.','Supprime un enchantement chez la cible ennemie. Temps de recharge réduit de 20...50% si l\'ennemi est victime d\'un maléfice.'],
1348=>['Vortex du Mangeur de Maléfices','Supprime un maléfice de l\'allié ciblé. Si un maléfice est levé de cette manière, les ennemis à proximité de cet allié subissent 30...90 points de dégâts et perdent un enchantement.','Supprime un maléfice de l\'allié ciblé. Effet de la suppression : inflige 30...90 points de dégâts et supprime un enchantement des ennemis à proximité de cet allié.'],
1349=>['Miroir de désenchantement','Ote un enchantement à la cible ennemie. Tous les membres du groupe de cet ennemi perdent aussi cet enchantement.','Supprime un enchantement chez la cible ennemie. Les membres du groupe de cet ennemi perdent aussi cet enchantement.'],
1350=>['Simple vol','Interrompt l\'action de la cible ennemie. Si une compétence est interrompue, elle est désactivée pendant 5...20 secondes et remplace Simple Vol.','Interrompt une action. Effet de l\'interruption : si une compétence est interrompue, elle est désactivée et remplace Simple Vol (5...20 secondes).'],
1351=>['Animation d\'horreur dévastatrice','Vous exploitez le cadavre le plus proche pour créer une horreur dévastatrice de niveau 1...17. Lorsque celle-ci meurt, elle est remplacée par une horreur broyée de niveau 0...15 qui inflige le Saignement à chacune de ses attaques.','Crée une horreur dévastatrice de niveau 1...17. Lorsque celle-ci meurt, elle est remplacée par une horreur déchiquetée de niveau 0...15 qui inflige le Saignement à chacune de ses attaques. Exploite un cadavre récent.'],
1352=>['Ordre des morts-vivants','Pendant 5 secondes, vos serviteurs infligent +3...16 points de dégâts, mais vous perdez 2% de votre santé maximum chaque fois qu\'un de vos serviteurs réussit une attaque.','(5 secondes.) Vos serviteurs infligent +3...16 points de dégâts. Effet de l\'attaque réussie d\'un serviteur : vous perdez 2% de votre santé maximum.'],
1353=>['Chair putride','Vous détruisez un des serviteurs morts-vivants animés visés. Tous les ennemis près de cette créature souffrent de Maladie pendant 5...15 secondes.','Détruit un de vos serviteurs morts-vivants. Inflige la Maladie (5...15 secondes) aux ennemis près de ce serviteur.'],
1354=>['Festin des morts','Vous détruisez l\'allié mort-vivant animé ciblé. Tous vos autres alliés morts-vivants animés sont soignés de 10...100 points de vie.','Détruit un de vos serviteurs morts-vivants. Soigne vos serviteurs de 10...100 points de vie.'],
1355=>['Os broyés','Pendant 60 secondes, chaque fois que le serviteur mort-vivant ciblé meurt, il est remplacé par une horreur broyée de niveau 0...15 qui inflige le Saignement à chacune de ses attaques.','(60 secondes.) Quand le serviteur mort-vivant visé meurt, il est remplacé par une horreur déchiquetée de niveau 0...15 dont les attaques infligent le Saignement.'],
1356=>['Contagion','Pendant 60 secondes, chaque fois que vous souffrez d\'une nouvelle condition, tous les ennemis dans la zone sont affectés par la même condition et vous sacrifiez 10...5% de votre santé maximum.','(60 secondes.) Chaque fois qu\'une condition vous est infligée, elle est aussi infligée à tous les ennemis dans la zone. Vous sacrifiez 10...5% de votre santé maximum chaque fois que cela arrive.'],
1358=>['Poumons ulcérés','Pendant 10...30 secondes, l\'ennemi visé et tous les ennemis proches subissent une dégénération de santé de -4 lorsqu\'ils sont pris de Saignement. A chaque fois qu\'ils utilisent un chant ou un cri, ils saignent pendant 5...20 secondes.','Inflige également des maléfices aux ennemis à proximité de votre cible (10...30 secondes). Si un de ces ennemis souffre de Saignement, il subit une dégénération de santé de -4. Inflige le Saignement (5...20 secondes) chaque fois que ces ennemis utilisent un chant ou un cri.'],
1359=>['Douleur de désenchantement','La cible ennemie perd 1...3 enchantements. Si un enchantement est perdu de cette manière, la cible et tous les ennemis adjacents perdent 10...100 points de vie.','La cible ennemie perd 1...3 enchantements. Effet de la suppression : la cible ennemie et tous les ennemis adjacents perdent 10...100 points de vie.'],
1360=>['Marque de Furie','Pendant 5 secondes, les alliés frappant l\'ennemi visé gagne 0...2 décharges d\'adrénaline. Lorsque ce maléfice prend fin, cet ennemi souffre d\'Armure brisée pendant 1...15 secondes.','(5 secondes.) Les alliés gagnent 0...2 décharges d\'adrénaline en touchant la cible ennemie. Effet final : inflige Armure brisée (1...15 secondes).'],
1362=>['Enchantement corrompu','Ote un enchantement à l\'ennemi ciblé. Si un enchantement est supprimé de cette manière, cet ennemi subit une dégénération de santé de -1...8 pendant 10 secondes.','Supprime un enchantement chez la cible ennemie. Effet de la suppression : dégénération de santé de -1...8 (10 secondes).'],
1363=>['Sceau du chagrin','La cible ennemie subit 15...75 points de dégâts. Si cette cible ennemie se trouve près d\'un cadavre ou si son familier est mort, cette compétence se recharge instantanément.','Inflige 15...75 points de dégâts. Rechargement instantané si l\'ennemi visé est près d\'un cadavre ou si son familier est mort.'],
1364=>['Sceau de souffrance','Vous souffrez de Saignement pendant 6 secondes. La prochaine compétence de Nécromant qui cible un ennemi provoque un Saignement pendant 2...16 secondes.','Vous saignez pendant 6 secondes. Applique un Saignement (2...16 secondes) à la cible de votre prochaine compétence de Nécromant.'],
1365=>['Sceau des âmes perdues','Si la cible ennemie a moins de 50% de santé, vous obtenez 10...100 points de vie et 1...10 points d\'énergie.','Vous gagnez 10...100 points de vie et 1...10 points d\'énergie si l\'ennemi visé a moins de 50% de santé.'],
1366=>['Puits d\'obscurité','Exploitez le cadavre le plus proche ou sacrifiez 66% de santé pour créer un Puits d\'obscurité pendant 5...50 secondes. Les ennemis victimes de maléfices dans ce puits ratent leurs attaques 50% du temps.','(5...50 secondes.) Les ennemis sous l\'effet d\'un maléfice présents dans ce puits ont 50% de chances de manquer leur cible. Exploite un cadavre frais ou sacrifie 66% de la santé.'],
1367=>['Afflux aveuglant','La cible ennemie subit 5...50 points de dégâts de la foudre. Cet ennemi et tous les ennemis adjacents sont aveuglés pendant 3...8 secondes. Ce sort a une pénétration d\'armure de 25%. S\'il frappe un ennemi en train d\'attaquer, tous les ennemis adjacents sont touchés eux aussi et le sort inflige 50% de dégâts supplémentaires.','Inflige 5...50 points de dégâts de la foudre. Aveugle la cible et les ennemis adjacents (3...8 secondes). 25% de pénétration d\'armure. Si la cible attaquait, le sort touche aussi les ennemis adjacents et inflige 50% de dégâts en plus.'],
1368=>['Vents glaciaux','L\'ennemi visé et tous les ennemis adjacents subissent 30...60 points de dégâts du froid. Pendant 10 secondes, le prochain maléfice de la Magie de l\'eau que vous lancez sur un ennemi souffrant de maléfice dure 25...100% plus longtemps.','(10 secondes.) Le prochain maléfice de la Magie de l\'eau lancé sur un ennemi dure 25...100% plus longtemps. Effet initial : infligent 30...60 points de dégâts du froid. Frappe également les ennemis adjacents.'],
1369=>['Eclair','Lance un Eclair qui inflige 5...50 points de dégâts de la foudre s\'il touche sa cible. Si l\'Eclair touche un ennemi en mouvement, celui-ci subit 5...50 points de dégâts de la foudre en plus. Ce sort a une pénétration d\'armure de 25%.','Projectile : inflige 5...50 points de dégâts de la foudre. Inflige 5...50 points de dégâts de la foudre supplémentaires si la cible se déplace. 25% de pénétration d\'armure.'],
1370=>['Hâte du jinn de tempête','Pendant 10...25 secondes, vous vous déplacez 25% plus vite. Chaque seconde de déplacement vous fait perdre 1 points d\'énergie.','(10...25 secondes.) Vous vous déplacez 25% plus vite. Vous perdez 1 points d\'énergie par seconde de déplacement.'],
1371=>['Briseur de pierre','Pendant 5...30 secondes, à chaque fois que vous infligez ou subissez des dégâts élémentaires ou physiques, ces dégâts sont convertis en dégâts de la terre.','(5...30 secondes.) Convertit les dégâts élémentaires et physiques que vous subissez ou infligez en dégâts de la terre.'],
1372=>['Tempête de sable','Vous créez une tempête de sable sur la position de l\'ennemi visé. Pendant 10 secondes, les ennemis à proximité subissent 20...40 points de dégâts de la terre chaque seconde. Les ennemis qui attaquent reçoivent 10...30 points de dégâts de la terre supplémentaires chaque seconde.','Inflige 20...40 points de dégâts de la terre par seconde (10 secondes). Frappe les ennemis à proximité de la position initiale de la cible. Les attaquants ennemis subissent 10...30 points de dégâts de la terre en plus par seconde.'],
1373=>['Gaine de pierre','Pendant 5...20 secondes, l\'allié ciblé et vous gagnez +1...30 en armure et êtes immunisés contre les coups critiques. Quand vous lancez ce sort, tous les ennemis près de vous et de votre cible subissent 15...70 points de dégâts de la terre et souffrent de Faiblesse pendant 5...20 secondes.','(5...20 secondes.) L\'allié ciblé et vous gagnez +1...30 en armure et une immunité contre les coups critiques. Effet initial : Les ennemis près de vous et de l\'allié ciblé subissent 15...70 points de dégâts de la terre et souffrent de Faiblesse (5...20 secondes).'],
1374=>['Faucon d\'ébène','Vous envoyez un projectile qui inflige 10...85 points de dégâts de la terre et entraîne la Faiblesse pendant 5...15 secondes si elle réussit.','Projectile : inflige 10...85 points de dégâts de la terre et provoque la Faiblesse (5...15 secondes).'],
1375=>['Aura de Chair de pierre','Pendant 5...15 secondes, les dégâts que vous recevez sont réduits de 1...31, et vous êtes immunisé contre les attaques critiques.','(5...15 secondes.) Les dégâts qui vous sont infligés sont réduits de 1...31 et vous êtes immunisé contre les coups critiques.'],
1376=>['Glyphe de rétablissement','Pendant 15 secondes, vos 2 prochains sorts vous guérissent de 30...105 points de vie, et vous êtes soigné de 150...400% du coût en énergie de chaque sort. ','(15 secondes.) Vos 2 prochains sorts vous guérissent de 30...105 points de vie et vous êtes soigné de 150...400% du coût en énergie de chaque sort.'],
1377=>['Prisme éthéré','Pendant 3 secondes, les dégâts que vous subissez sont réduits de 75%. Lorsque Prisme éthéré prend fin, vous gagnez 5...20 points d\'énergie.','(3 secondes.) Les dégâts que vous subissez sont réduits de 75%. Effet final : vous gagnez 5...20 points d\'énergie.'],
1378=>['Maître de la Magie','Pendant 1...61 secondes, toutes vos caractéristiques élémentaires passent à 8...14 et vos sorts élémentaires vous rendent 1 point d\'énergie plus 30% de leur coût en énergie.','(1...61 secondes.) Vos caractéristiques élémentaires passent à 8...14 et vos sorts élémentaires rendent 1 point d\'énergie plus 30% de leur coût en énergie.'],
1379=>['Regard embrasé','L\'ennemi visé subit 5...50 points de dégâts du feu. Si cet ennemi est embrasé, vous gagnez 5 points d\'énergie et 1 point d\'énergie supplémentaire tous les 2 rangs de Conservation d\'énergie.','Inflige 5...50 points de dégâts de feu. Vous gagnez 5 points d\'énergie et 1 point d\'énergie supplémentaire tous les 2 rangs de Conservation d\'énergie si la cible ennemie souffre de Brûlure.'],
1380=>['Chaleur de savane','Vous créez une Chaleur de savane sur la position de l\'ennemi visé. Pendant 5 secondes, tous les ennemis à proximité subissent 5...20 points de dégâts du feu pour chaque seconde d\'activation de ce sort.','Inflige 5...20 points de dégâts du feu par seconde à compter du lancement du sort (5 secondes). Frappe les ennemis à proximité de la position initiale de la cible.'],
1381=>['Hâte du jinn de flamme','Tous les ennemis adjacents reçoivent 15...120 points de dégâts du feu. Pendant 8...14 secondes, vous vous déplacez 25% plus vite. Hâte du jinn de flamme se recharge 50% plus vite si un ennemi est touché par ce sort.','(8...14 secondes.) Vous vous déplacez 25% plus vite. Effet initial : inflige 15...120 points de dégâts du feu aux ennemis qui vous sont adjacents. Si vous infligez des dégâts à un ennemi avec ce sort, il se recharge 50% plus vite.'],
1382=>['Rafale givrante','Si l\'ennemi visé est sous les effets d\'un maléfice de la Magie de l\'eau, il reçoit 20...80 points de dégâts du froid. Sinon, cet ennemi se déplace 66% moins vite pendant 1...5 secondes.','Inflige 20...80 points de dégâts du froid si l\'ennemi visé souffre d\'un maléfice de la Magie de l\'eau. Sinon, cet ennemi se déplace 66% moins vite pendant 1...5 secondes.'],
1390=>['Intervention du juge','Pendant 10 secondes, la prochaine fois que la cible (un allié ou vous-même) subit des dégâts qui devraient être fatals, ces dégâts sont annulés et un ennemi à proximité subit 30...180 points de dégâts sacrés.','(10 secondes.) Annule les dégâts mortels suivants. Effet de l\'annulation : inflige 30...180 points de dégâts sacrés à un ennemi près de l\'allié visé.'],
1391=>['Esprit de soutien','Pendant 5...23 secondes, chaque fois que la cible (un allié ou vous-même) subit des dégâts lorsqu\'elle est assommée, elle est soignée de 5...50 points de vie.','(5...23 secondes.) Soigne de 5...50 points de vie chaque fois que l\'allié visé subit des dégâts alors qu\'il est assommé.'],
1392=>['Guérison attentive','Pendant 10 secondes, la cible (un allié ou vous-même) bénéficie d\'une régénération de santé de +1...4. Si cette compétence prend fin prématurément, la cible récupère 30...120 points de vie.','(10 secondes.) L\'allié visé bénéficie d\'une régénération de santé de +1...4 et gagne 30...120 points de vie si cet enchantement prend fin prématurément.'],
1393=>['Compagnon du guérisseur','Pendant 10...55 secondes. La vitesse d\'incantation des sorts de Prières de guérison sera 50% plus rapide et vos soins sont 50% plus efficaces.','(10...55 secondes.) Les sorts de Prières de guérison sont lancés 50% plus vite et soignent 50% de santé en plus.'],
1394=>['Engagement du guérisseur','Pendant que vous maintenez cet enchantement, vos sorts de Prière de guérison vous confèrent 20% de santé en moins, mais coûtent -1...4 points d\'énergie.','Vos sorts de Prières de guérison coûtent 1...4 points d\'énergie en moins. Ces sorts soignent 20% de santé en moins.'],
1395=>['Balancier de Balthazar','Pendant 5...25 secondes, la prochaine fois que la cible (un allié ou vous-même) est assommée par un ennemi, l\'ennemi est assommé à sa place.','(5...25 secondes.) Assomme le premier ennemi qui tente d\'assommer l\'allié visé.'],
1396=>['Paroles de réconfort','La cible (un allié ou vous-même) est soignée de 20...65 points de vie et de 20...50 points de vie en plus si elle souffre d\'une condition.','Soigne de 20...65 points de vie. Soigne de 20...50 points de vie supplémentaires si l\'allié visé souffre d\'une condition.'],
1397=>['Lumière de la délivrance','Tous les membres du groupe sont soignés de 5...70 points de vie.','Soigne tout le groupe de 5...70 points de vie.'],
1398=>['Enchantement fléau','Pendant 30 secondes, chaque fois que l\'ennemi visé est la cible d\'un enchantement, le lanceur de cet enchantement subit 15...75 points de dégâts.','(30 secondes.) Inflige 15...75 points de dégâts à quiconque lance un enchantement sur l\'ennemi visé.'],
1399=>['Bouclier d\'absorption','Pendant 3...7 secondes, les dégâts reçus par la cible (un allié ou vous-même) sont réduits de 5 points chaque fois que cette cible est blessée pendant qu\'elle se trouve sous les effets de cet enchantement.','(3...7 secondes.) Réduit les dégâts subis par l\'allié visé de 5 points à chaque attaque.'],
1400=>['Revers de dégâts','Pendant 8 secondes, la prochaine fois que la cible (un allié ou vous-même) doit subir des dégâts, ces dégâts se retournent contre l\'ennemi (maximum 5...75 points).','(8 secondes.) Annule les dégâts suivants et en inflige la même quantité à l\'assaillant (maximum : 5...75).'],
1401=>['Toucher réparateur','La cible touchée (un allié ou vous-même) perd deux conditions et est soignée de 15...60 points de vie pour chaque condition supprimée de cette manière.','Supprime deux conditions. Soigne de 15...60 points de vie par condition supprimée.'],
1402=>['Entaille critique','Si cette attaque réussit, vous infligez +5...20 points de dégâts. Si elle inflige un coup critique, l\'ennemi visé est interrompu.','Inflige +5...20 points de dégâts. Interrompt une action si vous infligez un coup critique.'],
1403=>['Entaille agonisante','Si cette attaque réussit, vous infligez +5...20 points de dégâts. Si la cible ennemie souffre de Blessure profonde, vous interrompez son action.','Inflige +5...20 points de dégâts. Interrompt une action si l\'ennemi visé souffre de Blessure profonde.'],
1404=>['Peste','Pendant 1...15 secondes, vous attaquez 33% plus vite, mais vous vous déplacez 33% plus lentement.','(1...15 secondes.) Vous attaquez 33% plus vite. Vous vous déplacez 33% moins vite.'],
1405=>['Frappe de charge','Pendant 1...10 secondes, vous courez 33% plus vite. Votre prochaine attaque de mêlée réussie inflige +10...90 points de dégâts et cette pose prend fin. Cette pose prend fin si vous utilisez une compétence.','(1...10 secondes.) Vous vous déplacez 33% plus vite et infligez +10...90 points de dégâts avec votre prochaine attaque au corps à corps.Prend fin quand vous réussissez une attaque ou si vous utilisez une compétence.'],
1406=>['Coup de tête','La cible ennemie touchée reçoit 40...100 points de dégâts. Vous êtes frappé de Stupeur pendant 10 secondes.','Inflige 40...100 points de dégâts. Vous êtes frappé de Stupeur (10 secondes).'],
1407=>['Confort du lion','Tous vos sceaux sont désactivés pendant 12 secondes. Vous êtes soigné de 50...110 points de vie et bénéficiez de 0...3 décharges d\'adrénaline.','Vous êtes soigné de 50...110 points de vie et recevez 0...3 décharges d\'adrénaline. Désactive vos sceaux (12 secondes).'],
1408=>['Rage du Ntouka','Vous gagnez 1...7 décharges d\'adrénaline. Pendant 8, secondes chaque fois que utilisez une compétence d\'adrénaline, cette compétence se recharge pendant 3 secondes.','Vous gagnez 1...7 décharges d\'adrénaline. Pendant 8 secondes, les compétences d\'adrénaline utilisées se rechargent pendant 3 secondes.'],
1409=>['Frappe du Mokele','Si l\'attaque réussit, vous infligez +5...20 points de dégâts et gagnez 2 décharges d\'adrénaline.','Inflige +5...20 points de dégâts et vous procure 2 décharges d\'adrénaline.'],
1410=>['Attaque dominatrice','Si cette attaque réussit, elle inflige +1...20 points de dégâts. Si la cible ennemie est assommée, elle est frappée de Stupeur pendant 1...8 secondes.','Inflige +1...20 points de dégâts. Si la cible ennemie est assommée, elle est frappée de Stupeur (1...8 secondes).'],
1411=>['Sceau de constitution','Vous avez +50...300 de santé maximum. Le sceau prend fin si vous réussissez une attaque.','Vous avez +50...300 de santé maximum. Prend fin si vous réussissez une attaque.'],
1412=>['"Vous êtes seul !"','Si l\'ennemi ciblé n\'est pas proche d\'un allié, cet ennemi souffre d\'Infirmité et de Faiblesse pendant 8 secondes.','Inflige l\'Infirmité et la Faiblesse (8 secondes). Aucun effet si l\'ennemi visé est près d\'un de ses alliés.'],
1413=>['Explosion d\'agressivité','Pendant 2...10 secondes vous attaquez 33% plus vite. Lorsque cette pose de combat prend fin, vous perdez toute votre adrénaline.','(2...10 secondes.) Vous attaquez 33% plus vite. Effet final : vous perdez toute votre adrénaline.'],
1414=>['Charge enragée','Pendant 5...15 secondes, vous vous déplacez 25% plus vite. La Charge enragée prend fin lorsque vous touchez une cible. Vous gagnez alors 0...3 décharges d\'adrénaline lorsque vous réussissez une attaque au corps à corps.','(5...15 secondes.) Vous vous déplacez 25% plus vite. Votre attaque au corps à corps suivante vous procure +0...3 décharges d\'adrénaline. <c x="SkillDull">Cette compétence prend fin à l\'issue de votre attaque suivante.'],
1415=>['Taillade incapacitante','Si cette attaque réussit, l\'ennemi ciblé souffre d\'Infirmité pendant 5...15 secondes et commence à saigner pendant 10...25 secondes.','Inflige l\'Infirmité (5...15 secondes) et le Saignement (10...25 secondes).'],
1416=>['Entaille barbare','Si cette attaque réussit, vous infligez +5...30 points de dégâts. Si vous n\'êtes pas en pose de combat, vous causez également le Saignement pendant 5...15 secondes.','Inflige +5...30 points de dégâts. Inflige le Saignement (5...15 secondes) si vous n\'êtes pas en pose de combat.'],
1465=>['Coup préparé','Si cette attaque réussit, vous infligez +10...25 points de dégâts. Si vous êtes sous les effets d\'une préparation, vous obtenez 1...9 points d\'énergie.','Inflige +10...25 points de dégâts. Vous gagnez 1...9 points d\'énergie si vous êtes sous l\'effet d\'une préparation.'],
1466=>['Flèche brûlante','Si cette attaque réussit, vous infligez +10...30 points de dégâts et provoquez la Brûlure pendant 2...8 secondes.','Inflige +10...30 points de dégâts. Inflige la Brûlure (2...8 secondes).'],
1467=>['Tir arqué','Si cette flèche fait mouche, elle inflige +10...35 points de dégâts. Cette flèche ne peut pas être bloquée, mais se déplace 50% moins vite.','Inflige +10...35 points de dégâts. Impossible à bloquer. Cette flèche progresse 50% moins vite.'],
1468=>['Attaque solidaire','Votre animal se déplace instantanément vers la cible ennemie et sa prochaine attaque inflige le Saignement pendant 5...15 secondes. La prochaine fois qu\'une de vos attaques réussit, la cible ennemie est frappée d\'Infirmité pendant 5...15 secondes.','Votre animal se déplace instantanément vers la cible ennemie et sa prochaine attaque inflige le Saignement (5...15 secondes). La prochaine fois qu\'une de vos attaques réussit, la cible ennemie est frappée d\'Infirmité (5...15 secondes).'],
1469=>['Tir croisé','Si cette attaque touche un ennemi visé, elle inflige +5...20 points de dégâts. Si cet ennemi se trouve près d\'un de vos alliés, cette attaque ne pourra pas être bloquée.','Inflige +5...20 points de dégâts. Impossible à bloquer si l\'ennemi visé est près de vos alliés.'],
1470=>['Flèches barbelées','Pendant 24 secondes, vos flèches provoquent le Saignement pendant 3...15 secondes. Votre bonus d\'armure est réduit de 40 pendant que vous activez cette compétence.','(24 secondes.) Vos flèches provoquent le Saignement (3...15 secondes). Votre bonus d\'armure est réduit de 40 pendant que vous activez cette compétence.'],
1471=>['Focus du charognard','Pendant 10 secondes, si vous frappez une cible souffrant d\'une condition, vous obtenez 3...12 points d\'énergie.','(10 secondes.) Vous bénéficiez de 3...12 points d\'énergie si vous frappez un ennemi souffrant d\'une condition.'],
1472=>['Toxicité','Crée un esprit de niveau 1...10. Les créatures souffrant d\'Empoisonnement ou de Maladie à sa portée subissent une dégénération de santé de -2. Cet esprit disparaît au bout de 30...180 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...180 secondes). Les créatures souffrant d\'Empoisonnement ou de Maladie à portée subissent une dégénération de santé de -2.'],
1473=>['Sables mouvants','Crée un esprit de niveau 1...10. Toutes les créatures (sauf les esprits) dans sa portée perdent 1 point d\'énergie chaque fois qu\'elles attaquent ou utilisent une compétence. Cet esprit disparaît au bout de 30...180 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...180 secondes). Les créatures perdent 1 point d\'énergie chaque fois qu\'elles attaquent ou utilisent une compétence. N\'affecte pas les esprits.'],
1474=>['Etreinte de la tempête','Pendant 10 secondes, vous vous déplacez 25% plus vite. Cette pose de combat est renouvelée chaque fois que vous subissez des dégâts élémentaires.','(10 secondes.) Vous vous déplacez 25% plus vite. Renouvellement : chaque fois que vous subissez des dégâts élémentaires.'],
1475=>['Vitesse du trappeur','Pendant 5...30 secondes, vos pièges se rechargent 25% plus vite et se déclenchent 25% plus vite. Cette pose prend fin si vous réussissez une attaque.','(5...30 secondes.) Vos pièges se rechargent 25% plus vite et se déclenchent 25% plus vite. Prend fin si vous réussissez une attaque.'],
1476=>['Fil de détente','Quand le Fil de détente se déclenche, tous les ennemis à proximité subissent 5...20 points de dégâts perforants. Les ennemis souffrant d\'Infirmité sont assommés. Le Fil de détente fonctionne pendant 90 secondes. Vous pouvez être facilement interrompu lorsque vous activez cette compétence.','(90 secondes.) Inflige 5...20 points de dégâts perforants aux ennemis à proximité. Assomme les ennemis frappés d\'Infirmité. Cette compétence peut être facilement interrompue.'],
1478=>['Afflux de renouvellement','Pendant 8 secondes, la cible ennemie subit 2...12 points de dégâts par seconde. Lorsque ce maléfice prend fin, vous gagnez 1...8 points d\'énergie.','(8 secondes.) Inflige 2...12 points de dégâts par seconde. Effet final : vous gagnez 1...8 points d\'énergie.'],
1479=>['Offrande de l\'esprit','Vous gagnez 8...17 points d\'énergie. Si des esprits se trouvent à portée de voix, vous ne sacrifiez pas de santé.','Vous gagnez 8...17 points d\'énergie. Vous ne sacrifiez pas de santé si vous êtes à portée de voix d\'un esprit.'],
1480=>['Don de l\'esprit','Pendant 60 secondes, chaque fois que vous créez une créature, tous les alliés près de cette créature gagnent 5...50 points de vie et perdent 1 condition.','(60 secondes.) Chaque fois que vous créez une créature, tous les alliés à proximité gagnent 5...50 points de vie et perdent une condition.'],
1481=>['Sceau du pacte avec la mort','Vous ressuscitez le membre du groupe visé avec autant de santé que vous et 15...100% d\'énergie maximum. La prochaine fois que cet allié meurt dans les 120 secondes, vous mourez aussi.','Ressuscite le membre du groupe visé avec autant de santé que vous et 15...100% d\'énergie maximum. Pendant 120 secondes, vous mourrez si ce membre du groupe est à nouveau tué.'],
1482=>['Essence récupérée','Tous vos esprits meurent. Vous obtenez 5...20 points d\'énergie et tous vos rituels d\'asservissement sont rechargés si un esprit meurt de cette manière.','Tous vos esprits meurent. Si un esprit meurt de cette manière, vous obtenez 5...20 points d\'énergie et tous vos rituels d\'asservissement sont rechargés.'],
1483=>['Coup de bannissement','Si cette attaque réussit, elle inflige 10...60 points de dégâts sacrés. Elle inflige deux fois plus de dégâts aux créatures invoquées.','Inflige 10...60 points de dégâts sacrés. Inflige deux fois plus de dégâts aux créatures invoquées.'],
1484=>['Fauchage mystique','Si cette attaque réussit, elle inflige +3...12 points de dégâts. Si vous êtes sous l\'effet d\'un enchantement, cette attaque inflige +3...12 points de dégâts supplémentaires.','Inflige +3...12 points de dégâts. Inflige +3...12 points de dégâts supplémentaires si vous êtes sous l\'effet d\'un enchantement.'],
1485=>['Attaque érémitique','Si cette attaque réussit, elle inflige +1...10 points de dégâts et retire un enchantement de Derviche. Si un enchantement est retiré, vous infligez +1...10 points de dégâts à tous les ennemis adjacents.','Inflige +1...10 points de dégâts et retire un enchantement de Derviche. Effet de la suppression : inflige 1...10 points de dégâts supplémentaires à tous les ennemis adjacents.'],
1486=>['Moisson des impuretés','Si cette attaque réussit, elle inflige +3...15 points de dégâts. Chaque ennemi que vous touchez perd 1 condition. Simultanément, tous les ennemis adjacents à celui-ci subissent 10...40 points de dégâts sacrés.','Inflige +3...15 points de dégâts. Les ennemis touchés perdent 1 condition. Effet de la levée : tous les ennemis adjacents aux ennemis touchés subissent 10...40 points de dégâts sacrés.'],
1487=>['Fauchage des deux lunes','Vous perdez un enchantement de Derviche et gagnez 10...50 points de vie. Si un enchantement est perdu de cette manière, vous ne pouvez pas être bloqué, vous frappez à deux reprises et vous gagnez 10...70 points de vie supplémentaires.','Supprime un de vos enchantements de Derviche. Vous bénéficiez de 10...50 points de vie. Effet de la suppression : impossible à bloquer, attaque à deux reprises et 10...70 points de vie en plus.'],
1488=>['Fauchage victorieux','Si cette attaque réussit, elle inflige +5...25 points de dégâts. Si la cible ennemie dispose de moins de points de vie que vous, vous gagnez 30...80 points de vie.','Inflige +5...25 points de dégâts. Vous gagnez 30...80 points de vie par ennemi touché dont la santé est inférieure à la vôtre.'],
1489=>['Fauchage impérieux','Inflige +3...15 points de dégâts et supprime un enchantement de Derviche. Si vous perdez un enchantement de cette manière, le Fauchage impérieux ne peut pas être bloqué, supprime une pose de combat et inflige +3...15 points de dégâts supplémentaires.','Inflige +3...15 points de dégâts. Supprime un de vos enchantements de Derviche. Effet de la suppression : impossible à bloquer, supprime une pose de combat et inflige +3...15 points de dégâts supplémentaires.'],
1490=>['Assaut pieux','Si cette attaque réussit, elle inflige +10...20 points de dégâts et supprime un enchantement de Derviche. En cas de perte d\'un enchantement de Derviche, cette compétence se recharge 75% plus vite et les ennemis adjacents subissent 15...40 points de dégâts.','Inflige +10...20 points de dégâts. Supprime un de vos enchantements de Derviche. Effet de la suppression : cette compétence se recharge 75% plus vite et les ennemis adjacents subissent 15...40 points de dégâts.'],
1491=>['Tornade mystique','Inflige 10...60 points de dégâts du froid à tous les ennemis à proximité. Si vous êtes sous l\'effet d\'un enchantement, ce sort inflige 10...60 points de dégâts supplémentaires.','Inflige 10...60 points de dégâts du froid à tous les ennemis à proximité. Inflige 10...60 points de dégâts supplémentaires si vous êtes sous l\'effet d\'un enchantement.'],
1493=>['Doigts de Grenth','Tous les ennemis proches reçoivent 10...40 points de dégâts du froid. Pendant 30 secondes, vos attaques infligent des dégâts du froid. A l\'issue de cet enchantement, vous transférez 1...2 conditions à tous les ennemis proches.','(30 secondes.) Vos attaques infligent des dégâts du froid. Effet initial : infligent 10...40 points de dégâts du froid aux ennemis à proximité. Effet final : transfert 1...2 conditions à tous les ennemis proches.'],
1495=>['Aura d\'épines','Tous les ennemis adjacents souffrent de Saignement pendant 5...15 secondes. Pendant 30 secondes, cet enchantement est sans effet. Lorsque cet enchantement prend fin, tous les ennemis à proximité sont frappés d\'Infirmité pendant 3...8 secondes.','(30 secondes.) Effet initial : inflige le Saignement (5...15 secondes) aux ennemis à proximité. Effet final : inflige l\'Infirmité (3...8 secondes) aux ennemis à proximité.'],
1496=>['Rage de Balthazar','Tous les ennemis à proximité s\'embrasent pendant 1...3 secondes. Pendant 20 secondes à partir de ce moment, cet enchantement est sans effet. Au terme de cet enchantement, vous gagnez 1...2 décharges d\'adrénaline s\'il y a des ennemis à portée de voix.','(20 secondes.) Effet initial : inflige la condition Brûlure (1...3 secondes) aux ennemis à proximité. Effet final : gain de 1...2 décharges d\'adrénaline s\'il y a des ennemis à portée de voix.'],
1497=>['Manteau de poussière','Tous les ennemis proches reçoivent 10...40 points de dégâts de terre. Pendant 30 secondes, vos attaques infligent des dégâts de terre. A l\'issue de cet enchantement, tous les ennemis adjacents sont aveuglés pendant 1...4 secondes.','(30 secondes.) Vos attaques infligent des dégâts de la terre. Effet initial : inflige 10...40 points de dégâts de la terre aux ennemis proches. Effet final : provoque l\'Aveuglement des ennemis à proximité (1...4 secondes).'],
1498=>['Force stupéfiante','Tous les ennemis proches reçoivent 10...40 points de dégâts de la terre. Pendant 30 secondes, vos attaques infligent des dégâts de la terre. A l\'issue de cet enchantement, tous les ennemis adjacents subissent Armure brisée pendant 1...10 secondes.','(30 secondes.) Vos attaques infligent des dégâts de la terre. Effet initial : inflige 10...40 points de dégâts de la terre aux ennemis proches. Effet final : inflige Armure brisée (1...10 secondes) aux ennemis proches.'],
1499=>['Renouveau pieux','Pendant 8 secondes, rien ne se passe. Lorsque cet enchantement prend fin, Renouveau pieux est rechargé et vous gagnez 0...5 points d\'énergie et 0...30 points de vie.','(8 secondes.) Effet final : se recharge et vous gagnez 0...5 points d\'énergie et 0...30 points de vie.'],
1500=>['Manteau de mirage','Pendant 20 secondes, vous avez 40% de chances de bloquer les attaques, plus 4...10% par enchantement supplémentaire (max 80%). Tous les ennemis à proximité reçoivent 10...40 points de dégâts de la terre chaque fois qu\'un enchantement de Derviche vous est retiré.','(20 secondes.) Vous avez 40% de chances de bloquer les attaques, plus 4...10% par enchantement supplémentaire. Inflige 10...40 points de dégâts de la terre aux ennemis à proximité quand vous perdez un enchantement de Derviche.'],
1502=>['Zèle arcane','Pendant 10 secondes, chaque fois que vous lancez un sort, vous gagnez 2 points d\'énergie pour chaque enchantement qui vous affecte (2...7 points d\'énergie maximum).','(10 secondes.) Chaque fois que vous lancez un sort, vous gagnez 2 points d\'énergie (maximum : 2...7) par enchantement vous affectant.'],
1503=>['Vigueur mystique','Pendant 20 secondes, chaque fois que vous réussissez une attaque, vous gagnez 3...15 points de vie pour chaque enchantement qui vous affecte (25 points de vie maximum).','(20 secondes.) Chaque fois que vous réussissez une attaque, vous gagnez 3...15 points de vie (maximum : 25) par enchantement vous affectant.'],
1504=>['Intervention vigilante','Pendant 60 secondes, la prochaine fois que la santé de la cible (un allié ou vous-même) est inférieure à 25%, cette cible est soignée de 50...200 points de vie.','(60 secondes.) Soigne de 50...200 points de vie la prochaine fois que la santé de l\'allié est inférieure à 25%.'],
1505=>['Voeu de piété','Pendant 20 secondes, vous bénéficiez d\'un bonus d\'armure de +24 et d\'une régénération de santé de +1...4. Voeu de piété se renouvelle chaque fois qu\'un enchantement cesse de faire effet sur vous.','(20 secondes.) +24 de bonus d\'armure et +1...4 de régénération de santé. Renouvellement : chaque fois qu\'un enchantement vous affectant prend fin.'],
1506=>['Compagnon vital','Pendant 20 secondes, vous avez +40...100 de santé maximum. Lorsque cet enchantement prend fin, vous êtes soigné de 75...200 points de vie.','(20 secondes.) Vous avez +40...100 de santé maximum. Effet final : vous soigne de 75...200 points de vie.'],
1507=>['Coeur de la Flamme sacrée','Tous les ennemis à proximité subissent 5...30 points de dégâts sacrés. Pendant 30 secondes, vos attaques infligent des dégâts sacrés. Lorsque cet enchantement prend fin, tous les ennemis à proximité s\'embrasent pendant 2...5 secondes.','(30 secondes.) Vos attaques infligent des dégâts sacrés. Effet initial : inflige 5...30 points de dégâts sacrés aux ennemis proches. Effet final : inflige la Brûlure (2...5 secondes) aux ennemis à proximité.'],
1508=>['Prolongation des Enchantements','Pendant 10 secondes.), votre prochain enchantement de Derviche dure 10...150% plus longtemps.','(10 secondes.) Votre prochain enchantement de Derviche dure 10...150% plus longtemps.'],
1509=>['Intervention fidèle','Si votre santé descend en dessous de 50%, l\'Intervention fidèle prend fin et vous êtes soigné de 30...150 points de vie.','Vous gagnerez 30...150 points de vie la prochaine fois que vous subirez des dégâts et que votre santé descendra à moins de 50%.'],
1510=>['Eclats de sable','Pendant 30 secondes, vos 1...5 prochaines attaques à la faux infligent 10...60 points de dégâts de la terre à tous les ennemis adjacents.','(30 secondes.) Inflige 10...60 points de dégâts de la terre à tous les autres ennemis adjacents chaque fois que vous attaquez avec votre faux. Prend fin après 1...5 coups.'],
1512=>['Hâte de Lyssa','Pendant 3...15 secondes, vos enchantements de Derviche se rechargent 33% plus vite. Lorsque vous lancez cet enchantement, tous les ennemis à proximité sont interrompus. Au terme de cet enchantement, tous les ennemis à proximité sont interrompus. 50% de risques d\'échec si vous n\'avez pas Prières du vent de niveau 5 ou plus.','(3...15 secondes.) Vos enchantements de Derviche se rechargent 33% plus vite. Effet initial : interrompt tous les ennemis adjacents. Effet final : interrompt tous les ennemis adjacents. (50% de risques d\'échec si vous n\'avez pas Prières du vent de niveau 5 ou plus.)'],
1513=>['Mains directrices','Pendant 20 secondes, vos 0...3 prochaines attaques ne peuvent pas être bloquées. Une fois activée, cette compétence annule l\'Aveuglement.','(20 secondes.) vos 0...3 prochaines attaques ne peuvent pas être bloquées. Effet initial : annule l\'Aveuglement.'],
1514=>['Brève stabilité','Pendant 4...10 secondes, vous ne pouvez pas être assommé et vous déplacez 25% plus vite. Cet enchantement prend fin prématurément s\'il vous empêche d\'être assommé.','(4...10 secondes.) Vous ne pouvez pas être assommé et vous déplacez 25% plus vite. Prend fin s\'il vous empêche d\'être assommé.'],
1515=>['Armure de sainteté','Tous les ennemis adjacents sont frappés de Faiblesse pendant 5...15 secondes. Pendant 15 secondes, vous subissez 5...20 points de dégâts en moins de la part des ennemis souffrant d\'une condition.','Provoque la Faiblesse sur tous les ennemis adjacents (5...15 secondes). Les ennemis souffrant d\'une condition vous infligent 5...20 points de dégâts en moins (15 secondes).'],
1516=>['Régénération mystique','Pendant 5...20 secondes, vous bénéficiez d\'une régénération de santé de +1...4 pour chaque enchantement (8 maximum) qui vous affecte.','(5...20 secondes.) Vous bénéficiez d\'une régénération de santé de +1...4 pour chaque enchantement (8 maximum) qui vous affecte.'],
1517=>['Voeu du silence','Pendant 5...10 secondes, vous ne pouvez pas être la cible de sorts, et vous ne pouvez pas lancer de sorts.','(5...10 secondes.) Les sorts ennemis ne peuvent pas vous prendre pour cible. Vous ne pouvez pas utiliser de sorts.'],
1518=>['Avatar de Balthazar','Pendant 10...90 secondes, vous bénéficiez d\'un bonus d\'armure de +20 contre les dégâts physiques, vous gagnez de l\'adrénaline 25% plus vite, vos attaques infligent des dégâts sacrés, et chaque fois que vous perdez un enchantement de Derviche, les ennemis à proximité s\'embrasent pendant 1...3 secondes. Cette compétence est désactivée pendant 45 secondes.','(10...90 secondes.) Vous bénéficiez d\'un bonus d\'armure de +20 contre les dégâts physiques, vous gagnez de l\'adrénaline 25% plus vite, vos attaques infligent des dégâts sacrés, et vous infligez une Brûlure (1...3 secondes) aux ennemis à proximité chaque fois que vous perdez un enchantement de Derviche. Cette compétence est désactivée pendant 45 secondes.'],
1519=>['Avatar de Dwayna','Pendant 10...90 secondes, vos attaques infligent des dégâts sacrés. Dès que vous utilisez une compétence d\'attaque de Derviche, vous perdez 1 maléfice. Quand vous perdez un enchantement de Derviche, tous les alliés à portée de voix sont guéris à hauteur de 5...50 points de vie. Cette compétence est désactivée pendant 45 secondes.','(10...90 secondes.) Inflige des dégâts sacrés. Vous perdez 1 maléfice à chaque compétence d\'attaque de Derviche utilisée. Guérit les alliés à portée de voix à hauteur de 5...50 points de vie quand vous perdez un enchantement de Derviche. Cette compétence est désactivée pendant 45 secondes.'],
1520=>['Avatar de Grenth','Pendant 10...90 secondes, vos attaques à la faux infligent des dégâts obscurs et volent 0...12 points de vie. Vous êtes immunisé contre la Maladie et vous infligez Maladie à tous les ennemis adjacents pendant 3 secondes dès que vous perdez un enchantement de Derviche. Cette compétence est désactivée pendant 45 secondes.','(10...90 secondes.) Vos attaques à la faux infligent des dégâts obscurs et volent 0...12 points de vie. Vous êtes immunisé contre la Maladie. Inflige Maladie à tous les ennemis adjacents (3 secondes) quand vous perdez un enchantement de Derviche. Cette compétence est désactivée pendant 45 secondes.'],
1521=>['Avatar de Lyssa','Pendant 10...90 secondes, vos enchantements de Derviche se rechargent 50% plus vite et vos attaques infligent des dégâts chaotiques. Vous volez 1 points d\'énergie à tous les ennemis adjacents lorsque vous perdez un enchantement de Derviche. Cette compétence est désactivée pendant 45 secondes.','(10...90 secondes.) Vos enchantements de Derviche se rechargent 50% plus vite et infligent des dégâts chaotiques à chaque attaque. Vous volez 1 points d\'énergie aux ennemis adjacents lorsque vous perdez un enchantement de Derviche. Cette compétence est désactivée pendant 45 secondes.'],
1522=>['Avatar de Melandru','Pendant 10...90 secondes, vous bénéficiez de +150 points de vie et de +30 points d\'armure élémentaire. En outre, vos attaques infligent des dégâts de la terre. Quand vous perdez un enchantement de Derviche, tous les membres du groupe à portée de voix perdent 1 condition. Cette compétence est désactivée pendant 45 secondes.','(10...90 secondes.) +150 points de vie, +30 points d\'armure élémentaire et vos attaques infligent des dégâts de la terre. Tous les membres du groupe à portée de voix perdent 1 condition quand vous perdez un enchantement de Derviche. Cette compétence est désactivée pendant 45 secondes.'],
1523=>['Méditation','Perte de toute l\'adrénaline. Pendant 20 secondes, vous gagnez 1...4 points d\'énergie chaque fois qu\'un enchantement vous affectant prend fin.','(20 secondes.) Perte de toute l\'adrénaline. Gain de 1...4 points d\'énergie chaque fois qu\'un enchantement vous affectant prend fin.'],
1524=>['Zèle érémitique','Vous gagnez 1...3 points d\'énergie (maximum : 8 points d\'énergie) par ennemi à portée de voix. Pendant 10 secondes à partir de ce moment, cet enchantement est sans effet. A l\'issue de l\'enchantement, vous gagnez 1...3 points d\'énergie par ennemi à portée de voix (maximum 8 points d\'énergie).','(10 secondes.) Effet initial : vous gagnez 1...3 points d\'énergie (maximum : 8 points d\'énergie) par ennemi à portée de voix. Effet final : vous gagnez 1...3 points d\'énergie (maximum : 8 points d\'énergie) par ennemi à portée de voix.'],
1525=>['Guérison naturelle','Vous êtes soigné de 50...170 points de vie. Si vous n\'êtes pas sous l\'effet d\'un enchantement, ce sort s\'active 50% plus vite.','Vous soigne de 50...170 points de vie. Cette compétence s\'active 50% plus vite si vous n\'êtes pas sous l\'effet d\'un enchantement.'],
1526=>['Santé imprégnée','L\'allié visé est soigné de 5...50% de votre santé actuelle (maximum 300 points de vie).','Soigne de 5...50% de votre santé actuelle (maximum : 300). Vous ne pouvez pas vous prendre pour cible.'],
1527=>['Guérison mystique','Vous êtes soigné de 5...65 points de vie. Tous les membres du groupe enchantés sont également soignés de 5...65 points de vie.','Vous regagnez 5...65 points de vie. Tous les membres du groupe sont également soignés de 5...65 points de vie.'],
1528=>['Toucher de Dwayna','L\'allié ciblé touché est soigné de 60 points de vie pour chaque enchantement auquel vous êtes sujet (60...240 points maximum).','Soigne de 60 points de vie (maximum : 60...240) par enchantement vous affectant.'],
1529=>['Rétablissement pieux','Vous gagnez 80...150 points de vie et levez un enchantement de Derviche. Si un enchantement est levé de cette façon, vous perdez également 1...3 maléfices.','Vous gagnez 80...150 points de vie et levez un enchantement de Derviche. Effet de la levée : vous perdez 1...3 maléfices.'],
1530=>['Sceau de lumière pieuse','Supprime un enchantement de Derviche. Soigne l\'allié ciblé à hauteur de 30...150 points de vie. Si un enchantement est levé de cette façon, ce Sceau se recharge 75% plus vite.','Soigne de 30...150 points de vie. Supprime un de vos enchantements de Derviche. Effet de la suppression : rechargement 75% plus rapide.'],
1531=>['Aura intimidante','Pendant 60 secondes, vous bénéficiez de +40...100 points de santé maximum et subissez 1...10 points de dégâts en moins lors des attaques d\'ennemis disposant de moins de points de vie que vous.','(60 secondes.) Vus bénéficiez de +40...100 points de santé maximum et subissez 1...10 points de dégâts en moins lors des attaques d\'ennemis disposant de moins de points de vie que vous.'],
1532=>['Tempête de sable mystique','Crée une Tempête de sable à l\'endroit où vous vous trouvez d\'une durée de 3 secondes. Tous les ennemis à proximité subissent 10...40 points de dégâts de la terre par seconde. Les ennemis qui vous attaquent subissent 10...20 points de dégâts supplémentaires. Si vous êtes sous l\'effet d\'un enchantement lorsque vous lancez ce sort, celui-ci dure deux fois plus longtemps.','(3 secondes.) Inflige 10...40 points de dégâts de la terre par seconde. Inflige 10...20 points de dégâts supplémentaires aux ennemis qui vous attaquent. Affecte les ennemis proches de votre position initiale. Dure deux fois plus longtemps si vous êtes sous l\'effet d\'un enchantement.'],
1533=>['Vents de désenchantement','Supprime un de vos enchantements de Derviche. En cas de perte d\'enchantement, tous les ennemis à proximité perdent un enchantement et subissent 20...80 points de dégâts du froid.','Supprime un de vos enchantements de Derviche. Effet de la suppression : tous les ennemis à proximité perdent un enchantement et reçoivent 20...80 points de dégâts du froid.'],
1534=>['Toucher déchirant','Inflige 15...65 points de dégâts de froid à la cible ennemie. Vous perdez un enchantement de Derviche. En cas de perte d\'enchantement, la cible ennemie perd un enchantement et vous obtenez 2 décharges d\'adrénaline.','Inflige 15...65 points de dégâts de froid. Vous perdez un enchantement de Derviche. Effet de la suppression : la cible ennemie perd 1 enchantement et vous obtenez 2 décharges d\'adrénaline.'],
1535=>['Fauchage invalidant','Si votre attaque touche un ennemi, celui-ci est frappé d\'Infirmité pendant 3...12 secondes. Cette compétence inflige +3...15 points de dégâts en plus si l\'ennemi est en mouvement.','(3...12 secondes.) Inflige la condition Infirmité. Inflige +3...15 points de dégâts aux ennemis mobiles.'],
1536=>['Attaque blessante','Si cette attaque réussit, vous infligez +5...20 points de dégâts, l\'ennemi ciblé souffre de Saignement pendant 5...20 secondes et vous perdez un enchantement de Derviche. Si un enchantement a été levé, l\'ennemi ciblé souffre également de Blessure profonde pendant 5...20 secondes.','Inflige +5...20 points de dégâts et provoque le Saignement (5...20 secondes). Supprime un enchantement de Derviche. Effet de la suppression : inflige une Blessure profonde (5...20 secondes).'],
1537=>['Coup lassant','Vous supprimez un enchantement de Derviche. Si un enchantement a été levé, vous infligez une Blessure profonde pendant 3...10 secondes. Vous souffrez de Faiblesse pendant 10 secondes si un enchantement n\'est pas levé.','Supprime un enchantement de Derviche. Effet de la suppression : inflige une Blessure profonde (3...10 secondes). Vous souffrez de Faiblesse (10 secondes) si un enchantement n\'est pas perdu.'],
1538=>['Assaut de Lyssa','Si cette attaque réussit, elle interrompt une action. Si vous êtes sous le coup d\'un enchantement, toute compétence que vous interrompez est désactivée pendant 1...10 secondes de plus. Cette attaque inflige 50% des dégâts normaux.','Interrompt une action. Si vous êtes sous le coup d\'un enchantement, la compétence interrompue est désactivée pendant 1...10 secondes de plus. Cette attaque inflige 50% des dégâts normaux.'],
1539=>['Victoire frissonnante','Si elle réussit, cette attaque inflige +3...15 points de dégâts. A chaque ennemi touché dont la santé est inférieure à la vôtre, cet ennemi et tous les ennemis adjacents subissent 10...30 points de dégâts du froid.','Inflige +3...15 points de dégâts. Inflige 10...30 points de dégâts du froid à chaque ennemi touché dont la santé est inférieure à la vôtre, ainsi qu\'à tous les ennemis adjacents à ces cibles.'],
1540=>['Conviction','Pendant 10 secondes, vous gagnez +10 en armure si vous avez une condition et +1...3 en régénération de santé pour chaque condition dont vous souffrez. Lorsque cet enchantement prend fin, vous êtes libéré de 1...2 conditions.','(10 secondes.) +10 en armure si vous souffrez d\'une condition. +1...3 en régénération de santé par condition vous affectant. Effet final : vous perdez 1...2 conditions.'],
1541=>['Hâte enchantée','Pendant 7 secondes, vous vous déplacez 25% plus vite. Si cet enchantement s\'achève prématurément, vous perdez 1 conditions.','(7 secondes.) Vous vous déplacez 25% plus vite. Perte de 1 conditions, si cet enchantement s\'achève prématurément.'],
1542=>['Concentration pieuse','Pendant 5...20 secondes, vous ne pouvez pas être interrompu, mais pour chaque tentative d\'interruption contre vous, soit vous perdez 1 enchantement de Derviche, soit Concentration pieuse prend fin.','(5...20 secondes.) Evite les interruptions. Contrecoup : soit vous perdez 1 enchantement de Derviche, soit Concentration pieuse prend fin.'],
1543=>['Hâte pieuse','Vous levez un enchantement de Derviche et pendant 1...7 secondes vous vous déplacez 25% plus vite. En cas de perte d\'enchantement, vous courez 50% plus vite à la place.','(1...7 secondes.) Perte d\'un enchantement de Derviche et déplacement 25% plus rapide. Effet de la suppression : court 50% plus rapidement à la place.'],
1544=>['Charge tourbillonnante','Pendant 1...6 secondes, vous vous déplacez 33% plus vite que la normale. La prochaine fois que vous touchez un ennemi, tous les ennemis à proximité subissent 10...60 points de dégâts du froid et cet enchantement prend fin.','(1...6 secondes.) Vous vous déplacez 33% plus vite. Inflige 10...60 points de dégâts du froid à tous les autres ennemis adjacents la prochaine fois que vous touchez un ennemi. Cet enchantement prend alors fin.'],
1545=>['Test de foi','Inflige 15...75 points de dégâts du froid à la cible ennemie et lui enlève 1 enchantement. Si cet ennemi n\'était pas enchanté, il souffre de Stupeur pendant 2...6 secondes.','Inflige +15...75 points de dégâts du froid et retire 1 enchantement. L\'ennemi visé est frappé de Stupeur pendant 2...6 secondes s\'il n\'est pas enchanté.'],
1546=>['Javelot ardent','Si cette attaque réussit, elle inflige +5...25 points de dégâts et embrase la cible ennemie pendant 1...3 secondes.','Inflige +5...25 points de dégâts. Inflige la Brûlure (1...3 secondes).'],
1547=>['Lancer puissant','Votre javelot se déplace trois fois plus vite. Si l\'attaque réussit, vous infligez +10...40 points de dégâts.','Inflige +10...40 points de dégâts. Ce javelot se déplace trois fois plus vite.'],
1548=>['Javelot cruel','Si cette attaque réussit, vous infligez +10...50 points de dégâts. Si elle touche une cible immobile, vous infligez une Blessure profonde pendant 5...20 secondes.','Inflige +10...50 points de dégâts. Inflige la Blessure profonde (5...20 secondes) si la cible est immobile.'],
1549=>['Lancer d\'harrier','Si cette attaque réussit, vous infligez +5...20 points de dégâts. Si elle touche un ennemi en mouvement, elle inflige 5...40 points de dégâts en plus.','Inflige +5...20 points de dégâts. Inflige 5...40 points de dégâts supplémentaires si la cible se déplace.'],
1550=>['Lancer impitoyable','Si cette attaque réussit, vous infligez +10...40 points de dégâts. Cette attaque ne peut pas être bloquée.','Inflige +10...40 points de dégâts. Impossible à bloquer.'],
1551=>['Javelot d\'éclair','Frappe tous les ennemis entre vous et votre cible. Si cette attaque réussit, elle inflige +10...20 points de dégâts de foudre. Cette attaque a 25% de pénétration d\'armure.','Inflige +10...20 points de dégâts de la foudre. Pénétration d\'armure de 25%. Frappe tous les ennemis entre vous et votre cible.'],
1552=>['Javelots lassants','Si cette attaque réussit, vous infligez +10...40 points de dégâts. Vous souffrez de Faiblesse pendant 5 secondes.','Inflige +10...40 points de dégâts. Vous souffrez de Faiblesse (5 secondes).'],
1553=>['Hymne de furie','Pendant 10 secondes, tous les membres du groupe à portée de voix bénéficient de 2...5 décharges d\'adrénaline la prochaine fois qu\'ils utilisent une compétence d\'attaque.','(10 secondes.) Les membres du groupe à portée de voix récupèrent 2...5 décharges d\'adrénaline grâce à leur compétence d\'attaque suivante.'],
1554=>['Hymne d\'infirmité','Pendant 10 secondes, la prochaine compétence d\'attaque utilisée par chaque allié à portée de voix cause l\'Infirmité pendant 5...15 secondes.','(10 secondes.) Les alliés à portée de voix infligent l\'Infirmité (5...15 secondes) avec leur compétence d\'attaque suivante.'],
1555=>['Hymne défensif','Pendant 4...10 secondes, chaque membre du groupe à portée de voix a 50% de chances de bloquer les attaques qui lui sont lancées. Ce chant prend fin si cet allié frappe avec une compétence d\'attaque.','(4...10 secondes.) Les membres du groupe à portée de voix ont 50% de chances de bloquer. Prend fin quand vous réussissez une compétence d\'attaque.'],
1556=>['Bon voyage','Pendant 5...20 secondes, tous les alliés à portée de voix se déplacent 25% plus vite pendant qu\'ils sont sous les effets d\'un enchantement.','(5...20 secondes.) Les alliés à portée de voix se déplacent 25% plus vite s\'ils sont enchantés.'],
1557=>['Hymne de flamme','Pendant 10 secondes, la prochaine compétence d\'attaque utilisée par chaque membre du groupe à portée de voix cause aussi la Brûlure pendant 1...5 secondes.','(10 secondes.) Les membres du groupe à portée de voix infligent la Brûlure (1...5 secondes) avec leur compétence d\'attaque suivante.'],
1558=>['"Visez les yeux !"','Pendant 10 secondes, la prochaine fois que chaque allié à portée de voix lance une attaque, cette attaque a 30...100% de chances d\'infliger un coup critique.','(10 secondes.) Les alliés à portée de voix ont +30...100% de chances d\'infliger un coup critique avec leur attaque suivante.'],
1559=>['Hymne de jalousie','Pendant 10 secondes, la prochaine compétence d\'attaque utilisée par chaque allié à portée de voix inflige +10...25 points de dégâts contre les ennemis ayant plus de 50% de santé.','(10 secondes.) Les alliés à portée de voix infligent +10...25 points de dégâts avec leur compétence d\'attaque suivante. Le bonus de dégâts est appliqué uniquement contre les ennemis possédant plus de 50% de santé.'],
1560=>['Chant de la puissance','Pendant 5...20 secondes, chaque allié à portée de voix bénéficie d\'une régénération d\'énergie de 4 jusqu\'à ce qu\'il utilise une compétence.','(5...20 secondes.) Les alliés à portée de voix bénéficient d\'une régénération d\'énergie de +4 . Prend fin quand vous utilisez une compétence.'],
1561=>['Hymne zélé','Pendant 10 secondes, la prochaine fois que chaque allié à portée de voix utilise une compétence d\'attaque, il reçoit 1...8 points d\'énergie.','(10 secondes.) Les alliés à portée de voix gagnent 1...8 points d\'énergie avec leur compétence d\'attaque suivante.'],
1562=>['Aria de zèle','Pendant 10 secondes, la prochaine fois que chaque allié à portée de voix utilise un sort, il bénéficie de 1...6 points d\'énergie.','(10 secondes.) Les alliés à portée de voix gagnent 1...6 points d\'énergie avec leur sort suivant.'],
1563=>['Poème de zèle','Pendant 10 secondes, la prochaine fois que chaque allié à portée de voix utilise un sceau, il bénéficie de 1...8 points d\'énergie.','(10 secondes.) Les alliés à portée de voix gagnent 1...8 points d\'énergie avec leur sceau suivant.'],
1564=>['Ballade de rétablissement','Pendant 10 secondes, la prochaine fois que chaque membre du groupe à portée de voix subit des dégâts, il est soigné de 15...75 points de vie.','(10 secondes.) Les membres du groupe à portée de voix gagnent 15...75 points de vie la prochaine fois qu\'ils subissent des dégâts.'],
1565=>['Choeur de rétablissement','Pendant 10 secondes, la prochaine fois que chaque allié à portée de voix utilise un cri ou un chant, il est soigné de 30...90 points de vie.','(10 secondes.) Les alliés à portée de voix récupèrent 30...90 points de vie grâce à leur cri ou leur chant suivant.'],
1566=>['Aria de rétablissement','Pendant 10 secondes, la prochaine fois que chaque membre du groupe à portée de voix utilise un sort, il est soigné de 30...90 points de vie.','(10 secondes.) Les membres du groupe à portée de voix récupèrent 30...90 points de vie grâce à leur sort suivant.'],
1567=>['Chanson de concentration','Pendant 10 secondes, la prochaine compétence utilisée par chaque allié à portée de voix ne peut pas être interrompue.','(10 secondes.) La compétence suivante des alliés à portée de voix ne peut pas être interrompue.'],
1568=>['Hymne de direction','Pendant 10 secondes, la prochaine compétence d\'attaque utilisée par chaque membre du groupe à portée de voix ne peut pas être bloquée.','(10 secondes.) La compétence d\'attaque suivante des membres du groupe à portée de voix ne peut pas être bloquée.'],
1569=>['Choeur énergisant','Pendant 10 secondes, le prochain cri ou chant utilisé par chaque allié à portée de voix coûte 3...7 points d\'énergie en moins.','(10 secondes.) Le cri ou le chant suivant des alliés à portée de voix coûte 3...7 points d\'énergie en moins.'],
1570=>['Chanson de purification','Pendant 20 secondes, les prochaines compétences (au nombre de 1...6) utilisées par chaque allié à portée de voix ôtent 1 condition à cet allié.','(20 secondes.) Les alliés à portée de voix perdent une condition grâce à 1...6 compétences suivantes.'],
1571=>['Aria de leveur de maléfice','Pendant 10 secondes, la prochaine fois que chaque allié à portée de voix lance un sort, il perd un maléfice.','(10 secondes.) Les alliés à portée de voix perdent un maléfice grâce à leur sort suivant.'],
1572=>['"Préparez-vous !"','Pendant 5...15 secondes, la prochaine fois qu\'un allié doit être assommé, tous les ennemis à proximité subissent 15...75 points de dégâts à la place.','(5...15 secondes.) Empêche l\'allié visé d\'être assommé et inflige 15...75 points de dégâts à tous les ennemis près de lui. Vous ne pouvez pas vous prendre pour cible.'],
1573=>['Crainte','Si cette compétence touche un ennemi renversé, cet ennemi est frappé de Stupeur pendant 5...15 secondes.','Inflige la Stupeur (5...15 secondes). Aucun effet si la cible n\'est pas assommée.'],
1574=>['Harmonie persistante','Pendant 10...35 secondes, les chants et les cris durent 50% plus longtemps sur la cible alliée (autre qu\'un esprit).','(10...35 secondes.) Les chants et les cris affectant l\'allié visé durent 50% plus longtemps. Vous ne pouvez pas viser les esprits.'],
1575=>['Finale enflammé','Pendant 10...35 secondes, chaque fois qu\'un chant ou un cri sur la cible (autre qu\'un esprit) prend fin, tous les ennemis adjacents à cette cible s\'embrasent pendant 1...7 secondes.','(10...35 secondes.) Inflige la Brûlure (1...7 secondes) aux ennemis adjacents chaque fois qu\'un chant ou un cri affectant l\'allié visé prend fin. Vous ne pouvez pas viser les esprits.'],
1576=>['Refrain brûlant','Pendant 20 secondes, si la cible (autre qu\'un esprit) blesse un ennemi ayant plus de santé qu\'elle, cet ennemi s\'embrase pendant 1...3 secondes. Cet écho se reproduit chaque fois qu\'un chant ou un cri sur cet allié prend fin.','(20 secondes.) Inflige la Brûlure (1...3 secondes) si l\'allié visé frappe un ennemi possédant plus de santé. Renouvellement : chaque fois qu\'un chant ou un cri affectant cet allié prend fin. Vous ne pouvez pas viser les esprits.'],
1577=>['Finale de rétablissement','Pendant 10...35 secondes, chaque fois qu\'un chant ou un cri sur une cible (autre qu\'un esprit) prend fin, cette cible est soignée de 15...75 points de vie.','(10...35 secondes.) L\'allié visé gagne 15...75 points de vie chaque fois qu\'un chant ou un cri l\'affectant prend fin. Vous ne pouvez pas viser les esprits.'],
1578=>['Refrain de réparation','Pendant 15 secondes, la cible alliée (autre qu\'un esprit) bénéficie d\'une régénération de santé de +2...3. Cet écho est répété chaque fois qu\'un chant ou un cri sur cet allié prend fin.','(15 secondes.) L\'allié visé bénéficie d\'une régénération de santé de +2...3. Renouvellement : chaque fois qu\'un chant ou un cri affectant cet allié prend fin. Vous ne pouvez pas viser les esprits.'],
1579=>['Finale purifiant','Pendant 10...35 secondes, la cible alliée (autre qu\'un esprit) perd 1 condition chaque fois qu\'un chant ou un cri sur cet allié prend fin.','(10...35 secondes.) L\'allié visé perd une condition chaque fois qu\'un chant ou un cri l\'affectant prend fin. Vous ne pouvez pas viser les esprits.'],
1580=>['Refrain du Bladeturn','Pendant 20 secondes, l\'allié visé (autre qu\'un esprit) a 5...20% de chances de bloquer les attaques. Cet écho est répété chaque fois qu\'un chant ou un cri sur cet allié prend fin.','(20 secondes.) L\'allié visé a 5...20% de chances de bloquer les attaques. Renouvellement : chaque fois qu\'un chant ou un cri affectant cet allié prend fin. Vous ne pouvez pas viser les esprits.'],
1581=>['Sceau rayonnant','Si la cible ennemie souffre de Brûlure, vous bénéficiez de 5...15 points d\'énergie.','Vous gagnez 5...15 points d\'énergie si l\'ennemi visé souffre de Brûlure.'],
1583=>['Zèle du meneur','Pour chaque allié à proximité, vous bénéficiez de 2...4 points d\'énergie (maximum 8...12 points d\'énergie).','Vous gagnez 2...4 points d\'énergie (maximum : 8...12 points d\'énergie) par allié à proximité.'],
1584=>['Confort du meneur','Vous bénéficiez de 30...75 points de vie. Pour chaque allié à portée de voix, vous gagnez +10...20 points de vie supplémentaires (maximum 140 points de vie).','Vous bénéficiez de 30...75 points de vie. Vous gagnez 10...20 points de vie (maximum 140 points de vie) pour chaque allié à portée de voix.'],
1585=>['Sceau de synergie','La cible alliée est soignée de 40...100 points de vie. Si vous n\'êtes pas sous les effets d\'un enchantement, vous êtes aussi soigné de 40...100 points de vie.','Soigne l\'allié visé de 40...100 points de vie. Vous êtes aussi soigné de 40...100 points de vie si vous n\'êtes pas enchanté. Vous ne pouvez pas vous prendre pour cible.'],
1586=>['Protection angélique','Pendant 10 secondes, chaque fois que l\'allié visé subit plus de 250...80 points de dégâts par seconde, il est soigné pour tous les dégâts excédant ce nombre de points.','(10 secondes.) Les dégâts au-delà de 250...80 points subis par l\'allié visé durant chaque seconde sont convertis en points de vie. Vous ne pouvez pas vous prendre pour cible.'],
1587=>['Lien angélique','Pendant 10 secondes, la prochaine fois qu\'un allié à portée de voix doit subir des dégâts mortels, ces derniers sont annulés et il est soigné de 20...200 points de vie. Lien angélique prend fin sur tous les autres alliés.','(10 secondes.) La prochaine fois qu\'un allié à portée de voix doit subir des dégâts mortels, ces derniers sont annulés et il est soigné de 20...200 points de vie. Prend fin sur tous les autres alliés.'],
1588=>['Sceau cautère','Tous les membres du groupe perdent toutes leurs conditions. Vous êtes embrasé pendant 1 seconde pour chaque condition supprimée de cette façon.','Les membres du groupe perdent toutes leurs conditions. Vous souffrez de Brûlure (1 seconde par condition perdue).'],
1589=>['"Tenez bon !"','Pendant 5...20 secondes, tous les membres du groupe à portée de voix reçoivent +24 de bonus d\'armure lorsqu\'ils sont immobiles.','(5...20 secondes.) Les membres du groupe à portée de voix bénéficient d\'un bonus d\'armure de +24 quand ils sont immobiles.'],
1590=>['"Ouvrez le chemin !"','La cible alliée se déplace 25% plus vite pendant 1...5 secondes pour chaque allié à portée de voix (30 secondes maximum).','L\'allié visé se déplace 25% plus vite pendant 1...5 secondes pour chaque allié à portée de voix (maximum : 30 secondes).'],
1591=>['"Faites vite !"','Pendant 5...20 secondes, l\'allié visé se déplace 33% plus vite. Cette compétence prend fin si cet allié réussit son attaque.','(5...20 secondes.) L\'allié visé se déplace 33% plus vite. Prend fin si l\'allié visé réussit une attaque. Vous ne pouvez pas vous prendre pour cible.'],
1592=>['"Nous reviendrons !"','Tous les membres du groupe à portée de voix sont ressuscités avec 25...50% de leur santé et 5...20% de leur énergie.','Tous les membres du groupe à portée de voix sont ressuscités (25...50% de leur santé et 5...20% de leur énergie)'],
1593=>['"N\'abandonnez jamais !"','Tous les alliés à portée de voix ayant moins de 75% de santé gagnent 1...10 points d\'énergie.','Les alliés à portée de voix gagnent 1...10 points d\'énergie. Affecte uniquement les alliés possédant moins de 75% de santé.'],
1594=>['"À l\'aide !"','L\'allié ciblé (sauf les esprits) gagne 15...90 points de vie. Pendant 1...10 secondes, les sorts des autres alliés ciblant cet allié s\'incantent 50% plus vite.','(1...10 secondes.) L\'allié ciblé (sauf les esprits) gagne 15...90 points de vie et les sorts alliés s\'incantent 50% plus vite sur cette cible.'],
1595=>['"Repliez-vous !"','Pendant 4...10 secondes, tous les alliés à portée de voix bénéficient de 5...15 points de vie par seconde quand ils sont en mouvement et se déplacent 33% plus vite. "Repliez-vous !" prend fin sur l\'allié affecté par ce cri lorsque cet allié réussit une attaque.','(4...10 secondes.) Les alliés à portée de voix gagnent 5...15 points de vie par seconde quand ils sont en mouvement et se déplacent 33% plus vite. Prend fin pour tout allié réussissant une attaque.'],
1596=>['"Attention !"','Pendant 4...10 secondes, tous les alliés à portée de voix se déplacent 33% plus vite et gagnent 5...15 points de vie par seconde en se déplaçant.','(4...10 secondes.) Tous les alliés à portée de voix se déplacent 33% plus vite et gagnent 5...15 points de vie par seconde en se déplaçant.'],
1597=>['"Ils sont enflammés !"','Pendant 10 secondes, les membres du groupe à portée de voix subissent 5...35% de dégâts en moins lorsqu\'ils sont infligés par des ennemis souffrant de Brûlure.','(10 secondes.) Les ennemis souffrant de Brûlure infligent 5...35% de dégâts en moins aux membres du groupe à portée de voix.'],
1598=>['"Ne vous rendez jamais !"','Pendant 15 secondes, tous les membres du groupe à portée de voix ayant moins de 75% de santé bénéficient d\'une régénération de santé de +1...5.','(15 secondes.) Les membres du groupe à portée de voix bénéficient d\'une régénération de santé de +1...5. Affecte uniquement les membres du groupe possédant moins de 75% de santé.'],
1599=>['C\'est juste une petite blessure.','La cible alliée perd toutes ses conditions. Si une condition est supprimée de cette manière, cet allié se déplace 25% plus vite pendant 1...10 secondes.','Supprime toutes les conditions de la cible alliée. Cette dernière se déplace 25% plus vite (1...10 secondes) si une condition a été supprimée. Vous ne pouvez pas vous prendre pour cible.'],
1600=>['Javelot perforant','Si cette attaque réussit, votre cible souffre de Saignement pendant 5...20 secondes.','Provoque le Saignement (5...20 secondes).'],
1601=>['Attaque vicieuse','Si cette attaque réussit, vous infligez +5...20 points de dégâts. Si votre attaque inflige un coup critique, la cible ennemie souffre de Blessure profonde pendant 5...15 secondes.','Inflige +5...20 points de dégâts. Provoque la Blessure profonde (5...15 secondes) avec un coup critique.'],
1602=>['Frappe stupéfiante','Si cette attaque réussit, vous infligez +10...50 points de dégâts. Si elle touche un ennemi qui souffre d\'une condition, celui-ci est aussi frappé de Stupeur pendant 4...10 secondes.','Inflige +10...50 points de dégâts. Inflige la Stupeur (4...10 secondes) si la cible souffre d\'une condition.'],
1603=>['Javelot impitoyable','Si cette attaque touche un ennemi ayant moins de 50% de santé, cet ennemi souffre de Blessure profonde pendant 5...20 secondes.','Provoque la Blessure profonde (5...20 secondes). Aucun effet si la cible a plus de 50% de santé.'],
1604=>['Lancer d\'interruption','Si cette attaque affecte un ennemi souffrant d\'une condition, cet ennemi est interrompu.','Interrompt les actions. Aucun effet si la cible ne souffre pas d\'une condition.'],
1605=>['Lancer sauvage','Si elle réussit, cette attaque inflige +5...20 points de dégâts et toute pose utilisée par la cible prend fin. Impossible à bloquer. Toutes vos attaques avec autre chose qu\'une lance sont désactivées pendant 3 secondes.','Inflige +5...20 points de dégâts. Impossible à bloquer. Met fin à la pose de la cible.Désactive vos compétences offensives autres qu\'à la lance pendant 3 secondes.'],
1633=>['Coup malicieux','Si cette attaque frappe un ennemi souffrant d\'une condition, vous infligez +10...30 points de dégâts ainsi qu\'un coup critique.','Si la cible ennemie souffre d\'une condition, cette attaque inflige +10...30 points de dégâts et un coup critique.'],
1634=>['Assaut dévastateur','Doit suivre une attaque main gauche. Si elle réussit, vous infligez 5...50 points de dégâts et la cible ennemie perd un enchantement. Cette attaque ne peut pas être bloquée.','Inflige 5...50 points de dégâts. Supprime un enchantement. Impossible à bloquer. Doit succéder à une attaque main gauche.'],
1635=>['Attaques du crâne doré','Si vous êtes sous les effets d\'un enchantement et si cette attaque réussit, la cible ennemie est frappée de Stupeur pendant 1...12 secondes.','Inflige la Stupeur (1...12 secondes). Aucun effet si la cible n\'est pas sous les effets d\'un enchantement.'],
1636=>['Attaque de l\'araignée noire','Doit toucher un ennemi affecté par un maléfice. Si elle réussit, cette attaque inflige +5...20 points de dégâts et l\'ennemi visé est empoisonné pendant 5...20 secondes.','Inflige +5...20 points de dégâts. Provoque l\'Empoisonnement (5...20 secondes). Doit frapper un ennemi victime d\'un maléfice.'],
1637=>['Coup du renard doré','Si cette attaque réussit, vous infligez +10...30 points de dégâts à l\'ennemi ciblé. Si vous vous trouvez sous les effets d\'un enchantement, cette attaque ne pourra pas être bloquée.','Inflige +10...30 points de dégâts. Impossible à bloquer si vous êtes enchanté.'],
1638=>['Hâte mortelle','Pendant 10...35 secondes, les sorts dont la portée est réduite de moitié sont lancés 5...50% plus vite et se rechargent 5...60% plus vite.','(10...35 secondes.) Vos sorts dont la portée est réduite de moitié sont lancés 5...50% plus vite et se rechargent 5...60% plus vite.'],
1639=>['Remède de l\'Assassin','Pendant 30 secondes, les prochaines compétences d\'attaque (au nombre de 1...10) que vous utilisez suppriment une condition.','(30 secondes.) Vos compétences d\'attaque suivantes( 1...10 compétences d\'attaque) suppriment une condition chacune.'],
1640=>['Promesse du renard','Pendant 5...20 secondes, vos attaques avec des dagues ne peuvent pas être bloquées. Cet enchantement prend fin la prochaine fois qu\'une de vos attaques échoue.','(5...20 secondes.) Vos attaques avec des dagues sont impossibles à bloquer. Prend fin dès que vous manquez une attaque.'],
1641=>['Neutralité simulée','Pendant 4...10 secondes, vous bénéficiez d\'une régénération de santé de +7 et de +80 points de bonus d\'armure. Cet enchantement prend fin si une attaque réussit ou si vous utilisez une compétence.','(4...10 secondes.) Vous bénéficiez d\'une régénération de santé de +7 et d\'un bonus d\'armure de +80. Prend fin si vous réussissez une attaque ou utilisez une compétence.'],
1642=>['Chausse-trappes cachées','Vos compétences autres que celles d\'Assassin sont désactivées pendant 3 secondes. Pendant 1...10 secondes, l\'ennemi ciblé se déplace 50% moins vite. Lorsque ce maléfice prend fin, cet ennemi subit Infirmité pendant 1...15 secondes.','(1...10 secondes.) Ralentit les déplacements de 50%. Effet final : inflige l\'Infirmité (1...15 secondes). Vos compétences, sauf celles d\'Assassin, sont désactivées (10 secondes).'],
1643=>['Assaut d\'Enchantements','Doit succéder à une attaque d\'ambidextrie. La cible ennemie perd tous ses enchantements.','Supprime tous les enchantements. Doit succéder à une attaque d\'ambidextrie.'],
1644=>['Effondrement du gaspilleur','Vous faites une Foulée de l\'ombre vers la cible ennemie. Si cette dernière n\'utilisait pas de compétence, elle est assommée. Toutes vos compétences autres que des attaques à la dague sont désactivées pendant 10 secondes.','Vous faites une Foulée de l\'ombre vers la cible ennemie. Assomme l\'ennemi s\'il n\'utilise pas de compétence.Désactive vos compétences autres que les attaques à la dague (10 secondes).'],
1645=>['Enchantements levés','Si la cible ennemie touchée est assommée, elle perd un enchantement.','Supprime un enchantement.Aucun effet si l\'ennemi visé n\'est pas assommé.'],
1646=>['Présage mortel','Pendant 5...35 secondes, la prochaine fois que les dégâts font chuter la santé de l\'ennemi en dessous de 50%, vous infligez une Blessure profonde pendant 5...20 secondes et vous faites une foulée de l\'ombre vers cet ennemi. Sa portée est la moitié de celle d\'un sort normal.','(5...35 secondes.) Inflige la Blessure profonde (5...20 secondes) à l\'ennemi visé. Vous faites une foulée de l\'ombre vers lui dès que les dégâts font chuter sa santé en dessous de 50%.'],
1647=>['Sceau de choc toxique','Si la cible ennemie souffre d\'Empoisonnement, cet ennemi subit 10...100 points de dégâts.','Inflige 10...100 points de dégâts. Aucun effet si l\'ennemi visé n\'est pas empoisonné.'],
1648=>['Sceau de l\'aube','Pour chaque maléfice qui affecte la cible ennemie, celle-ci perd un enchantement.','Supprime un enchantement par maléfice affectant l\'ennemi visé.'],
1649=>['Méthode de l\'Assassin','Pendant 20 secondes, si vous êtes équipé de dagues, vous attaquez 5...20% plus vite et avez +5...35% de chances d\'infliger un coup critique.','(20 secondes.) Si vous êtes équipé de dagues, vous attaquez 5...20% plus vite et avez +5...35% de chances d\'infliger un coup critique.'],
1650=>['Marche de l\'ombre','Vous faites une Foulée de l\'ombre jusqu\'à la cible ennemie. Pendant 15 secondes, rien ne se passe. Vos compétences d\'attaques sont inutilisables pendant 1 seconde ; vos enchantements et poses de combat sont inutilisables pendant 10 secondes. Lorsque cette pose prend fin, vous retournez à votre position initiale.','(15 secondes.) Vous faites une Foulée de l\'ombre jusqu\'à la cible ennemie. Effet final : retour à votre position initiale. Désactive vos compétences d\'attaques pendant 1 seconde. Désactive vos enchantements et poses de combat pendant 10 secondes.'],
1651=>['Retraite de la mort','Vous faites une Foulée de l\'ombre jusqu\'à la cible alliée. Si vous possédez moins de santé que cet allié, vous bénéficiez de 40...130 points de vie.','Vous gagnez 40...130 points de vie si vous avez moins de santé que l\'allié visé. Effet initial : vous faites une foulée de l\'ombre vers cet allié. Vous ne pouvez pas vous prendre pour cible.'],
1652=>['Prison d\'ombre','Vous faites une Foulée de l\'ombre en direction de la cible ennemie. Pendant 1...7 secondes, la cible se déplace 66% moins vite.','Vous faites une foulée de l\'ombre vers la cible ennemie. Cet ennemi se déplace 66% moins vite (1...7 secondes).'],
1653=>['Echange','Vous faites une foulée de l\'ombre vers la créature invoquée ciblée et vice-versa.','Vous faites une foulée de l\'ombre vers la créature invoquée ciblée et vice-versa.'],
1654=>['Mêlée de l\'ombre','Vous faites une foulée de l\'Ombre vers l\'allié ciblé. Lorsque vous cessez d\'utiliser cet enchantement, vous retournez à votre position d\'origine.','Vous faites une foulée de l\'ombre vers l\'allié visé. Effet final : vous retournez sur votre position d\'origine. Vous ne pouvez pas vous prendre pour cible.'],
1655=>['Prix de l\'orgueil','Pendant 5 secondes, la prochaine fois que la cible ennemie utilise une compétence d\'élite, elle perd 3...15 points d\'énergie.','(5 secondes.) L\'ennemi visé perdra 3...15 points d\'énergie la prochaine fois qu\'il utilisera une compétence élite.'],
1656=>['Air de Désenchantement','Vous supprimez un enchantement à la cible ennemie et à tous les ennemis à proximité. Pendant 5...20 secondes, les enchantements expirent 150...300% plus vite sur ces ennemis.','Inflige également un maléfice aux ennemis proches de votre cible (5...20 secondes). Lève un enchantement à la cible et aux ennemis à proximité. Les enchantements expirent 150...300% plus vite sur ces ennemis.'],
1657=>['Sceau de Maladresse','Si la cible ennemie attaque, cet ennemi ainsi que tous les ennemis adjacents sont interrompus et subissent 15...60 points de dégâts. Tous les ennemis utilisant des compétences d\'attaque sont assommés.','Interrompt une attaque pour la cible ennemie et tous les ennemis adjacents. Effet de l\'interruption : inflige 15...60 points de dégâts et assomme les ennemis utilisant des compétences d\'attaque.'],
1658=>['Posture symbolique','Pendant 5...20 secondes, le prochain sceau que vous activez se recharge 20...80% plus vite.','(5...20 secondes.) Votre prochain sceau se recharge 20...80% plus vite.'],
1659=>['Frisson toxique','La cible ennemie subit 15...75 points de dégâts du froid. S\'il est sous les effets d\'un enchantement ou d\'un maléfice, cet ennemi souffre d\'Empoisonnement pendant 10...25 secondes.','Inflige 15...75 points de dégâts du froid. Inflige l\'Empoisonnement (10...25 secondes) si l\'ennemi visé est affecté par un maléfice ou un enchantement.'],
1660=>['Puits du silence','Exploitez le cadavre visé ou sacrifiez 66% de santé pour créer un Puits du silence pendant 10...30 secondes. Les ennemis se trouvant dans ce puits ne peuvent pas utiliser de cris ou de chants et subissent une dégénération de santé de -1...4.','(10...30 secondes.) Les ennemis présents dans ce puits ne peuvent pas utiliser de cris ni de chants et subissent -1...4 points de dégénération de santé. Exploite un cadavre frais ou sacrifie 66% de la santé.'],
1661=>['Pierre fluorescente','Vous envoyez un projectile qui inflige 5...50 points de dégâts de la terre si l\'attaque réussit. Si ce sort frappe un ennemi souffrant de Faiblesse, vous gagnez 5 points d\'énergie et 1 point d\'énergie supplémentaire tous les 2 rangs de Conservation d\'énergie.','Projectile : inflige 5...50 points de dégâts de la terre. Vous gagnez 5 points d\'énergie et 1 point d\'énergie supplémentaire tous les 2 rangs de Conservation d\'énergie si la cible ennemie souffre de Faiblesse.'],
1662=>['Explosion de l\'âme','La cible ennemie subit 15...60 points de dégâts du feu. Si vous avez plus d\'énergie que la cible ennemie, vous gagnez 1...8 points d\'énergie.','Inflige 15...60 points de dégâts de feu. Vous gagnez 1...8 points d\'énergie si vous avez plus d\'énergie que la cible ennemie.'],
1663=>['Flamme élémentaire','Pendant 10...35 secondes, chaque fois que vous infligez un maléfice élémentaire à un ennemi, cet ennemi s\'embrase pendant 1...5 secondes.','(10...35 secondes.) Inflige la Brûlure (1...5 secondes) chaque fois que vous infligez un maléfice élémentaire à un ennemi visé.'],
1664=>['Invocation de la foudre','L\'ennemi visé et jusqu\'à deux autres ennemis proches de lui subissent 10...90 points de dégâts de la foudre. Ce sort a une pénétration d\'armure de 25%.','Inflige 10...90 points de dégâts de la foudre. Frappe deux ennemis proches de la cible. 25% de pénétration d\'armure.'],
1683=>['Gardien pensif','Pendant 5...11 secondes, la cible (un allié ou vous-même) a 50% de chances de bloquer les attaques lancées par des ennemis enchantés.','(5...11 secondes.) 50% de chances de bloquer les ennemis enchantés.'],
1684=>['Clairvoyance du Scribe','Pendant 10...35 secondes, vous gagnez 3 points d\'énergie chaque fois que vous utilisez un sceau.','(10...35 secondes.) Vous obtenez 3 points d\'énergie chaque fois que vous utilisez un sceau.'],
1685=>['Hâte sacrée','Pendant 1...60 secondes, vos sorts de Prières de guérison sont lancés 50% plus rapidement. Cet enchantement prend fin si vous lancez un autre enchantement.','(1...60 secondes.) Vos sorts de Prières de guérison sont lancés 50% plus vite. Prend fin si vous lancez un enchantement.'],
1686=>['Lueur','Soigne la cible (un allié ou vous-même) de 10...115 points de vie.','Soigne de 10...115 points de vie.'],
1687=>['Bénédiction zélée','Vous guérissez la cible (un allié ou vous-même) de 30...180 points de vie. Si celle-ci possédait moins de 50% de santé, vous récupérez 7 points d\'énergie.','Soigne de 30...180 points de vie. Vous gagnez 7 points d\'énergie si l\'allié visé avait moins de 50% de santé.'],
1688=>['Zèle du Défenseur','Pendant 10...30 secondes, chaque fois que l\'ennemi visé réussit une attaque, vous bénéficiez de 2 points d\'énergie.','(10...30 secondes.) Vous gagnez 2 points d\'énergie chaque fois que l\'ennemi visé réussit une attaque.'],
1689=>['Sceau de colère mystique','La cible ennemie subit 25 points de dégâts sacrés pour chaque enchantement qui vous affecte (30...120 points de dégâts sacrés maximum).','Inflige 25 points de dégâts sacrés par enchantement vous affectant (maximum : 30...120 points de dégâts sacrés).'],
1690=>['Sceau de suppression','Si la cible (un allié ou vous-même) est sous les effets d\'un enchantement, elle perd un maléfice et une condition.','Supprime une condition et un maléfice. Aucun effet si l\'allié visé n\'est pas enchanté.'],
1691=>['Suppression de condition','Supprime une condition affectant une cible (un allié ou vous-même). Si cette cible est sous les effets d\'un enchantement, elle est soignée de 15...75 points de vie.','Supprime une condition. Soigne de 15...75 points de vie si l\'allié visé est enchanté.'],
1692=>['Diversion des maléfices','Supprime jusqu\'à 1...3 maléfices affectant la cible (un allié ou vous-même). Pour chaque maléfice ôté de cette manière, la cible perd une condition et gagne 15...75 points de vie.','Supprime 1...3 maléfices. L\'allié visé perd une condition et gagne 15...75 points de vie par maléfice supprimé.'],
1693=>['Contre-attaque','Si cette attaque réussit, vous infligez +5...35 points de dégâts. Si vous frappez un ennemi qui attaque, vous obtenez 2...6 points d\'énergie.','Inflige +5...35 points de dégâts. Vous gagnez 2...6 points d\'énergie si l\'ennemi visé attaque.'],
1694=>['Frappe du chasseur de mages','Si cette attaque réussit, vous infligez +7...25 points de dégâts. Si votre cible se trouve sous les effets d\'un enchantement, cette attaque ne pourra pas être bloquée.','Inflige +7...25 points de dégâts. Impossible à bloquer si l\'ennemi visé est enchanté.'],
1695=>['Attaque de soldat','Si cette attaque réussit, vous infligez +10...40 points de dégâts supplémentaires. Si vous êtes sous les effets d\'un chant ou d\'un cri, cette attaque ne pourra pas être bloquée.','Inflige +10...40 points de dégâts. Impossible à bloquer si vous êtes sous l\'effet d\'un chant ou d\'un cri.'],
1696=>['Décapitation','You lose all adrenaline and all Energy. This attack is unblockable, you deal +5...80 damage, and cause a Deep Wound for 5...20 seconds. This attack is always critical and if foe is killed, nearby foes are Weakened for 8 seconds.','Deals +5...80 damage. Inflicts Deep Wound condition (5...20 seconds). Automatic critical hit. If foe is killed, nearby foes are Weakened (8 seconds). You lose all adrenaline and Energy.'],
1697=>['Attaque du chasseur de mages','Si cette attaque réussit, la cible ennemie est assommée. Si votre cible est sous les effets d\'un enchantement, cette attaque ne peut pas être bloquée.','Attaque assommante. Impossible à bloquer si l\'ennemi visé est enchanté.'],
1698=>['Pose du soldat','Pendant 5...15 secondes, vous avez 75% de chances de bloquer les attaques. Vous attaquez 33% plus vite lorsque vous êtes sous l\'effet d\'un cri ou d\'un chant.','(5...15 secondes.) Vous avez 75% de chances de bloquer les attaques. Vous attaquez 33% plus vite lorsque vous êtes sous l\'effet d\'un cri ou d\'un chant.'],
1699=>['Défense du soldat','Pendant 1...6 secondes, vous avez 75% de chances de bloquer les attaques lorsque que vous êtes sous l\'effet d\'un cri ou d\'un chant. Vous gagnez 1 décharge d\'adrénaline chaque fois que vous bloquez une attaque.','(1...6 secondes.) Vous avez 75% de chances de bloquer les attaques lorsque vous êtes sous l\'effet d\'un cri ou d\'un chant. Effet du blocage : vous gagnez 1 décharge d\'adrénaline.'],
1700=>['Défense frénétique','Pendant 8 secondes, vous avez 75% de chances de bloquer les attaques dirigées contre vous, mais vous subissez le double de dégâts.','(8 secondes.) Vous avez 75% de chances de bloquer. Vous subissez le double de dégâts.'],
1701=>['Pose stable','Pendant 10 secondes), la prochaine attaque qui doit vous assommer échoue et vous recevez 1...4 décharges) d\'adrénaline et 1...7 points d\'énergie.','(10 secondes.) La prochaine attaque qui devrait vous assommer échoue et vous gagnez 1...4 décharges d\'adrénaline et 1...7 points d\'énergie.'],
1702=>['Frappe Croc-d\'acier','Si cette attaque réussit, vous infligez +1...31 points de dégâts. Si vous frappez un ennemi assommé, vous bénéficiez de 1...5 décharges d\'adrénaline.','Inflige +1...31 points de dégâts. Vous gagnez 1...5 décharges d\'adrénaline si l\'ennemi visé est assommé.'],
1719=>['Tir hurleur','Si cette attaque réussit, vous infligez +10...25 points de dégâts. Si votre cible est à portée de voix, elle souffre de Saignement pendant 5...20 secondes.','Inflige +10...25 points de dégâts. Inflige le Saignement (5...20 secondes) si l\'ennemi visé est à portée de voix.'],
1720=>['Flèche vive','Si l\'attaque réussit, vous infligez +5...20 points de dégâts. Si vous causez un coup critique, vous infligez +5...25 points de dégâts supplémentaires.','Inflige +5...20 points de dégâts. Inflige +5...25 points de dégâts supplémentaires si vous faites un coup critique.'],
1721=>['Férocité unie','Pendant 3...15 secondes, vous et votre familier attaquez 33% plus vite et courez 25% plus vite.','(3...15 secondes.) Votre familier et vous attaquez 33% plus vite et vous déplacez 25% plus vite. Aucun effet si votre familier est mort.'],
1722=>['Flèche fourchue','Vous décochez deux flèches simultanément sur la cible ennemie. Si vous êtes sous les effets d\'un enchantement ou d\'un maléfice, vous ne décochez qu\'une seule flèche.','Vous tirez deux flèches en même temps. Vous ne tirez qu\'une flèche si vous êtes enchanté ou sous l\'effet d\'un maléfice.'],
1723=>['Précision perturbatrice','Pendant 36 secondes, chaque fois que vos flèches infligent un coup critique, elles interrompent aussi votre cible.','(36 secondes.) Interrompt une action chaque fois que vos flèches infligent un coup critique.'],
1724=>['Dextérité de l\'expert','Pendant 1...20 secondes, vous attaquez 33% plus vite et votre caractéristique d\'Adresse au tir est augmentée de 2.','(1...20 secondes.) Vous attaquez 33% plus vite et votre caractéristique d\'Adresse au tir est augmentée de +2.'],
1725=>['Vents mugissants','Crée un esprit de niveau 1...10. Les chants et les cris coûtent 1...5 points d\'énergie en plus. L\'esprit meurt au bout de 30...180 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...180 secondes). Les chants et les cris coûtent 1...5 points d\'énergie en plus pour les créatures à portée.'],
1726=>['Tir du Fléau des mages','Si cette attaque réussit, elle interrompt l\'action de la cible ennemie. S\'il s\'agissait d\'un sort, il est inutilisable pendant 10 secondes supplémentaires. Cette attaque ne peut pas être bloquée.','Interrompt une action. Effet de l\'interruption : un sort interrompu est désactivé pendant +10 secondes. Impossible à bloquer.'],
1727=>['Foulée naturelle','Pendant 1...8 secondes, vous courez 33% plus vite et avez 50% de chances de bloquer les attaques qui vous sont lancées. La foulée naturelle prend fin si vous êtes affecté par un maléfice ou un enchantement.','(1...8 secondes.) Vous vous déplacez 33% plus vite et avez 50% de chances de bloquer. Prend fin si vous êtes affecté par un maléfice ou un enchantement.'],
1728=>['Saccage du Heket','Pendant 5...11 secondes, vous attaquez 33% plus vite. Cette pose de combat prend fin si vous utilisez une compétence d\'attaque.','(5...11 secondes.) Vous attaquez 33% plus vite. Prend fin si vous utilisez une compétence d\'attaque.'],
1729=>['Piège de fumée','Lorsque le Piège de fumée est déclenché, les ennemis à proximité sont frappés d\'Aveuglement et de Stupeur pendant 5...10 secondes. Le Piège de fumée prend fin au bout de 90 secondes. Vous êtes plus susceptible d\'être victime d\'interruption lorsque vous activez cette compétence.','(90 secondes.) Inflige les altérations Aveuglement et Stupeur (5...10 secondes) aux ennemis dans la zone. Interruption facile.'],
1730=>['Chaleur exaspérante','Crée un esprit de niveau 1...10. Les créatures dans sa portée (autres que des esprits) récupèrent de l\'adrénaline deux fois plus vite. Cet esprit disparaît au bout de 30...120 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...120 secondes). Les créatures à portée gagnent deux fois plus d\'adrénaline.'],
1731=>['Sogolon était énergique','Pendant 60 secondes, les chants et cris que vous utilisez durent 20...50% plus longtemps.','(60 secondes.) Les cris et les chants que vous utilisez durent 20...50% plus longtemps.'],
1732=>['Glaive était destructrice','Vous tenez les cendres de Glaive pendant un maximum de 30...60 secondes. En tenant ses cendres, toutes les compétences du Ritualiste bénéficient de 20% de pénétration d\'armure. Lorsque vous déposez ses cendres, tous les ennemis dans la zone subissent 15...85 points de dégâts de la foudre.','(30...60 secondes.) Vos compétences de Ritualiste bénéficient de 20% de pénétration d\'armure. Effet de la pose : inflige 15...85 points de dégâts de la foudre à tous les ennemis dans la zone.'],
1733=>['Attaque du porteur','La cible ennemie reçoit 10...60 points de dégâts de la foudre. Si vous êtes sous les effets d\'un sort d\'altération d\'arme, vous infligez 10...50 points de dégâts de la foudre supplémentaires.','Inflige 10...60 points de dégâts de la foudre. Inflige 10...50 points de dégâts de la foudre supplémentaires si vous êtes sous l\'effet d\'un sort d\'altération d\'arme.'],
1734=>['Regard de fureur','Anéantit l\'esprit visé et crée un esprit de fureur de niveau 1...14. Les attaques de cet esprit infligent 5...20 points de dégâts. Cet esprit meurt au bout de 30...60 secondes.','Supprime un esprit. Crée un esprit de niveau 1...14 (durée de vie de 30...60 secondes). Ses attaques infligent 5...20 points de dégâts.'],
1736=>['Force de l\'esprit','Pendant 15...60 secondes, vos attaques infligent 5...35 points de dégâts en plus sous les effets d\'un sort d\'altération d\'arme.','(15...60 secondes.) Vos attaques infligent +5...35 points de dégâts si vous êtes sous l\'effet d\'un sort d\'altération d\'arme.'],
1737=>['Zèle du porteur','Pendant 10...40 secondes, chaque fois que vous lancez un sort d\'altération d\'arme sur un allié, vous bénéficiez de 1...5 points d\'énergie.','(10...40 secondes.) Vous obtenez 1...5 points d\'énergie chaque fois que vous lancez un sort d\'altération d\'arme.'],
1738=>['Vision intérieure','Pendant 8...20 secondes, vous ne pouvez pas souffrir d\'Aveuglement.','(8...20 secondes.) Vous êtes immunisé contre l\'Aveuglement.'],
1739=>['Souvenirs renouvelés','Pendant 5...20 secondes, pendant que vous tenez un objet, tout sort d\'altération d\'armes ou d\'objets coûte 5...35% d\'énergie en moins.','(5...20 secondes.) Vos sorts d\'altération d\'armes ou d\'objets coûtent 5...35% d\'énergie en moins. Aucun effet si vous ne tenez pas d\'objet.'],
1740=>['Remède du porteur','Pendant 10...30 secondes, chaque fois que vous lancez un sort d\'altération d\'arme sur un allié, cet allié perd 2 altérations.','(10...30 secondes.) Chaque fois que vous lancez un sort d\'altération d\'arme, l\'allié ciblé perd 2 altérations.'],
1741=>['Lumière du miroir fantôme','L\'allié visé est soigné de 15...90 points de vie. Si vous êtes à portée de voix d\'un esprit, vous êtes aussi soigné de 15...90 points de vie.','Soigne de 15...90 points de vie. Vous gagnez 15...90 points de vie si vous êtes à portée de voix d\'un esprit. Vous ne pouvez pas vous prendre pour cible.'],
1742=>['Sceau de puissance spectrale','Pendant 5...20 secondes, tous les esprits que vous contrôlez à portée de voix attaquent 33% plus vite et infligent +5...10 points de dégâts.','(5...20 secondes.) Tous les esprits que vous contrôlez à portée de voix attaquent 33% plus vite et infligent +5...10 points de dégâts.'],
1743=>['Sceau d\'asservissement','Vous perdez 200...50 points de vie et asservissez l\'esprit visé contrôlé par l\'ennemi. (50% de risques d\'échec avec Puissance de l\'Invocation 4 ou inférieure.)','Vous perdez 200...50 points de vie. Vous asservissez l\'esprit visé contrôlé par l\'ennemi. <c x="SkillDull">50% de risques d\'échec avec Puissance de l\'Invocation 5 ou supérieure.'],
1744=>['Charge du gardien','La cible ennemie reçoit 20...85 points de dégâts de la foudre. Si vous tenez un objet, vous bénéficiez de 7 points d\'énergie et de 5...50 points de vie.','Inflige 20...85 points de dégâts de la foudre. Vous gagnez 7 points d\'énergie et 5...50 points de vie si vous tenez un objet.'],
1745=>['Angoisse','Crée un esprit de niveau 1...11. L\'attaque de cet esprit inflige 5...20 points de dégâts et deux fois plus de dégâts à des ennemis affectés par un maléfice. L\'esprit meurt au bout de 15...45 secondes.','Crée un esprit de niveau 1...11 (durée de vie de 15...45 secondes). Ses attaques infligent 5...20 points de dégâts. Les ennemis victimes de maléfices subissent deux fois plus de dégâts.'],
1747=>['Responsabilisation','Crée un esprit de niveau 1...14. Tous les alliés dans sa portée qui portent un objet bénéficient de 15...45 de santé maximum et de 10 points d\'énergie maximum. Cet esprit disparaît au bout de 15...60 secondes.','Crée un esprit de niveau 1...14 (durée de vie de 15...60 secondes). Les alliés à portée qui tiennent un objet gagnent 15...45 points de vie maximum et 10 points d\'énergie maximum.'],
1748=>['Récupération','Crée un esprit de niveau 1...14. Les conditions affectant les alliés à portée de cet esprit prennent fin 20...50% plus vite. Cet esprit disparaît au bout de 30...60 secondes.','Crée un esprit de niveau 1...14 (durée de vie de 30...60 secondes). Les conditions dont souffrent les alliés à portée prennent fin 20...50% plus vite.'],
1749=>['Arme de furie','Pendant 5...20 secondes, la cible (un allié ou vous-même) bénéficie de 100% d\'adrénaline supplémentaire et d\'1 point d\'énergie chaque fois qu\'elle réussit une attaque.','(5...20 secondes.) Chaque fois qu\'elle réussit un attaque, la cible (allié ou vous-même) gagne 100% d\'adrénaline en plus et +1 point d\'énergie.'],
1750=>['Arme de Xinrae','Pendant 8 secondes, la prochaine fois que la cible alliée subit des dégâts, ceux-ci sont limités à 5% de sa santé maximum et cet allié vole jusqu\'à 20...80 points de vie à son assaillant.','(8 secondes.) La prochaine fois que la cible alliée subit des dégâts, ceux-ci sont limités à 5% de sa santé maximum et cet allié vole jusqu\'à 20...80 points de vie à son assaillant.'],
1751=>['Arme du belliciste','Pendant 3...13 secondes, si la cible (un allié ou vous-même) attaque un ennemi qui n\'attaque pas, celui-ci est interrompu.','(3...13 secondes.) Les attaques interrompent une action. N\'interrompt pas les ennemis qui attaquent.'],
1752=>['Arme de remède','Pendant 8 secondes, la prochaine fois que l\'allié visé subit des dégâts ou un vol de vie, il absorbe 20...80 points de vie à cet ennemi et perd 2 altérations.','(8 secondes.) La prochaine fois que l\'allié visé subit des dégâts ou un vol de vie, il absorbe 20...80 points de vie à cet ennemi et perd 2 altérations.'],
1753=>['Frappe déchirante','Vous infligez +5...20 points de dégâts et perdez un enchantement de Derviche. En cas de perte d\'enchantement, vous retirez un enchantement à chaque ennemi touché.','Inflige +5...20 points de dégâts. Vous perdez un enchantement de Derviche. Effet de la suppression : les ennemis touchés perdent un enchantement.'],
1754=>['Attaque','Pendant 3...15 secondes, vous attaquez, vous vous déplacez et vous gagnez de l\'adrénaline 25% plus vite.','(3...15 secondes.) Vous attaquez, vous vous déplacez et vous gagnez de l\'adrénaline 25% plus vite.'],
1755=>['Corruption mystique','Tous les ennemis adjacents sont frappés de Maladie pendant 1...10 secondes. Pendant 20 secondes, rien ne se passe. La durée de la Maladie est doublée si vous êtes sous le coup d\'un enchantement quand vous activez cette compétence. Une fois cet enchantement dissipé, tous les membres du groupe à portée de voix sont soignés de la Maladie.','(20 secondes.) Effet initial : tous les ennemis adjacents souffrent de Maladie (pendant 1...10 secondes). Durée doublée si vous êtes déjà sous le coup d\'un enchantement. Effet final : les membres du groupe à portée de voix perdent Maladie.'],
1756=>['Empoigne de Grenth','For 20 seconds, your attack skills also Cripple that foe for 1...11 seconds and you transfer 1...3 conditions from yourself to that foe.','(20 seconds.) Inflict Cripple (1...11 seconds) with your attack skills and transfer 1...3 conditions.'],
1757=>['Voile d\'épines','Lorsque vous lancez cet enchantement, tous les ennemis à proximité subissent 5...50 points de dégâts perforants. Pendant 5...25 secondes, les sorts vous infligent 5...35% points de dégâts en moins.','(5...25 secondes.) Les dégâts que vous infligent les sorts sont réduits de 5...35%. Effet initial : inflige 5...50 points de dégâts perforants aux ennemis à proximité.'],
1758=>['Empoigne d\'harrier','Pendant 5...20 secondes, les attaques lancées contre des ennemis en mouvement causent l\'Infirmité chez ces ennemis pendant 2...9 secondes. Lorsque vous lancez cet enchantement, vous êtes soulagé de l\'Infirmité et d\'une autre condition. Cet enchantement prend fin après 1...3 applications d\'Infirmité.','(5...20 secondes.) Les attaques contre les ennemis en mouvement les font également souffrir d\'Infirmité. Effet initial : vous perdez Infirmité et une autre condition. Prend fin après 1...3 applications d\'Infirmité.'],
1759=>['Voeu de force','Pendant 15 secondes, chaque fois que vous attaquez un ennemi à la faux, tous les ennemis à proximité subissent 10...25 points de dégâts tranchants.','(15 secondes.) Les attaques à la faux infligent 10...25 points de dégâts tranchants à tous les ennemis adjacents chaque fois que vous attaquez.'],
1760=>['Aura de poussière d\'ébène','Quand vous lancez cet enchantement, tous les ennemis adjacents sont aveuglés pendant 1...7 secondes. Pendant 30 secondes, si vous tenez une arme de dégâts de la terre, vos compétences d\'attaques de mêlée infligent +3...30 points de dégâts de la terre. Lorsque cet enchantement prend fin, vous êtes libéré de l\'Aveuglement.','(30 secondes.) inflige +3...30 points de dégâts de la terre à chaque attaque de mêlée. Effet initial : les ennemis adjacents sont aveuglés pendant 1...7 secondes. Effet final : annule l\'Aveuglement. Aucun effet si vous n\'utilisez pas une arme infligeant des dégâts de la terre.'],
1761=>['Voeu zélé','Pendant 20 secondes, vous avez -2 de régénération d\'énergie, et vous bénéficiez de 1...6 points d\'énergie chaque fois que vous réussissez une attaque.','(20 secondes.) Vous gagnez 1...6 points d\'énergie chaque fois que vous réussissez une attaque. Votre régénération d\'énergie est réduite de -2.'],
1762=>['Coeur de furie','Pendant 2...10 secondes, vous attaquez 25% plus vite.','(2...10 secondes.) Votre vitesse d\'attaque est augmentée de 25%.'],
1763=>['Renouveau zélé','Tous les ennemis à proximité subissent 5...30 points de dégâts sacrés. Pendant 5...25 secondes, chaque fois que vous touchez un ennemi, vous avez -1 en régénération d\'énergie et gagnez 1 point d\'énergie. Si cet enchantement prend fin prématurément, vous gagnez 1...5 points d\'énergie.','(5...25 secondes.) Effet initial : inflige 5...30 points de dégâts sacrés aux ennemis proches. A chacun de vos coups, vous avez -1 en régénération d\'énergie et gagnez 1 point d\'énergie. +1...5 points d\'énergie si cet enchantement prend fin prématurément.'],
1764=>['Clairvoyance de l\'attaquant','Pendant 3...10 secondes, vous avez 50% de chances de bloquer les attaques lorsque vous attaquez. Quand cet enchantement prend fin, tous les ennemis à proximité sont frappés de Faiblesse pendant 3...15 secondes.','(3...10 secondes.) 50% de chances de blocage pendant une attaque. Effet final : les ennemis adjacents sont frappés de Faiblesse pendant 3...15 secondes.'],
1765=>['Aura déchirante','Lorsque vous lancez cet enchantement, tous les ennemis à proximité subissent 10...40 points de dégâts du froid. Pendant 30 secondes, vos compétences d\'attaque suppriment les enchantements des ennemis assommés. A l\'issue de cet enchantement, tous les ennemis adjacents sont affectés par Armure brisée pendant 1...10 secondes.','(30 secondes.) Vos compétences d\'attaque suppriment les enchantements des ennemis assommés. Effet initial : inflige 10...40 points de dégâts du froid aux ennemis proches. Effet final : les ennemis proches subissent Armure brisée pendant 1...10 secondes.'],
1766=>['Grâce de Pied-de-plume','Pendant 5...20 secondes, vous vous déplacez 25% plus vite et les conditions prennent fin 50% plus vite.','(5...20 secondes.) Vous vous déplacez 25% plus vite et les conditions prennent fin 50% plus vite.'],
1767=>['Frappe du moissonneur','Si cette attaque réussit, la cible ennemie souffre d\'Infirmité pendant 3...15 secondes. Vous perdez un enchantement de Derviche. Si un enchantement a été levé, cette attaque renverse la cible pendant 2...3 secondes.','(3...15 secondes.) Inflige Infirmité. Vous perdez un enchantement de Derviche. Effet de la suppression : renverse la cible pendant 2...3 secondes.'],
1768=>['Hâte d\'harrier','Pendant 2...8 secondes, vous vous déplacez 25% plus vite et infligez +3...12 points de dégâts supplémentaires aux ennemis en mouvement.','(2...8 secondes.) Vous vous déplacez 25% plus vite et infligez +3...12 points de dégâts aux ennemis en mouvement.'],
1769=>['Colère concentrée','Pendant 45 secondes, vous obtenez 0...150% d\'adrénaline en plus.','(45 secondes.) Vous gagnez 0...150% d\'adrénaline en plus.'],
1770=>['Tempérament naturel','Pendant 4...15 secondes, vous bénéficiez de 33% d\'adrénaline en plus lorsque vous n\'êtes pas affecté par un enchantement.','(4...15 secondes.) Vous gagnez 33% d\'adrénaline en plus. Aucun effet si vous êtes enchanté.'],
1771=>['Chant de rétablissement','Pendant 10 secondes, la prochaine fois que chaque membre du groupe à portée de voix utilise une compétence, il est soigné de 45...110 points de vie.','(10 secondes.) Les membres du groupe à portée de voix récupèrent 45...110 points de vie grâce à leur compétence suivante.'],
1772=>['Poème de purification','Pendant 5...20 secondes, la prochaine fois que chaque allié à portée de voix utilise un sceau, il perd 1 condition.','(5...20 secondes.) Les alliés à portée de voix perdent une condition grâce à leur sceau suivant.'],
1773=>['Fureur du soldat','Pendant 10...35 secondes, si vous êtes sous l\'effet d\'un chant ou d\'un cri, votre vitesse d\'attaque augmente de 33% et vous bénéficiez de 33% d\'adrénaline en plus, mais vous avez un malus d\'armure de -20.','(10...35 secondes.) Vous attaquez 33% plus vite et bénéficiez de 33% d\'adrénaline en plus si vous êtes sous l\'effet d\'un cri ou d\'un chant. Vous avez un malus d\'armure de -20.'],
1774=>['Refrain agressif','Pendant 5...25 secondes, vous attaquez 25% plus vite mais votre armure est réduite de -20. Cet écho se renouvelle chaque fois qu\'un chant ou un cri vous affectant prend fin.','(5...25 secondes.) Votre vitesse d\'attaque est augmentée de 25%. Renouvellement : chaque fois qu\'un chant ou un cri vous affectant prend fin. Vous avez un malus d\'armure de -20.'],
1775=>['Finale énergisant','Pendant 10...35 secondes, chaque fois qu\'un chant ou un cri sur une cible (autre qu\'un esprit) prend fin, cette cible reçoit 1...2 points d\'énergie.','(10...35 secondes.) L\'allié visé gagne 1...2 points d\'énergie chaque fois qu\'un chant ou un cri l\'affectant prend fin. Vous ne pouvez pas viser les esprits.'],
1776=>['Sceau d\'agression','Si vous êtes sous les effets d\'un chant ou d\'un cri, vous gagnez 2 décharges d\'adrénaline.','Vous gagnez 2 décharges d\'adrénaline si vous êtes sous l\'effet d\'un cri ou d\'un chant.'],
1777=>['Sceau du remède','Vous perdez 1 condition.','Vous perdez une condition.'],
1778=>['Sceau de retour','Vous ressuscitez le membre du groupe visé avec 5...20% de santé et 1...4% d\'énergie pour chaque membre du groupe à portée de voix.','Ressuscite le membre du groupe visé (5...20% de santé et 1...4% d\'énergie par membre du groupe à portée de voix).'],
1779=>['"Profitez de votre temps !"','Vous bénéficiez de 2 décharges d\'adrénaline pour chaque membre du groupe à portée de voix (1...8 décharges d\'adrénaline maximum).','Vous gagnez 2 points d\'adrénaline (maximum : 1...8) par membre du groupe à portée de voix.'],
1780=>['"Pas touche !"','Pendant 20 secondes, les 1...5 prochaines compétences de contact utilisées contre les alliés à portée de voix échouent.','(20 secondes.) les 1...5 prochaines compétences de contact utilisées contre les alliés à portée de voix échouent.'],
1781=>['"Trouvez leur faiblesse !"','Pendant 5...20 secondes, la prochaine fois que l\'allié ciblé attaque, il inflige +5...50 points de dégâts et cause aussi une Blessure profonde pendant 5...20 secondes.','(5...20 secondes.) La prochaine attaque portée par l\'allié ciblé inflige +5...50 points de dégâts et provoque une Blessure profonde (5...20 secondes).'],
1782=>['"La force est avec vous !"','Pendant 2...4 secondes, tous les alliés à portée de voix bénéficient d\'une régénération d\'énergie de 1...2.','(2...4 secondes.) Tous les alliés à portée de voix bénéficient d\'une régénération d\'énergie de 1...2.'],
1783=>['Javelot de l\'assassin','Si cette attaque réussit, vous infligez +5...25 points de dégâts. Si votre ennemi a plus de santé que vous, il souffre de Blessure profonde pendant 5...20 secondes.','Inflige +5...25 points de dégâts. Inflige la Blessure profonde (5...20 secondes) si la cible a plus de santé que vous.'],
1784=>['Javeline leste','Si l\'attaque réussit, vous infligez +5...20 points de dégâts. Si vous êtes sous les effets d\'un enchantement, ce javelot vole deux fois plus vite et ne peut pas être bloqué.','Inflige +5...20 points de dégâts. Ce javelot se déplace deux fois plus vite et ne peut être bloqué si vous êtes enchanté.'],
1814=>['Regard du Porteur de lumière','Le serviteur démoniaque d\'Abaddon visé subit 100 points de dégâts sacrés et est interrompu. Cette compétence touche un ennemi supplémentaire dans la zone pour chaque rang de Porteur de Lumière que vous atteignez. Cette compétence est désactivée pendant les 15 secondes suivant son utilisation.','Le serviteur démoniaque d\'Abaddon visé subit 100 points de dégâts sacrés et est interrompu. L\'attaque affecte un ennemi supplémentaire dans la zone pour chaque rang de Porteur de lumière que vous atteignez. Cette compétence est désactivée (15 secondes).'],
1815=>['Sceau du Porteur de lumière','Si vous vous trouvez dans la zone d\'un serviteur démoniaque d\'Abaddon, vous gagnez 3...5 décharges d\'adrénaline et 16...24 points d\'énergie.','Vous gagnez 3...5 décharges d\'adrénaline et 16...24 points d\'énergie si vous vous trouvez dans la zone d\'un serviteur démoniaque d\'Abaddon.'],
1816=>['Sceau de Renaissance du Lancier du Soleil','Ressuscite le coéquipier mort visé à votre position avec la totalité de ses points de vie et 10% d\'énergie pour chaque grade de Lancier du Soleil que vous avez atteint. Ce Sceau ne peut être utilisé qu\'une fois par mission à moins qu\'il ne soit rechargé par une augmentation de moral.','Ressuscite l\'allié mort visé à votre position (santé maximum et 10% d\'énergie pour chaque rang de Lancier du Soleil que vous avez atteint). Ce sceau ne se recharge que lorsque vous obtenez une augmentation de moral.'],
1948=>['Sanctuaire de l\'ombre','Vous êtes aveuglé pendant 5 secondes. Vous bénéficiez d\'une régénération de santé de +7...10 et d\'un bonus d\'armure de +40 pendant 10 secondes.','(10 secondes.) Vous bénéficiez d\'une régénération de santé de +7...10 et d\'un bonus d\'armure de +40. Vous êtes aveuglé (5 secondes).'],
1949=>['Cauchemar éthéré','L\'ennemi visé perd 5...8 points d\'énergie. Pour chaque point d\'énergie perdu de cette manière, la cible et tous les ennemis dans la zone subissent une dégénération de santé de -1 pendant 10 secondes.','Provoque une perte de 5...8 points d\'énergie. La cible et les ennemis dans la zone subissent une dégénération de santé de -1 pour chaque point d\'énergie perdu (10 secondes).'],
1950=>['Sceau de corruption','La cible ennemie et tous les ennemis à proximité subissent 20...30 points de dégâts. Pour chaque ennemi affecté souffrant d\'une condition ou d\'un maléfice, vous gagnez 2 points d\'énergie (12...20 points d\'énergie maximum).','Inflige 20...30 points de dégâts à la cible et aux ennemis à proximité. Vous gagnez 2 points d\'énergie (maximum : 12...20) pour chacun de ces ennemis souffrant d\'une condition ou d\'un maléfice.'],
1951=>['Seigneur élémentaire','Pendant 40...60 secondes, toutes vos caractéristiques élémentaires augmentent de 1. Chaque fois que vous lancez un sort, vous gagnez 1 point d\'énergie tous les 10 rangs de Conservation d\'énergie et êtes soigné de 100...300% du coût en énergie pour ce sort.','(40...60 secondes.) Toutes vos caractéristiques élémentaires augmentent de 1. Chaque fois que vous lancez un sort, vous gagnez 1 point d\'énergie tous les 10 rangs de Conservation d\'énergie et êtes soigné de 100...300% du coût en énergie pour ce sort.'],
1952=>['Esprit altruiste','Pendant 15...20 secondes, les sorts lancés sur un allié coûtent 3 points d\'énergie en moins.','(15...20 secondes.) Les sorts lancés sur un allié coûtent 3 points d\'énergie en moins.'],
1953=>['Triple tir','Vous tirez simultanément 3 flèches sur l\'ennemi visé. Ces flèches infligent 40...25% de dégâts en moins.','Vous tirez simultanément 3 flèches sur l\'ennemi visé. Ces flèches infligent 40...25% de dégâts en moins.'],
1954=>['"Sauvez votre peau !"','Pendant 4...6 secondes, tous les autres membres du groupe bénéficient d\'un bonus d\'armure de +100.','(4...6 secondes.) Tous les autres membres du groupe gagnent un bonus d\'armure de +100.'],
1955=>['Aura de la puissance sacrée','Pendant 45 secondes, vous infligez 20...25 points de dégâts sacrés à tous les ennemis adjacents lorsque vous perdez un enchantement de Derviche.','(45 secondes.) Chaque fois que vous perdez un enchantement de Derviche, les ennemis adjacents subissent 20...25 points de dégâts sacrés.'],
1957=>['Javelot de furie','Cette attaque inflige +30...40 points de dégâts. Si cette attaque touche un ennemi souffrant d\'une condition, vous bénéficiez de 3...6 décharges d\'adrénaline.','Inflige +30...40 points de dégâts. Vous gagnez 3...6 décharges d\'adrénaline si vous frappez un ennemi affecté par une condition.'],
1986=>['Assaut vampirique','Doit succéder à une attaque main gauche. Si cette attaque réussit, vous volez 10...40 points de vie.','Vole 10...40 points de vie si cette attaque réussit. Doit succéder à une attaque main gauche.'],
1987=>['Coup du lotus','Doit succéder à une attaque main droite. Si elle réussit, cette attaque inflige +10...25 points de dégâts et vous bénéficiez de 5...20 points d\'énergie.','Inflige +10...25 points de dégâts. Vous gagnez 5...20 points d\'énergie. Doit succéder à une attaque main droite.'],
1988=>['Attaque des crocs dorés','Doit succéder à une attaque main droite. Si vous êtes sous les effets d\'un enchantement et si cette attaque réussit, la cible ennemie souffre de Blessure profonde pendant 5...20 secondes.','Inflige la Blessure profonde (5...20 secondes) si vous êtes enchanté. Doit succéder à une attaque main droite.'],
1990=>['Coup du lotus tombant','Doit toucher un ennemi assommé. Si l\'attaque réussit, vous infligez +15...35 points de dégâts et bénéficiez de 1...12 points d\'énergie.','Inflige +15...35 points de dégâts. Vous gagnez 1...12 points d\'énergie. Aucun effet si la cible ennemie n\'est pas assommée.'],
1991=>['Sceau sadique','Vous bénéficiez de 10...45 points de vie pour chaque condition dont souffre la cible ennemie.','Vous bénéficiez de 10...45 points de vie pour chaque condition dont souffre la cible ennemie.'],
1992=>['Sceau de distraction','Si l\'ennemi visé est en train de lancer un sort, celui-ci est interrompu et désactivé pendant 1...5 secondes pour chaque sceau dont vous êtes équipé.','Interrompt un sort. Effet de l\'interruption : le sort de l\'ennemi visé est désactivé 1...5 secondes par sceau dont vous êtes équipé.'],
1993=>['Sceau de Rappel','Pendant 6 secondes, vous subissez une dégénération d\'énergie de -4. Lorsque cet effet prend fin, vous recevez 13...20 points d\'énergie.','(6 secondes.) Vous bénéficiez d\'une régénération d\'énergie de -4. Effet final : vous gagnez 13...20 points d\'énergie.'],
1994=>['Verrouillage de pouvoir','Si l\'ennemi visé est en train de lancer un sort ou un chant, celui-ci est interrompu et désactivé pendant 5...13 secondes supplémentaires.','Interrompt un sort ou un chant. Effet de l\'interruption : le sort ou le chant interrompu est indisponible pendant +5...13 secondes.'],
1995=>['Pas de petites économies','Si la cible ennemie ne lance pas de sort ou n\'attaque pas, vous gagnez 8...13 points d\'énergie.','Vous gagnez 8...13 points d\'énergie si l\'ennemi visé n\'attaque pas et ne lance pas de sort.'],
1996=>['La somme de toutes les peurs','Pendant 4...12 secondes, la cible ennemie se déplace, attaque et lance des sorts 33% moins vite.','(4...12 secondes.) L\'ennemi visé se déplace, attaque et lance des sorts 33% moins vite.'],
1997=>['Aura de Flétrissure','Pendant 5...20 secondes, les attaques au corps à corps de la cible (allié ou vous-même) provoquent la Faiblesse pendant 5...20 secondes.','(5...20 secondes.) Les attaques au corps à corps de l\'allié visé infligent la Faiblesse (5...20 secondes.)'],
1998=>['Cacophonie','Pendant 15 secondes, à chaque fois que l\'ennemi ciblé utilise un cri ou un chant, il subit 30...105 points de dégâts.','(15 secondes.) Inflige 30...105 points de dégâts chaque fois que l\'ennemi visé utilise un cri ou un chant.'],
1999=>['Etreinte de l\'hiver','Pendant 2...6 secondes, l\'ennemi visé se déplace 66% moins vite et subit 5...15 points de dégâts en se déplaçant.','(2...6 secondes.) L\'ennemi visé se déplace 66% moins vite et subit 5...15 points de dégâts en se déplaçant.'],
2000=>['Chaînes de terre','Pendant 3 secondes, la cible et tous les ennemis à proximité se déplacent 90% moins vite. Lorsqu\'elles prennent fin, les Chaînes de terre infligent Faiblesse pendant 5...20 secondes.','(3 secondes.) La cible et les ennemis à proximité se déplacent 90% moins vite. Inflige Faiblesse pendant 5...20 secondes en prenant fin.'],
2001=>['Protection de faiblesse','Vous créez une Protection de faiblesse sur votre position. Pendant 5...20 secondes, les ennemis dans cette zone souffrent de Faiblesse pendant 5...20 secondes à chaque fois qu\'ils subissent des dégâts élémentaires.','(5...20 secondes.) Inflige la Faiblesse (5...20 secondes) à tous les ennemis subissant des dégâts élémentaires dans cette Protection.'],
2002=>['Glyphe de rapidité','Pendant 15 secondes, 1...5 prochains sorts lancés se rechargent 25% plus vite et les projectiles propulsés se déplacent 200% plus vite.','(15 secondes.) 1...5 de vos sorts suivants se rechargent 25% plus vite et les projectiles correspondants se déplacent 200% plus vite.'],
2003=>['Guérison de maléfice','Lève un maléfice de la cible (allié ou vous-même). Si un maléfice est levé de cette manière, cette cible est soignée de 30...100 points de vie.','Supprime un maléfice. Effet de la suppression : soigne de 30...100 points de vie.'],
2004=>['Expiation des conditions','Ote une condition de la cible (allié ou vous-même). Si une condition est ôtée de cette manière, les ennemis dans la zone subissent 10...60 points de dégâts sacrés.','Supprime une condition. Effet de la suppression : inflige 10...60 points de dégâts sacrés aux ennemis dans la zone de l\'allié visé.'],
2005=>['Compagnon du châtiment','Pendant 30 secondes, vos Prières du châtiment reçoivent un double bonus de Faveur divine.','(30 secondes.) Vos Prières du châtiment reçoivent un double bonus de soins de Faveur divine.'],
2006=>['Sceau de pénitence','La cible ennemie subit 26...56 points de dégâts sacrés. Si elle attaquait, vous bénéficiez de 4...14 points d\'énergie.','Inflige 26...56 points de dégâts sacrés. Vous gagnez 4...14 points d\'énergie si l\'ennemi visé attaque.'],
2007=>['Voile purifiant','Pendant que vous maintenez cet enchantement, les conditions expirent 5...50% plus vite sur la cible (allié ou vous-même). Lorsque cet enchantement prend fin, une condition de cette cible est supprimée.','Les conditions affectant l\'allié visé prennent fin 5...50% plus vite. Effet final : supprime une condition.'],
2008=>['Collision pulvérisante','Si vous touchez un ennemi assommé, celui-ci souffre de Faiblesse et de Blessure profonde pendant 5...20 secondes.','Inflige la Faiblesse et la Blessure profonde (5...20 secondes) si l\'ennemi visé est assommé.'],
2009=>['Coup enthousiaste','Cette attaque inflige toujours un coup critique si elle réussit.','Inflige toujours un coup critique.'],
2010=>['Coupe-genou','Si l\'attaque touche un ennemi frappé d\'Infirmité, vous gagnez 2...7 points d\'énergie et 1...3 décharges d\'adrénaline.','Vous gagnez 2...7 points d\'énergie et 1...3 décharges d\'adrénaline si l\'ennemi visé est frappé d\'Infirmité.'],
2011=>['Grappin','Vous et la cible ennemie touchée êtes assommés. Vous perdez votre pose actuelle.','Provoque l\'assommement. Vous êtes aussi assommé. Votre pose actuelle prend fin.'],
2012=>['Faux rayonnante','Cette attaque inflige +1 points de dégâts pour chaque point d\'énergie que vous possédez (5...30 points de dégâts maximum). Vous gagnez 1...7 points d\'énergie si cette attaque réussit.','Inflige +1 point de dégâts (maximum : 5...30) par point d\'énergie dont vous disposez. Gain de 1...7 points d\'énergie.'],
2013=>['Aura de Grenth','Pendant 20 secondes, vous infligez 5...25 points de dégâts en moins et absorbez 5...25 points de vie chaque fois que vous attaquez avec votre faux. Lorsque vous lancez cet enchantement, vous absorbez 5...25 points de vie des ennemis adjacents.','(20 secondes.) Vous infligez 5...25 points de dégâts en moins et absorbez 5...25 points de vie lorsque vous attaquez avec votre faux. Effet initial : absorbe 5...25 points de vie des ennemis adjacents.'],
2014=>['Sceau de contrainte pieuse','Supprime un enchantement de Derviche. L\'ennemi visé est frappé d\'Infirmité pendant 5...15 secondes. Si un enchantement a été supprimé, tous les ennemis à proximité de votre cible souffrent eux aussi d\'Infirmité et ce sceau se recharge 75% plus vite.','Inflige l\'altération Infirmité (5...15 secondes). Supprime un de vos enchantements de Derviche. Effet de la suppression : inflige également Infirmité aux ennemis à proximité de votre cible et se recharge 75% plus vite.'],
2015=>['Faux du fermier','Si cette attaque réussit, vous infligez +5...20 points de dégâts. Si vous frappez plus d\'un ennemi, cette attaque se recharge instantanément.','Inflige +5...20 points de dégâts. Rechargement instantané si vous frappez plus d\'un ennemi.'],
2016=>['Lee Sa était énergique','Vous tenez les cendres de Lee Sa pendant 5...15 secondes. Pendant ce temps, vous bénéficiez d\'une régénération d\'énergie de +2. Lorsque vous déposez ses cendres, vous gagnez +1...10 points d\'énergie.','(5...15 secondes.) Vous bénéficiez d\'une régénération d\'énergie de +2. Effet de la pose : vous gagnez +1...10 points d\'énergie.'],
2017=>['Hymne de lassitude','Pendant 8 secondes, la prochaine compétence d\'attaque utilisée par chaque allié à portée de voix cause aussi la Faiblesse pendant 1...16 secondes.','(8 secondes.) La compétence d\'attaque suivante des alliés à portée de voix inflige la Faiblesse (1...16 secondes).'],
2018=>['Hymne d\'interruption','Pendant 1...10 secondes, la prochaine compétence d\'attaque utilisée par chaque allié à portée de voix interrompt également une action.','(1...10 secondes.) La compétence d\'attaque suivante des alliés à portée de voix interrompt une action.'],
2051=>['Invocation des esprits','Tous les esprits que vous contrôlez font une foulée de l\'ombre vers votre position et gagnent 60...100 points de vie.','Les esprits que vous contrôlez font une Foulée de l\'ombre vers votre position et gagnent 60...100 points de vie.'],
2052=>['Crocs de l\'ombre','Vous faites une foulée de l\'ombre vers la cible ennemie. Pendant 10 secondes, ce maléfice n\'a aucun effet. Lorsqu\'il prend fin, vous retournez à votre position d\'origine et cet ennemi souffre de Blessure profonde pendant 5...20 secondes.','Vous faites une foulée de l\'ombre vers la cible ennemie. Effet final au bout de 10 secondes : inflige la Blessure profonde (5...20 secondes). Vous regagnez votre position de départ.'],
2053=>['Risque calculé','Pendant 3...24 secondes, les attaques de l\'ennemi visé infligent +10 points de dégâts, mais il y a 50% de chances que les dégâts de chaque attaque soient subis par cet ennemi et non sa cible (Points de dégâts : maximum 15...100).','(3...24 secondes.) Les attaques de l\'ennemi visé infligent +10 points de dégâts. Chaque attaque a 50% de chances d\'infliger des dégâts (maximum 15...100) à cet ennemi et non à sa cible.'],
2054=>['Rétraction d\'armure','Pendant 10 secondes, la cible ennemie souffre d\'une dégénération de santé de -1...4. Lorsque ce maléfice prend fin, cet ennemi a une Armure brisée pendant 5...20 secondes.','(10 secondes.) Provoque une dégénération de santé de -1...4. Effet final : inflige la condition Armure brisée (5...20 secondes).'],
2055=>['Anévrisme','La cible ennemie récupère toute son énergie. Pour chaque point d\'énergie acquis de cette manière, cet ennemi subit 1...3 points de dégâts et tous les ennemis adjacents perdent un point d\'énergie. (Energie perdue : maximum 1...30).','La cible ennemie récupère toute son énergie. Pour chaque point d\'énergie acquis, la cible subit 1...3 points de dégâts et tous les ennemis adjacents perdent un point d\'énergie (maximum 1...30).'],
2056=>['Oeil errant','Pendant 4 secondes, la prochaine fois que l\'ennemi visé attaque, son attaque est interrompue et tous les ennemis à proximité subissent 30...110 points de dégâts.','(4 secondes.) Interrompt l\'attaque suivante de l\'ennemi visé. Effet de l\'interruption : 30...110 points de dégâts aux ennemis à proximité.'],
2057=>['Festin immonde','Toutes les conditions de l\'allié vous sont transférées. Pour chaque condition acquise de cette manière, vous obtenez 0...45 points de vie et 2...4 points d\'énergie. Cette compétence se recharge deux fois plus vite si vous supprimez Maladie de votre cible.','Vous transfère toutes les conditions de l\'allié. Vous gagnez 0...45 points de vie et 2...4 points d\'énergie par condition transférée. Temps de recharge réduit de moitié si vous supprimez Maladie. Auto-ciblage impossible.'],
2058=>['Fiel putride','Pendant 5...25 secondes, la cible ennemie souffre d\'une dégénération de santé de -1...3. Si elle meurt sous l\'effet de ce maléfice, tous les ennemis à proximité subissent 25...85 points de dégâts.','(5...25 secondes.) Provoque une dégénération de santé de -1...3. Inflige 25...85 points de dégâts à tous les ennemis à proximité si l\'ennemi visé meurt.'],
2059=>['Traumatisme','La cible ennemie subit 10...30 points de dégâts de la foudre et a une Armure brisée pendant 5...20 secondes. Ce sort a 25% de pénétration d\'armure. Si vous êtes en état d\'Afflux, ce sort frappe les ennemis adjacents.','Inflige 10...30 points de dégâts de la foudre. Inflige la condition Armure brisée (5...20 secondes). 25% de pénétration d\'armure. En état d\'Afflux, affecte les ennemis adjacents.'],
2060=>['Glyphe d\'immolation','Pendant 15 secondes, 1...4 prochains sorts qui visent un ennemi provoquent la Brûlure pendant 1...4 secondes.','(15 secondes.) 1...4 de vos prochains sorts visant un ennemi provoquent la Brûlure (1...4 secondes).'],
2061=>['Esprit patient','Pendant 2 secondes, la cible (allié ou vous-même) est sous les effets d\'Esprit patient. A moins que cet enchantement ne s\'achève prématurément, cet allié est soigné de 30...120 points de vie lorsque l\'enchantement prend fin.','(2 secondes.) Effet final : soigne de 30...120 points de vie. Aucun effet si interrompu prématurément.'],
2062=>['Ruban de guérison','La cible alliée est soignée de 20...110 points de vie. 2 autres alliés maximum à proximité de la cible sont soignés de 10...100 points de vie.','Soigne de 20...110 points de vie. Soigne deux autres alliés près de la cible de 10...100 points de vie. Vous ne pouvez pas vous prendre pour cible.'],
2063=>['Ame inébranlable','Pendant 3...8 secondes, la cible alliée ne peut pas être assommée.','(3...8 secondes.) L\'allié visé ne peut pas être assommé. Vous ne pouvez pas vous prendre pour cible.'],
2064=>['Esprit impeccable','Pendant 1...15 secondes, l\'allié visé perd un maléfice toutes les 5 secondes.','(1...15 secondes.) Supprime un maléfice toutes les 5 secondes. Vous ne pouvez pas vous prendre pour cible.'],
2065=>['Ame impeccable','Pendant 1...15 secondes, l\'allié visé perd une condition toutes les 3 secondes.','(1...15 secondes.) Supprime une condition toutes les 3 secondes. Vous ne pouvez pas vous prendre pour cible.'],
2066=>['Désarmement','Interrompt l\'action de l\'ennemi visé. S\'il s\'agissait d\'une attaque, celle-ci et toutes les autres sont désactivées pendant 0...3 secondes.','Interrompt l\'ennemi visé. Effet de l\'interruption : désactive les compétences d\'attaque de l\'ennemi (0...3 secondes) s\'il attaquait.'],
2067=>['"C\'est ce que je comptais faire !"','Si vous êtes assommé, vous gagnez 1...6 décharges d\'adrénaline.','Vous gagnez 1...6 décharges d\'adrénaline si vous êtes assommé.'],
2068=>['Feu rapide','Pendant 5...25 secondes, vous attaquez 33% plus vite pendant que vous tenez un arc.','(5...25 secondes.) Vous attaquez 33% plus vite pendant que vous tenez un arc.'],
2069=>['Tir du chasseur paresseux','Si cette attaque réussit, la cible ennemie subit +10...25 points de dégâts. Si elle n\'utilisait pas de compétence, Tir du chasseur paresseux inflige +10...35 points de dégâts supplémentaires.','Inflige +10...25 points de dégâts. Inflige +10...35 points de dégâts supplémentaires si l\'ennemi visé n\'utilise pas de compétence.'],
2070=>['Trancheur d\'aura','Si cette attaque réussit, vous infligez un Saignement pendant 5...15 secondes. Si vous êtes sous l\'effet d\'un enchantement, vous infligez en outre Armure brisée pendant 1...10 secondes.','(5...15 secondes.) Provoque le Saignement. Inflige également Armure brisée (1...10 secondes) si vous êtes sous l\'emprise d\'un enchantement.'],
2071=>['Frappe zélée','Si cette attaque réussit, vous infligez +5...20 points de dégâts. Vous gagnez 3 points d\'énergie et 1 décharge d\'adrénaline à chaque adversaire touché.','Inflige +5...20 points de dégâts. Vous gagnez 3 points d\'énergie et 1 décharge d\'adrénaline à chaque adversaire touché.'],
2072=>['Li Ming était pure','Vous tenez les cendres de Li Ming pendant 5...20 secondes. Pendant ce temps, les conditions qui vous affectent prennent fin 10...50% plus vite. Lorsque vous déposez ses cendres, tous les alliés à portée de voix perdent 1...4 conditions.','(5...20 secondes.) Les conditions qui vous affectent prennent fin 10...50% plus vite. Effet de la pose : supprime 1...4 conditions affectant les alliés à portée de voix.'],
2073=>['Arme d\'agression','Pendant 5...15 secondes, vous attaquez 25% plus vite.','(5...15 secondes.) Vous attaquez 25% plus vite.'],
2074=>['Cogne-poitrine','Si cette attaque touche un ennemi ayant une Armure brisée, celui-ci souffre de Blessure profonde pendant 5...20 secondes.','Inflige la Blessure profonde (5...20 secondes) si l\'ennemi visé a une Armure brisée.'],
2075=>['Refrain rapide','Pendant 8...20 secondes, la cible (allié ou vous-même) se déplace 25% plus vite. Cet écho est répété chaque fois qu\'un chant ou un cri sur cet allié prend fin.','(8...20 secondes.) L\'allié visé se déplace 25% plus vite. Renouvellement : chaque fois qu\'un chant ou un cri affectant cet allié prend fin.'],
2091=>['Sanctuaire de l\'ombre','Vous êtes aveuglé pendant 5 secondes. Vous bénéficiez d\'une régénération de santé de +7...10 et d\'un bonus d\'armure de +40 pendant 10 secondes.','(10 secondes.) Vous bénéficiez d\'une régénération de santé de +7...10 et d\'un bonus d\'armure de +40. Vous êtes aveuglé (5 secondes).'],
2092=>['Cauchemar éthéré','L\'ennemi visé perd 5...8 points d\'énergie. Pour chaque point d\'énergie perdu de cette manière, la cible et tous les ennemis dans la zone subissent une dégénération de santé de -1 pendant 10 secondes.','Provoque une perte de 5...8 points d\'énergie. La cible et les ennemis dans la zone subissent une dégénération de santé de -1 pour chaque point d\'énergie perdu (10 secondes).'],
2093=>['Sceau de corruption','La cible ennemie et tous les ennemis à proximité subissent 20...30 points de dégâts. Pour chaque ennemi affecté souffrant d\'une condition ou d\'un maléfice, vous gagnez 2 points d\'énergie (12...20 points d\'énergie maximum).','Inflige 20...30 points de dégâts à la cible et aux ennemis à proximité. Vous gagnez 2 points d\'énergie (maximum : 12...20) pour chacun de ces ennemis souffrant d\'une condition ou d\'un maléfice.'],
2094=>['Seigneur élémentaire','Pendant 40...60 secondes, toutes vos caractéristiques élémentaires augmentent de 1. Chaque fois que vous lancez un sort, vous gagnez 1 point d\'énergie tous les 10 rangs de Conservation d\'énergie et êtes soigné de 100...300% du coût en énergie pour ce sort.','(40...60 secondes.) Toutes vos caractéristiques élémentaires augmentent de 1. Chaque fois que vous lancez un sort, vous gagnez 1 point d\'énergie tous les 10 rangs de Conservation d\'énergie et êtes soigné de 100...300% du coût en énergie pour ce sort.'],
2095=>['Esprit altruiste','Pendant 15...20 secondes, les sorts lancés sur un allié coûtent 3 points d\'énergie en moins.','(15...20 secondes.) Les sorts lancés sur un allié coûtent 3 points d\'énergie en moins.'],
2096=>['Triple tir','Vous tirez simultanément 3 flèches sur l\'ennemi visé. Ces flèches infligent 40...25% de dégâts en moins.','Vous tirez simultanément 3 flèches sur l\'ennemi visé. Ces flèches infligent 40...25% de dégâts en moins.'],
2097=>['"Sauvez votre peau !"','Pendant 4...6 secondes, tous les autres membres du groupe bénéficient d\'un bonus d\'armure de +100.','(4...6 secondes.) Tous les autres membres du groupe gagnent un bonus d\'armure de +100.'],
2098=>['Aura de la puissance sacrée','Pendant 45 secondes, vous infligez 20...25 points de dégâts sacrés à tous les ennemis adjacents lorsque vous perdez un enchantement de Derviche.','(45 secondes.) Chaque fois que vous perdez un enchantement de Derviche, les ennemis adjacents subissent 20...25 points de dégâts sacrés.'],
2099=>['Javelot de furie','Cette attaque inflige +30...40 points de dégâts. Si cette attaque touche un ennemi souffrant d\'une condition, vous bénéficiez de 3...6 décharges d\'adrénaline.','Inflige +30...40 points de dégâts. Vous gagnez 3...6 décharges d\'adrénaline si vous frappez un ennemi affecté par une condition.'],
2100=>['Invocation des esprits','Tous les esprits que vous contrôlez font une foulée de l\'ombre vers votre position et gagnent 60...100 points de vie.','Les esprits que vous contrôlez font une foulée de l\'ombre vers votre position et gagnent 60...100 points de vie.'],
2101=>['Agilité critique','Pendant 4 secondes et 1 seconde supplémentaire pour chaque rang d\'Attaque critique, vous attaquez 33% plus vite et bénéficiez d\'un bonus d\'armure de +15...25. Cette compétence se relance à chaque fois que vous infligez un coup critique.','( 4 secondes, plus 1 seconde supplémentaire pour chaque rang d\'Attaque critique). Vous attaquez 33% plus vite et bénéficiez d\'un bonus d\'armure de +15...25. Renouvellement : chaque fois que vous infligez un coup critique.'],
2102=>['Cri de douleur','Interrompt la compétence de l\'ennemi visé. Si celui-ci souffrait d\'un maléfice d\'Envoûteur, lui et tous les ennemis proches encaissent 25...50 points de dégâts et subissent une dégénération de santé de -3...5 pendant 10 secondes.','Interrompt une compétence. Si l\'ennemi visé souffrait d\'un maléfice d\'Envoûteur, la cible et les ennemis dans la zone encaissent 25...50 points de dégâts et subissent une dégénération de santé de -3...5 (10 secondes).'],
2103=>['Nécrose','Si l\'ennemi visé souffre d\'une condition ou d\'un maléfice, il subit 60...90 points de dégâts.','Inflige 60...90 points de dégâts si l\'ennemi visé est affecté par une condition ou un maléfice.'],
2104=>['Intensité','Pendant 10 secondes, la prochaine fois que vous infligez des dégâts élémentaires via un sort, tous les autres ennemis dans la zone de la cible subissent 60...70% de ces dégâts.','(10 secondes.) La prochaine fois que vous infligez des dégâts élémentaires via un sort, tous les autres ennemis dans la zone de la cible subissent 60...70% de ces dégâts.'],
2105=>['Graine de vie','Pendant 2...5 secondes, à chaque fois que l\'allié visé subit des dégâts, tous les membres du groupe sont soignés de 2 points de vie pour chaque rang de Faveur divine.','(2...5 secondes.) Soigne les membres du groupe de 2 points de vie pour chaque rang de Faveur divine à chaque fois que l\'allié visé subit des dégâts. Vous ne pouvez pas vous prendre pour cible.'],
2107=>['Attaque tourbillon','Attaque la cible et tous les ennemis adjacents. Chaque attaque réussie inflige +13...20 points de dégâts.','Attaque la cible et les ennemis adjacents et inflige +13...20 points de dégâts.'],
2108=>['Saccage collectif','Pendant 18...25 secondes, votre familier et vous attaquez 25% plus vite et bénéficiez d\'une régénération de santé de +1...3.','(18...25 secondes.) Votre familier et vous attaquez 25% plus vite et bénéficiez d\'une régénération de santé de +1...3.'],
2109=>['Aura éternelle','Vous bénéficiez de +100 points de vie maximum. Lorsque cet enchantement prend fin, tous les membres du groupe dans la zone sont ressuscités avec 40...50% de leur santé et 20...30% de leur énergie.','Vous bénéficiez de +100 points de vie maximum. Effet final : tous les membres du groupe dans la zone sont ressuscités avec 40...50% de leur santé et 20...30% de leur énergie.'],
2110=>['Vampirisme','Crée un esprit de niveau 4...14 qui disparaît au bout de 75...150 secondes. Les attaques de cet esprit volent jusqu\'à 10...20 points de vie et vous êtes soigné de 10...20 points de vie.','Crée un esprit de niveau 4...14 (durée de vie de 75...150 secondes). Ses attaques volent 10...20 points de vie et vous soignent de 10...20 points de vie.'],
2112=>['"Il n\'y a rien à craindre !"','Pendant 4 secondes plus 1 seconde supplémentaire tous les 2 points de Charisme, tous les membres du groupe à portée de voix subissent 20...35% de dégâts en moins. Les membres du groupe affectés sont soignés de 35...60 points de vie lorsque ce cri prend fin.','(4 secondes, plus 1 seconde tous les 2 rangs de Charisme.) Réduit les dégâts de 20...35% pour les membres du groupe à portée de voix. Effet final : soigne de 35...60 points de vie.'],
2116=>['Attaque sournoise','Si cette attaque réussit, la cible ennemie souffre d\'Aveuglement pendant 5...8 secondes. Cette attaque compte comme une attaque main droite.','Inflige l\'Aveuglement (5...8 secondes). Compte comme une attaque main droite.'],
2135=>['Piétinement du boeuf','Doit succéder à une attaque main gauche. Si l\'attaque réussit, Vous infligez +5...20 points de dégâts. Si vous touchez un ennemi frappé d\'Infirmité, il est assommé.','Inflige +5...20 points de dégâts. Attaque assommante si l\'ennemi visé souffre d\'Infirmité. Doit succéder à une attaque main gauche.'],
2136=>['Défense poudre fumigène','Pendant 8 secondes, la prochaine fois que vous êtes frappé, vous subissez la moitié des dégâts et tous les ennemis adjacents souffrent d\'Aveuglement pendant 2...6 secondes.','(8 secondes.) La prochaine fois que vous êtes frappé, vous subissez la moitié des dégâts et infligez l\'Aveuglement (2...6 secondes) aux ennemis adjacents.'],
2137=>['Images déroutantes','Pendant 2...10 secondes, les ennemis visés mettent deux fois plus longtemps à activer leurs compétences autres que les attaques.','(2...10 secondes.) L\'ennemi visé met deux fois plus longtemps à activer ses compétences autres que les attaques.'],
2138=>['Vigueur du lanceur de maléfices','Pendant 10 secondes, vous bénéficiez d\'une régénération de santé de +1...8. Vigueur du lanceur de maléfices prend fin si vous utilisez une compétence autre qu\'un maléfice.','(10 secondes.) Vous bénéficiez d\'une régénération de santé de +1...8. Prend fin si vous utilisez une compétence autre qu\'un maléfice.'],
2139=>['Masochisme','Pendant 10...40 secondes, vos attributs Magie de mort et Moisson des âmes augmentent de 2 points et vous sacrifiez 5...3% de votre santé maximale lorsque vous lancez un sort.','(10...40 secondes.) Vous gagnez +2 en Magie de mort et Moisson des âmes. Vous sacrifiez 5...3% de votre santé maximale lorsque vous lancez un sort.'],
2140=>['Piège perforant','Quand ce piège se déclenche, tous les ennemis à proximité subissent 5...50 points de dégâts perforants. Les ennemis ayant une Armure brisée subissent 15...60 points de dégâts supplémentaires. Ce piège fonctionne pendant 90 secondes. Vous pouvez être facilement interrompu lorsque vous activez cette compétence.','(90 secondes.) Affecte les ennemis à proximité. Inflige 5...50 points de dégâts perforants. Inflige 15...60 points de dégâts supplémentaires à tous les ennemis qui ont une Armure brisée. Cette compétence peut être facilement interrompue.'],
2141=>['Camaraderie','Si vous avez moins de santé que votre familier, vous êtes soigné de 30...120 points de vie. Si votre familier a moins de santé que vous, il est soigné de 30...120 points de vie.','Vous soigne de 30...120 points de vie si vous avez moins de santé que votre familier. Soigne votre familier de 30...120 points de vie s\'il a moins de santé que vous.'],
2142=>['Agression barbare','Pendant 5...20 secondes, votre familier attaque 33% plus vite et inflige 3...10 points de dégâts supplémentaires.','(5...20 secondes.) Votre familier attaque 33% plus vite et inflige +3...10 points de dégâts.'],
2143=>['Tir d\'interruption','Si cette attaque réussit, l\'action de la cible ennemie est interrompue. S\'il s\'agissait d\'une compétence, vous infligez +10...40 points de dégâts.','Interrompt une action. Effet de l\'interruption : +10...40 points de dégâts si vous interrompez une compétence.'],
2144=>['Volée','Toutes vos préparations sont annulées. Vous décochez des flèches sur la cible ennemie et un maximum de 3 ennemis adjacents à votre cible. Ces flèches infligent +1...10 points de dégâts si elles touchent l\'ennemi.','Inflige +1...10 points de dégâts. Frappe un maximum de 3 ennemis adjacents à votre cible. Toutes vos préparations sont annulées.'],
2145=>['Concentration experte','Pendant 24 secondes, vos compétences d\'attaques à l\'arc coûtent 1...2 points d\'énergie en moins et infligent 1...10 points de dégâts supplémentaires.','(24 secondes.) Vos compétences d\'attaques à l\'arc coûtent 1...2 points d\'énergie en moins et infligent +1...10 points de dégâts.'],
2146=>['Fureur pieuse','Supprime un enchantement de Derviche. Pendant 1...7 secondes, vous attaquez 25% plus vite. Si un enchantement a été supprimé, cette pose de combat dure deux fois plus longtemps.','(1...7 secondes.) Vous attaquez 25% plus vite et levez un de vos enchantements de Derviche. Effet de la suppression : cette pose de combat dure deux fois plus longtemps.'],
2147=>['Victoire paralysante','Si votre attaque touche un ennemi, celui-ci est frappé d\'Infirmité pendant 3...8 secondes. Si vous avez plus de points de vie que l\'ennemi visé, tous les ennemis adjacents subissent 10...30 points de dégâts de la terre.','(3...8 secondes.) L\'ennemi visé est frappé d\'Infirmité. Si vous avez plus de points de vie que l\'ennemi visé, tous les ennemis adjacents subissent 10...30 points de dégâts de la terre.'],
2148=>['Arme de fractionnement','Pendant 4...10 secondes, les 3 prochaines attaques de la cible (allié ou vous-même) bénéficient d\'une pénétration d\'armure de 10% et provoquent une Armure brisée pendant 5...20 secondes.','(4...10 secondes.) Les 3 prochaines attaques de l\'allié visé infligent la condition Armure brisée (5...20 secondes) et offrent une pénétration d\'armure de 10%.'],
2149=>['Arme du renouveau','Pendant 5...20 secondes, la prochaine fois que la cible (allié ou vous-même) frappe avec une compétence d\'attaque, elle reçoit 1...7 points d\'énergie.','(5...20 secondes.) L\'allié visé gagne 1...7 points d\'énergie la prochaine fois qu\'il réussit une compétence d\'attaque.'],
2150=>['Javelot mutilant','Si votre attaque affecte un ennemi souffrant de Saignement, celui-ci est frappé d\'Infirmité pendant 5...20 secondes.','Inflige l\'Infirmité (5...20 secondes) si l\'ennemi visé souffre de Saignement.'],
2186=>['Sceau de corruption mortelle','La cible ennemie subit 5...35 points de dégâts pour chaque condition affectant cet ennemi (maximum : 130).','Inflige 5...35 points de dégâts (maximum : 130) pour chaque condition affectant l\'ennemi visé.'],
2187=>['Méthode du Maître','Pendant 60 secondes, lorsque vous êtes équipé d\'une arme autre que des dagues, vous avez 3...33% de chances supplémentaires d\'infliger un coup critique.','(60 secondes.) Vous avez +3...33% de chances d\'infliger un coup critique si votre arme n\'est pas une dague.'],
2188=>['Défenses profanées','Pendant 5...20 secondes, la prochaine fois que la cible ennemie bloque, elle subit 30...120 points de dégâts.','(5...20 secondes.) Inflige 30...120 points de dégâts lorsque l\'ennemi visé bloque la prochaine attaque.'],
2189=>['Regard d\'Angorodon','Vous volez 10...50 points de vie à la cible ennemie. Si vous souffrez d\'une condition, vous recevez 3...12 points d\'énergie.','Vole 10...50 points de vie. Vous gagnez 3...12 points d\'énergie si vous souffrez d\'une condition.'],
2190=>['Afflux magnétique','L\'ennemi visé subit 15...75 points de dégâts. Si vous êtes en état d\'Afflux, l\'Afflux magnétique enchante tous les alliés à portée de voix pendant 1...5 secondes, leur permettant de bloquer la prochaine attaque.','Inflige 15...75 points de dégâts. Si vous êtes en état d\'Afflux, les alliés à portée de voix sont sous l\'effet de l\'enchantement pendant 1...5 secondes et bloquent la prochaine attaque.'],
2191=>['Terrain glissant','Si l\'ennemi visé ou les ennemis adjacents souffrent d\'Aveuglement ou se déplacent, ils sont assommés. Il y a 50% de risques d\'échec avec une Magie de l\'eau inférieure à 5.',' Provoque l\'assommement si cet ennemi souffre d\'Aveuglement ou se déplace. Affecte les ennemis adjacents à votre cible. 50% de risques d\'échec avec une Magie de l\'eau 4 ou inférieure.'],
2192=>['Glace scintillante','La cible ennemie subit 5...50 points de dégâts du froid. Si elle est affectée par un maléfice de la Magie de l\'eau, vous recevez 5 points d\'énergie et 1 point d\'énergie supplémentaire tous les 2 rangs de Conservation d\'énergie.','Inflige 5...50 points de dégâts du froid. Vous gagnez 5 points d\'énergie et 1 point d\'énergie supplémentaire tous les 2 rangs de Conservation d\'énergie si la cible ennemie est affectée par un maléfice de la Magie de l\'eau.'],
2193=>['Explosion d\'énergie','La cible ennemie subit 1...2 points de dégâts pour chaque point d\'énergie que vous possédez (130 points de dégâts maximum).','Inflige 1...2 points de dégâts (maximum : 130) par point d\'énergie dont vous disposez.'],
2194=>['Frappe de diversion','Si la Frappe de diversion réussit, vous n\'infligez pas de dégâts mais vous interrompez l\'action de la cible ennemie. Si l\'ennemi a une Armure brisée, cette compétence est inutilisable pendant 30 secondes.','Interrompt une action. Effet de l\'interruption : désactive la compétence interrompue (30 secondes) si l\'ennemi visé a une Armure brisée. N\'inflige pas de dégâts.'],
2195=>['Attaque symbolique','Si cette attaque réussit, vous infligez +12 points de dégâts pour chaque sceau dont vous êtes équipé (maximum 70 points de dégâts ).','Inflige +12 points de dégâts (maximum : 70) par sceau dont vous êtes équipé.'],
2196=>['Vitesse du soldat','Pendant 3...18 secondes, vous vous déplacez 15% plus vite. Votre vitesse de déplacement est encore augmentée de 15% lorsque vous êtes sous l\'effet d\'un cri ou d\'un chant.','(3...18 secondes.) Vous vous déplacez 15% plus vite, et encore 15% plus vite si vous êtes affecté par un chant ou un cri.'],
2197=>['Frappe corporelle','Si cette attaque réussit, l\'ennemi visé subit +10...40 points de dégâts. S\'il a une Armure brisée, il souffre de Blessure profonde pendant 0...15 secondes.','Inflige +10...40 points de dégâts. Inflige la Blessure profonde (0...15 secondes) si la cible ennemie a une Armure brisée.'],
2198=>['Tir corporel','Si cette attaque réussit, vous infligez +5...20 points de dégâts. Si vous frappez un ennemi ayant une Armure brisée, vous bénéficiez de 5...10 points d\'énergie.','Inflige +5...20 points de dégâts. Vous gagnez 5...10 points d\'énergie si l\'ennemi visé a une Armure brisée.'],
2199=>['Sceau de Joute empoisonnée','Pendant 60 secondes, votre prochaine attaque provoque également l\'Empoisonnement pendant 8...15 secondes.','(60 secondes.) Votre attaque suivante inflige l\'Empoisonnement (8...15 secondes).'],
2200=>['Sceau de vitesse mystique','Pendant 30 secondes, vos 1...3 prochains enchantements autociblés sont lancés automatiquement. Les enchantements instantanés ne diminuent pas votre nombre d\'utilisations possibles de cette compétence.','(30 secondes.) Vos 1...3 prochains enchantements autociblés sont lancés instantanément. Les enchantements instantanés ne diminuent pas votre nombre d\'utilisations possibles de cette compétence.'],
2201=>['Bouclier de force','Pendant 1...16 secondes, bloque jusqu\'à 1 attaques à votre encontre. Si une attaque est bloquée, tous les ennemis adjacents qui attaquent sont assommés et souffrent de Faiblesse pendant 5...20 secondes.','(1...16 secondes.) Bloque les 1 prochaines attaques à votre encontre. Assomme et inflige la Faiblesse (5...20 secondes) aux ennemis adjacents qui attaquent.'],
2202=>['Etreinte réparatrice','La cible (allié ou vous-même) est soignée de 30...90 points de vie. Si la cible est sous les effets d\'un sort d\'altération d\'arme, elle perd une condition.','Soigne de 30...90 points de vie. Supprime une condition si l\'allié visé est sous l\'effet d\'un sort d\'altération d\'arme.'],
2203=>['Aura de sangsue de l\'esprit','Pendant 5...20 secondes, tous vos esprits à portée de voix infligent 5...20 points de dégâts en moins et volent 5...20 points de vie lorsqu\'ils attaquent.','(5...20 secondes.) Tous vos esprits à portée de voix infligent 5...20 points de dégâts en moins et volent 5...20 points de vie lorsqu\'ils attaquent.'],
2204=>['Rajeunissement','Vous créez un esprit de niveau 1...20. Celui-ci soigne tous les membres du groupe à portée de voix de 3...10 points de vie par seconde. Cet esprit perd 3...10 points de vie pour chaque membre du groupe soigné de cette manière. Il meurt au bout de 30...90 secondes.','Crée un esprit de niveau 1...20 (durée de vie de 30...90 secondes). Soigne les membres du groupe à portée de voix de 3...10 points de vie par seconde. Coût des soins : cet esprit perd 3...10 points de vie.'],
2205=>['Agonie','Vous créez un esprit de niveau 1...12. Celui-ci fait perdre 3...10 points de vie par seconde aux ennemis à portée de voix. Cet esprit perd 3...10 points de vie pour chaque ennemi blessé de cette manière. Il meurt au bout de 30...90 secondes.','Crée un esprit de niveau 1...12 (durée de vie de 30...90 secondes). Fait perdre 3...10 points de vie par seconde aux ennemis à portée de voix. Cet esprit perd 3...10 points de vie par ennemi perdant de la santé.'],
2206=>['Arme spectrale','Pendant 5...20 secondes, la prochaine attaque de la cible alliée ne peut pas être bloquée.','(5...20 secondes.) L\'attaque suivante de l\'allié visé est impossible à bloquer. Vous ne pouvez pas vous prendre pour cible.'],
2207=>['Discours stimulant','Vous perdez toute votre adrénaline et la cible alliée reçoit 1...8 décharges d\'adrénaline.','L\'allié visé gagne 1...8 décharges d\'adrénaline. Vous ne pouvez pas vous prendre pour cible. Vous perdez toute votre adrénaline.'],
2208=>['Bouclier incandescent','Pendant 3...9 secondes, si vous utilisez un bouclier, la prochaine compétence d\'attaque utilisée contre vous est bloquée. S\'il s\'agissait d\'une attaque au corps à corps, votre attaquant s\'embrase pendant 1...6 secondes.','(3...9 secondes.) Bloque la compétence d\'attaque suivante vous visant. Inflige la Brûlure (1...6 secondes) s\'il s\'agit d\'une attaque au corps à corps. Aucun effet si vous n\'utilisez pas de bouclier.'],
2209=>['Javelot sacré','Si cette attaque réussit, vous infligez +5...20 points de dégâts. Si elle frappe une créature invoquée, tous les ennemis à proximité subissent 15...90 points de dégâts sacrés et s\'embrasent pendant 3 secondes.','Inflige +5...20 points de dégâts. Inflige 15...90 points de dégâts sacrés et la Brûlure (3 secondes) aux ennemis à proximité si vous frappez une créature invoquée.'],
2210=>['Frappe du javelot','Si cette attaque réussit, vous infligez +5...20 points de dégâts et la cible ennemie est frappée de Stupeur pendant 4...10 secondes. Cette attaque a une portée rapprochée.','Inflige +5...20 points de dégâts et provoque la Stupeur (4...10 secondes). Cette attaque a une portée rapprochée.'],
2211=>['Acide alchimique d\'Alkar','Vous lancez l\'Acide alchimique d\'Alkar sur l\'ennemi visé. La cible et les ennemis adjacents subissent 40...50 points de dégâts. Les Destructeurs subissent 45...70 points de dégâts en plus et ont une Armure brisée pendant 14...20 secondes.','Projectile : inflige 40...50 points de dégâts à la cible et aux ennemis adjacents. Inflige 45...70 points de dégâts supplémentaires et la condition Armure brisée (14...20 secondes) aux Destructeurs.'],
2212=>['Lumière de Deldrimor','Tous les ennemis dans la zone subissent 55...80 points de dégâts sacrés. Tous les objets cachés à portée sont révélés sur votre boussole.','Inflige 55...80 points de dégâts sacrés aux ennemis dans la zone. Révèle les objets cachés de la zone sur la boussole.'],
2213=>['Morsure d\'oreille','La cible ennemie touchée subit 50...70 points de dégâts perforants et souffre de Saignement pendant 15...25 secondes.','Inflige 50...70 points de dégâts perforants et provoque le Saignement (15...25 secondes).'],
2214=>['Coup bas','Inflige 45...70 points de dégâts à l\'ennemi visé. Si l\'ennemi visé est assommé, il reçoit 30...50 points de dégâts supplémentaires et subit la condition Armure brisée pendant 14...20 secondes.','Inflige 45...70 points de dégâts. Inflige 30...50 points de dégâts supplémentaires et la condition Armure brisée (14...20 secondes) si l\'ennemi visé est assommé.'],
2215=>['Coup du bagarreur','Vous assénez un coup de tête à la cible ennemie touchée qui lui inflige 45...70 points de dégâts et l\'assomme si l\'attaque réussit.','Inflige 45...70 points de dégâts et assomme.'],
2216=>['"Ne trébuche pas !"','Pendant 3...5 secondes, les membres du groupe à portée de voix ne peuvent pas être assommés.','(3...5 secondes.) Empêche d\'être assommé. Affecte les membres du groupe à portée de voix.'],
2217=>['"Par le marteau d\'Ural !"','Pendant 30 secondes, tous les morts de votre groupe à portée de voix sont ressuscités avec l\'intégralité de leurs points de vie et d\'énergie. Les membres du groupe ressuscités infligent 25...33% plus de dégâts. Une fois cet effet dissipé, les membres du groupe affectés meurent. Cette compétence n\'engendre pas de handicap.','(30 secondes.) Ressuscite tous les morts du groupe à portée de voix avec l\'intégralité de leurs points de vie et d\'énergie. Les membres du groupe affectés infligent 25...33% plus de dégâts. Les membres du groupe affectés meurent une fois l\'effet dissipé, mais ne reçoivent pas de handicap.'],
2218=>['Maître ivre','Pendant 72...90 secondes, vos vitesses de mouvement et d\'attaque sont augmentées de 10...15%. Si vous êtes ivre lorsque vous activez cette compétence, vos vitesses de mouvement et d\'attaque sont augmentées de 25...33%.','(72...90 secondes.) Vous attaquez et vous déplacez 10...15% plus vite si vous n\'êtes pas ivre. Vous attaquez et vous déplacez 25...33% plus vite si vous êtes ivre.'],
2219=>['Arme du Grand Nain','Pendant 20 secondes, l\'arme de l\'allié visé inflige +15...20 points de dégâts et a 28...40% de chances d\'assommer.','(20 secondes.) +15...20 de dégâts d\'arme et 28...40% de chances d\'assommer avec les attaques. Vous ne pouvez pas vous prendre pour cible.'],
2220=>['Armure du Grand Nain','Pendant 22...40 secondes, la cible (allié ou vous-même) reçoit un bonus d\'armure de +24, +60 de santé maximum et un bonus d\'armure supplémentaire de +24 contre les Destructeurs.','(22...40 secondes.) Bonus d\'armure de +24 et +60 de santé maximum. Bonus d\'armure supplémentaire de +24 contre les Destructeurs.'],
2221=>['Souffle du Grand Nain','Tous les membres du groupe sont soulagés de la Brûlure et soignés de 50...60 points de vie.','Supprime la Brûlure et soigne de 50...60 points de vie. Affecte les membres du groupe.'],
2222=>['Tempête de neige','Vous créez une tempête de neige sur la position de l\'ennemi visé. Pendant 5 secondes, les ennemis adjacents à cette position subissent 30...40 points de dégâts du froid par seconde.','Inflige 30...40 points de dégâts du froid par seconde (5 secondes). Frappe les ennemis adjacents à la position initiale de l\'ennemi visé.'],
2223=>['Piège de poudre noire','Quand ce piège se déclenche, tous les ennemis à proximité subissent 20...30 points de dégâts, souffrent d\'Aveuglement et commencent à saigner pendant 7...10 secondes. Cette compétence fonctionne pendant 90 secondes. Vous pouvez être facilement interrompu lorsque vous l\'utilisez.','(90 secondes.) Affecte les ennemis à proximité. Inflige 20...30 points de dégâts. Inflige l\'Aveuglement et le Saignement (7...10 secondes). Cette compétence peut être facilement interrompue.'],
2224=>['Invocation du Mursaat','Vous invoquez un Mursaat de niveau 14...20 qui vit pendant 40...60 secondes et est équipé de Décharge incapacitante. Vous ne pouvez activer qu\'une seule invocation asura à la fois.','Vous invoquez un Mursaat de niveau 14...20 (durée de vie de 40...60 secondes) qui est équipé de Décharge incapacitante. Vous ne pouvez activer qu\'une seule invocation asura à la fois.'],
2225=>['Invocation du Jinn de rubis','Vous invoquez un Jinn de rubis de niveau 14...20 qui vit pendant 40...60 secondes et est équipé d\'Immolation. Vous ne pouvez activer qu\'une seule invocation asura à la fois.','Vous invoquez un Jinn de rubis de niveau 14...20 (durée de vie de 40...60 secondes) qui est équipé d\'Immolation. Vous ne pouvez activer qu\'une seule invocation asura à la fois.'],
2226=>['Invocation du Lutin de glace','Vous invoquez un Lutin de glace de niveau 14...20 qui vit pendant 40...60 secondes et est équipé de Tessons de glace. Vous ne pouvez activer qu\'une seule invocation asura à la fois.','Vous invoquez un Lutin de glace de niveau 14...20 (durée de vie de 40...60 secondes) qui est équipé de Tessons de glace. Vous ne pouvez activer qu\'une seule invocation asura à la fois.'],
2227=>['Invocation du Chaman naga','Vous invoquez un Chaman naga de niveau 14...20 qui vit pendant 40...60 secondes et est équipé de Lapidation. Vous ne pouvez activer qu\'une seule invocation asura à la fois.','Vous invoquez un Chaman naga de niveau 14...20 (durée de vie de 40...60 secondes) qui est équipé de Lapidation. Vous ne pouvez activer qu\'une seule invocation asura à la fois.'],
2228=>['Frappe habile','Si cette attaque réussit, l\'ennemi visé subit 18...30 points de dégâts. S\'il possède une Armure brisée, il commence à saigner pendant 18...30 secondes.','Inflige 18...30 points de dégâts. Inflige le Saignement (18...30 secondes) si l\'ennemi visé a une Armure brisée.'],
2229=>['Sceau d\'infection','Si la cible ennemie souffre de Saignement, elle souffre de Maladie pendant 13...20 secondes.','Inflige la Maladie (13...20 secondes) si l\'ennemi visé souffre de Saignement.'],
2230=>['Sceau tryptophane','Pendant 14...20 secondes, la cible ennemie et tous les ennemis adjacents se déplacent et attaquent 23...40% moins vite.','(14...20 secondes.) La cible et les ennemis adjacents attaquent et se déplacent 23...40% moins vite.'],
2231=>['Etendard du courage de la bataille d\'Ebon','Vous plantez un Etendard du courage de la bataille d\'Ebon sur votre position actuelle. Pendant 14...20 secondes, les alliés autres que des esprits dans cette zone bénéficient d\'un bonus d\'armure de +24 et d\'un bonus d\'armure supplémentaire de +24 contre les Charrs.','(14...20 secondes.) Les alliés dans cette Protection bénéficient d\'un bonus d\'armure de +24 et d\'un bonus d\'armure supplémentaire de +24 contre les Charrs. Les esprits ne sont pas affectés.'],
2232=>['Etendard de sagesse de la bataille d\'Ebon','Vous plantez un Etendard de sagesse de la bataille d\'Ebon sur votre position actuelle. Pendant 14...20 secondes, les alliés autres que des esprits dans cette zone ont 44...60% de chances de réduire de moitié le temps de recharge des sorts qu\'ils lancent.','(14...20 secondes.) Les sorts lancés par les alliés dans cette Protection ont 44...60% de chances de se recharger 50% plus vite. Les esprits ne sont pas affectés.'],
2233=>['Etendard d\'honneur de la bataille d\'Ebon','Vous plantez un Etendard d\'honneur de la bataille d\'Ebon sur votre position actuelle. Pendant 14...20 secondes, les alliés autres que des esprits dans cette zone infligent +8...15 points de dégâts et +7...10 points de dégâts en plus contre les Charrs.','(14...20 secondes.) Les alliés dans cette Protection infligent +8...15 points de dégâts et +7...10 points de dégâts supplémentaires contre les Charrs. Les esprits ne sont pas affectés.'],
2234=>['Tireur d\'élite de soutien de l\'Avant-garde d\'Ebon','La cible ennemie subit 54...90 points de dégâts perforants et souffre de Saignement pendant 5...25 secondes. Cette attaque a 10% de chances d\'infliger 540...900 points de dégâts perforants supplémentaires. Si cette attaque frappe un Charr, elle a 25% de chances d\'infliger 540...900 points de dégâts perforants supplémentaires.','Inflige 54...90 points de dégâts perforants et provoque le Saignement (5...25 secondes). 10% de chances d\'infliger +540...900 points de dégâts perforants. 25% de chances d\'infliger +540...900 points de dégâts perforants si la cible ennemie est un Charr.'],
2235=>['Assassin de soutien de l\'Avant-garde d\'Ebon','Vous invoquez un Assassin de l\'Avant-garde d\'Ebon de niveau 14...20 équipé de Paume d\'acier, Crocs du renard et Coup des neuf queues. Cet Assassin fait une Foulée de l\'ombre vers la cible ennemie. Si cette dernière est un Charr, l\'Assassin vit pendant 24...30 secondes. Si ce n\'est pas un Charr, l\'Assassin vit pendant 12...15 secondes.','Invoque un assassin de niveau 14...20 équipé de Paume d\'acier, Crocs du renard et Coup des neuf queues. Cet assassin fait une foulée de l\'ombre vers l\'ennemi. Si cet ennemi est un Charr, l\'assassin vit pendant 24...30 secondes. Si ce n\'est pas un Charr, il vit pendant 12...15 secondes.'],
2236=>['Puits de ruine','Exploitez le cadavre le plus proche ou sacrifiez 66% de santé pour créer à cet endroit un Puits de désolation. Pendant 5...30 secondes, chaque fois qu\'un ennemi pris dans la zone d\'effet subit des dégâts physiques, il souffre d\'Armure fissurée pendant 5...20 secondes.','(5...30 secondes.) Inflige l\'altération Armure fissurée (5...20 secondes) à tout ennemi pris dans la zone d\'effet qui subit des dégâts physiques. Exploite un cadavre frais ou sacrifie 66% de santé.'],
2237=>['Atrophie','Pendant 3...7 secondes, la caractéristique principale de la cible ennemie est réduite à 0.','(3...7 secondes.) Réduit la caractéristique principale de l\'ennemi à 0.'],
2238=>['Javelot de rédemption','Si cette attaque réussit, vous infligez +5...20 points de dégâts. Si elle échoue, vous perdez une condition.','Inflige +5...20 points de dégâts. Si l\'attaque échoue, vous perdez une condition.'],
2353=>['"Finissez-le !"','Si la cible ennemie a moins de 50% de santé, elle subit 44...80 points de dégâts, a une Armure brisée et souffre de Blessure profonde pendant 12...20 secondes.','Inflige 44...80 points de dégâts et provoque deux conditions : Armure brisée et Blessure profonde (12...20 secondes). Aucun effet si l\'ennemi visé a plus de 50% de santé.'],
2354=>['"Esquive ceci !"','Pendant 16...20 secondes, votre prochaine attaque ne peut pas être bloquée et inflige +14...20 points de dégâts.','(16...20 secondes.) votre prochaine attaque ne peut pas être bloquée et inflige +14...20 points de dégâts.'],
2355=>['Je suis le plus fort !','Vos 5...8 prochaines attaques infligent +14...20 points de dégâts en plus.','Vos attaques suivantes (5...8 attaques) infligent +14...20 points de dégâts.'],
2356=>['"Rien ne peut m\'arrêter !"','Pendant 16...20 secondes, vous bénéficiez d\'un bonus d\'armure +24 et ne pouvez pas être assommé ni frappé d\'Infirmité.','(16...20 secondes.) Vous bénéficiez d\'un bonus d\'armure de +24 et ne pouvez pas être assommé ni frappé d\'Infirmité.'],
2357=>['Une pointe de ruse','La cible ennemie touchée subit 44...80 points de dégâts. Si cet ennemi était assommé, il ne peut pas attaquer pendant 5...8 secondes.','Inflige 44...80 points de dégâts. L\'ennemi visé ne peut pas attaquer (5...8 secondes) s\'il a été assommé.'],
2358=>['"Tu te déplaces comme un Nain !"','L\'ennemi visé est renversé et subit 44...80 points de dégâts. Il est en outre frappé d\'Infirmité pendant 8...15 secondes.','Inflige 44...80 points de dégâts, renverse et frappe d\'Infirmité (8...15 secondes).'],
2359=>['"Vous êtes tous des mauviettes !"','La cible ennemie et les ennemis adjacents souffrent de Faiblesse pendant 8...12 secondes.','Inflige la Faiblesse (8...12 secondes). Affecte également les ennemis adjacents.'],
2360=>['Aucune douleur','Pendant 30 secondes, vous bénéficiez d\'une régénération de santé de +2...3. Si vous êtes ivre lorsque vous activez cette compétence, vous recevez également +200...300 de santé maximum.','(30 secondes.) Vous bénéficiez d\'une régénération de santé de +2...3. Vous obtenez +200...300 de santé maximum si vous êtes ivre quand vous activez cette compétence.'],
2361=>['Gourdin d\'un millier d\'ours','Si cette attaque réussit, elle inflige +6...9 points de dégâts pour chaque ennemi adjacent (maximum 60 points de dégâts). Si la cible ennemie n\'est pas humaine, elle est assommée.','Inflige +6...9 points de dégâts (60 points maximum) par ennemi adjacent. Attaque assommante si l\'ennemi visé n\'est pas humain.'],
2374=>['Bénédiction de l\'ours','Vous perdez tous les effets et prenez l\'apparence d\'un ours. Pendant 60 secondes, vous avez 100 points d\'armure et 750...800 points de vie. Toutes vos caractéristiques se remettent à 0 et les attaques de l\'ours remplacent vos compétences.','Vous perdez tous les effets et prenez l\'apparence d\'un ours (60 secondes). Toutes vos caractéristiques se remettent à 0, les attaques de l\'ours remplacent vos compétences et vous avez 100 points d\'armure et 750...800 points de vie.'],
2379=>['Bénédiction du loup','Vous perdez tous les effets et prenez l\'apparence d\'un loup. Pendant 60 secondes, vous avez 80 points d\'armure, 660...700 points de vie et une régénération de santé de 2...4. Toutes vos caractéristiques se remettent à 0 et les attaques du loup remplacent vos compétences.','Vous perdez tous les effets et prenez l\'apparence d\'un loup (60 secondes). Toutes vos caractéristiques se remettent à 0, les attaques du loup remplacent vos compétences et vous avez 80 points d\'armure, 660...700 points de vie et une régénération de santé de 2...4.'],
2384=>['Bénédiction du corbeau','Vous perdez tous les effets et prenez l\'apparence d\'un corbeau. Pendant 60 secondes, vous avez 80 points d\'armure, 660...700 points de vie et avez 20...30% de chances de bloquer. Toutes vos caractéristiques se remettent à 0 et les attaques du corbeau remplacent vos compétences.','Vous perdez tous les effets et prenez l\'apparence d\'un corbeau (60 secondes). Toutes vos caractéristiques se remettent à 0, les attaques du corbeau remplacent vos compétences, vous avez 80 points d\'armure, 660...700 points de vie et avez 20...30% de chances de bloquer.'],
2411=>['Distorsion de l\'esprit','Pendant 10...16 secondes, vous vous déplacez 20...33% plus vite et le temps d\'incantation de vos sorts est réduit de 20%.','(10...16 secondes.) Vous vous déplacez 20...33% plus vite et lancez vos sorts 20% plus vite.'],
2412=>['Criminel improbable','Pendant 10...20 secondes, l\'ennemi ciblé ne peut plus utiliser un sort choisi aléatoirement et Criminel improbable est remplacé par ce sort. Vous bénéficiez de 5...10 points d\'énergie.','(10...20 secondes.) Désactive un sort. Cette compétence remplace ce sort. Vous gagnez 5...10 points d\'énergie.'],
2413=>['Technobabillage','La cible ennemie et tous les ennemis adjacents subissent 30...40 points de dégâts. Si cet ennemi n\'est pas un boss, lui et tous les ennemis adjacents sont frappés de Stupeur pendant 3...5 secondes.','Inflige 30...40 points de dégâts à la cible et aux ennemis adjacents. Provoque la Stupeur (3...5 secondes) si la cible n\'était pas un boss.'],
2414=>['Champ de rayonnement','Pendant 5 secondes, les ennemis se trouvant dans la zone subissent une dégénération de santé de -4...6. Lorsque le portail disparaît, les ennemis dans la zone souffrent de Maladie pendant 12...20 secondes.','(5 secondes.) Fait subir une dégénération de santé de -4...6 aux ennemis dans la zone. Effet final : inflige la Maladie (12...20 secondes) aux ennemis dans la zone.'],
2415=>['Scan asura','Pendant 9...12 secondes, vos attaques ne peuvent pas manquer l\'ennemi visé. Tuer un ennemi sous l\'effet du Scan asura réduit votre handicap de 5%.','(9...12 secondes.) Vous ne pouvez pas manquer l\'ennemi visé. Si vous tuez cet ennemi, vous perdez 5% de votre handicap.'],
2416=>['Air de supériorité','Pendant 20...30 secondes, vous obtenez une augmentation asura aléatoire à chaque fois que vous gagnez de l\'XP en tuant un ennemi.','(20...30 secondes.) Vous obtenez une augmentation asura aléatoire chaque fois que vous gagnez de l\'XP en tuant un ennemi.'],
2417=>['Blocage mental','Pendant 5...11 secondes, vous avez 50% de chances de bloquer des attaques. Cet enchantement se réapplique à chaque fois qu\'un ennemi vous attaque.','(5...11 secondes.) Vous avez 50% de chances de bloquer. Renouvellement : chaque fois qu\'un ennemi vous frappe.'],
2418=>['Inverseur de douleur','Pendant 6...10 secondes, à chaque fois que l\'ennemi visé inflige des dégâts, il subit 100...140% des dégâts qu\'il inflige (80 points de dégâts maximum).','(6...10 secondes.) Inflige 100...140% des dégâts (maximum 80 points) à la cible ennemie à chaque fois qu\'elle inflige des dégâts.'],
2420=>['Echappatoire d\'Ebon','Vous faites une Foulée de l\'ombre vers la cible alliée. Cet allié et vous-même êtes soignés de 70...110 points de vie.','L\'allié visé et vous êtes soignés de 70...110 points de vie. Effet initial : vous faites une foulée de l\'ombre vers cet allié. Vous ne pouvez pas vous prendre pour cible.'],
2421=>['Piège de faiblesse','Quand ce piège se déclenche, tous les ennemis à proximité souffrent de Faiblesse pendant 10...20 secondes et subissent 24...50 points de dégâts de la foudre. Tous les Charrs sont assommés. Ce piège fonctionne pendant 90 secondes. Vous pouvez être facilement interrompu lorsque vous activez cette compétence.','(90 secondes.) Affecte les ennemis à proximité. Inflige 24...50 points de dégâts de la Foudre. Inflige la Faiblesse (10...20 secondes). Assomme les Charrs. Cette compétence peut être facilement interrompue.'],
2422=>['Vents','Vous créez un esprit de niveau 4...10. Tous les ennemis dans sa portée ont 15% de risques de manquer leurs attaques à distance. Cet esprit meurt au bout de 54...90 secondes.','Crée un esprit de niveau 4...10 (durée de vie de 54...90 secondes). Affecte les ennemis à portée. 15% de risques de rater les attaques à distance.'],
2423=>['Stabilité naine','Pendant 24...30 secondes, vos poses durent 55...100% plus longtemps. Si vous avez activé cette compétence lorsque vous étiez ivre, vous ne pouvez pas être assommé.','(24...30 secondes.) Vos poses de combat durent 55...100% plus longtemps. Vous ne pouvez pas être assommé si vous avez activé cette compétence en étant ivre.'],
2657=>['Cri de hâte (PvP)','Pendant 30 secondes, votre familier bénéficie de 25% de vitesse d\'attaque en plus et se déplace 25% plus vite.','(30 secondes.) Votre familier se déplace et attaque 25% plus rapidement.'],
2734=>['Délabrement spirituel (PvP)','Pendant 5...40 secondes, lorsque cet ennemi est la cible de l\'une de vos compétences d\'Envoûteur autre qu\'un maléfice, il perd 1 point d\'énergie. Si l\'énergie de l\'ennemi visé tombe à 0, le Délabrement spirituel prend fin et l\'ennemi subit 15...100 points de dégâts.','(5...40 secondes.) Provoque la perte d\'un point d\'énergie chaque fois que l\'ennemi est la cible de vos compétences d\'Envoûteur autre qu\'un maléfice. Si l\'énergie de l\'ennemi visé tombe à 0, le Délabrement spirituel prend fin et l\'ennemi subit 15...100 points de dégâts.'],
2803=>['Gel spirituel (PvP)','L\'ennemi visé subit 10...60 points de dégâts du froid. Si vous avez plus d\'énergie que l\'ennemi visé, il subit 10...60 points de dégâts du froid en plus et se déplace 90% plus lentement pendant 1...5 secondes.','Inflige 10...60 points de dégâts du froid. Si vous avez plus d\'énergie que l\'ennemi visé, il subit 10...60 points de dégâts du froid en plus et se déplace 90% plus lentement (1...5 secondes).'],
2804=>['Choc spirituel (PvP)','La cible ennemie subit 10...50 points de dégâts de la foudre. Si vous avez plus d\'énergie qu\'elle, elle subit 10...50 points de dégâts de la foudre supplémentaires et est renversée. Ce sort a une pénétration d\'armure de 25%.','Inflige 10...50 points de dégâts de la foudre. Si vous avez plus d\'énergie que la cible, elle subit +10...50 points de dégâts de la foudre et est renversée. 25% de pénétration d\'armure.'],
2805=>['Forme de brume (PvP)','Pendant 10...45 secondes, vous subissez 33% de dégâts en moins face aux ennemis sous l\'effet d\'un maléfice de la Magie de l\'eau. Quand vous lancez un sort élémentaire, tous les alliés (autres qu\'esprits) à portée de voix regagnent 50...250% du coût énergétique du sort. Ce sort ne fonctionne pas sur les alliés ayant plus de 80% de points de vie.','(10...45 secondes.) 33% de dégâts en moins face aux ennemis sous l\'effet d\'un maléfice de la Magie de l\'eau. Les alliés (autres qu\'esprits) à portée de voix regagnent 50...250% du coût énergétique de vos sorts élémentaires. Ne fonctionne pas sur les alliés ayant plus de 80% de points de vie.'],
2806=>['Protection contre le mal (PvP)','Crée une protection contre le mal à cette position. Pendant 5...15 secondes, les alliés (autres qu\'esprits) dans cette zone bénéficient de +1...3 en régénération de santé, +12...24 en armure et encore +12...24 en armure contre les dégâts élémentaires. Ce sort est désactivé pendant 30 secondes.','(5...15 secondes.) Les alliés bénéficiant de cette protection gagnent +1...3 en régénération de santé, +12...24 en armure et encore +12...24 en armure contre les dégâts élémentaires. Les esprits ne sont pas affectés. Cette compétence est désactivée pendant 30 secondes.'],
2807=>['Chevauchée de l\'éclair (PvP)','Vous rejoignez la cible à la vitesse de l\'éclair. Tous les ennemis adjacents sont aveuglés pendant 1...5 secondes. Si votre cible est un ennemi, il subit 10...70 points de dégâts de la foudre. Ce sort a une pénétration d\'armure de 25%.','Inflige 10...70 points de dégâts de la foudre. 25% de pénétration d\'armure. Aveugle tous les ennemis adjacents (1...5 secondes). Vous rejoignez la cible instantanément. La cible peut être un allié.'],
2808=>['Frappe enragée (PvP)','Si la Frappe enragée fait mouche, vous gagnez 1...3 décharges d\'adrénaline. Si vous touchez un ennemi en mouvement, vous infligez +10...40 points de dégâts et votre cible est assommée.','Si vous faites mouche, vous gagnez 1...3 décharges d\'adrénaline. Inflige +10...40 points de dégâts et renverse la cible si celle-ci était en mouvement.'],
2809=>['Flamme d\'obsidienne','Inflige 22...92 points de dégâts à la cible ennemie. Ce sort ignore l\'armure.','Inflige 22...92 points de dégâts.'],
2857=>['Egide (PvP)','Pendant 1...3 secondes, le membre du groupe visé ne peut pas être la cible de sorts hostiles, et les attaques contre lui échouent.','(1...3 secondes.) Le membre du groupe visé ne peut pas être la cible de sorts hostiles. Les attaques portées contre lui échouent. Auto-ciblage impossible.'],
2858=>['"Prenez garde !" (PvP)','Les membres du groupe à portée de voix bénéficient d\'un bonus d\'armure de +5...25 pendant 10 secondes. Ce cri prend fin au bout de 1...3 attaques reçues.','(10 secondes.) Les membres du groupe à portée de voix bénéficient d\'un bonus d\'armure de +5...25. Prend fin au bout de 1...3 attaques reçues.'],
2859=>['Affaiblissement (PvP)','La cible est frappée de Faiblesse pendant 10...30 secondes.','Inflige la Faiblesse (10...30 secondes).'],
2860=>['Renouveau éthéré (PvP)','Pendant 10 secondes, à chaque fois que vous lancez un sort, vous gagnez 1...3 points d\'énergie et 5...20 points de vie pour chaque enchantement qui vous affecte.','(10 secondes.) Chaque fois que vous lancez un sort, vous gagnez 1...3 points d\'énergie et 5...20 points de vie par enchantement vous affectant.'],
2861=>['Attaque pénétrante (PvP)','Si l\'Attaque pénétrante réussit, vous infligez +5...15 points de dégâts et cette attaque offre une pénétration d\'armure de 10%.','Inflige +5...15 points de dégâts. Pénétration d\'armure de 10%.'],
2862=>['Silhouette (PvP)','Pendant 5...15 secondes, tous les sorts hostiles qui vous sont lancés échouent et toutes les attaques contre vous manquent. Lorsque la compétence prend fin, il ne vous reste que 5...50 points de vie.','(5...15 secondes.) Tous les sorts hostiles qui vous sont lancés échouent et toutes les attaques contre vous manquent. Effet final : il ne vous reste que 5...50 points de vie.'],
2863=>['Discorde (PvP)','Si la cible ennemie souffre d\'une condition et est affectée par un maléfice ou un enchantement, elle subit 30...110 points de dégâts.','Inflige 30...110 points de dégâts. Sans effet si la cible ennemie ne souffre d\'aucune condition et n\'est sous les effets d\'aucun maléfice ou enchantement.'],
2864=>['Attaque éclatante (PvP)','Si l\'Attaque éclatante réussit, vous infligez +5...15 points de dégâts et cette attaque offre une pénétration d\'armure de 10%.','Inflige +5...15 points de dégâts. Pénétration d\'armure de 10%.'],
2866=>['Chair de ma chair (PvP)','Vous perdez la moitié de vos points de vie. Vous ressuscitez le membre du groupe ciblé avec le nombre de points de vie actuel dont vous disposez et 5...20% d\'énergie.','Ressuscite le membre du groupe visé. (Moitié de votre capital actuel de points de vie et 5...20% d\'énergie). Vous perdez la moitié de vos points de vie.'],
2867=>['Rage de l\'ancêtre (PvP)','Pendant 3 secondes, tous les ennemis adjacents à la cible alliée subissent 4...50 points de dégâts de la foudre par seconde.','(3 secondes.) Inflige 4...50 points de dégâts de la foudre par seconde aux ennemis adjacents à l\'allié visé.'],
2868=>['Arme à fragmentation (PvP)','Pendant 20 secondes, la cible (un allié ou vous-même) possède une Arme à fragmentation. 1...5 de ses prochaines attaques réussies infligent 5...40 points de dégâts à 4 ennemis adjacents maximum.','(20 secondes.) Les attaques infligent 5...40 points de dégâts à 3 ennemis adjacents. Prend fin au bout de 1...5 attaques.'],
2869=>['Remède de l\'Assassin (PvP)','Pendant 30 secondes, les prochaines compétences d\'attaque (1...10) que vous utilisez suppriment une condition.','(30 secondes.) Vos compétences d\'attaque suivantes (1...10) suppriment une condition chacune.'],
2871=>['Lumière de la délivrance (PvP)','Tous les membres du groupe sont soignés de 5...70 points de vie. Toutes vos Prières de châtiment sont inutilisables pendant 20 secondes.','Soigne tout le groupe de 5...70 points de vie. Désactive vos Prières de châtiment (20 secondes).'],
2872=>['Sceau du pacte avec la mort (PvP)','Vous ressuscitez le membre du groupe visé avec autant de santé que vous et 15...100% d\'énergie maximum. La prochaine fois que cet allié meurt dans les 120 secondes, vous mourez aussi.','Ressuscite le membre du groupe visé avec autant de santé que vous et 15...100% d\'énergie maximum. Pendant 120 secondes, vous mourez si ce membre du groupe est à nouveau tué.'],
2875=>['Lancer d\'harrier (PvP)','Si cette attaque réussit, vous infligez +5...20 points de dégâts. Si elle touche un ennemi en mouvement, elle inflige 5...40 points de dégâts en plus.','Inflige +5...20 points de dégâts. Inflige 5...40 points de dégâts supplémentaires si la cible se déplace.'],
2876=>['Hymne défensif (PvP)','Pendant 4...10 secondes, chaque membre du groupe à portée de voix a 50% de chances de bloquer les attaques qui lui sont lancées. Ce chant prend fin si cet allié frappe avec une compétence d\'attaque.','(4...10 secondes.) Les membres du groupe à portée de voix ont 50% de chances de bloquer. Prend fin quand votre compétence d\'attaque réussit.'],
2877=>['Ballade de rétablissement (PvP)','Pendant 10 secondes, la prochaine fois que chaque membre du groupe à portée de voix subit des dégâts, il est soigné de 15...75 points de vie.','(10 secondes.) Les membres du groupe à portée de voix gagnent 15...75 points de vie la prochaine fois qu\'ils subissent des dégâts.'],
2878=>['Chant de rétablissement (PvP)','Pendant 10 secondes, la prochaine fois que chaque membre du groupe à portée de voix utilise une compétence, il est soigné de 45...110 points de vie.','(10 secondes.) Les membres du groupe à portée de voix récupèrent 45...110 points de vie grâce à leur prochaine compétence.'],
2879=>['"Attention !" (PvP)','Pendant 4...10 secondes, tous les alliés à portée de voix se déplacent 33% plus vite et gagnent 5...15 points de vie par seconde en se déplaçant.','(4...10 secondes.) Tous les alliés à portée de voix se déplacent 33% plus vite et gagnent 5...15 points de vie par seconde en se déplaçant.'],
2880=>['"Ne vous rendez jamais !" (PvP)','Pendant 10 secondes, tous les membres du groupe à portée de voix ayant moins de 75% de santé bénéficient d\'une régénération de santé de +1...5.','(10 secondes.) Les membres du groupe à portée de voix bénéficient d\'une régénération de santé de +1...5. Affecte uniquement les membres du groupe possédant moins de 75% de santé.'],
2883=>['"Pour la justice !" (PvP)','Pendant 8 secondes, chaque fois que vous réussissez une attaque, vous obtenez 1 décharges d\'adrénaline supplémentaires.','(8 secondes.) Vous obtenez 1 décharges d\'adrénaline supplémentaires chaque fois que vous réussissez une attaque.'],
2884=>['Régénération mystique (PvP)','Pendant 5...20 secondes, vous bénéficiez d\'une régénération de santé de +1...4 pour chaque enchantement (3 maximum) qui vous affecte.','(5...20 secondes.) Vous bénéficiez d\'une régénération de santé de +1...4 pour chaque enchantement (3 maximum) qui vous affecte.'],
2885=>['Sang du faible (PvP)','L\'ennemi visé et tous les ennemis proches souffrent de Faiblesse pendant 1...16 secondes.','Inflige la Faiblesse (1...16 secondes) à l\'ennemi visé et aux ennemis à proximité.'],
2887=>['Sceau du jugement (PvP)','La cible ennemie est assommée. Elle subit 5...50 points de dégâts sacrés, ainsi que les ennemis adjacents. Sa portée est la moitié de celle d\'un sceau normal.','Assomme la cible. Inflige 5...50 points de dégâts sacrés à la cible et aux ennemis adjacents.'],
2891=>['Aura inflexible (PvP)','Vous ressuscitez le membre du groupe mort ciblé avec 100% de sa santé et de son énergie. Si vous arrêtez de maintenir cet enchantement ou s\'il est dissipé, ce membre du groupe meurt et crée un cadavre utilisé. Les morts subies en étant la cible d\'Aura inflexible ne causent pas de handicap de moral. (50% de risques d\'échec avec Faveur divine inférieure à 5.)','Ressuscite le membre du groupe ciblé (santé maximale, énergie maximale). Effet final : cet allié meurt et crée un cadavre utilisé. N\'inflige pas de handicap de mort. 50% de risques d\'échec à moins d\'avoir au moins 5 points en Faveur divine.'],
2892=>['Lien spirituel (PvP)','Pendant 8 secondes, à chaque fois que la cible (un allié ou vous-même) subit plus de 50 points de dégâts infligés par les 10 prochaines attaques ou sorts, cette cible est soignée de 30...90 points de vie.','(8 secondes.) Soigne de 30...90 points de vie chaque fois que l\'allié visé subit plus de 50 points de dégâts. Prend fin lorsque cet allié a subi des dégâts de 10 attaques ou sorts.'],
2893=>['Arme de protection (PvP)','Pendant 3...8 secondes, la cible (un allié ou vous-même) possède une Arme de protection qui lui confère une régénération de santé de +2...4 et 50% de chances de bloquer les attaques. L\'Arme de protection prend fin si la cible attaque.','(3...8 secondes.) Confère une régénération de santé de +2...4. 50% de chances de bloquer. Prend fin si la cible attaque.'],
2895=>['Compagnon du châtiment (PvP)','Pendant 4 secondes, vos Prières du châtiment reçoivent un double bonus de Faveur divine.','(4 secondes.) Vos Prières du châtiment reçoivent un double bonus de soins de Faveur divine.'],
2925=>['Tir du chasseur paresseux (PvP)','Si cette attaque réussit, la cible ennemie subit +5...15 points de dégâts. Si elle n\'utilisait pas de compétence, Tir du chasseur paresseux inflige +5...20 points de dégâts supplémentaires.','Inflige +5...15 points de dégâts. Inflige +5...20 points de dégâts supplémentaires si l\'ennemi visé n\'utilise pas de compétence.'],
2959=>['Dextérité de l\'expert (PvP)','Pendant 1...20 secondes, vous attaquez 15% plus vite et votre caractéristique d\'Adresse au tir est augmentée de 1.','(1...20 secondes.) Vous attaquez 15% plus vite et votre caractéristique d\'Adresse au tir est augmentée de +1.'],
2965=>['Sceau des Esprits (PvP)','Vous gagnez 3...12 points d\'énergie si vous êtes à portée de voix d\'un esprit.','Vous gagnez 3...12 points d\'énergie. Aucun effet si vous n\'êtes pas à portée de voix d\'un esprit.'],
2966=>['Sceau de puissance spectrale (PvP)','Les attaques de la créature invoquée alliée ciblée infligent 5...35 points de dégâts supplémentaires. La créature meurt au bout de 10 secondes.','La créature invoquée alliée ciblée inflige +5...35 points de dégâts. Cette créature meurt au bout de 10 secondes.'],
2969=>['Lecture du vent (PvP)','Pendant 24 secondes, vos flèches se déplacent deux fois plus vite.','(24 secondes.) Vos flèches se déplacent deux fois plus vite.'],
2998=>['Fragilité (PvP)','Pendant 8...20 secondes, l\'ennemi visé et les ennemis adjacents subissent 5...20 points de dégâts chaque fois qu\'ils sont affectés ou libérés d\'une nouvelle condition.','Inflige également des maléfices aux ennemis adjacents à la cible (8...20 secondes). Ces ennemis subissent 5...20 points de dégâts chaque fois qu\'ils gagnent ou perdent une condition.'],
2999=>['Force de l\'honneur (PvP)','Tant que cet enchantement est actif, la cible (un allié ou vous-même) inflige 1...5 points de dégâts supplémentaires au corps à corps.','La cible (un allié ou vous-même) inflige 1...5 points de dégâts supplémentaires au corps à corps.'],
3002=>['Endurance du Guerrier (PvP)','Pendant 5...35 secondes, vous gagnez 3 points d\'énergie pour chaque attaque au corps à corps réussie. L\'Endurance du Guerrier ne peut pas faire grimper votre énergie au-delà de 10...25.','(5...35 secondes.) Vous gagnez 3 points d\'énergie pour chaque attaque au corps à corps réussie. Vous ne gagnez aucun point d\'énergie si votre énergie est déjà supérieure à 10...25.'],
3003=>['Armure de l\'impassible (PvP)','Pendant 10...35 secondes, vous avez une réduction de dégâts de base de 10 pendant que vous lancez des Rituels d\'asservissement.','(10...35 secondes.) Vous avez une réduction de dégâts de base de 10 pendant que vous lancez des Rituels d\'asservissement.'],
3005=>['Union (PvP)','Crée un esprit de niveau 1...8. A chaque fois qu\'un allié à sa portée (autre qu\'un esprit) subit des dégâts ou un vol de vie, ceux-ci sont réduits de 15 points et l\'esprit subit 15 points de dégâts. Il disparaît au bout de 30...60 secondes.','Crée un esprit de niveau 1...8 (durée de vie de 30...60 secondes). A chaque fois qu\'un allié à sa portée (autre qu\'un esprit) subit des dégâts ou un vol de vie, ceux-ci sont réduits de 15 points et l\'esprit subit 15 points de dégâts.'],
3006=>['Mélodie des Ombres (PvP)','Crée un esprit de niveau 1...6. Les attaques de l\'esprit infligent +5...20 points de dégâts et entraînent l\'Aveuglement pendant 1...6 secondes. Il meurt au bout de 30 secondes.','Crée un esprit de niveau 1...6 (durée de vie de 30 secondes). Ses attaques infligent +5...20 points de dégâts et entraînent l\'Aveuglement (1...6 secondes).'],
3007=>['Douleur (PvP)','Crée un esprit de niveau 1...8. Les attaques de cet esprit infligent 5...30 points de dégâts. Il meurt au bout de 30...150 secondes.','Crée un esprit de niveau 1...8 (durée de vie de 30...150 secondes). Ses attaques infligent 5...30 points de dégâts.'],
3008=>['Destruction (PvP)','Crée un esprit de niveau 1...10 qui meurt après 30 secondes. Lorsque cet esprit meurt, tous les ennemis dans la zone subissent 1...10 points de dégâts pour chaque seconde de vie de l\'esprit (maximum de 150 points de dégâts).','Crée un esprit de niveau 1...10 (durée de vie de 30 secondes). A sa mort, il inflige 1...10 points de dégâts pour chaque seconde de vie à tous les ennemis dans la zone (maximum de 150 points de dégâts).'],
3009=>['Apaisement','Crée un esprit de niveau 1...8. Les ennemis dans sa portée mettent deux fois plus de temps pour récupérer de l\'adrénaline. Il meurt au bout de 15...45 secondes.','Crée un esprit de niveau 1...8 (durée de vie de 15...45 secondes). Les ennemis à portée accumulent de l\'adrénaline deux fois moins vite.'],
3010=>['Déplacement (PvP)','Crée un esprit de niveau 1...10. Tous les alliés autres que des esprits à portée ont 75% de chances de bloquer les attaques. Chaque fois qu\'une attaque est bloquée de cette manière, cet esprit subit 60 points de dégâts. Il disparaît au bout de 30...60 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...60 secondes). Les alliés (autres que les esprits) à portée ont 75% de chances de bloquer. Effet du blocage : cet esprit subit 60 points de dégâts.'],
3011=>['Préservation (PvP)','Crée un esprit de niveau 1...10. Toutes les 4 secondes, cet esprit soigne un allié (autre qu\'un esprit) dans la zone de 10...115 points de vie. Il disparaît au bout de 90 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 90 secondes). Toutes les 4 secondes, cet esprit soigne un allié (autre qu\'un esprit) de 10...115 points de vie.'],
3012=>['Vie (PvP)','Crée un esprit de niveau 1...10. Lorsque cet esprit meurt, tous les alliés (autres que des esprits) dans sa portée sont soignés de 1...7 points de vie pour chaque seconde d\'existence de cet esprit. Il meurt au bout de 20 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 20 secondes). Affecte les alliés à portée, à l\'exception des esprits. Effet final : soigne de 1...7 points de vie par seconde d\'existence de cet esprit.'],
3013=>['Rétablissement (PvP)','Crée un esprit de niveau 1...10. Les alliés (autres que des esprits) dans sa portée bénéficient d\'une régénération de santé de +1...3. Il meurt au bout de 15...45 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 15...45 secondes). Les alliés (autres que les esprits) à portée bénéficient d\'une régénération de santé de +1...3.'],
3014=>['Dissonance (PvP)','Crée un esprit de niveau 1...8. Celui-ci inflige 5...20 points de dégâts et toute personne touchée par cette attaque est interrompue. Il meurt au bout de 10...25 secondes.','Crée un esprit de niveau 1...8 (durée de vie de 10...25 secondes). Ses attaques infligent 5...20 points de dégâts et interrompent les actions.'],
3015=>['Lien terrestre (PvP)','Crée un esprit de niveau 1...10. Tous les ennemis (autres que des esprits) assommés dans sa portée le sont pour au moins 3 secondes. Chaque fois, cet esprit perd 50...25 points de vie. Il meurt au bout de 15...45 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 15...45 secondes). Chaque fois que des ennemis (autres que des esprits) à portée sont assommés, ils le sont pour au moins 3 secondes. Coût de l\'assommement : cet esprit perd 50...25 points de vie.'],
3016=>['Protection (PvP)','Crée un esprit de niveau 1...8. Les alliés (autres que des esprits) dans sa portée ne peuvent pas perdre plus de 10% de leur santé maximum sur une attaque. Lorsque cet esprit empêche les dégâts, il perd 75...45 points de vie. Cet esprit dure 30...60 secondes.','Crée un esprit de niveau 1...8 (durée de vie de 30...60 secondes). Les alliés (autres que les esprits) à portée ne peuvent pas perdre plus de 10% de leur santé maximum d\'un seul coup. Coût de la prévention des dégâts : cet esprit perd 75...45 points de vie.'],
3017=>['Désenchantement (PvP)','Crée un esprit de niveau 1...8. Celui-ci inflige 5...20 points de dégâts et toute personne touchée par cette attaque perd un enchantement. Il meurt au bout de 15...40 secondes.','Crée un esprit de niveau 1...8 (durée de vie de 15...40 secondes). Ses attaques infligent 5...20 points de dégâts et suppriment un enchantement.'],
3018=>['Restauration (PvP)','Crée un esprit de niveau 1...10. Lorsque cet esprit meurt, tous les membres du groupe dans la zone sont ressuscités avec 5...50% de leur santé et 0 point d\'énergie. Cet esprit meurt au bout de 30 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30 secondes). Effet final : ressuscite les membres du groupe dans la zone avec 5...50% de santé et 0 point d\'énergie.'],
3019=>['Mélodie du sang (PvP)','Crée un esprit de niveau 1...8 qui disparaît au bout de 30...150 secondes. Les attaques de cet esprit volent jusqu\'à 5...25 points de vie.','Crée un esprit de niveau 1...8 (durée de vie de 30...150 secondes). Ses attaques volent 5...25 points de vie.'],
3020=>['Voyage (PvP)','Crée un esprit de niveau 1...8. Chaque fois que l\'attaque de cet esprit touche un ennemi immobile, celui-ci est assommé et l\'esprit perd 70...50 points de vie. Il meurt au bout de 30...60 secondes.','Crée un esprit de niveau 1...8 (durée de vie de 30...60 secondes). Ses attaques peuvent assommer les ennemis immobiles. Coût de l\'assommement : cet esprit perd 70...50 points de vie.'],
3021=>['Chaleur de savane (PvP)','Vous créez une Chaleur de savane sur la position de l\'ennemi visé. Pendant 5 secondes, tous les ennemis à proximité subissent 5...20 points de dégâts du feu pour chaque seconde d\'activation de ce sort.','Inflige 5...20 points de dégâts du feu par seconde à compter du lancement du sort (5 secondes). Frappe les ennemis à proximité de la position initiale de la cible.'],
3022=>['Regard de fureur (PvP)','Anéantit l\'esprit allié visé et crée un esprit de fureur de niveau 1...10. Les attaques de cet esprit infligent 5...20 points de dégâts. Cet esprit meurt au bout de 30...60 secondes.','Détruit un esprit allié. Crée un esprit de niveau 1...10 (durée de vie de 30...60 secondes). Ses attaques infligent 5...20 points de dégâts.'],
3023=>['Angoisse (PvP)','Crée un esprit de niveau 1...7. L\'attaque de cet esprit inflige 5...20 points de dégâts et deux fois plus de dégâts à des ennemis affectés par un maléfice. Il meurt au bout de 15...45 secondes.','Crée un esprit de niveau 1...7 (durée de vie de 15...45 secondes). Ses attaques infligent 5...20 points de dégâts. Les ennemis victimes de maléfices subissent deux fois plus de dégâts.'],
3024=>['Responsabilisation (PvP)','Crée un esprit de niveau 1...10. Tous les alliés dans sa portée qui portent un objet bénéficient de 15...45 de santé maximum et de 10 points d\'énergie maximum. Il meurt au bout de 15...60 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 15...60 secondes). Les alliés à portée qui tiennent un objet gagnent 15...45 points de vie maximum et 10 points d\'énergie maximum.'],
3025=>['Récupération (PvP)','Crée un esprit de niveau 1...10. Les conditions affectant les alliés à portée de cet esprit prennent fin 20...50% plus vite. Il meurt au bout de 30...60 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 30...60 secondes). Les conditions dont souffrent les alliés à portée prennent fin 20...50% plus vite.'],
3026=>['"Visez les yeux !" (PvP)','Pendant 10 secondes, la prochaine fois que chaque allié à portée de voix lance une attaque, cette attaque a 30...75% de chances d\'infliger un coup critique.','(10 secondes.) Les alliés à portée de voix ont +30...75% de chances d\'infliger un coup critique avec leur attaque suivante.'],
3027=>['"Préparez-vous !" (PvP)','Pendant 5...15 secondes, la prochaine fois qu\'un allié doit être assommé, 1 ennemi à proximité subit 15...90 points de dégâts à la place.','(5...15 secondes.) Empêche l\'allié visé d\'être assommé la fois suivante où il devrait l\'être et inflige 15...90 points de dégâts à un ennemi près de lui. Vous ne pouvez pas vous prendre pour cible.'],
3028=>['Finale enflammé (PvP)','Pendant 10...35 secondes, chaque fois qu\'un chant ou un cri sur la cible (autre qu\'un esprit) prend fin, tous les ennemis adjacents à cette cible s\'embrasent pendant 1...5 secondes.','(10...35 secondes.) Inflige la Brûlure (1...5 secondes) aux ennemis adjacents chaque fois qu\'un chant ou un cri affectant l\'allié visé prend fin. Vous ne pouvez pas viser les esprits.'],
3029=>['Refrain du Bladeturn (PvP)','Pendant 20 secondes, la cible alliée (autre qu\'un esprit) a un bonus d\'armure de +10...40 contre les dégâts tranchants. Cet écho est répété chaque fois qu\'un chant ou un cri sur cet allié prend fin.','(20 secondes.) L\'allié visé bénéficie d\'un bonus d\'armure de +10...40 contre les dégâts tranchants. Renouvellement : chaque fois qu\'un chant ou un cri affectant cet allié prend fin. Vous ne pouvez pas viser les esprits.'],
3030=>['Sceau de retour (PvP)','Vous ressuscitez le membre du groupe visé avec 5...20% de santé et 1...4% d\'énergie pour chaque membre du groupe à portée de voix.','Ressuscite le membre du groupe visé (5...20% de santé et 1...4% d\'énergie par membre du groupe à portée de voix).'],
3031=>['"Pas touche !" (PvP)','Pendant 20 secondes, les 1...5 prochaines compétences de contact utilisées contre vous échouent.','(20 secondes.) les 1...5 prochaines compétences de contact utilisées contre vous échouent.'],
3032=>['"Tenez bon !" (PvP)','Pendant 5...20 secondes, tous les membres du groupe à portée de voix reçoivent +24 de bonus d\'armure lorsqu\'ils sont immobiles. Cet effet prend fin sur l\'allié affecté par ce cri lorsque cet allié attaque.','(5...20 secondes.) Les membres du groupe à portée de voix bénéficient d\'un bonus d\'armure de +24 quand ils sont immobiles. Prend fin pour tout allié qui attaque.'],
3033=>['"Nous reviendrons !" (PvP)','Pendant 10 secondes, chaque fois que les membres du groupe à portée de voix utilisent une compétence de résurrection, leurs alliés morts reviennent à la vie avec 10...75% de santé et 5...50% d\'énergie en plus.','(10 secondes.) Chaque fois que les membres du groupe à portée de voix utilisent une compétence de résurrection, leurs alliés morts reviennent à la vie avec 10...75% de santé et 5...50% d\'énergie en plus.'],
3034=>['"Trouvez leur faiblesse !" (PvP)','Pendant 5...20 secondes, la prochaine fois que la cible (un allié ou vous-même) inflige un coup critique, elle cause aussi une Blessure profonde pendant 5...20 secondes.','(5...20 secondes.) Le prochain coup critique infligé par la cible alliée provoque la Blessure profonde (5...20 secondes).'],
3035=>['"N\'abandonnez jamais !" (PvP)','Tous les alliés à portée de voix ayant moins de 75% de santé gagnent 1...10 points d\'énergie.','Les alliés à portée de voix gagnent 1...10 points d\'énergie. Affecte uniquement les alliés possédant moins de 75% de santé.'],
3036=>['"À l\'aide !" (PvP)','L\'allié ciblé (sauf les esprits) gagne 5...50 points de vie. Pendant 1...10 secondes, les sorts des autres alliés ciblant cet allié s\'incantent 50% plus vite.','(1...10 secondes.) L\'allié ciblé (sauf les esprits) gagne 5...50 points de vie et les sorts alliés s\'incantent 50% plus vite sur cette cible.'],
3037=>['"Repliez-vous !" (PvP)','Pendant 4...10 secondes, tous les alliés à portée de voix bénéficient de 5...15 points de vie par seconde lorsqu\'ils sont en mouvement et se déplacent 33% plus vite. "Repliez-vous !" prend fin sur l\'allié affecté par ce cri lorsque cet allié réussit une attaque.','(4...10 secondes.) Les alliés à portée de voix gagnent 5...15 points de vie par seconde quand ils sont en mouvement et se déplacent 33% plus vite. Prend fin pour tout allié réussissant une attaque.'],
3038=>['Agonie (PvP)','Crée un esprit de niveau 1...8. Celui-ci fait perdre 3...10 points de vie par seconde aux ennemis à portée de voix. Cet esprit perd 3...10 points de vie pour chaque ennemi blessé de cette manière. Il meurt au bout de 30...90 secondes.','Crée un esprit de niveau 1...8 (durée de vie de 30...90 secondes). Fait perdre 3...10 points de vie par seconde aux ennemis à portée de voix. Cet esprit perd 3...10 points de vie par ennemi perdant de la santé.'],
3039=>['Rajeunissement (PvP)','Crée un esprit de niveau 1...16. Celui-ci soigne tous les membres du groupe à portée de voix de 3...10 points de vie par seconde. Cet esprit perd 3...10 points de vie pour chaque membre du groupe soigné de cette manière. Il meurt au bout de 30...90 secondes.','Crée un esprit de niveau 1...16 (durée de vie de 30...90 secondes). Soigne les membres du groupe à portée de voix de 3...10 points de vie par seconde. Coût des soins : cet esprit perd 3...10 points de vie.'],
3040=>['Hymne d\'interruption (PvP)','Pendant 1...10 secondes, la prochaine compétence d\'attaque utilisée par chaque allié à portée de voix interrompt également une action.','(1...10 secondes.) La compétence d\'attaque suivante des alliés à portée de voix interrompt une action.'],
3045=>['Bien-être animal (PvP)','Vous soignez votre familier de 40...120 points de vie. S\'il est mort, il est ressuscité avec 10...58% de santé. Si vous utilisez Bien-être animal, votre familier vous accompagnera lors de vos déplacements.','Votre familier gagne 40...120 points de vie. Ressuscite votre familier (10...58% de santé). Si vous utilisez Bien-être animal, votre familier vous accompagnera lors de vos déplacements.'],
3047=>['Assaut de Melandru (PvP)','Votre familier tente un Assaut de Melandru qui inflige +5...20 points de dégâts. Si cette attaque frappe un ennemi sous l\'effet d\'un enchantement, cet ennemi, ainsi que tous les ennemis adjacents, subissent +5...35 points de dégâts','Inflige +5...20 points de dégâts. Inflige +5...35 points de dégâts supplémentaires à l\'ennemi visé et aux ennemis adjacents si la cible est sous l\'effet d\'un enchantement.'],
3048=>['Linceul de détresse (PvP)','Pendant 30...60 secondes, si votre santé est inférieure à 50%, vous avez 75% de chances de bloquer les attaques.','(30...60 secondes.) Vous avez 75% de chances de bloquer les attaques. Sans effet si votre santé est supérieure à 50%.'],
3049=>['Furie invisible (PvP)','Pendant 15...60 secondes, vous ne pouvez pas être bloqué par des ennemis aveuglés.','(15...60 secondes.) Vous ne pouvez pas être bloqué par des ennemis aveuglés.'],
3050=>['Lien du prédateur (PvP)','Pendant 5...20 secondes, les attaques réussies de votre familier vous soignent de 1...31 points de vie.','(5...20 secondes.) Vous obtenez 1...31 points de vie chaque fois que votre familier réussit une attaque.'],
3051=>['Coup enragé (PvP)','Votre familier tente un Coup enragé qui inflige +3...23 points de dégâts (bonus maximal : 60) pour chaque compétence de Domptage qui se recharge.','Inflige +3...23 points de dégâts (maximum : 60) pour chacune de vos compétences de Domptage se rechargeant.'],
3053=>['Sceau de corruption mortelle (PvP)','Doit succéder à une attaque d\'ambidextrie. La cible ennemie subit 5...35 points de dégâts pour chaque condition affectant cet ennemi (maximum : 130).','Inflige 5...35 points de dégâts (maximum : 130) pour chaque condition affectant l\'ennemi visé. Doit succéder à une attaque d\'ambidextrie.'],
3054=>['Masochisme (PvP)','Pendant 30 secondes, vous gagnez 1...3 points d\'énergie chaque fois que vous sacrifiez de la santé.','(30 secondes.) Vous recevez 1...3 points d\'énergie chaque fois que vous sacrifiez de la santé.'],
3058=>['Festin impie (PvP)','Vous volez jusqu\'à 10...65 points de vie à 1...4 ennemis maximum se trouvant dans la zone.','Vole 10...65 points de vie à 1...4 ennemis dans la zone autour de vous.'],
3059=>['Sceau d\'agonie (PvP)','Vous souffrez de Saignement pendant 25 secondes. Tous les ennemis à proximité subissent 10...70 points de dégâts.','Inflige 10...70 points de dégâts aux ennemis à proximité. Vous êtes pris de Saignement (25 secondes).'],
3060=>['Evasion (PvP)','Pendant 1...8 secondes, vous vous déplacez 33% plus vite et avez 75% de chances de bloquer les attaques. L\'Evasion prend fin si vous effectuez une attaque au corps à corps.','(1...8 secondes.) Vous vous déplacez 33% plus vite et avez 75% de chances de bloquer. Prend fin si vous effectuez une attaque au corps à corps.'],
3061=>['Efflorescence mortelle (PvP)','Doit succéder à une attaque main gauche. Si elle réussit, l\'Efflorescence mortelle inflige +20...45 points de dégâts à l\'ennemi visé et 20...45 points de dégâts à tous les ennemis adjacents.','Inflige +20...45 points de dégâts. Affecte également les ennemis près de la cible. Doit succéder à une attaque main gauche.'],
3062=>['Finale de rétablissement (PvP)','Pendant 10...35 secondes, les 5 prochaines fois qu\'un chant ou un cri sur une cible (autre qu\'un esprit) prend fin, cette cible est soignée de 15...75 points de vie.','(10...35 secondes.) L\'allié visé reçoit 15...75 points de vie les 5 prochaines fois qu\'un cri ou un chant sur cet allié prend fin. Vous ne pouvez pas viser les esprits.'],
3063=>['Mantra de résolution (PvP)','Pendant 5 secondes, vous ne pouvez pas être interrompu, mais pour chaque tentative d\'interruption, soit vous perdez 10...4 points d\'énergie, soit le Mantra de résolution prend fin.','(5 secondes.) Vous protège des interruptions. Coût de la protection : vous perdez 10...4 points d\'énergie ou le Mantra de résolution prend fin.'],
3141=>['Réflexes foudroyants (PvP)','Pendant 5...11 secondes, vous avez 75% de chances de bloquer les attaques au corps à corps et les projectiles. Vous attaquez aussi 33% plus vite.','(5...11 secondes.) Vous attaquez 33% plus vite et avez 75% de chances de bloquer.'],
3143=>['Coup de renouvellement (PvP)','Si Coup de renouvellement réussit, il inflige +5...20 points de dégâts. Si vous frappez un ennemi assommé, vous gagnez 3 points d\'énergie et cette attaque se recharge instantanément.','Inflige +5...20 points de dégâts. Vous gagnez 3 points d\'énergie et cette attaque se recharge instantanément si la cible ennemie était assommée.'],
3144=>['Guérison partagée (PvP)','Si votre santé ou celle de votre familier est en dessous de 75%, vous regagnez tous les deux 25...145 points de vie. Si votre familier est mort, il est ressuscité avec 50% de santé.','Votre familier et vous êtes soignés de 25...145. Si votre familier est mort, il est ressuscité avec 50% de santé. Ne fonctionne que si votre santé ou celle de votre familier est en dessous de 75%.'],
3145=>['Flèches de verre (PvP)','Pendant 10...35 secondes, vos flèches infligent +6...18 points de dégâts si elles touchent leur objectif, et entraînent le Saignement pendant 10...20 secondes si elles sont bloquées.','(10...35 secondes.) Vos flèches infligent +6...18 points de dégâts. Provoque le Saignement si elles sont bloquées (10...20 secondes).'],
3147=>['Flèche vive (PvP)','Cette attaque inflige +5...15 points de dégâts si elle réussit. Si vous causez un coup critique, vous infligez +5...30 points de dégâts supplémentaires.','Inflige +5...15 points de dégâts. Inflige +5...30 points de dégâts supplémentaires si vous faites un coup critique.'],
3148=>['Hymne de la jalousie (PvP)','Pendant 10 secondes, la prochaine compétence d\'attaque utilisée par chaque allié à portée de voix inflige +10...20 points de dégâts contre les ennemis ayant plus de 50% de santé.','(10 secondes.) Les alliés à portée de voix infligent +10...20 points de dégâts avec leur compétence d\'attaque suivante. Le bonus de dégâts est appliqué uniquement contre les ennemis possédant plus de 50% de santé.'],
3149=>['Refrain de réparation (PvP)','Pendant 15 secondes, vous bénéficiez d\'une régénération de santé de +2...3. Cet écho se renouvelle chaque fois qu\'un chant ou un cri vous affectant prend fin.','(15 secondes.) Vous bénéficiez d\'une régénération de santé de +2...3. Renouvellement : chaque fois qu\'un chant ou un cri vous affectant prend fin.'],
3151=>['Empathie (PvP)','Pendant 5...15 secondes, chaque fois que l\'ennemi visé attaque, il subit 15...45 points de dégâts.','(5...15 secondes.) L\'ennemi visé subit 15...45 points de dégâts dès lors qu\'il attaque.'],
3152=>['Angoisse paralysante (PvP)','Pendant 5...20 secondes, la cible se déplace 50% moins vite et subit une dégénération de santé de -2...6.','(5...20 secondes.) L\'ennemi visé se déplace 50% moins vite et subit une dégénération de santé de -2...6.'],
3156=>['Pose du soldat (PvP)','Pendant 4...10 secondes, vous attaquez 33% plus vite lorsque que vous êtes sous l\'effet d\'un cri ou d\'un chant.','(4...10 secondes.) Vous attaquez 33% plus vite lorsque vous êtes sous l\'effet d\'un cri ou d\'un chant.'],
3157=>['Glaive était destructrice (PvP)','Vous tenez les cendres de Glaive pendant un maximum de 30...60 secondes. En tenant ses cendres, toutes les compétences du Ritualiste bénéficient de 10% de pénétration d\'armure. Lorsque vous déposez ses cendres, tous les ennemis dans la zone subissent 15...85 points de dégâts de la foudre.','(30...60 secondes.) Vos compétences de Ritualiste bénéficient de 10% de pénétration d\'armure. Effet de la pose : inflige 15...85 points de dégâts de la foudre à tous les ennemis dans la zone.'],
3179=>['Mantra des sceaux (PvP)','Pendant 10...40 secondes, vous bénéficiez de +3 d\'armure par sceau équipé. Quand vous utilisez un sceau, vous gagnez 5...60 points de vie.','(10...40 secondes.) Vous bénéficiez de +3 d\'armure par sceau. Quand vous utilisez un sceau, vous gagnez 5...60 points de vie.'],
3180=>['Dispersion des illusions (PvP)','Dissipe un maléfice d\'Envoûteur sur l\'ennemi ciblé. Si un maléfice est dissipé, cet ennemi subit 15...75 points de dégâts et les ennemis adjacents subissent 75% de ces dégâts.','Dissipe un maléfice d\'Envoûteur sur l\'ennemi ciblé. Effet de la suppression : 15...75 points de dégâts à l\'ennemi ciblé et 75% de ces dégâts à tous les ennemis adjacents.'],
3181=>['Armes illusoires (PvP)','Pendant 30 secondes, vos attaques au corps à corps ne peuvent ni réussir ni échouer. La compétence Armes Illusoires inflige à la place 20...60 points de dégâts à vos cibles chaque fois que vous attaquez au corps à corps.','(30 secondes.) Inflige 20...60 points de dégâts aux ennemis à la place d\'autres dégâts ou effets lors de combats rapprochés. Vos attaques au corps à corps ne peuvent ni réussir ni échouer.'],
3183=>['Migraine (PvP)','Pendant 4...16 secondes, la cible ennemie subit une dégénération de santé de -1...8 et le temps d\'activation de ses compétences est rallongé de 100%.','(4...16 secondes.) Entraîne une dégénération de santé de -1...8 et double le temps d\'activation des compétences.'],
3184=>['Cumul de douleur (PvP)','L\'ennemi visé subit 10...35 points de dégâts. Si celui-ci est affecté par 2 maléfices ou plus, il souffre de Blessure profonde pendant 5...20 secondes.','Inflige 10...35 points de dégâts. Provoque une Blessure profonde (5...20 secondes) si la cible ennemie est affectée par 2 maléfices ou plus.'],
3185=>['Instabilité psychique (PvP)','Interrompt l\'action de l\'ennemi visé. S\'il s\'agit d\'une compétence, cet ennemi et tous les ennemis adjacents sont assommés pendant 2...3 secondes. (50 % de risques d\'échec avec Incantation rapide 4 ou inférieure).','Interrompt une action. Effet de l\'interruption : s\'il s\'agit d\'une compétence, pendant 2...3 secondes l\'ennemi visé et tous les ennemis proches sont assommés. 50 % de risques d\'échec avec Incantation rapide 4 ou inférieure.'],
3186=>['Fardeau partagé (PvP)','Pendant 5...20 secondes, la cible ennemie et tous les ennemis dans la zone attaquent, lancent des sorts et se déplacent 33% plus lentement.','Inflige également des maléfices aux ennemis à proximité de votre cible (5...20 secondes). Ces ennemis attaquent, lancent des sorts et se déplacent 33% moins vite.'],
3187=>['Vol de vitesse (PvP)','Pendant 1...10 secondes, le temps d\'incantation des sorts de l\'ennemi visé et de tous les ennemis adjacents est doublé. Le temps d\'incantation des sorts que vous lancez sur ces ennemis visés est réduit de 50%.','Inflige également des maléfices aux ennemis adjacents (1...10 secondes). Double le temps de lancement des sorts. Le temps d\'incantation des sorts lancés sur les ennemis affectés est réduit de -50%.'],
3188=>['Sceau contre nature (PvP)','L\'ennemi visé subit 10...60 points de dégâts. Si cet ennemi est sous l\'effet d\'un maléfice ou d\'un enchantement, les ennemis adjacents à votre cible subissent 10...60 points de dégâts. Toutes vos compétences autres qu\'Envoûteur sont désactivées pendant 10 secondes.','Inflige 10...60 points de dégâts. Inflige 10...60 points de dégâts aux autres ennemis adjacents si la cible est sous l\'effet d\'un maléfice ou d\'un enchantement. Toutes vos compétences autres qu\'Envoûteur sont désactivées (pendant 10 secondes).'],
3189=>['Douleur spirituelle (PvP)','L\'ennemi visé subit 5...40 points de dégâts. Toutes les créatures hostiles invoquées situées près de cet ennemi subissent 25...125 points de dégâts.','Inflige 5...40 points de dégâts. Inflige 25...125 points de dégâts aux créatures hostiles invoquées qui sont situées près de l\'ennemi visé.'],
3190=>['Frustration (PvP)','Pendant 5...20 secondes, la cible ennemie lance ses sorts 50% moins vite et subit 5...50 points de dégâts chaque fois qu\'elle est interrompue.','(5...20 secondes.) Entraîne un ralentissement de 50% du temps d\'incantation des sorts. L\'ennemi visé subit 5...50 points de dégâts chaque fois qu\'il est interrompu.'],
3191=>['Défiance (PvP)','Pendant 6 secondes, le prochain sort que l\'ennemi ciblé lance sur l\'un de vos alliés échoue et inflige 10...60 points de dégâts à cet ennemi ainsi que 75% de ces dégâts à tous les ennemis à proximité.','(6 secondes.) Le prochain sort que l\'ennemi ciblé lance sur l\'un de vos alliés échoue et lui inflige 10...60 points de dégâts ainsi que 75% de ces dégâts aux ennemis à proximité.'],
3192=>['Enigme de l\'enchanteur (PvP)','Pendant 10 secondes, l\'ennemi ciblé lance ses enchantements 100...200% moins vite. Si aucun enchantement n\'affecte l\'ennemi ciblé lorsque ce maléfice est appliqué, il subit 10...100 points de dégâts et tous les ennemis adjacents encaissent 75% de ces dégâts.','Inflige 100...200% de ralentissement à l\'incantation des enchantements (10 secondes). Effet initial : si aucun enchantement n\'affecte l\'ennemi ciblé, il subit 10...100 points de dégâts et tous les ennemis adjacents encaissent 75% de ces dégâts.'],
3193=>['Sceau de Maladresse (PvP)','Si la cible ennemie attaque, cet ennemi ainsi que tous les ennemis adjacents sont interrompus et subissent 15...60 points de dégâts. Tous les ennemis utilisant des compétences d\'attaque sont assommés.','Interrompt une attaque pour la cible ennemie et tous les ennemis adjacents. Effet de l\'interruption : inflige 15...60 points de dégâts et assomme les ennemis utilisant des compétences d\'attaque.'],
3194=>['Miroir de désenchantement (PvP)','Dissipe un enchantement de la cible ennemie. Tous les membres du groupe de cet ennemi perdent aussi cet enchantement.','Dissipe un enchantement de la cible ennemie. Les membres du groupe de cet ennemi perdent aussi cet enchantement.'],
3195=>['Oeil errant (PvP)','Pendant 4 secondes, la prochaine fois que l\'ennemi visé attaque, son attaque est interrompue et tous les ennemis à proximité subissent 10...92 points de dégâts.','(4 secondes.) Interrompt l\'attaque suivante de l\'ennemi visé. Effet de l\'interruption : les ennemis à proximité subissent 10...92 points de dégâts.'],
3196=>['Risque calculé (PvP)','Pendant 3...12 secondes, les attaques de l\'ennemi visé infligent 10 points de dégâts supplémentaires, mais il y a 50% de chances que les dégâts de chacune de ses attaques lui soient infligés. (Maximum 15...60 points de dégâts.)','La cible ennemie inflige +10 points de dégâts avec ses attaques (3...12 secondes). Il y a 50% de chances que les dégâts de chaque attaque soient infligés (maximum 15...60) à cet ennemi et non à sa cible.'],
3204=>['Défi à la douleur (PvP)','Pendant 20 secondes, vous avez 90...300 points de vie supplémentaires et bénéficiez d\'un bonus d\'armure de +20.','(20 secondes.) Vous bénéficiez d\'une santé maximum de +90...300 et d\'un bonus d\'armure de +20.'],
3232=>['Guérison de groupe (PvP)','Soigne tout le groupe de 30...75 points de vie.','Soigne tout le groupe de 30...75.'],
3233=>['Vainqueur dépouillé (PvP)','Pendant 3...15 secondes, chaque fois que l\'ennemi ciblé attaque ou lance un sort sur une créature ayant moins de santé, cet ennemi perd 15...75 points de vie.','(3...15 secondes.) Provoque une perte de 15...75 points de vie chaque fois que la cible ennemie attaque ou lance un sort sur une créature ayant une santé inférieure à la sienne.'],
3234=>['Visions de Regret (PvP)','Pendant 10 secondes, la cible et les ennemis adjacents subissent 10...30 points de dégâts chaque fois qu\'ils utilisent une compétence et 5...40 points de dégâts s\'ils ne sont pas affectés par un autre maléfice d\'Envoûteur.','Inflige également des maléfices aux ennemis adjacents à la cible (10 secondes). Ils subissent 10...30 points de dégâts chaque fois qu\'ils utilisent une compétence et 5...40 points de dégâts supplémentaires s\'ils ne sont pas affectés par un autre maléfice d\'Envoûteur.'],
3251=>['Crocs du renard (PvP)','Doit succéder à une attaque main droite. Crocs du renard est une attaque impossible à bloquer ; elle inflige +10...25 points de dégâts si elle réussit.','Inflige +10...25 points de dégâts. Impossible à bloquer. Doit succéder à une attaque main droite.'],
3252=>['Affront sauvage (PvP)','Doit succéder à une attaque main droite. Si elle réussit, cette attaque inflige +10...35 points de dégâts et chaque pose utilisée par la cible prend fin. Cette attaque ne peut être bloquée.','Inflige +10...35 points de dégâts. Annule la pose de la cible ennemie. Impossible à bloquer. Doit succéder à une attaque main droite.'],
3263=>['Frappe implacable (PvP)','Si cette attaque réussit, elle inflige 10...60 points de dégâts sacrés. Elle inflige deux fois plus de dégâts aux créatures invoquées.','Inflige 10...60 points de dégâts sacrés. Inflige deux fois plus de dégâts aux créatures invoquées.'],
3264=>['Fauchage des deux lunes (PvP)','Vous perdez un enchantement de Derviche et gagnez 10...20 points de vie. Si un enchantement est perdu de cette manière, vous ne pouvez pas être bloqué, vous frappez à deux reprises (en infligeant à chaque fois 25% de dégâts de moins que la normale) et vous gagnez 10...30 points de vie supplémentaires.','Supprime un de vos enchantements de Derviche. Vous bénéficiez de 10...20 points de vie. Effet de la levée : impossible à bloquer, double attaque à -25% de dégâts chacune, 10...30 points de vie supplémentaires.'],
3265=>['Fauchage impérieux (PvP)','Inflige +3...15 points de dégâts et supprime un enchantement de Derviche. Si vous perdez un enchantement de cette manière, le Fauchage impérieux ne peut pas être bloqué et supprime une pose de combat.','Inflige +3...15 points de dégâts. Supprime un de vos enchantements de Derviche. Effet de la suppression : impossible à bloquer, supprime une pose de combat.'],
3266=>['Assaut pieux (PvP)','Vous supprimez un enchantement de Derviche. En cas de perte d\'un enchantement de Derviche, cette compétence se recharge 75% plus vite et les ennemis adjacents subissent 15...40 points de dégâts.','Supprime un de vos enchantements de Derviche. Effet de la suppression : cette compétence se recharge 75% plus vite et les ennemis adjacents subissent 15...40 points de dégâts.'],
3269=>['Mains directrices (PvP)','Pendant 20 secondes, vos 0...3 prochaines attaques ne peuvent pas être bloquées. Une fois activée, cette compétence annule l\'Aveuglement.','(20 secondes.) vos 0...3 prochaines attaques ne peuvent pas être bloquées. Effet initial : annule l\'Aveuglement.'],
3270=>['Avatar de Dwayna (PvP)','Pendant 10...90 secondes, vos attaques infligent des dégâts sacrés. Dès que vous utilisez une compétence d\'attaque de Derviche, vous perdez 1 maléfice. Quand vous perdez un enchantement de Derviche, vous êtes guéri à hauteur de 5...50 points de vie. Cette compétence est désactivée pendant 45 secondes.','(10...90 secondes.) Inflige des dégâts sacrés. Vous perdez 1 maléfice à chaque compétence d\'attaque de Derviche utilisée. Vous êtes guéri à hauteur de 5...50 points de vie quand vous perdez un enchantement de Derviche. Cette compétence est désactivée pendant 45 secondes.'],
3271=>['Avatar de Melandru (PvP)','Pendant 10...90 secondes, vous bénéficiez de +100 points de vie et de +30 points d\'armure élémentaire. En outre, vos attaques infligent des dégâts de la terre. Quand vous perdez un enchantement de Derviche, vous perdez 2 conditions. Cette compétence est désactivée pendant 45 secondes.','(10...90 secondes.) +100 points de vie, +30 points d\'armure élémentaire et vos attaques infligent des dégâts de la terre. 2 conditions vous affectant sont levées quand vous perdez un enchantement de Derviche. Cette compétence est désactivée pendant 45 secondes.'],
3272=>['Guérison mystique (PvP)','Vous êtes soigné de 5...65 points de vie. Tous les membres du groupe enchantés sont également soignés de 5...65 points de vie.','Vous regagnez 5...65 points de vie. Tous les membres du groupe sont également soignés de 5...65 points de vie.'],
3273=>['Sceau de contrainte pieuse (PvP)','Perte d\'un enchantement de Derviche et l\'ennemi ciblé est frappé d\'infirmité pendant 5...15 secondes. En cas de perte d\'enchantement, cette compétence se recharge 50% plus vite.','(5...15 secondes.) Inflige l\'Infirmité à l\'ennemi ciblé et lève 1 de vos enchantements de Derviche. Effet de la suppression : rechargement 50% plus rapide.'],
3289=>['Rêves enfiévrés (PvP)','Pendant 5...15 secondes, chaque fois que l\'ennemi visé est affecté par une nouvelle condition, tous les ennemis dans la zone en sont également affectés.','(5...15 secondes.) Toute nouvelle condition affectant l\'ennemi visé est aussi infligée aux ennemis dans la zone.'],
3346=>['Aura d\'épines (PvP)','Tous les ennemis adjacents souffrent de Saignement pendant 5...15 secondes. Pendant 30 secondes, cet enchantement est sans effet. Lorsque cet enchantement prend fin, tous les ennemis à proximité sont frappés d\'Infirmité pendant 3...8 secondes.','(30 secondes.) Effet initial : inflige le Saignement (5...15 secondes) aux ennemis à proximité. Effet final : inflige l\'Infirmité (3...8 secondes) aux ennemis à proximité.'],
3347=>['Manteau de poussière (PvP)','Tous les ennemis à proximité subissent 10...40 points de dégâts de la terre. Pendant 30 secondes, vos attaques infligent des dégâts de la terre. Lorsque cet enchantement prend fin, tous les ennemis à proximité sont aveuglés pendant 1...4 secondes.','(30 secondes.) Vos attaques infligent des dégâts de la terre. Effet initial : inflige 10...40 points de dégâts de la terre aux ennemis à proximité. Effet final : inflige l\'Aveuglement (1...4 secondes) aux ennemis à proximité.'],
3348=>['Hâte de Lyssa (PvP)','Pendant 3...15 secondes, vos enchantements de Derviche se rechargent 33% plus vite. Lorsque vous activez cet enchantement, tous les ennemis adjacents sont interrompus. Lorsque cet enchantement prend fin, tous les ennemis adjacents sont interrompus. 50 % de risques d\'échec sauf si vous disposez de Prières du Vent 5 ou plus.','(3...15 secondes.) Vos enchantements de Derviche se rechargent 33% plus vite. Effet initial : interrompt tous les ennemis adjacents. Effet final : interrompt tous les ennemis adjacents. (50 % de risques d\'échec sauf si vous disposez de Prières du Vent 5 ou plus.)'],
3365=>['Attaque (PvP)','Pendant 2...8 secondes, vous attaquez et vous gagnez de l\'adrénaline 25% plus vite.','(2...8 secondes.) Vous attaquez et vous gagnez de l\'adrénaline 25% plus vite.'],
3366=>['Coeur de furie (PvP)','Pendant 2...10 secondes, vous attaquez 25% plus vite.','(2...10 secondes.) Votre vitesse d\'attaque est augmentée de 25%.'],
3367=>['Attaque blessante (PvP)','Si cette attaque réussit, l\'ennemi ciblé souffre de Saignement pendant 5...20 secondes et vous perdez un enchantement de Derviche. Si un enchantement a été levé, l\'ennemi ciblé souffre également de Blessure profonde pendant 5...20 secondes.','Provoque le Saignement (5...20 secondes). Supprime un enchantement de Derviche. Effet de la suppression : inflige une Blessure profonde (5...20 secondes).'],
3368=>['Fureur pieuse (PvP)','Supprime un enchantement de Derviche. Pendant 1...5 secondes, vous attaquez 25% plus vite. Si un enchantement a été supprimé, cette pose de combat dure deux fois plus longtemps.','(1...5 secondes.) Vous attaquez 25% plus vite et levez un de vos enchantements de Derviche. Effet de la suppression : cette pose de combat dure deux fois plus longtemps.'],
3373=>['Illusion de hâte (PvP)','Pendant 5...11 secondes, vous vous déplacez 33% plus vite. Lorsque l\'Illusion de hâte prend fin, vous souffrez d\'Infirmité pendant 3 secondes.','(5...11 secondes.) Vous vous déplacez 33% plus vite. Effet final : vous souffrez d\'Infirmité (3 secondes).'],
3374=>['Illusion de douleur (PvP)','Pendant 8 secondes, l\'ennemi visé souffre d\'une dégénération de santé de -3...10 et subit 3...10 points de dégâts par seconde. Quand l\'Illusion de douleur prend fin ou se renouvelle, cet ennemi est soigné de 36...120 points de vie.','(8 secondes.) Provoque une dégénération de santé de -3...10 et l\'ennemi visé subit 3...10 points de dégâts toutes les secondes. Effet final : cet ennemi est soigné de 36...120 points de vie. Cet effet prend fin quand il se renouvelle.'],
3375=>['Aura de rétablissement (PvP)','Pendant 60 secondes, vous gagnez 0...1 points d\'énergie et êtes soigné de 200...400% du coût en énergie pour chaque sort que vous lancez.','(60 secondes.) Vous gagnez 0...1 points d\'énergie et êtes soigné de 200...400% du coût en énergie pour chaque sort que vous lancez.'],
3386=>['Toile d\'interruption (PvP)','Interrompt la cible ennemie. Pendant 10 secondes, la cible ennemie est sous l\'emprise de Toile d\'interruption. Lorsque ce maléfice prend fin, cet ennemi est interrompu à nouveau.','(10 secondes.) Effet initial : interrompt une compétence. Effet final : interrompt une compétence.'],
3396=>['Masse foudroyante (PvP)','La cible ennemie subit 10...100 points de dégâts de la foudre. La Masse foudroyante a 25% de pénétration d\'armure.','Inflige 10...100 points de dégâts de la foudre. 25% de pénétration d\'armure.'],
3397=>['Flamme élémentaire (PvP)','Pendant 5...20 secondes, chaque fois que vous infligez un maléfice élémentaire à un ennemi ciblé, cet ennemi s\'embrase pendant 1...2 secondes.','(5...20 secondes.) Inflige la Brûlure (1...2 secondes) chaque fois que vous infligez un maléfice élémentaire à un ennemi visé.'],
3398=>['Terrain glissant (PvP)','Si l\'ennemi visé souffre d\'Aveuglement ou se déplace, il est assommé. (50% de risques d\'échec avec Magie de l\'eau 4 ou inférieure.)','Provoque l\'assommement si cet ennemi souffre d\'Aveuglement ou se déplace. 50 % de risques d\'échec sauf si vous disposez d\'une Magie de l\'eau 5 ou plus.'],
3422=>['Protection du temps','Vous créez une Protection du Temps sur votre position actuelle. Pendant 6...20 secondes, les alliés situés dans cette zone et qui ne sont pas des esprits lancent des sorts 15...20 % plus vite et recharge leurs compétences 15...20 % plus vite. Compétence PvE','(6...20 secondes.) Les alliés situés dans cette zone lancent des sorts 15...20 % plus vite et recharge leurs compétences 15...20 % plus vite. Les alliés qui ne sont pas des esprits ne sont pas affectés. Compétence PvE '],
3423=>['Preneur d\'Âmes','Pendant 3...30 secondes, vos attaques sacrifient 15...20 points de vie et infligent 15...20 points de dégâts supplémentaires. Compétence PvE','(3...30 secondes.) Les attaques infligent +15...20 points de dégâts et sacrifient 15...20 points de vie. Compétence PvE'],
3424=>['Au-delà de la limite','Tant que cet enchantement est actif, vos sorts se lancent 20...50 % plus vite et se rechargent 40...80 % plus vite, cependant vous gagnez de l\'Afflux en continu. Compétence PvE','Les sorts se lancent 20...50 % plus vite et se rechargent 40...80 % plus vite. Vous gagnez de l\'Afflux en continu lorsqu\'il est actif. Compétence PvE'],
3425=>['Frappe du jugement','Attaque la cible et les ennemis adjacents. Chaque attaque inflige +13...30 de dégâts sacrés et renverse les ennemis en combats. Compétence PvE','Attaque la cible et les ennemis adjacents pour +13...30 de dégâts sacrés. Renverse les ennemis en combats. Compétence PvE'],
3426=>['Pose des septs armes','Pendant 3...20 secondes, vos caractéristiques d\'armes augmentent de 1...15 et vos attaques sont 33 % plus rapide. Compétence PvE','(3...20 secondes.) Les caractéristiques d\'armes augmentent de 1...15. Vous attaquez 33 % plus vite. Compétence PvE'],
3427=>['"Ensemble et unis !"','Pendant 3...15 secondes, tous les membres du groupe près de vous ou de votre familier infligent +5...15 points de dégâts supplémentaires et bénéficient d\'une régénération de santé de +1...7. Compétence PvE','(3...15 secondes.) Tous les membres du groupe près de vous ou de votre familier infligent +5...15 points de dégâts et gagnent une régénération de santé de +1...7. Compétence PvE'],
3428=>['Voleur d\'ombre','Vous faites une Foulée de l\'ombre jusqu\'à la cible ennemie. Pendant 5...20 secondes, les caractéristiques de cet ennemi sont réduites de 1...5 et vos caractéristiques sont augmentées de 1...5. Cette compétence compte comme une attaque main droite. Compétence PvE','Vous faites une Foulée de l\'ombre jusqu\'à la cible ennemie. Pendant 5...20 secondes, les caractéristiques de cet ennemi sont réduites de 1...5 et vos caractéristiques sont augmentées de 1...5. Compte comme une attaque main droite. Compétence PvE'],
3429=>['Armes des trois forges','Pendant 3...20 secondes, les alliés situés à portée de voix et qui ne sont pas des esprits bénéficient des effets d\'un sort d\'altération d\'arme aléatoire. Compétence PvE','(3...20 secondes.) Les alliés situés à portée de voix bénéficient des effets d\'un sort d\'altération d\'arme aléatoire. Les alliés qui ne sont pas des esprits ne sont pas affectés. Compétence PvE '],
3430=>['Voeu de révolution','Pendant 3...10 secondes, vous bénéficiez d\'une régénération d\'énergie de +1...6. Cette compétence s\'applique à nouveau à chaque fois que vous utilisez une compétence qui n\'est pas une compétence de Derviche. Compétence PvE','(3...10 secondes.) Vous bénéficiez d\'une régénération d\'énergie de +1...6. Renouvellement : à chaque fois que vous utilisez une compétence qui n\'est pas une compétence de Derviche. Compétence PvE'],
3431=>['Rengaine héroïque','Pendant 3...15 secondes, l\'allié ciblé, s\'il n\'est pas un esprit, bénéficie de +1...3 pour toutes ses caractéristiques. Cet écho se renouvelle chaque fois qu\'un chant ou un cri vous affectant prend fin. Compétence PvE','(3...15 secondes.) L\'allié ciblé bénéficie de +1...3 pour toutes ses caractéristiques. Renouvellement : à chaque fois qu\'un chant ou un cri affectant cet allié prend fin. Les alliés qui ne sont pas des esprits ne sont pas affectés. Compétence PvE '],
3437=>['Faux du fermier (PvP)','Si cette attaque réussit, vous infligez +5...35 points de dégâts. Si vous frappez plus d\'un ennemi, cette attaque se recharge instantanément.','Inflige +5...35 points de dégâts. Rechargement instantané si vous frappez plus d\'un ennemi.'],
3442=>['Lancer puissant (PvP)','Votre javelot se déplace trois fois plus vite. Si l\'attaque réussit, vous infligez +10...40 points de dégâts.','Inflige +10...40 points de dégâts. Ce javelot se déplace trois fois plus vite.'],
3443=>['Frénésie','Pendant 8 secondes, vous attaquez 33% plus vite, mais vous subissez 200...150% de dégâts.','(8 secondes.) Vous attaquez 33% plus vite. Vous subissez 200...150% de dégâts.'],
3444=>['Cent lames','Pendant 15 secondes, à chaque fois que vous attaquez avec une épée, tous les ennemis adjacents subissent 10...30 points de dégâts tranchants.','(15 secondes.) Inflige 10...30 points de dégâts tranchants à tous les ennemis adjacents chaque fois que vous attaquez avec une épée.'],
3445=>['Renouveau de la nature','Create a level 1...10 spirit. For 30...240 seconds, enchantments and hexes cast by non-spirit creatures take 50...75% longer to cast, and it costs twice as much Energy to maintain enchantments. This spirit dies after 30...240 seconds.','Creates a level 1...10 spirit (30...240 second lifespan). For creatures in range, enchantments and Hexes take 50...75% longer to cast and it costs twice as much Energy to maintain enchantments. Does not affect spirits.'],
3446=>['Soul Ignition','While you maintain this enchantment, reduce Overcast at a rate of 1...2 per second. You and all adjacent foes are afflicted with burning while this enchantment is active.','Reduce Overcast by 1...2 per second. You and all adjacent foes are afflicted with burning.'],
3447=>['Embarras de l\'incapable','Après 3 secondes, l\'ennemi ciblé subit 20...100 points de dégâts et les ennemis adjacents subissent 75% de ces dégâts. Si cet ennemi réussit à utiliser une compétence, Embarras du gaspilleur prend fin prématurément et n\'inflige aucun dégât.','(3 secondes.) Effet final : inflige 20...100 points de dégâts à l\'ennemi ciblé et 75% de ces dégâts aux ennemis adjacents. Aucun effet et prend fin prématurément si l\'ennemi ciblé réussit à utiliser une compétence.'],
3448=>['Paix et harmonie','La cible alliée perd 0...4 conditions et maléfices. Pendant 1...3 secondes, les conditions et maléfices expirent 90% plus vite sur cet allié. Toutes vos Prières de châtiment sont désactivées pendant 20 secondes.','La cible alliée perd 0...4 conditions et maléfices. Les conditions et maléfices expirent 90% plus vite sur cet allié (1...3 secondes). Désactives vos Prières de châtiment (20 secondes).'],
3449=>['Attaque du protecteur','Si cette attaque frappe un ennemi en mouvement, vous infligez 10...40 points de dégâts supplémentaires.','Inflige +10...40 points de dégâts si la cible est en mouvement.'],
3450=>['Tir incapacitant','Si le Tir incapacitant réussit, la cible est frappée d\'Infirmité pendant 4...14 secondes. Cette attaque ne peut être bloquée.','Ne peut être bloqué. Inflige l\'Infirmité (4...14 secondes).'],
3451=>['Cri d\'Otyugh','Pendant 5...15 secondes, votre familier bénéficie d\'un bonus d\'armure de +24 et ne peut pas être bloqué.','(5...15 secondes.) Votre familier bénéficie d\'un bonus d\'armure de +24 et ses attaques ne peuvent être bloquées.'],
3452=>['Linceul de l\'Ombre','Pendant 2...7 secondes, l\'ennemi visé ne peut pas être la cible d\'enchantements.','(2...7 secondes.) La cible ennemie ne peut pas être la cible d\'enchantements.'],
3453=>['Ruée','Pendant 3 secondes, vous courez 50% plus vite. Tous les 2 points d\'Arts des ombres réduisent le temps de recharge de 1 secondes (maximum 6 secondes).','(3 secondes.) Vous vous déplacez 50% plus vite. Tous les 2 points d\'Arts des ombres réduisent le temps de recharge de 1 secondes (maximum 6 secondes).'],
3454=>['Gardien protecteur','Pendant 1...4 secondes, tous les membres du groupe à portée de voix ont 75% de chances de bloquer les attaques. Le cas échéant, tous les alliés à proximité sont soignés de 10...35 points de vie et la compétence prend fin.','(1...4 secondes.) Les membres du groupe à portée de voix ont 75% de chances de bloquer les attaques. Effet du blocage : les alliés à proximité sont soignés de 10...35 points de vie et la compétence prend fin.'],
3455=>['Coup propice','Si Coup propice réussit, il inflige +5...20 points de dégâts et vous gagnez 2...4 points d\'énergie. Si la cible ennemie souffre de Faiblesse, cette attaque ne peut être bloquée.','Inflige +5...20 points de dégâts et vous gagnez 2...4 points d\'énergie. Ne peut être bloqué si l\'ennemi est Affaibli.'],
3456=>['"Froussard !"','Si la cible ennemie est en mouvement, elle sera assommée.','Attaque assommante si la cible ennemie se déplace.'],
3457=>['Défense du protecteur','Pendant 4...8 secondes, les alliés adjacents à votre position ont 75% de chances de bloquer les attaques. La défense du protecteur prend fin si vous bougez.','(4...8 secondes.) Les alliés adjacents à votre position ont 75% de chances de bloquer. Prend fin si vous vous déplacez.'],
3458=>['Rage primitive','Pendant 1...9 secondes, vous attaquez 33% plus vite et vous vous déplacez 33% plus rapidement, mais vous subissez 200...150% de dégâts.','(1...9 secondes.) Vous attaquez 33% plus vite et vous vous déplacez 33% plus rapidement. Vous subissez 200...150% de dégâts.'],
3459=>['Tir de Melandru','Si le Tir de Melandru réussit, votre cible souffre de Saignement pendant 5...25 secondes. Si le tir touche un ennemi en fuite ou assommé, ce dernier reçoit +10...25 points de dégâts et souffre d\'Infirmité pendant 5...15 secondes.','Provoque le Saignement (5...25 secondes). Inflige +10...25 points de dégâts et provoque l\'Infirmité (5...15 secondes) si la cible ennemie est en fuite ou assommée.'],
3460=>['Tranquillité','Crée un esprit de niveau 1...10. Les enchantements lancés par les créatures (autres que des esprits) se trouvant dans sa portée se terminent 10...30% plus vite. Cet esprit disparaît au bout de 15...120 secondes.','Crée un esprit de niveau 1...10 (durée de vie de 15...120 secondes). Les enchantements prennent fin 10...30% plus vite sur les créatures à portée. N\'affecte pas les esprits.'],
3461=>['Contorsion de l\'âme','Pendant 5...45 secondes, vos rituels d\'asservissement coûtent 15 points d\'énergie en moins (minimum 5) et se rechargent 25...50% plus vite. Contorsion de l\'âme prend fin après 1...3 rituels d\'asservissement.','(5...45 secondes.) Vos rituels d\'asservissement coûtent 15 points d\'énergie en moins (minimum 5) et se rechargent 25...50% plus vite. Prend fin après 1...3 rituels d\'asservissement.'],
3462=>['Arme guidée','Pendant 4...10 secondes, les attaques de la cible visée (allié ou vous-même) ne peuvent pas être bloquées.','(4...10 secondes.) Les attaques sont impossibles à bloquer.'],
3463=>['Taquinerie','Si la cible ennemie utilise une compétence, elle et les autres ennemis de la zone sont interrompus et vous volez 0...5 points d\'énergie à chaque ennemi de la zone.','Interrompt une compétence. Effet de l\'interruption : les autres ennemis de la zone sont aussi interrompus et vous volez 0...5 points d\'énergie à chaque ennemi de la zone.'],
3464=>['Peste','Pendant 1...15 secondes, vous attaquez 33% plus vite, mais vous vous déplacez 33% plus lentement. Prend fin si vous utilisez une compétence d\'attaque à distance.','(1...15 secondes.) Vous attaquez 33% plus vite. Prend fin si vous utilisez une compétence d\'attaque à distance. Vous vous déplacez 33% moins vite.'],
3465=>['Frappe de charge','Pendant 1...10 secondes, vous courez 33% plus vite. Votre prochaine attaque de mêlée réussie inflige +10...80 points de dégâts et cette pose prend fin. Cette pose prend fin si vous utilisez une compétence.','(1...10 secondes.) Vous vous déplacez 33% plus vite et infligez +10...80 points de dégâts avec votre prochaine attaque au corps à corps.Prend fin quand vous réussissez une attaque ou si vous utilisez une compétence.'],
3466=>['Chaleur exaspérante','Create a level 1...10 spirit. Non-spirit creatures within its range gain adrenaline 33...66% as fast. This spirit dies after 30...120 seconds.','Creates a level 1...10 spirit (30...120 second lifespan). Adrenaline gain increased by 33...66% for creatures in range.'],
3467=>['Corruption mystique','Tous les ennemis adjacents sont frappés de Maladie pendant 2...6 secondes. Pendant 20 secondes, rien ne se passe. La durée de la Maladie est doublée si vous êtes sous le coup d\'un enchantement quand vous activez cette compétence. Une fois cet enchantement dissipé, tous les membres du groupe à portée de voix sont soignés de la Maladie.','(20 secondes.) Effet initial : tous les ennemis adjacents souffrent de Maladie (pendant 2...6 secondes). Durée doublée si vous êtes déjà sous le coup d\'un enchantement. Effet final : les membres du groupe à portée de voix perdent Maladie.'],
3468=>['Empoigne d\'harrier','Pendant 5...20 secondes, les attaques au corps à corps lancées contre des ennemis en mouvement causent l\'Infirmité chez ces ennemis pendant 2...9 secondes. Lorsque vous lancez cet enchantement, vous perdez Infirmité et une autre altération. Cet enchantement prend fin après 1...3 applications d\'Infirmité.','(5...20 secondes.) Les attaques au corps à corps contre les ennemis en mouvement les font également souffrir d\'Infirmité. Effet initial : vous perdez Infirmité et une autre altération. Prend fin après 1...3 applications d\'Infirmité.'],
3469=>['Manteau de mirage','Pendant 1...7 secondes, vous avez 30...60% de chances de bloquer les attaques. Lorsque vous lancez cet enchantement, tous les ennemis adjacents reçoivent 10...40 points de dégâts de la terre.','(1...7 secondes.) Vous avez 30...60 % de chances de bloquer les attaques. Effet initial : inflige 10...40 points de dégâts de la terre aux ennemis proches.'],
3470=>['Brève stabilité','Pendant 2...8 secondes, vous ne pouvez pas être assommé et vous déplacez 25% plus vite. Cet enchantement prend fin prématurément s\'il vous empêche d\'être assommé.','(2...8 secondes.) Vous ne pouvez pas être assommé et vous déplacez 25% plus vite. Prend fin s\'il vous empêche d\'être assommé.'],
3471=>['Rétablissement pieux','Vous gagnez 80...150 points de vie et levez un enchantement de Derviche. Si un enchantement est levé de cette façon, vous perdez également 1 maléfices.','Vous gagnez 80...150 points de vie et levez un enchantement de Derviche. Effet de la levée : vous perdez 1 maléfices.'],
3472=>['Charge tourbillonnante','Pendant 1...6 secondes, vous vous déplacez 33% plus vite que la normale. La prochaine fois que vous touchez un ennemi, tous les ennemis à proximité subissent 10...50 points de dégâts du froid et cet enchantement prend fin.','(1...6 secondes.) Vous vous déplacez 33% plus vite. Inflige 10...50 points de dégâts du froid à tous les autres ennemis adjacents la prochaine fois que vous touchez un ennemi. Cet enchantement prend alors fin.'],
3473=>['Trancheur d\'aura','Si cette attaque réussit, vous infligez un Saignement pendant 5...15 secondes. Si vous êtes sous l\'effet d\'un enchantement, vous infligez en outre Armure brisée pendant 1...10 secondes.','(5...15 secondes.) Provoque le Saignement. Inflige également Armure brisée (1...10 secondes) si vous êtes sous l\'emprise d\'un enchantement.'],
];}
